import { useState, useMemo, useRef, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem, CollectionItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Folder, FileText, File, Image as ImageIcon, Video, Music, Archive, FileCode, ArrowUpDown, ArrowUp, ArrowDown, Loader2 } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"
import { Checkbox } from "@/components/ui/checkbox"
import { useUserCache } from "@/hooks/use-user-cache"
import { retrieveRendition } from "@/lib/rendition"

type ItemType = "document" | "collection"
type MemberItem = (ContentObjectItem | CollectionItem) & { itemType: ItemType }

type SortField = "relevance" | "name" | "type" | "created_at" | "updated_at" | "created_by"
type SortDirection = "asc" | "desc"

interface ItemsDataTableProps {
    items: MemberItem[]
    onCollectionClick?: (collection: CollectionItem) => void
    loading?: boolean
    loadingMore?: boolean
    hasMore?: boolean
    loadMore?: () => void
    selectedIds?: Set<string>
    onToggleSelection?: (id: string) => void
    onSelectAll?: () => void
    onClearSelection?: () => void
    searchActive?: boolean
}

interface ItemThumbnailProps {
    item: MemberItem
}

function ItemThumbnail({ item }: ItemThumbnailProps) {
    const { client } = useUserSession()
    const toast = useToast()
    const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
    const [imageError, setImageError] = useState(false)

    const getFileIcon = () => {
        if (item.itemType === "collection") {
            return <Folder className="h-5 w-5 text-muted-foreground" />
        }

        const doc = item as ContentObjectItem
        const mime = doc.content?.type?.toLowerCase() || ""
        const type = doc.type?.id?.toLowerCase() || ""

        if (mime.startsWith("image/") || type === "image") {
            return <ImageIcon className="h-5 w-5 text-muted-foreground" />
        }
        if (mime.startsWith("video/") || type === "video") {
            return <Video className="h-5 w-5 text-muted-foreground" />
        }
        if (mime.startsWith("audio/") || type === "audio") {
            return <Music className="h-5 w-5 text-muted-foreground" />
        }
        if (mime.includes("pdf") || type === "pdf") {
            return <FileText className="h-5 w-5 text-muted-foreground" />
        }
        if (mime.includes("zip") || mime.includes("tar") || mime.includes("rar") || type === "archive") {
            return <Archive className="h-5 w-5 text-muted-foreground" />
        }
        if (mime.includes("code") || mime.includes("javascript") || mime.includes("typescript") || type === "code") {
            return <FileCode className="h-5 w-5 text-muted-foreground" />
        }
        return <File className="h-5 w-5 text-muted-foreground" />
    }

    const canHaveThumbnail = () => {
        if (item.itemType === "collection") return false
        const doc = item as ContentObjectItem
        const mime = doc.content?.type?.toLowerCase() || ""
        const type = doc.type?.id?.toLowerCase() || ""
        return mime.startsWith("image/") || type === "image" ||
               mime.startsWith("video/") || type === "video" ||
               mime.includes("pdf") || type === "pdf"
    }

    useEffect(() => {
        if (client && item.itemType === "document" && canHaveThumbnail()) {
            const doc = item as ContentObjectItem
            retrieveRendition(
                client,
                doc,
                setThumbnailUrl,
                () => {}, // We don't need alt text for small thumbnails
                toast,
                64 // Small thumbnail size
            ).catch(() => {
                setImageError(true)
            })
        }
    }, [item.id, client])

    const showThumbnail = canHaveThumbnail() && thumbnailUrl && !imageError

    if (showThumbnail) {
        return (
            <div className="w-8 h-8 rounded overflow-hidden bg-muted flex-shrink-0">
                <img
                    src={thumbnailUrl}
                    alt=""
                    className="w-full h-full object-cover"
                    onError={() => setImageError(true)}
                />
            </div>
        )
    }

    return (
        <div className="w-8 h-8 rounded bg-muted/50 flex items-center justify-center flex-shrink-0">
            {getFileIcon()}
        </div>
    )
}

export function ItemsDataTable({ items, onCollectionClick, loading, loadingMore, hasMore, loadMore, selectedIds, onToggleSelection, onSelectAll, onClearSelection, searchActive }: ItemsDataTableProps) {
    const { t } = useTranslation(["collections", "common"])
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const { getUserDisplayName } = useUserCache(client)
    const containerRef = useRef<HTMLDivElement>(null)

    const [sortField, setSortField] = useState<SortField>(searchActive ? "relevance" : "name")
    const [sortDirection, setSortDirection] = useState<SortDirection>("asc")

    // Auto-switch to relevance sort when search is active
    useEffect(() => {
        setSortField(searchActive ? "relevance" : "name")
        if (!searchActive) setSortDirection("asc")
    }, [searchActive])

    const selectionEnabled = !!onToggleSelection
    const documentItems = items.filter(item => item.itemType === "document")
    const selectedCount = selectedIds?.size ?? 0
    const allDocumentsSelected = documentItems.length > 0 && documentItems.every(item => selectedIds?.has(item.id))
    const someDocumentsSelected = selectedCount > 0 && !allDocumentsSelected

    const handleHeaderCheckboxChange = () => {
        if (allDocumentsSelected) {
            onClearSelection?.()
        } else {
            onSelectAll?.()
        }
    }

    const handleSort = (field: SortField) => {
        if (sortField === field) {
            setSortDirection(sortDirection === "asc" ? "desc" : "asc")
        } else {
            setSortField(field)
            setSortDirection("asc")
        }
    }

    // Handle infinite scroll
    const handleScroll = () => {
        if (!containerRef.current || loading || loadingMore || !hasMore || !loadMore) {
            return
        }

        const { scrollTop, scrollHeight, clientHeight } = containerRef.current
        const diff = scrollHeight - scrollTop - clientHeight

        if (diff < 100) {
            loadMore()
        }
    }

    useEffect(() => {
        const container = containerRef.current
        if (container) {
            container.addEventListener("scroll", handleScroll)
            return () => container.removeEventListener("scroll", handleScroll)
        }
    }, [loading, loadingMore, hasMore, loadMore])

    const sortedItems = useMemo(() => {
        if (sortField === "relevance") return items
        return [...items].sort((a, b) => {
            let aValue: string | number = ""
            let bValue: string | number = ""

            switch (sortField) {
                case "name":
                    aValue = a.name?.toLowerCase() || ""
                    bValue = b.name?.toLowerCase() || ""
                    break
                case "type":
                    aValue = a.itemType === "collection" ? "collection" : (a as ContentObjectItem).type?.id || ""
                    bValue = b.itemType === "collection" ? "collection" : (b as ContentObjectItem).type?.id || ""
                    break
                case "created_at":
                    aValue = a.created_at ? new Date(a.created_at).getTime() : 0
                    bValue = b.created_at ? new Date(b.created_at).getTime() : 0
                    break
                case "updated_at":
                    aValue = a.updated_at ? new Date(a.updated_at).getTime() : 0
                    bValue = b.updated_at ? new Date(b.updated_at).getTime() : 0
                    break
                case "created_by":
                    aValue = (a as ContentObjectItem).created_by || ""
                    bValue = (b as ContentObjectItem).created_by || ""
                    break
            }

            if (aValue < bValue) return sortDirection === "asc" ? -1 : 1
            if (aValue > bValue) return sortDirection === "asc" ? 1 : -1
            return 0
        })
    }, [items, sortField, sortDirection])

    const formatDate = (dateString: string | undefined) => {
        if (!dateString) return "-"
        const date = new Date(dateString)
        return date.toLocaleDateString()
    }

    const getTypeName = (item: MemberItem) => {
        if (item.itemType === "collection") {
            return t("common:collection")
        }
        const doc = item as ContentObjectItem
        return typeRegistry?.getTypeName(doc.type?.id || "") || doc.type?.name || t("common:document") || "Document"
    }

    const getCreatedBy = (item: MemberItem) => {
        if (item.itemType === "collection") return "-"
        const doc = item as ContentObjectItem
        if (!doc.created_by) return "-"
        return getUserDisplayName(doc.created_by, undefined)
    }

    const SortIcon = ({ field }: { field: SortField }) => {
        if (sortField !== field) {
            return <ArrowUpDown className="h-3 w-3 ml-1 opacity-50" />
        }
        return sortDirection === "asc"
            ? <ArrowUp className="h-3 w-3 ml-1" />
            : <ArrowDown className="h-3 w-3 ml-1" />
    }

    const handleRowClick = (item: MemberItem, e: React.MouseEvent) => {
        if (item.itemType === "collection" && onCollectionClick) {
            e.stopPropagation()
            onCollectionClick(item as CollectionItem)
        }
    }

    const handleRowCheckboxClick = (e: React.MouseEvent, itemId: string) => {
        e.stopPropagation()
        e.preventDefault()
        onToggleSelection?.(itemId)
    }

    const renderRow = (item: MemberItem) => {
        const isSelected = selectedIds?.has(item.id) ?? false
        const isDocument = item.itemType === "document"
        const name = (item as ContentObjectItem)?.properties?.title || item?.name || item.id

        const rowContent = (
            <div
                key={item.id}
                className="flex items-center w-full min-w-0 border-b border-border hover:bg-muted/50 cursor-pointer transition-colors"
                onClick={(e) => handleRowClick(item, e)}
            >
                {/* Checkbox column - only for documents when selection is enabled */}
                {selectionEnabled && (
                    <div
                        className="w-10 p-2 flex items-center justify-center flex-shrink-0"
                        onClick={(e) => isDocument ? handleRowCheckboxClick(e, item.id) : undefined}
                    >
                        {isDocument && (
                            <Checkbox
                                checked={isSelected}
                                onCheckedChange={() => onToggleSelection?.(item.id)}
                                onClick={(e) => e.stopPropagation()}
                            />
                        )}
                    </div>
                )}
                {/* Thumbnail - always visible */}
                <div className="w-12 sm:w-14 p-2 flex items-center justify-center flex-shrink-0">
                    <ItemThumbnail item={item} />
                </div>
                {/* Name - always visible, flexible */}
                <div className="flex-1 w-0 min-w-0 p-2 font-medium truncate" title={name}>
                    {name}
                </div>
                {/* Type - visible on md+ */}
                <div className="hidden md:flex w-32 lg:w-40 p-2 flex-shrink-0">
                    <Badge variant="outline" className="text-xs truncate max-w-full">
                        {getTypeName(item)}
                    </Badge>
                </div>
                {/* Created - visible on lg+ */}
                <div className="hidden lg:block w-24 xl:w-28 p-2 text-muted-foreground text-sm flex-shrink-0">
                    {formatDate(item.created_at)}
                </div>
                {/* Modified - visible on xl+ */}
                <div className="hidden xl:block w-28 p-2 text-muted-foreground text-sm flex-shrink-0">
                    {formatDate(item.updated_at)}
                </div>
                {/* Creator - visible on 2xl+ */}
                <div className="hidden 2xl:block w-36 p-2 text-muted-foreground text-sm truncate flex-shrink-0" title={getCreatedBy(item)}>
                    {getCreatedBy(item)}
                </div>
            </div>
        )

        if (item.itemType === "document") {
            return (
                <DocumentOverlay key={item.id} documentId={item.id}>
                    {rowContent}
                </DocumentOverlay>
            )
        }

        return rowContent
    }

    return (
        <div className="flex flex-col h-full w-full max-w-full border border-border rounded-sm overflow-hidden">
            {/* Sticky Header */}
            <div className="flex items-center w-full min-w-0 bg-muted/50 border-b border-border flex-shrink-0">
                {/* Checkbox column header */}
                {selectionEnabled && (
                    <div className="w-10 p-2 flex items-center justify-center flex-shrink-0">
                        <Checkbox
                            checked={allDocumentsSelected}
                            onCheckedChange={handleHeaderCheckboxChange}
                            className={someDocumentsSelected ? "data-[state=checked]:bg-primary" : ""}
                            {...(someDocumentsSelected && { "data-state": "indeterminate" })}
                        />
                    </div>
                )}
                {/* Thumbnail column */}
                <div className="w-12 sm:w-14 p-2 flex-shrink-0"></div>
                {/* Name */}
                <div
                    className="flex-1 w-0 min-w-0 p-2 cursor-pointer hover:text-foreground select-none text-sm font-medium text-muted-foreground"
                    onClick={() => handleSort("name")}
                >
                    <span className="flex items-center">
                        Name
                        <SortIcon field="name" />
                    </span>
                </div>
                {/* Type - visible on md+ */}
                <div
                    className="hidden md:flex w-32 lg:w-40 p-2 cursor-pointer hover:text-foreground select-none text-sm font-medium text-muted-foreground flex-shrink-0"
                    onClick={() => handleSort("type")}
                >
                    <span className="flex items-center">
                        Type
                        <SortIcon field="type" />
                    </span>
                </div>
                {/* Created - visible on lg+ */}
                <div
                    className="hidden lg:block w-24 xl:w-28 p-2 cursor-pointer hover:text-foreground select-none text-sm font-medium text-muted-foreground flex-shrink-0"
                    onClick={() => handleSort("created_at")}
                >
                    <span className="flex items-center">
                        Created
                        <SortIcon field="created_at" />
                    </span>
                </div>
                {/* Modified - visible on xl+ */}
                <div
                    className="hidden xl:block w-28 p-2 cursor-pointer hover:text-foreground select-none text-sm font-medium text-muted-foreground flex-shrink-0"
                    onClick={() => handleSort("updated_at")}
                >
                    <span className="flex items-center">
                        Modified
                        <SortIcon field="updated_at" />
                    </span>
                </div>
                {/* Creator - visible on 2xl+ */}
                <div
                    className="hidden 2xl:block w-36 p-2 cursor-pointer hover:text-foreground select-none text-sm font-medium text-muted-foreground flex-shrink-0"
                    onClick={() => handleSort("created_by")}
                >
                    <span className="flex items-center">
                        Creator
                        <SortIcon field="created_by" />
                    </span>
                </div>
            </div>

            {/* Scrollable Body */}
            <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-hidden bg-background">
                {sortedItems.map(renderRow)}

                {/* Loading indicator */}
                {(loadingMore || loading) && items.length > 0 && (
                    <div className="w-full flex justify-center items-center p-4">
                        <Loader2 className="h-6 w-6 animate-spin text-primary" />
                    </div>
                )}

                {/* Load more trigger area */}
                {hasMore && loadMore && !loadingMore && items.length > 0 && (
                    <div className="h-4" />
                )}
            </div>
        </div>
    )
}
