import { useCallback, useEffect, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { CollectionItem } from "@vertesia/common"
import { useDebounce, useFetch } from "@vertesia/ui/core"
import { useNavigate } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Search, FolderOpen, Loader2, ListFilter, X, ChevronRight, User, Users, LayoutGrid, List } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { EXECUTION_CONTAINER_FACETS } from "@/constants/facets"
import { useUserCache } from "@/hooks/use-user-cache"
import { cn } from "@/lib/utils"

interface FacetBucket {
    _id: string
    count: number
}

type FacetsResult = Record<string, FacetBucket[]>

export function ExecutionsSearchPanel() {
    const { t } = useTranslation(["executions", "common"])
    const { client, isLoading: sessionLoading, user } = useUserSession()
    const appInstallation = useAppInstallation()
    const navigate = useNavigate()
    const { getUserDisplayName } = useUserCache(client)

    const EXECUTION_CONTAINER = appInstallation?.settings?.EXECUTION_CONTAINER as string || undefined

    const [searchQuery, setSearchQuery] = useState("")
    const [selectedFilters, setSelectedFilters] = useState<Record<string, string[]>>({})
    const [filterOpen, setFilterOpen] = useState(false)
    const [viewMode, setViewMode] = useState<"mine" | "all">("mine")
    const [displayMode, setDisplayMode] = useState<"cards" | "table">(() => {
        const saved = localStorage.getItem("executions-display-mode")
        return saved === "table" ? "table" : "cards"
    })
    const debouncedSearchQuery = useDebounce(searchQuery, 300)

    const buildSearchQuery = useCallback((query: string, filters: Record<string, string[]>, userOnly: boolean) => {
        const trimmedQuery = query.trim()
        const match: Record<string, any> = {}

        if (userOnly && user?.user_id) {
            match.created_by = `user:${user.user_id}`
        } else if (filters.created_by?.length) {
            match.created_by = filters.created_by.length === 1 ? filters.created_by[0] : { $in: filters.created_by }
        }
        if (filters.interaction?.length) {
            match["properties.interaction"] = filters.interaction.length === 1 ? filters.interaction[0] : { $in: filters.interaction }
        }

        return {
            type: EXECUTION_CONTAINER,
            name: trimmedQuery || undefined,
            match: Object.keys(match).length > 0 ? match : undefined
        }
    }, [EXECUTION_CONTAINER, user?.user_id])

    const searchFacets = useCallback(async (query: string, filters: Record<string, string[]>, userOnly: boolean): Promise<FacetsResult> => {
        if (!client || !EXECUTION_CONTAINER) {
            return {}
        }

        const searchQuery = buildSearchQuery(query, filters, userOnly)
        const facets = await client.store.collections.computeListFacets({
            facets: EXECUTION_CONTAINER_FACETS,
            query: searchQuery
        })

        return facets as FacetsResult
    }, [client, EXECUTION_CONTAINER, buildSearchQuery])

    const PAGE_SIZE = 20

    const userOnly = viewMode === "mine"

    const { data: facets } = useFetch(
        () => searchFacets(debouncedSearchQuery, selectedFilters, userOnly),
        [debouncedSearchQuery, selectedFilters, userOnly, searchFacets]
    )

    const [collections, setCollections] = useState<CollectionItem[]>([])
    const [isLoading, setIsLoading] = useState(false)
    const [isLoadingMore, setIsLoadingMore] = useState(false)
    const [hasMore, setHasMore] = useState(true)
    const [error, setError] = useState<Error | null>(null)
    const offsetRef = useRef(0)
    const sentinelRef = useRef<HTMLDivElement>(null)

    const loadCollections = useCallback(async (offset: number, isInitial: boolean) => {
        if (!client || !EXECUTION_CONTAINER) {
            return
        }

        if (isInitial) {
            setIsLoading(true)
            setError(null)
        } else {
            setIsLoadingMore(true)
        }

        try {
            const query = buildSearchQuery(debouncedSearchQuery, selectedFilters, userOnly)
            const results = await client.store.collections.search({
                ...query,
                limit: PAGE_SIZE,
                offset,
            })

            if (isInitial) {
                setCollections(results)
            } else {
                setCollections((prev) => [...prev, ...results])
            }

            setHasMore(results.length >= PAGE_SIZE)
            offsetRef.current = offset + results.length
        } catch (err) {
            setError(err instanceof Error ? err : new Error("Failed to load executions"))
        } finally {
            if (isInitial) {
                setIsLoading(false)
            } else {
                setIsLoadingMore(false)
            }
        }
    }, [client, EXECUTION_CONTAINER, buildSearchQuery, debouncedSearchQuery, selectedFilters, userOnly])

    useEffect(() => {
        offsetRef.current = 0
        setCollections([])
        setHasMore(true)
        loadCollections(0, true)
    }, [loadCollections])

    useEffect(() => {
        const sentinel = sentinelRef.current
        if (!sentinel || !hasMore || isLoading) {
            return
        }

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && hasMore && !isLoadingMore && !isLoading) {
                    loadCollections(offsetRef.current, false)
                }
            },
            { threshold: 0.1 }
        )

        observer.observe(sentinel)
        return () => observer.disconnect()
    }, [hasMore, isLoadingMore, isLoading, loadCollections])

    const handleFilterToggle = (facetName: string, value: string) => {
        setSelectedFilters(prev => {
            const current = prev[facetName] || []
            const isSelected = current.includes(value)
            return {
                ...prev,
                [facetName]: isSelected
                    ? current.filter(v => v !== value)
                    : [...current, value]
            }
        })
    }

    const clearFilters = () => {
        setSelectedFilters({})
    }

    const totalSelectedFilters = Object.entries(selectedFilters).reduce((acc, [key, arr]) => {
        if (viewMode === "mine" && key === "created_by") {
            return acc
        }
        return acc + arr.length
    }, 0)

    const formatDateTime = (dateString: string): string => {
        const date = new Date(dateString)
        return date.toLocaleString("en-US", {
            year: "numeric",
            month: "short",
            day: "numeric",
            hour: "2-digit",
            minute: "2-digit"
        })
    }

    const handleCollectionClick = (collectionId: string) => {
        navigate(`/agents/executions/${collectionId}`)
    }

    if (sessionLoading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
        )
    }

    if (!EXECUTION_CONTAINER) {
        return (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
                <FolderOpen className="h-12 w-12" />
                <p>{t("executions:containerTypeNotConfigured")}</p>
            </div>
        )
    }

    return (
        <div className="flex flex-col w-full h-full gap-6 p-2">
            <div className="flex flex-col gap-6 flex-shrink-0">
                <div className="flex items-center gap-2">
                    <ToggleGroup
                        type="single"
                        value={viewMode}
                        onValueChange={(value) => value && setViewMode(value as "mine" | "all")}
                        variant="outline"
                    >
                        <ToggleGroupItem value="mine" aria-label="My executions" className="hover:bg-muted/50 data-[state=on]:bg-info-background data-[state=on]:text-info">
                            <User className="h-4 w-4" />
                            <span className="mr-1">{t("executions:mine")}</span>
                        </ToggleGroupItem>
                        <ToggleGroupItem value="all" aria-label="All executions" className="hover:bg-muted/50 data-[state=on]:bg-info-background data-[state=on]:text-info">
                            <Users className="h-4 w-4" />
                            <span className="mr-1">{t("executions:all")}</span>
                        </ToggleGroupItem>
                    </ToggleGroup>
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder={t("executions:searchPlaceholder")}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10"
                        />
                    </div>
                    <div className="flex items-center border rounded-md">
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => { setDisplayMode("cards"); localStorage.setItem("executions-display-mode", "cards") }}
                            className={cn(
                                "h-8 w-8 rounded-r-none",
                                displayMode === "cards" && "bg-muted"
                            )}
                            title={t("executions:cardView")}
                        >
                            <LayoutGrid className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => { setDisplayMode("table"); localStorage.setItem("executions-display-mode", "table") }}
                            className={cn(
                                "h-8 w-8 rounded-l-none",
                                displayMode === "table" && "bg-muted"
                            )}
                            title={t("executions:tableView")}
                        >
                            <List className="h-4 w-4" />
                        </Button>
                    </div>
                    <Popover open={filterOpen} onOpenChange={setFilterOpen}>
                        <PopoverTrigger asChild>
                            <Button variant="outline" className="gap-2">
                                <ListFilter className="h-4 w-4" />
                                {t("common:actions.filters")}
                                {totalSelectedFilters > 0 && (
                                    <Badge variant="secondary" className="ml-1 px-1.5 py-0.5 text-xs">
                                        {totalSelectedFilters}
                                    </Badge>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-72 p-0" align="end">
                            <div className="flex flex-col">
                                <div className="flex items-center justify-between px-4 py-3 border-b">
                                    <span className="font-medium text-sm">{t("common:actions.filters")}</span>
                                    {totalSelectedFilters > 0 && (
                                        <Button variant="ghost" size="sm" onClick={clearFilters} className="h-auto p-1 text-xs">
                                            {t("common:actions.clearAll")}
                                        </Button>
                                    )}
                                </div>

                                {facets?.interaction && facets.interaction.length > 0 && (
                                    <Collapsible className="group border-b">
                                        <CollapsibleTrigger className="flex h-10 w-full items-center justify-between px-4 py-2 text-sm font-medium hover:bg-info-background transition-colors hover:cursor-pointer">
                                            <span>{t("executions:interaction")}</span>
                                            <ChevronRight className="h-4 w-4 transition-transform group-data-[state=open]:rotate-90" />
                                        </CollapsibleTrigger>
                                        <CollapsibleContent>
                                            <div className="flex flex-col px-4 pb-3 gap-1">
                                                {facets.interaction.map((bucket) => (
                                                    <div
                                                        key={bucket._id}
                                                        className="flex items-center justify-between rounded-md px-2 py-2 hover:bg-info-background transition-colors cursor-pointer"
                                                        onClick={() => handleFilterToggle("interaction", bucket._id)}
                                                    >
                                                        <div className="flex items-center gap-2 flex-1 min-w-0">
                                                            <Checkbox
                                                                checked={selectedFilters.interaction?.includes(bucket._id)}
                                                                onCheckedChange={() => handleFilterToggle("interaction", bucket._id)}
                                                                onClick={(e) => e.stopPropagation()}
                                                            />
                                                            <span className="text-sm truncate flex-1">{bucket._id}</span>
                                                        </div>
                                                        <Badge variant="secondary" className="text-xs ml-2 flex-shrink-0">
                                                            {bucket.count}
                                                        </Badge>
                                                    </div>
                                                ))}
                                            </div>
                                        </CollapsibleContent>
                                    </Collapsible>
                                )}

                                {!userOnly && facets?.created_by && facets.created_by.length > 0 && (
                                    <Collapsible className="group border-b last:border-b-0">
                                        <CollapsibleTrigger className="flex h-10 w-full items-center justify-between px-4 py-2 text-sm font-medium hover:bg-info-background transition-colors hover:cursor-pointer">
                                            <span>{t("executions:createdBy")}</span>
                                            <ChevronRight className="h-4 w-4 transition-transform group-data-[state=open]:rotate-90" />
                                        </CollapsibleTrigger>
                                        <CollapsibleContent>
                                            <div className="flex flex-col px-4 pb-3 gap-1">
                                                {facets.created_by.map((bucket) => (
                                                    <div
                                                        key={bucket._id}
                                                        className="flex items-center justify-between rounded-md px-2 py-2 hover:bg-info-background transition-colors cursor-pointer"
                                                        onClick={() => handleFilterToggle("created_by", bucket._id)}
                                                    >
                                                        <div className="flex items-center gap-2 flex-1 min-w-0">
                                                            <Checkbox
                                                                checked={selectedFilters.created_by?.includes(bucket._id)}
                                                                onCheckedChange={() => handleFilterToggle("created_by", bucket._id)}
                                                                onClick={(e) => e.stopPropagation()}
                                                            />
                                                            <span className="text-sm truncate flex-1">{getUserDisplayName(bucket._id, undefined)}</span>
                                                        </div>
                                                        <Badge variant="secondary" className="text-xs ml-2 flex-shrink-0">
                                                            {bucket.count}
                                                        </Badge>
                                                    </div>
                                                ))}
                                            </div>
                                        </CollapsibleContent>
                                    </Collapsible>
                                )}

                                {(!facets?.interaction?.length && (userOnly || !facets?.created_by?.length)) && (
                                    <span className="text-sm text-muted-foreground text-center py-4">{t("executions:noFiltersAvailable")}</span>
                                )}
                            </div>
                        </PopoverContent>
                    </Popover>
                </div>

                {totalSelectedFilters > 0 && (
                    <div className="flex flex-wrap items-center gap-2">
                        {selectedFilters.interaction?.map((value) => (
                            <Badge key={`interaction-${value}`} variant="secondary" className="gap-1 pr-1">
                                {value}
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-4 w-4 p-0 hover:bg-transparent"
                                    onClick={() => handleFilterToggle("interaction", value)}
                                >
                                    <X className="h-3 w-3" />
                                </Button>
                            </Badge>
                        ))}
                        {!userOnly && selectedFilters.created_by?.map((value) => (
                            <Badge key={`created_by-${value}`} variant="secondary" className="gap-1 pr-1">
                                {getUserDisplayName(value, undefined)}
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-4 w-4 p-0 hover:bg-transparent"
                                    onClick={() => handleFilterToggle("created_by", value)}
                                >
                                    <X className="h-3 w-3" />
                                </Button>
                            </Badge>
                        ))}
                    </div>
                )}
            </div>

            <div className="flex-1 min-h-0 flex flex-col pb-2">
                {error && (
                    <div className="text-destructive text-sm">
                        {t("executions:failedToLoad", { message: error.message })}
                    </div>
                )}

                {isLoading && (
                    <div className="flex items-center justify-center py-8">
                        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                    </div>
                )}

                {!isLoading && collections && collections.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-12 text-muted-foreground gap-2">
                        <FolderOpen className="h-10 w-10" />
                        <p>{t("executions:noExecutionsFound")}</p>
                    </div>
                )}

                {!isLoading && collections && collections.length > 0 && displayMode === "cards" && (
                    <div className="flex-1 min-h-0 overflow-y-auto">
                        <div className="grid gap-4 grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
                            {collections.map((collection) => (
                                <Card
                                    key={collection.id}
                                    className="h-full flex flex-col cursor-pointer hover:bg-muted/50 hover:shadow-lg hover:border-primary/50 transition-all"
                                    onClick={() => handleCollectionClick(collection.id)}
                                >
                                    <CardHeader className="pb-2 flex-1">
                                        <CardTitle className="text-base truncate">{collection.name}</CardTitle>
                                        {collection.description && (
                                            <CardDescription className="line-clamp-2">
                                                {collection.description}
                                            </CardDescription>
                                        )}
                                    </CardHeader>
                                    <CardContent className="mt-auto">
                                        <div className="flex flex-col gap-1 text-sm text-muted-foreground">
                                            <Badge>{(collection as any)?.properties?.interaction}</Badge>
                                            <div className="flex items-center gap-2">
                                                <span className="font-medium">{t("executions:createdBy")}:</span>
                                                <span className="truncate">{getUserDisplayName(collection.created_by, undefined)}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <span className="font-medium">{t("executions:createdAt")}:</span>
                                                <span>{formatDateTime(collection.created_at)}</span>
                                            </div>
                                        </div>
                                    </CardContent>
                                </Card>
                            ))}
                        </div>
                        {hasMore && (
                            <div ref={sentinelRef} className="flex items-center justify-center py-4">
                                {isLoadingMore && <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />}
                            </div>
                        )}
                    </div>
                )}

                {!isLoading && collections && collections.length > 0 && displayMode === "table" && (
                    <div className="flex-1 min-h-0 min-w-0 border rounded-md overflow-y-auto overflow-x-auto">
                        <table className="w-full caption-bottom text-sm table-fixed">
                            <TableHeader className="sticky top-0 z-10 bg-muted shadow-[inset_0_-1px_0_var(--border)]">
                                <TableRow>
                                    <TableHead>{t("executions:name")}</TableHead>
                                    <TableHead className="hidden md:table-cell">{t("executions:description")}</TableHead>
                                    <TableHead>{t("executions:interaction")}</TableHead>
                                    <TableHead>{t("executions:createdBy")}</TableHead>
                                    <TableHead>{t("executions:createdAt")}</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {collections.map((collection) => (
                                    <TableRow
                                        key={collection.id}
                                        className="cursor-pointer"
                                        onClick={() => handleCollectionClick(collection.id)}
                                    >
                                        <TableCell className="font-medium truncate max-w-[200px]">
                                            {collection.name}
                                        </TableCell>
                                        <TableCell className="hidden md:table-cell truncate max-w-[300px] text-muted-foreground">
                                            {collection.description || "—"}
                                        </TableCell>
                                        <TableCell>
                                            <Badge>{(collection as any)?.properties?.interaction}</Badge>
                                        </TableCell>
                                        <TableCell className="truncate max-w-[150px]">
                                            {getUserDisplayName(collection.created_by, undefined)}
                                        </TableCell>
                                        <TableCell className="text-muted-foreground whitespace-nowrap">
                                            {formatDateTime(collection.created_at)}
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </table>
                        {hasMore && (
                            <div ref={sentinelRef} className="flex items-center justify-center py-4">
                                {isLoadingMore && <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    )
}
