import { ReactNode } from "react"
import { useTranslation } from "react-i18next"
import { StepType } from "@/features/agents/utils/stepAnalyzer"

interface AgentPanelHeaderPanelProps {
    stepType: StepType
    stepLabel?: string
    children?: ReactNode
}
export function AgentPanelHeaderPanel({ stepType, stepLabel, children }: Readonly<AgentPanelHeaderPanelProps>) {
    const { t } = useTranslation("agents")

    const getTitle = () => {
        switch (stepType) {
            case "details":
                return t("steps.executionDetails")
            case "document":
                return t("steps.selectDocument")
            case "documents":
                return t("steps.selectDocuments")
            case "media":
                return t("steps.uploadMedia")
            case "medias":
                return t("steps.uploadMediaFiles")
            case "object":
                return t("steps.selectObject")
            case "objects":
                return t("steps.selectObjects")
            case "parameters":
                return t("steps.configureParameters")
            case "summary":
                return t("steps.reviewExecute")
            case "done":
                return t("steps.executionComplete")
            default:
                return stepLabel || ""
        }
    }

    const getDescription = () => {
        switch (stepType) {
            case "details":
                return t("steps.executionDetailsDescription")
            case "document":
                return t("steps.selectDocumentDescription")
            case "documents":
                return t("steps.selectDocumentsDescription")
            case "media":
                return t("steps.uploadMediaDescription")
            case "medias":
                return t("steps.uploadMediaDescription")
            case "object":
                return t("steps.selectObjectDescription")
            case "objects":
                return t("steps.selectObjectsDescription")
            case "parameters":
                return t("steps.configureParametersDescription")
            case "summary":
                return t("steps.reviewExecuteDescription")
            case "done":
                return t("steps.executionCompleteDescription")
            default:
                return ""
        }
    }

    return (
        <div className="p-4 border-b flex flex-row justify-between items-center">
            <div className="flex flex-col gap-1">
                <h2 className="text-xl font-semibold">{getTitle()}</h2>
                <p className="text-sm text-muted-foreground">{getDescription()}</p>
            </div>
            {children && <div className="flex items-center gap-2">{children}</div>}
        </div>
    )
}
