import { useMemo } from "react"
import { InteractionRef } from "@vertesia/common"
import { useNavigate } from "@vertesia/ui/router"
import { icons, Bot } from "lucide-react"
import { InteractionTags } from "@/components/cards/InteractionTags"
import { Badge } from "@/components/ui/badge"
import { Card, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"

function parseDescriptionIcon(description: string | undefined): { iconName: string | null; cleanDescription: string } {
    if (!description) {
        return { iconName: null, cleanDescription: "No description available" }
    }

    const iconPattern = /^\[icon:([A-Za-z0-9]+)\]\s*/
    const match = description.match(iconPattern)

    if (match) {
        return {
            iconName: match[1],
            cleanDescription: description.replace(iconPattern, "").trimStart()
        }
    }

    return { iconName: null, cleanDescription: description }
}

interface InteractionCardProps {
    interaction: InteractionRef
    showTags?: boolean
}
export function InteractionCard({ interaction, showTags = false }: Readonly<InteractionCardProps>) {
    const navigate = useNavigate()

    const { iconName, cleanDescription } = useMemo(() => {
        return parseDescriptionIcon(interaction?.description)
    }, [interaction?.description])

    const IconComponent = useMemo(() => {
        if (iconName && iconName in icons) {
            return icons[iconName as keyof typeof icons]
        }
        return Bot
    }, [iconName])

    return (
        <Card className="h-48 hover:shadow-lg hover:bg-muted/50 transition-all cursor-pointer hover:border-primary/50" onClick={() => navigate(`/agents/${interaction.id}`)}>
            <CardHeader className="h-full">
                <div className="flex items-center gap-3 mb-2">
                    <IconComponent className="size-6 text-primary flex-shrink-0" />
                    <CardTitle className="text-xl truncate">{interaction.name}</CardTitle>
                    <Badge variant="outline" className="text-xs p-1 flex-shrink-0">
                        v{interaction.version}
                    </Badge>
                </div>
                <CardDescription className="text-base line-clamp-3">{cleanDescription}</CardDescription>
                {
                    (showTags && interaction.tags && interaction.tags.length > 0) && (
                        <InteractionTags tags={interaction.tags} />
                    )
                }
            </CardHeader>
        </Card>
    )
}
