import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"

interface SearchWeightsSectionProps {
    settings: Record<string, any> | undefined
    onSave: (weights: { enable: boolean; text: number; images: number; properties: number }) => void
    loading?: boolean
}
export function SearchWeightsSection({ settings, onSave, loading }: Readonly<SearchWeightsSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [enable, setEnable] = useState(settings?.ENABLE ?? false)
    const [weights, setWeights] = useState({
        text: settings?.TEXT ?? 33,
        images: settings?.IMAGES ?? 33,
        properties: settings?.PROPERTIES ?? 33,
    })

    const handleWeightChange = (field: keyof typeof weights, value: string) => {
        const parsed = value === "" ? 0 : parseInt(value, 10)
        if (!isNaN(parsed)) {
            setWeights((prev) => ({ ...prev, [field]: parsed }))
        }
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:searchWeights.title")}</CardTitle>
                <CardDescription>
                    {t("settings:searchWeights.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex items-center justify-between">
                    <div className="flex flex-col gap-1">
                        <Label htmlFor="weight-enable">{t("settings:searchWeights.enableWeightedSearch")}</Label>
                        <p className="text-sm text-muted-foreground">
                            {t("settings:searchWeights.enableWeightedSearchHelp")}
                        </p>
                    </div>
                    <Switch id="weight-enable" checked={enable} onCheckedChange={setEnable} />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="weight-text">{t("settings:searchWeights.text")}</Label>
                        <Input
                            id="weight-text"
                            type="number"
                            min={0}
                            value={weights.text}
                            disabled={!enable}
                            onChange={(e) => handleWeightChange("text", e.target.value)}
                        />
                    </div>
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="weight-images">{t("settings:searchWeights.images")}</Label>
                        <Input
                            id="weight-images"
                            type="number"
                            min={0}
                            value={weights.images}
                            disabled={!enable}
                            onChange={(e) => handleWeightChange("images", e.target.value)}
                        />
                    </div>
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="weight-properties">{t("settings:searchWeights.properties")}</Label>
                        <Input
                            id="weight-properties"
                            type="number"
                            min={0}
                            value={weights.properties}
                            disabled={!enable}
                            onChange={(e) => handleWeightChange("properties", e.target.value)}
                        />
                    </div>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ enable, ...weights })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
