import { useEffect, useRef, useState } from "react"
import { Check } from "lucide-react"
import { DynamicStep } from "@/features/agents/utils/stepAnalyzer"
import { cn } from "@/lib/utils"

type DisplayMode = "all" | "prev-current-next-last" | "first-current-last" | "current-only"

interface AgentCreationHeaderPanelProps {
    steps: DynamicStep[]
    currentStepId: string
    isExecuting: boolean
}
export function AgentCreationHeaderPanel({ steps, currentStepId, isExecuting }: Readonly<AgentCreationHeaderPanelProps>) {
    const containerRef = useRef<HTMLDivElement>(null)
    const [displayMode, setDisplayMode] = useState<DisplayMode>("all")

    // Filter out the "done" step from display
    const displaySteps = steps.filter((step) => step.type !== "done")
    const currentIndex = displaySteps.findIndex((step) => step.id === currentStepId)

    useEffect(() => {
        const updateDisplayMode = () => {
            if (!containerRef.current) return

            const containerWidth = containerRef.current.offsetWidth
            const stepCount = displaySteps.length

            // Approximate space needed per step (circle + label + connector)
            const spacePerStep = 150 // 40px circle + 96px connector + some padding
            const totalSpaceNeeded = stepCount * spacePerStep

            if (totalSpaceNeeded <= containerWidth) {
                setDisplayMode("all")
            } else if (spacePerStep * 4 + 100 <= containerWidth) {
                // Space for prev, current, next, last + ellipsis
                setDisplayMode("prev-current-next-last")
            } else if (spacePerStep * 3 + 100 <= containerWidth) {
                // Space for first, current, last + ellipsis
                setDisplayMode("first-current-last")
            } else {
                setDisplayMode("current-only")
            }
        }

        updateDisplayMode()
        window.addEventListener("resize", updateDisplayMode)
        return () => window.removeEventListener("resize", updateDisplayMode)
    }, [displaySteps.length])

    const getVisibleSteps = (): DynamicStep[] => {
        if (displayMode === "all") {
            return displaySteps
        }

        if (displayMode === "current-only") {
            return [displaySteps[currentIndex]]
        }

        const result: DynamicStep[] = []

        if (displayMode === "prev-current-next-last") {
            // Always try to show 4 consecutive steps
            const targetCount = 4
            const totalSteps = displaySteps.length

            // Calculate the window of steps to show
            let startIndex = currentIndex - 1 // Start with prev
            let endIndex = currentIndex + 2 // Try to show current + next + one more

            // Adjust if we're near the end - shift window left
            if (endIndex >= totalSteps) {
                const overflow = endIndex - totalSteps + 1
                startIndex = Math.max(0, startIndex - overflow)
                endIndex = totalSteps - 1
            }

            // Adjust if we're near the start - ensure we show targetCount steps
            if (startIndex < 0) {
                startIndex = 0
                endIndex = Math.min(totalSteps - 1, startIndex + targetCount - 1)
            }

            // Fill the result with the consecutive steps
            for (let i = startIndex; i <= endIndex; i++) {
                result.push(displaySteps[i])
            }

            return result
        }

        // first-current-last mode - always show 3 consecutive steps
        const targetCount = 3
        const totalSteps = displaySteps.length

        // Calculate the window centered on current
        let startIndex = Math.max(0, currentIndex - 1)
        const endIndex = Math.min(totalSteps - 1, startIndex + targetCount - 1)

        // Adjust if we don't have enough steps on the right
        if (endIndex - startIndex + 1 < targetCount) {
            startIndex = Math.max(0, endIndex - targetCount + 1)
        }

        // Fill the result with consecutive steps
        for (let i = startIndex; i <= endIndex; i++) {
            result.push(displaySteps[i])
        }

        return result
    }

    const visibleSteps = getVisibleSteps()

    const getStepStatus = (step: DynamicStep) => {
        const stepIndex = displaySteps.findIndex((s) => s.id === step.id)
        return {
            isCompleted: stepIndex < currentIndex,
            isCurrent: stepIndex === currentIndex,
        }
    }

    return (
        <div ref={containerRef} className="flex items-start justify-center w-full">
            {visibleSteps.map((item, index) => {
                const step = item as DynamicStep
                const { isCompleted, isCurrent } = getStepStatus(step)
                const stepIndex = displaySteps.findIndex((s) => s.id === step.id)

                return (
                    <div key={step.id} className="flex items-center">
                        {/* Step column: circle on top, label below */}
                        <div className="flex flex-col items-center gap-2">
                            <div className={cn("flex items-center justify-center w-10 h-10 rounded-full border-2 transition-colors", (isCompleted || isExecuting) ? "bg-primary border-primary text-primary-foreground" : isCurrent ? "border-primary text-primary" : "border-border text-muted-foreground")}>
                                {
                                    (isCompleted || isExecuting) ? (
                                        <Check className="w-5 h-5" />
                                    ) : (
                                        <span className="font-semibold">{stepIndex + 1}</span>
                                    )
                                }
                            </div>
                            <span className={cn("text-sm font-medium whitespace-nowrap", isCurrent ? "text-primary" : (isCompleted || isExecuting) ? "text-foreground" : "text-muted-foreground")}>
                                {step.label}
                            </span>
                        </div>
                        {/* Connector bar (at circle level) - only if not the last visible item */}
                        {index < visibleSteps.length - 1 && (
                            <div
                                className={cn("w-24 h-0.5 mx-4 -mt-8", (isCompleted || isExecuting) ? "bg-primary" : "bg-border")}
                            />
                        )}
                    </div>
                )
            })}
        </div>
    )
}
