export function toLocaleDateTimeString(date: Date) {
    return `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`
}

/**
 * Format a date as a short relative label: "Today", "Yesterday", "N days ago"
 * for dates within the last week, falling back to the locale date string.
 *
 * TODO(i18n): the relative labels are hardcoded English (matching the prior
 * inline implementations). Move them to the i18n catalogs in a follow-up.
 */
export function formatRelativeDate(dateString: string): string {
    const date = new Date(dateString)
    const now = new Date()

    const dateDay = new Date(date.getFullYear(), date.getMonth(), date.getDate())
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
    const diffDays = Math.floor((today.getTime() - dateDay.getTime()) / 86400000)

    if (diffDays === 0) {
        return "Today"
    }
    if (diffDays === 1) {
        return "Yesterday"
    }
    if (diffDays < 7) {
        return `${diffDays} days ago`
    }
    return date.toLocaleDateString()
}
