import { useState, useEffect } from "react"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { FileSearch } from "lucide-react"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { useEcmTypesWhitelist } from "@/hooks/use-ecm-types-whitelist"
import { DocumentThumbnailWithModal } from "./DocumentThumbnailWithModal"

interface DocumentPreviewProps {
    limit?: number
}

export function DocumentPreview({ limit = 12 }: DocumentPreviewProps) {
    const { client } = useUserSession()
    const toast = useToast()
    const ecmTypesWhitelist = useEcmTypesWhitelist()
    const [documents, setDocuments] = useState<ContentObjectItem[]>([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        if (!client) {
            setLoading(false)
            return
        }

        const fetchDocuments = async () => {
            setLoading(true)
            try {
                const objects = await client.objects.list({
                    limit,
                    ...(ecmTypesWhitelist && { query: { types: ecmTypesWhitelist } })
                }) as ContentObjectItem[]

                setDocuments(objects)
            } catch (error) {
                console.error("Failed to fetch documents:", error)
                if (toast) {
                    toast({
                        status: "error",
                        title: "Failed to load documents",
                        description: "Unable to fetch document previews. Please try again."
                    })
                }
            } finally {
                setLoading(false)
            }
        }

        fetchDocuments()
    }, [client, limit, toast, ecmTypesWhitelist])

    if (loading) {
        return (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {[...Array(8)].map((_, i) => (
                    <Card key={i} className="overflow-hidden">
                        <Skeleton className="w-full aspect-square" />
                        <CardContent className="p-3">
                            <Skeleton className="h-4 w-full mb-2" />
                            <Skeleton className="h-3 w-24" />
                        </CardContent>
                    </Card>
                ))}
            </div>
        )
    }

    if (documents.length === 0) {
        return (
            <Card>
                <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                    <FileSearch className="h-16 w-16 text-muted-foreground" />
                    <div className="text-center">
                        <p className="text-lg font-medium">No documents found</p>
                        <p className="text-sm text-muted-foreground mt-1">
                            Upload your first document to see it here
                        </p>
                    </div>
                </CardContent>
            </Card>
        )
    }

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {documents.map((doc) => (
                <DocumentThumbnailWithModal key={doc.id} document={doc} showHoverInfo />
            ))}
        </div>
    )
}
