import { useTranslation } from "react-i18next"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"

interface AgentDetailsPanelProps {
    name: string
    description: string
    setName: (name: string) => void
    setDescription: (description: string) => void
}

export function AgentDetailsPanel({ name, description, setName, setDescription }: Readonly<AgentDetailsPanelProps>) {
    const { t } = useTranslation("agents")

    return (
        <div className="flex flex-col gap-4 h-full mt-4">
            <div className="space-y-2">
                <Label htmlFor="agent-name" className="flex items-center gap-1">
                    {t("execution.executionName")}
                    <span className="text-destructive">*</span>
                </Label>
                <p className="text-sm text-muted-foreground">
                    {t("execution.executionNameHelp")}
                </p>
                <Input
                    id="agent-name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder={t("execution.executionNamePlaceholder")}
                    className="w-full"
                />
            </div>
            <div className="flex flex-col gap-1 h-full ">
                <Label htmlFor="agent-description" className="flex items-center gap-1">
                    {t("execution.executionDescription")}
                    <span className="text-destructive">*</span>
                </Label>
                <p className="text-sm text-muted-foreground">
                    {t("execution.executionDescriptionHelp")}
                </p>
                <Textarea
                    id="agent-description"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder={t("execution.executionDescriptionPlaceholder")}
                    className="w-full flex-1"
                />
            </div>
        </div>
    )
}
