import { useCallback, useState } from "react"
import { useUserSession } from "@vertesia/ui/session"
import { ContentItem, ContentType } from "@/features/agents/components/DocumentMediaPanel/types"

interface UseContentUploadOptions {
    type: ContentType
    onUploadComplete?: (items: ContentItem[]) => void
}

interface UseContentUploadReturn {
    upload: (files: File[]) => Promise<ContentItem[]>
    isUploading: boolean
    progress: number
    error: Error | null
}

export function useContentUpload({
    type,
    onUploadComplete,
}: UseContentUploadOptions): UseContentUploadReturn {
    const { client } = useUserSession()
    const [isUploading, setIsUploading] = useState(false)
    const [progress, setProgress] = useState(0)
    const [error, setError] = useState<Error | null>(null)

    const upload = useCallback(
        async (files: File[]): Promise<ContentItem[]> => {
            if (!client || files.length === 0) {
                return []
            }

            setIsUploading(true)
            setProgress(0)
            setError(null)

            const uploadedItems: ContentItem[] = []

            try {
                for (let i = 0; i < files.length; i++) {
                    const file = files[i]

                    const result = await client.objects.create({ content: file })

                    const item: ContentItem = {
                        id: result.id,
                        name: result.name || file.name,
                        mimeType: file.type,
                        createdAt: new Date().toISOString(),
                        type: type === "media" ? "Media" : "Document",
                    }

                    uploadedItems.push(item)
                    setProgress(Math.round(((i + 1) / files.length) * 100))
                }

                onUploadComplete?.(uploadedItems)
                return uploadedItems
            } catch (err) {
                setError(err as Error)
                throw err
            } finally {
                setIsUploading(false)
            }
        },
        [client, type, onUploadComplete]
    )

    return {
        upload,
        isUploading,
        progress,
        error,
    }
}
