export type ColorSchemeId = keyof typeof COLOR_SCHEMES

/**
 * Module-level reference to the element that receives theme attributes
 * (data-scheme, dark/light class). In shadow DOM, this is a wrapper div
 * inside the shadow tree. Falls back to document.documentElement for
 * standalone mode.
 */
let themeRootElement: HTMLElement | null = null

export function setThemeRootElement(el: HTMLElement | null) {
    themeRootElement = el
}

export function getThemeRootElement(): HTMLElement {
    return themeRootElement || document.documentElement
}

export function applyColorScheme(scheme: ColorSchemeId) {
    const root = getThemeRootElement()
    if (scheme === "default") {
        root.removeAttribute("data-scheme")
    } else {
        root.setAttribute("data-scheme", scheme)
    }
}

export function getCurrentColorScheme(): ColorSchemeId {
    return (getThemeRootElement().getAttribute("data-scheme") as ColorSchemeId) || "default"
}
