import { useContext, useEffect, useMemo, useState } from "react"
import { useTranslation } from "react-i18next"
import { ThemeProviderContext } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { ChevronsUpDown, Computer, Globe, LayoutGrid, LogOut, Moon, Palette, Sun } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { DropdownMenu, DropdownMenuContent, DropdownMenuGroup, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { SidebarMenuButton, useSidebar } from "@/components/ui/sidebar"
import { DASHBOARD_VIEW_PREFERENCE, LANGUAGE_PREFERENCE } from "@/constants/cookies"
import { useColorScheme } from "@/hooks/use-color-scheme"
import { SUPPORTED_LANGUAGES, type SupportedLanguage } from "@/i18n"
import { getInitials, isAdmin } from "@/lib/user"
import { COLOR_SCHEMES, type ColorSchemeId } from "@/themes"

export function UserNavigation() {
    const { client, logout, user } = useUserSession()
    const { state } = useSidebar()
    const { theme, setTheme } = useContext(ThemeProviderContext)
    const { colorScheme, setColorScheme } = useColorScheme()
    const { t, i18n } = useTranslation()

    const [pictureUrl, setPictureUrl] = useState<string | null>(null)
    const [showAdminPanel, setShowAdminPanel] = useState(() => {
        return localStorage.getItem(DASHBOARD_VIEW_PREFERENCE) === "admin"
    })

    const userIsAdmin = isAdmin(user)

    const isAppsPath = useMemo(() => {
        const pathSegments = location.pathname.split("/")
        return pathSegments.length >= 2 && pathSegments[1] === "apps"
    }, [location.pathname])

    const handleLogout = () => {
        logout()
    }

    const navigateToMainApp = () => {
        window.location.href = `/apps`
    }

    useEffect(() => {
        if (!client || !user || user?.sub.includes(":")) {
            setPictureUrl(null)
            return
        }

        client.users.retrieve(user.sub)
            .then((response) => {
                setPictureUrl(response?.picture ? response.picture : null)
            })
    }, [user, client])

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild className={`hover:cursor-pointer ${state !== "collapsed" && "border"}`}>
                <SidebarMenuButton size="lg" className="data-[state=open]:bg-sidebar-accent bg-background data-[state=open]:text-sidebar-accent-foreground">
                    <Avatar className="h-8 w-8 border rounded-lg">
                        { (pictureUrl) && <AvatarImage src={pictureUrl} alt={user?.name} /> }
                        <AvatarFallback className="rounded-lg">{getInitials(user?.name)}</AvatarFallback>
                    </Avatar>
                    <div className="grid flex-1 text-left text-sm leading-tight">
                        <span className="truncate font-medium">{user?.name}</span>
                        <span className="truncate text-xs">{user?.email}</span>
                    </div>
                    <ChevronsUpDown className="ml-auto size-4" />
                </SidebarMenuButton>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="min-w-56 rounded-lg" side="top" align="start" sideOffset={4}>
                <DropdownMenuLabel className="p-0 font-normal">
                    <div className="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
                        <Avatar className="h-8 w-8 rounded-lg">
                            { (pictureUrl) && <AvatarImage src={pictureUrl} alt={user?.name} /> }
                            <AvatarFallback className="rounded-lg">{getInitials(user?.name)}</AvatarFallback>
                        </Avatar>
                        <div className="grid flex-1 text-left text-sm leading-tight">
                            <span className="truncate font-medium">{user?.name}</span>
                            <span className="truncate text-xs">{user?.email}</span>
                        </div>
                    </div>
                </DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                    <div className="flex items-center justify-between px-2 py-1.5">
                        <span className="text-sm font-light">{t("theme.label")}</span>
                        <div className="flex gap-1 rounded-md border p-0.5">
                            <button
                                onClick={() => setTheme("light")}
                                className={`p-1.5 hover:cursor-pointer rounded transition-colors ${theme === "light" ? "bg-primary text-primary-foreground" : "hover:bg-accent"}`}
                                title={t("theme.light")}
                            >
                                <Sun className="h-4 w-4" />
                            </button>
                            <button
                                onClick={() => setTheme("dark")}
                                className={`p-1.5 hover:cursor-pointer rounded transition-colors ${theme === "dark" ? "bg-primary text-primary-foreground" : "hover:bg-accent"}`}
                                title={t("theme.dark")}
                            >
                                <Moon className="h-4 w-4" />
                            </button>
                            <button
                                onClick={() => setTheme("system")}
                                className={`p-1.5 hover:cursor-pointer rounded transition-colors ${theme === "system" ? "bg-primary text-primary-foreground" : "hover:bg-accent"}`}
                                title={t("theme.system")}
                            >
                                <Computer className="h-4 w-4" />
                            </button>
                        </div>
                    </div>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                    <div className="flex items-center justify-between px-2 py-1.5 gap-2">
                        <span className="text-sm font-light">{t("colorScheme.label")}</span>
                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <button className="flex items-center gap-1.5 rounded-md border px-2 py-1.5 text-xs hover:cursor-pointer hover:bg-accent transition-colors">
                                    <Palette className="h-3.5 w-3.5" />
                                    {t(COLOR_SCHEMES[colorScheme].labelKey)}
                                </button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                                {(Object.entries(COLOR_SCHEMES) as [ColorSchemeId, typeof COLOR_SCHEMES[ColorSchemeId]][]).map(([id, scheme]) => (
                                    <DropdownMenuItem
                                        key={id}
                                        onClick={() => setColorScheme(id)}
                                        className={colorScheme === id ? "bg-accent" : ""}
                                    >
                                        <span
                                            className="h-3 w-3 shrink-0 rounded-full border"
                                            style={{ backgroundColor: scheme.swatch }}
                                        />
                                        {t(scheme.labelKey)}
                                    </DropdownMenuItem>
                                ))}
                            </DropdownMenuContent>
                        </DropdownMenu>
                    </div>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                    <div className="flex items-center justify-between px-2 py-1.5">
                        <span className="text-sm font-light">{t("language.label")}</span>
                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <button className="flex items-center gap-1.5 rounded-md border px-2 py-1.5 text-xs hover:cursor-pointer hover:bg-accent transition-colors">
                                    <Globe className="h-3.5 w-3.5" />
                                    {SUPPORTED_LANGUAGES[i18n.language as SupportedLanguage] || SUPPORTED_LANGUAGES.en}
                                </button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                                {Object.entries(SUPPORTED_LANGUAGES).map(([code, name]) => (
                                    <DropdownMenuItem
                                        key={code}
                                        onClick={() => {
                                            i18n.changeLanguage(code)
                                            localStorage.setItem(LANGUAGE_PREFERENCE, code)
                                        }}
                                        className={i18n.language === code ? "bg-accent" : ""}
                                    >
                                        {name}
                                    </DropdownMenuItem>
                                ))}
                            </DropdownMenuContent>
                        </DropdownMenu>
                    </div>
                </DropdownMenuGroup>
                {
                    (userIsAdmin) && (
                        <>
                            <DropdownMenuSeparator />
                            <DropdownMenuGroup>
                                <div className="flex items-center justify-between px-2 py-1.5 gap-2">
                                    <span className="text-sm font-light">{t("dashboardView.label")}</span>
                                    <div className="flex gap-1 rounded-md border p-0.5">
                                        <button
                                            onClick={() => {
                                                setShowAdminPanel(false)
                                                localStorage.setItem(DASHBOARD_VIEW_PREFERENCE, "user")
                                                window.location.reload()
                                            }}
                                            className={`px-3 py-1.5 hover:cursor-pointer rounded transition-colors text-xs ${!showAdminPanel ? "bg-primary text-primary-foreground" : "hover:bg-accent"}`}
                                            title={t("dashboardView.user")}
                                        >
                                            {t("dashboardView.user")}
                                        </button>
                                        <button
                                            onClick={() => {
                                                setShowAdminPanel(true)
                                                localStorage.setItem(DASHBOARD_VIEW_PREFERENCE, "admin")
                                                window.location.reload()
                                            }}
                                            className={`px-3 py-1.5 hover:cursor-pointer rounded transition-colors text-xs ${showAdminPanel ? "bg-primary text-primary-foreground" : "hover:bg-accent"}`}
                                            title={t("dashboardView.admin")}
                                        >
                                            {t("dashboardView.admin")}
                                        </button>
                                    </div>
                                </div>
                            </DropdownMenuGroup>
                        </>
                    )
                }
                {
                    (isAppsPath) && (
                        <>
                            <DropdownMenuSeparator />
                            <DropdownMenuGroup>
                                <DropdownMenuItem onClick={navigateToMainApp}>
                                    <LayoutGrid className="p-0.5" />
                                    <div className="text-sm font-light text-left">{t("appPortal")}</div>
                                </DropdownMenuItem>
                            </DropdownMenuGroup>
                        </>
                    )
                }
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleLogout}>
                    <LogOut />
                    {t("actions.logOut")}
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    )
}