import { useEffect, useState } from "react"
import { ToastFn } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { retrieveRenditionById } from "@/lib/rendition"

const noopToast = (() => {}) as unknown as ToastFn

export function useRenditionUrl(objectId: string | undefined, size: number = 128) {
    const { client } = useUserSession()
    const [url, setUrl] = useState("")

    useEffect(() => {
        if (client && objectId) {
            retrieveRenditionById(client, objectId, setUrl, () => {}, noopToast, size)
        } else {
            setUrl("")
        }
    }, [client, objectId, size])

    return url
}
