import { CollectionItem, ContentObjectItem } from "@vertesia/common"
import { FileText, FolderOpen, Plus } from "lucide-react"
import { CommandItem } from "@/components/ui/command"

interface MemberSearchItemProps {
    item: ContentObjectItem | CollectionItem
    type: "document" | "collection"
    onSelect: (item: ContentObjectItem | CollectionItem) => void
}

export function MemberSearchItem({ item, type, onSelect }: MemberSearchItemProps) {
    const name = (item as ContentObjectItem).name || (item as CollectionItem).name || item.id

    return (
        <CommandItem
            value={item.id}
            onSelect={() => onSelect(item)}
            className="flex items-center justify-between"
        >
            <div className="flex items-center gap-2 min-w-0 flex-1">
                {type === "document" ? (
                    <FileText className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                ) : (
                    <FolderOpen className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                )}
                <span className="truncate">{name}</span>
            </div>
            <Plus className="h-4 w-4 text-muted-foreground flex-shrink-0" />
        </CommandItem>
    )
}
