import { useEffect, useRef } from "react"
import { ContentObjectItem } from "@vertesia/common"
import { useAppInstallation } from "@vertesia/ui/shell"
import { FileSearch, Loader2 } from "lucide-react"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { DEFAULT_LIBRARY_GRID_COLS, DEFAULT_LIBRARY_ADVANCED_GRID_COLS } from "@/features/settings/LibrarySection"
import { DocumentThumbnailWithModal } from "./DocumentThumbnailWithModal"

interface LibraryGridProps {
    documents: ContentObjectItem[]
    loading?: boolean
    loadingMore?: boolean
    hasMore?: boolean
    loadMore?: () => void
    isAdvancedSearch?: boolean
    selectedIds?: Set<string>
    onToggleSelection?: (id: string) => void
}
export function LibraryGrid({ documents, loading, loadingMore, hasMore, loadMore, isAdvancedSearch = false, selectedIds, onToggleSelection }: LibraryGridProps) {
    const selectionEnabled = !!onToggleSelection
    const gridContainerRef = useRef<HTMLDivElement>(null)
    const loadMoreRef = useRef<HTMLDivElement>(null)
    const appInstallation = useAppInstallation()
    const s = appInstallation?.settings

    const gridCols = {
        sm: Number(s?.LIBRARY_GRID_COLS_SM) || DEFAULT_LIBRARY_GRID_COLS.sm,
        md: Number(s?.LIBRARY_GRID_COLS_MD) || DEFAULT_LIBRARY_GRID_COLS.md,
        lg: Number(s?.LIBRARY_GRID_COLS_LG) || DEFAULT_LIBRARY_GRID_COLS.lg,
        xl: Number(s?.LIBRARY_GRID_COLS_XL) || DEFAULT_LIBRARY_GRID_COLS.xl,
    }
    const advGridCols = {
        sm: Number(s?.LIBRARY_ADVANCED_GRID_COLS_SM) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.sm,
        md: Number(s?.LIBRARY_ADVANCED_GRID_COLS_MD) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.md,
        lg: Number(s?.LIBRARY_ADVANCED_GRID_COLS_LG) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.lg,
        xl: Number(s?.LIBRARY_ADVANCED_GRID_COLS_XL) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.xl,
    }
    const cols = isAdvancedSearch ? advGridCols : gridCols

    const handleScroll = () => {
        if (!gridContainerRef.current || loading || loadingMore || !hasMore || !loadMore) {
            return
        }

        const { scrollTop, scrollHeight, clientHeight } = gridContainerRef.current
        const diff = scrollHeight - scrollTop - clientHeight

        if (diff < 100) {
            loadMore()
        }
    }

    useEffect(() => {
        const gridContainer = gridContainerRef.current
        if (gridContainer) {
            gridContainer.addEventListener("scroll", handleScroll)

            return () => {
                gridContainer.removeEventListener("scroll", handleScroll)
            }
        }
    }, [loading, loadingMore, hasMore])
    return (
        <div
            ref={gridContainerRef}
            className="flex flex-col h-full w-full overflow-auto"
            style={{
                "--grid-sm": cols.sm,
                "--grid-md": cols.md,
                "--grid-lg": cols.lg,
                "--grid-xl": cols.xl,
            } as React.CSSProperties}
        >
            <style>{`
                @media (min-width: 640px) { .library-grid { grid-template-columns: repeat(var(--grid-sm), minmax(0, 1fr)) !important; } }
                @media (min-width: 768px) { .library-grid { grid-template-columns: repeat(var(--grid-md), minmax(0, 1fr)) !important; } }
                @media (min-width: 1024px) { .library-grid { grid-template-columns: repeat(var(--grid-lg), minmax(0, 1fr)) !important; } }
                @media (min-width: 1280px) { .library-grid { grid-template-columns: repeat(var(--grid-xl), minmax(0, 1fr)) !important; } }
            `}</style>
            <div className="library-grid grid grid-cols-1 gap-2">
                {loading && documents.length === 0 ? (
                    [...Array(20)].map((_, i) => (
                        <Card key={i} className="overflow-hidden rounded-sm">
                            <Skeleton className="w-full aspect-square rounded-none" />
                            <CardContent className="p-3">
                                <Skeleton className="h-4 w-full mb-2" />
                                <Skeleton className="h-3 w-24" />
                            </CardContent>
                        </Card>
                    ))
                ) : documents.length === 0 ? (
                    <div className="col-span-full">
                        <Card>
                            <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                                <FileSearch className="h-16 w-16 text-muted-foreground" />
                                <div className="text-center">
                                    <p className="text-lg font-medium">No documents found</p>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        Try adjusting your filters or search terms
                                    </p>
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                ) : (
                    documents.map((doc) => (
                        <DocumentThumbnailWithModal
                            key={doc.id}
                            document={doc}
                            showDetails
                            selected={selectedIds?.has(doc.id)}
                            onToggleSelection={onToggleSelection ? () => onToggleSelection(doc.id) : undefined}
                            selectionEnabled={selectionEnabled}
                        />
                    ))
                )}
            </div>

            {(loadingMore || loading) && documents.length > 0 && (
                <div className="w-full flex justify-center items-center p-4">
                    <Loader2 className="h-6 w-6 animate-spin text-primary" />
                </div>
            )}

            {hasMore && loadMore && !loadingMore && documents.length > 0 && (
                <div ref={loadMoreRef} className="h-4" />
            )}
        </div>
    )
}
