import { useEffect, useRef } from "react"
import DocViewer, { DocViewerRenderers } from "react-doc-viewer"

interface SpreadsheetDisplayProps {
    uri: string
}
export function SpreadsheetDisplay({ uri }: Readonly<SpreadsheetDisplayProps>) {
    const containerRef = useRef<HTMLDivElement>(null)
    const documents = [{ uri }]

    useEffect(() => {
        const triggerResize = () => {
            window.dispatchEvent(new Event("resize"))
        }

        const timeout = setTimeout(triggerResize, 100)

        return () => clearTimeout(timeout)
    }, [uri])

    useEffect(() => {
        if (!containerRef.current) return

        const resizeObserver = new ResizeObserver(() => {
            window.dispatchEvent(new Event("resize"))
        })

        resizeObserver.observe(containerRef.current)

        return () => {
            resizeObserver.disconnect()
        }
    }, [])

    return (
        <>
            <style>
                {`
                    .doc-viewer-container {
                        flex: 1;
                        height: 100%;
                        width: 100%;
                        display: flex !important;
                        flex-direction: column !important;
                    }
                    .doc-viewer-container #react-doc-viewer,
                    .doc-viewer-container #proxy-renderer,
                    .doc-viewer-container #msdoc-renderer,
                    .doc-viewer-container #msdoc-iframe,
                    .doc-viewer-container .sc-dtInlm,
                    .doc-viewer-container .sc-jXbUNg,
                    .doc-viewer-container .sc-dLMFU,
                    .doc-viewer-container .sc-eDPEul {
                        height: 100% !important;
                        width: 100% !important;
                        box-sizing: border-box !important;
                        flex: 1 !important;
                    }
                    .doc-viewer-container #msdoc-iframe {
                        border: none !important;
                    }
                `}
            </style>
            <div ref={containerRef} className="doc-viewer-container">
                <DocViewer
                    documents={documents}
                    pluginRenderers={DocViewerRenderers}
                    config={{
                        header: {
                            disableHeader: true,
                            disableFileName: true,
                            retainURLParams: true
                        }
                    }}
                    style={{ width: "100%", height: "100%", flex: 1 }}
                />
            </div>
        </>
    )
}