import { FileText, Upload, Edit, Trash2, Eye } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { ActivityRecord } from "@/models/dashboard"

interface ActivityItemProps {
    activity: ActivityRecord
}

export function ActivityItem({ activity }: ActivityItemProps) {
    const formatTimestamp = (timestamp: string) => {
        const date = new Date(timestamp)
        const now = new Date()
        const diffMs = now.getTime() - date.getTime()
        const diffMins = Math.floor(diffMs / 60000)
        const diffHours = Math.floor(diffMs / 3600000)
        const diffDays = Math.floor(diffMs / 86400000)

        if (diffMins < 1) return "Just now"
        if (diffMins < 60) return `${diffMins}m ago`
        if (diffHours < 24) return `${diffHours}h ago`
        if (diffDays < 7) return `${diffDays}d ago`
        return date.toLocaleDateString()
    }

    const formatFileSize = (bytes?: number) => {
        if (!bytes) return ""
        if (bytes < 1024) return `${bytes} B`
        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
        if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
        return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`
    }

    const getActionIcon = () => {
        switch (activity.action) {
            case "upload":
                return <Upload className="h-4 w-4" />
            case "edit":
                return <Edit className="h-4 w-4" />
            case "delete":
                return <Trash2 className="h-4 w-4" />
            case "view":
                return <Eye className="h-4 w-4" />
            default:
                return <FileText className="h-4 w-4" />
        }
    }

    const getActionBadgeVariant = () => {
        switch (activity.action) {
            case "upload":
                return "default"
            case "edit":
                return "secondary"
            case "delete":
                return "destructive"
            default:
                return "outline"
        }
    }

    const getInitials = (name?: string) => {
        if (!name) return "U"
        return name.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2)
    }

    return (
        <div className="flex flex-row items-center gap-4 py-3">
            <Avatar className="h-9 w-9">
                {activity.userAvatar && <AvatarImage src={activity.userAvatar} alt={activity.userName} />}
                <AvatarFallback>{getInitials(activity.userName)}</AvatarFallback>
            </Avatar>
            <div className="flex flex-col gap-1 flex-1 min-w-0">
                <div className="flex flex-row items-center gap-2">
                    <p className="text-sm font-medium truncate">{activity.documentName}</p>
                    <Badge variant={getActionBadgeVariant() as any} className="flex flex-row items-center gap-1">
                        {getActionIcon()}
                        <span className="capitalize">{activity.action}</span>
                    </Badge>
                </div>
                <div className="flex flex-row items-center gap-2 text-xs text-muted-foreground">
                    {activity.userName && <span>{activity.userName}</span>}
                    {activity.userName && <span>•</span>}
                    <span>{formatTimestamp(activity.timestamp)}</span>
                    {activity.fileSize && (
                        <>
                            <span>•</span>
                            <span>{formatFileSize(activity.fileSize)}</span>
                        </>
                    )}
                </div>
            </div>
        </div>
    )
}
