import { useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"

interface DeleteDocumentModalProps {
    document: ContentObjectItem
    open: boolean
    setOpen: (open: boolean) => void
    onDelete: () => void
}
export function DeleteDocumentModal({ document, open, setOpen, onDelete }: Readonly<DeleteDocumentModalProps>) {
    const { t } = useTranslation(["library", "common"])
    const { client } = useUserSession()
    const toast = useToast()

    const [isDeleting, setIsDeleting] = useState(false)

    const deleteDocument = () => {
        setIsDeleting(true)
        client.objects
            .delete(document.id)
            .then(() => {
                toast({
                    status: "success",
                    title: t("library:document.deleteSuccess"),
                    description: t("library:document.deleteSuccessDescription"),
                    duration: 4000,
                })
                onDelete()
                setOpen(false)
            })
            .catch((error) => {
                toast({
                    status: "error",
                    title: t("library:document.deleteError"),
                    description: error.message,
                    duration: 4000,
                })
                setIsDeleting(false)
            })
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>{t("library:document.deleteTitle", { typeName: document?.type?.name ?? t("common:document") })}</DialogTitle>
                </DialogHeader>
                <p>{t("library:document.deleteConfirm", { typeName: document?.type?.name ?? t("common:document") })}</p>
                <DialogFooter>
                    <Button variant="destructive" onClick={() => setOpen(false)} disabled={isDeleting}>
                        {t("common:actions.cancel")}
                    </Button>
                    <Button variant="outline" onClick={deleteDocument} disabled={isDeleting}>
                        {isDeleting ? t("common:actions.deleting") : t("common:actions.delete")}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}
