import { useState, useEffect, useMemo, useCallback } from "react"
import { useTranslation } from "react-i18next"
import { VectorSearchQuery } from "@vertesia/common"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { FilterSection } from "@/components/filters/FilterSection"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { DocumentCardList } from "@/components/widgets/DocumentCardList"
import { LibraryFilters } from "@/components/widgets/LibraryFilters"
import { LibraryGrid } from "@/components/widgets/LibraryGrid"
import { SelectionActionBar } from "@/components/widgets/SelectionActionBar"
import { ViewModeSwitcher, ViewMode } from "@/components/widgets/ViewModeSwitcher"
import { LAST_VIEW_MODE } from "@/constants/cookies"
import { advancedSearchFilters, advancedFacets, basicFacets } from "@/constants/facets"
import { useFavorites } from "@/contexts/FavoritesContext"
import { AddToCollectionModal } from "@/features/document/modals/AddToCollectionModal"
import { useEcmTypesWhitelist } from "@/hooks/use-ecm-types-whitelist"
import { useUserCache } from "@/hooks/use-user-cache"
import { transformFacetStatusResponses, transformFacetTypeResponses, transformFacetUserResponses, transformProjectPropertiesFacetsWithFilter } from "@/lib/facet"
import { FacetResponse } from "@/models/facets"
import { SearchableProperty, BasicFilterOption, SEARCH_TYPES, FIELD_TYPES } from "@/models/search"
import { useWatchDocumentSearchResult, useWatchDocumentSearchFacets } from "@/plugins/providers/document/DocumentSearchContext"

interface SearchFilters {
    [key: string]: any
}

// The filters panel is always shown; this toggles which configured facet set it lists.
type FacetMode = "basic" | "advanced"

export function LibraryPanel() {
    const { t } = useTranslation(["library", "common"])
    const { hasMore, search, isSearching: loading, objects } = useWatchDocumentSearchResult()
    const facets = useWatchDocumentSearchFacets()
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const { getUserDisplayName } = useUserCache(client)
    const ecmTypesWhitelist = useEcmTypesWhitelist()
    const { addMany: addManyToFavorites } = useFavorites()
    const appInstallation = useAppInstallation()
    const weightsSettings = appInstallation?.settings?.WEIGHTS
    const advancedFacetSpecs: { name: string; field: string }[] = appInstallation?.settings?.ADVANCED_FACETS ?? advancedFacets
    const basicFacetSpecs: { name: string; field: string }[] = appInstallation?.settings?.BASIC_FACETS ?? basicFacets

    const [facetMode, setFacetMode] = useState<FacetMode>("basic")
    const [loadingMore, setLoadingMore] = useState(false)
    const [filters, setFilters] = useState<SearchFilters>({})
    const [debouncedSearch, setDebouncedSearch] = useState<string>("")
    const [searchableFilters, setSearchableFilters] = useState<SearchableProperty[]>(advancedSearchFilters)
    const [clearTrigger, setClearTrigger] = useState(0)
    const [autoSearch, setAutoSearch] = useState(true)
    const [scoreThreshold, setScoreThreshold] = useState(0.60)
    const [viewMode, setViewMode] = useState<ViewMode>(() => {
        const saved = localStorage.getItem(LAST_VIEW_MODE)
        return (saved === "grid" || saved === "table") ? saved : "grid"
    })

    // Selection state
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
    const [isAddToCollectionOpen, setIsAddToCollectionOpen] = useState(false)

    const handleViewModeChange = (mode: ViewMode) => {
        localStorage.setItem(LAST_VIEW_MODE, mode)
        setViewMode(mode)
    }

    // Score threshold filtering
    const isSearchActive = !!debouncedSearch.trim()

    const filteredObjects = useMemo(() => {
        if (!isSearchActive) return objects
        return objects.filter(obj => (obj.score ?? 0) >= scoreThreshold)
    }, [objects, scoreThreshold, isSearchActive])

    useEffect(() => {
        if (!debouncedSearch.trim()) {
            setScoreThreshold(0.60)
        }
    }, [debouncedSearch])

    // Selection handlers
    const toggleSelection = useCallback((id: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev)
            if (next.has(id)) {
                next.delete(id)
            } else {
                next.add(id)
            }
            return next
        })
    }, [])

    const selectAllDocuments = useCallback(() => {
        setSelectedIds(new Set(filteredObjects.map(doc => doc.id)))
    }, [filteredObjects])

    const clearSelection = useCallback(() => {
        setSelectedIds(new Set())
    }, [])

    const selectedDocuments = useMemo(() => {
        return filteredObjects.filter(doc => selectedIds.has(doc.id))
    }, [filteredObjects, selectedIds])

    const handleAddToCollection = () => {
        setIsAddToCollectionOpen(true)
    }

    const handleAddToCollectionDone = () => {
        setIsAddToCollectionOpen(false)
        clearSelection()
    }

    const handleAddToFavorites = async () => {
        await addManyToFavorites(Array.from(selectedIds))
        clearSelection()
    }

    // Debounce search query
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(filters.search || "")
        }, 300)

        return () => clearTimeout(timer)
    }, [filters.search])

    // Update advanced filters when facets change
    useEffect(() => {
        // Update system filters with facet values
        const systemFilters = advancedSearchFilters.map(filter => {
            const facetData = (facets as any)[filter.property]

            if (!facetData) {
                return { ...filter, values: [] }
            }

            let transformedValues: FacetResponse[] = []
            if (filter.property === "type") {
                transformedValues = transformFacetTypeResponses(facetData, typeRegistry)
            } else {
                transformedValues = transformFacetStatusResponses(facetData)
            }

            return { ...filter, values: transformedValues }
        })

        // Dynamically generate filters from the configured advanced facet specs (excluding system facets)
        const reservedFields = new Set([...advancedSearchFilters.map(f => f.property), "content.type", "total"])
        const dynamicPropertySpecs = advancedFacetSpecs
            .filter(spec => !reservedFields.has(spec.field) && !reservedFields.has(spec.name))
            .map(spec => ({ name: spec.name, field: spec.field, match: false }))

        const propertyFacets = transformProjectPropertiesFacetsWithFilter(facets, dynamicPropertySpecs)

        const dynamicFilters: SearchableProperty[] = propertyFacets.map(pf => {
            const label = pf.name && pf.name !== pf.field
                ? pf.name
                : pf.field
                    .replace("properties.", "")
                    .split(/[_.]/)
                    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                    .join(" ")

            return {
                id: pf.field,
                label,
                placeholder: `Filter by ${label}`,
                property: pf.field,
                type: FIELD_TYPES.LIST,
                searchType: SEARCH_TYPES.SELECTION_MULTIPLE,
                values: pf.values,
                system: false
            }
        })

        setSearchableFilters([...systemFilters, ...dynamicFilters])
    }, [facets, typeRegistry, advancedFacetSpecs])

    // Build the configurable basic filters shown in the search bar dropdown
    const basicFilters: BasicFilterOption[] = useMemo(() => {
        // The PropertySelect exposes the type as "type.id"; the search facet is "type".
        const resolveField = (field: string) => (field === "type.id" ? "type" : field)

        // These are the placeholder field-keys used by the default config, not real
        // display labels — when the admin keeps them we fall back to localized labels.
        const defaultNames = new Set(["type", "status", "created_by", "mime_type"])

        const labelFor = (spec: { name: string; field: string }): string => {
            // Respect a custom display name set by the admin in settings.
            if (spec.name && spec.name !== spec.field && !defaultNames.has(spec.name)) {
                return spec.name
            }
            switch (resolveField(spec.field)) {
                case "type": return t("common:filters.contentType")
                case "status": return t("common:filters.statuses")
                case "created_by": return t("common:properties.createdBy")
                case "content.type": return t("common:filters.mimeType")
                default:
                    return spec.field
                        .replace("properties.", "")
                        .split(/[_.]/)
                        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                        .join(" ")
            }
        }

        // The facet response may be keyed by either the spec field or its name
        // (e.g. when the facet has been renamed), so look up both.
        const rawFacet = (spec: { name: string; field: string }) =>
            (facets as any)[spec.field] ?? (facets as any)[resolveField(spec.field)] ?? (facets as any)[spec.name]

        const valuesFor = (spec: { name: string; field: string }): FacetResponse[] => {
            const field = resolveField(spec.field)
            switch (field) {
                case "type": return transformFacetTypeResponses(rawFacet(spec), typeRegistry)
                case "created_by": return transformFacetUserResponses(rawFacet(spec))
                default:
                    if (field.startsWith("properties.")) {
                        return transformProjectPropertiesFacetsWithFilter(facets, [{ name: spec.name, field: spec.field }])[0]?.values ?? []
                    }
                    return transformFacetStatusResponses(rawFacet(spec))
            }
        }

        return basicFacetSpecs.map(spec => {
            const field = resolveField(spec.field)
            return {
                id: field === "content.type" ? "mime_type" : field,
                field: spec.field,
                label: labelFor(spec),
                values: valuesFor(spec),
            }
        })
    }, [facets, typeRegistry, basicFacetSpecs, t])

    // Update search query when filters change
    const searchObjects = () => {
        const matchFilters: any = {}

        // Build match filters dynamically based on searchableFilters configuration
        searchableFilters.forEach(filter => {
            const filterValue = filters[filter.id]
            if (filterValue !== undefined) {
                // Use the property path from filter configuration
                if (filter.property.startsWith("properties.")) {
                    // For multi-select with array values, use $in operator
                    if (Array.isArray(filterValue) && filterValue.length > 0) {
                        matchFilters[filter.property] = { $in: filterValue }
                    } else if (!Array.isArray(filterValue)) {
                        matchFilters[filter.property] = filterValue
                    }
                } else if (filter.id === "created_by") {
                    if (Array.isArray(filterValue) && filterValue.length > 0) {
                        matchFilters[filter.property] = { $in: filterValue }
                    } else if (!Array.isArray(filterValue)) {
                        matchFilters[filter.property] = filterValue
                    }
                }
            }
        })

        // Include any properties.* filters not yet in searchableFilters
        // (needed for initial search with pre-set filters before facets are loaded)
        Object.keys(filters).forEach(key => {
            if (key.startsWith("properties.") && !matchFilters[key]) {
                const filterValue = filters[key]
                if (Array.isArray(filterValue) && filterValue.length > 0) {
                    matchFilters[key] = { $in: filterValue }
                } else if (filterValue && !Array.isArray(filterValue)) {
                    matchFilters[key] = filterValue
                }
            }
        })

        // Handle mime_type filter (content.type)
        const mimeTypeFilter = filters?.mime_type
        if (mimeTypeFilter) {
            matchFilters["content.type"] = mimeTypeFilter
        }

        // Handle type filter specially (already expects array format)
        const typeFilter = filters?.type
        let typesArray: string[] | undefined = undefined
        if (typeFilter) {
            typesArray = Array.isArray(typeFilter) ? typeFilter : [typeFilter]
        }

        // Apply ECM types whitelist
        if (ecmTypesWhitelist) {
            if (typesArray) {
                typesArray = typesArray.filter(t => ecmTypesWhitelist.includes(t))
            } else {
                typesArray = ecmTypesWhitelist
            }
        }

        // Handle status filter (could be single or array)
        const statusFilter = filters?.status
        let statusValue: any = undefined
        if (statusFilter) {
            statusValue = statusFilter
        }

        const query: any = {
            types: typesArray,
            status: statusValue,
            match: Object.keys(matchFilters).length > 0 ? matchFilters : undefined
        }

        // Add vector search when search query is present
        if (debouncedSearch && debouncedSearch.trim()) {
            const vector: VectorSearchQuery = {
                text: debouncedSearch,
                config: {
                    text: true,
                    image: true,
                    properties: true
                }
            }
            query.vector = vector

            if (weightsSettings?.ENABLE) {
                query.weights = {
                    text: weightsSettings.TEXT,
                    image: weightsSettings.IMAGES,
                    properties: weightsSettings.PROPERTIES,
                }
            }
        }

        search.query = query
        search.search()
    }

    const updateFilters = (newFilters: Partial<SearchFilters>) => {
        // If newFilters is empty object, clear all filters
        if (Object.keys(newFilters).length === 0) {
            setFilters({})
            return
        }

        const updatedFilters = { ...filters }

        // Update or remove filter values
        Object.keys(newFilters).forEach(key => {
            if (newFilters[key] === undefined) {
                delete updatedFilters[key]
            } else {
                updatedFilters[key] = newFilters[key]
            }
        })

        setFilters(updatedFilters)
    }

    const loadMore = () => {
        if (!loadingMore && hasMore) {
            setLoadingMore(true)
            search.loadMore().finally(() => {
                setLoadingMore(false)
            })
        }
    }

    // Create a stable reference for non-search filters
    const nonSearchFilters = useMemo(() => {
        const { search, ...rest } = filters
        return rest
    }, [JSON.stringify((() => { const { search, ...rest } = filters; return rest })())])

    // Search when debounced search changes (always auto-search for text input)
    useEffect(() => {
        if (debouncedSearch !== undefined) {
            searchObjects()
        }
    }, [debouncedSearch])

    // Search when non-search filters or facet mode change.
    // In advanced mode, only auto-search if autoSearch is enabled.
    useEffect(() => {
        const shouldAutoSearch = facetMode === "basic" || autoSearch
        if (shouldAutoSearch) {
            searchObjects()
        }
    }, [nonSearchFilters, facetMode])

    // Reset autoSearch to true when switching back to basic mode
    useEffect(() => {
        if (facetMode === "basic") {
            setAutoSearch(true)
        }
    }, [facetMode])

    // Initial search on mount
    useEffect(() => {
        searchObjects()
    }, [])

    const getFilterLabel = (filterKey: string, value: any): string => {
        // Handle boolean values
        if (typeof value === "boolean") {
            return value ? "Yes" : "No"
        }

        // Convert to string for processing
        const stringValue = String(value)

        switch (filterKey) {
            case "type":
                return typeRegistry?.getTypeName(stringValue) || stringValue
            case "status":
                return stringValue
            case "created_by":
                return getUserDisplayName(stringValue, undefined)
            default:
                return stringValue
        }
    }

    const handleClearAllFilters = () => {
        setFilters({ search: filters.search }) // Keep search term, clear everything else
        setClearTrigger(prev => prev + 1)
    }

    const handleFilterSelection = (filterId: string, value: string | string[] | undefined) => {
        updateFilters({ [filterId]: value })
    }

    const renderSearchableFilter = (filter: SearchableProperty) => {
        if (!filter.values || filter.values.length === 0) return null

        const isMultiple = filter.searchType === SEARCH_TYPES.SELECTION_MULTIPLE

        return (
            <FilterSection
                key={filter.id}
                label={filter.label}
                items={filter.values}
                selectedValue={filters[filter.id]}
                onSelection={(value) => handleFilterSelection(filter.id, value)}
                onClear={clearTrigger}
                getLabelFn={(value) => getFilterLabel(filter.id, value)}
                multiple={isMultiple}
            />
        )
    }

    // Any non-search filter active (basic single-select or advanced multi-select).
    const hasActiveFilters = Object.keys(filters).some(key => key !== "search" && filters[key] !== undefined)

    // Basic filters are single-select facets (one value per facet).
    const renderBasicFilter = (filter: BasicFilterOption) => {
        if (!filter.values || filter.values.length === 0) return null
        return (
            <FilterSection
                key={filter.id}
                label={filter.label}
                items={filter.values}
                selectedValue={filters[filter.id]}
                onSelection={(value) => handleFilterSelection(filter.id, value)}
                onClear={clearTrigger}
                getLabelFn={(value) => getFilterLabel(filter.id, value)}
                multiple={false}
            />
        )
    }

    const renderFiltersPanel = () => (
        <Card className="w-80 flex-shrink-0 flex flex-col rounded-sm">
            <div className="flex flex-col gap-3 p-4 flex-shrink-0 bg-muted/50">
                <div className="flex items-center justify-between">
                    <h2 className="text-lg font-semibold">{t("common:actions.filters")}</h2>
                    {hasActiveFilters && (
                        <Button variant="ghost" size="sm" onClick={handleClearAllFilters}>
                            {t("common:actions.clearAll")}
                        </Button>
                    )}
                </div>
                {/* Basic (default) ↔ Advanced facet-set toggle */}
                <ToggleGroup
                    type="single"
                    value={facetMode}
                    onValueChange={(v) => v && setFacetMode(v as FacetMode)}
                    variant="outline"
                    className="w-full"
                >
                    <ToggleGroupItem value="basic" className="flex-1">{t("library:basic")}</ToggleGroupItem>
                    <ToggleGroupItem value="advanced" className="flex-1">{t("library:advanced")}</ToggleGroupItem>
                </ToggleGroup>
            </div>

            <Separator className="flex-shrink-0" />

            <div className="overflow-y-auto flex-1">
                {facetMode === "basic"
                    ? basicFilters.map(renderBasicFilter)
                    : searchableFilters.map(filter => renderSearchableFilter(filter))}
            </div>

            {/* Auto-search toggle and manual search button (advanced mode only) */}
            {facetMode === "advanced" && (
                <div className="p-4 flex-shrink-0 space-y-3 border-t bg-muted/50">
                    <div className="flex items-center gap-3">
                        <Switch
                            id="auto-search"
                            checked={autoSearch}
                            onCheckedChange={setAutoSearch}
                        />
                        <Label htmlFor="auto-search" className="text-sm font-medium cursor-pointer">
                            {t("library:autoSearch")}
                        </Label>
                    </div>

                    {!autoSearch && (
                        <Button
                            onClick={searchObjects}
                            disabled={loading}
                            className="w-full"
                            size="lg"
                        >
                            {t("common:actions.search")}
                        </Button>
                    )}
                </div>
            )}
        </Card>
    )

    return (
        <div className="flex flex-col w-full h-full gap-4 p-2">
            {/* Search bar + view-mode switcher */}
            <div className="flex-shrink-0 flex gap-2">
                <div className="flex-1">
                    <LibraryFilters
                        filters={filters}
                        onFiltersChange={updateFilters}
                        onRefresh={searchObjects}
                        basicFilters={basicFilters}
                        getValueLabel={getFilterLabel}
                        isAdvancedSearch={facetMode === "advanced"}
                        scoreThreshold={scoreThreshold}
                        onScoreThresholdChange={setScoreThreshold}
                    />
                </div>
                <ViewModeSwitcher value={viewMode} onValueChange={handleViewModeChange} />
            </div>

            {/* Content Area with Grid/Card list and the always-on Filters Panel */}
            <div className="flex flex-1 gap-3 overflow-hidden">
                {/* Scrollable Grid/Table with infinite scroll */}
                <div className="flex-1 overflow-hidden">
                    {viewMode === "grid" ? (
                        <LibraryGrid
                            documents={filteredObjects}
                            loading={loading}
                            loadingMore={loadingMore}
                            hasMore={hasMore}
                            loadMore={loadMore}
                            // The filters panel is always present, so the grid always uses the
                            // reduced ("with panel") column count.
                            isAdvancedSearch={true}
                            selectedIds={selectedIds}
                            onToggleSelection={toggleSelection}
                        />
                    ) : (
                        <DocumentCardList
                            documents={filteredObjects}
                            loading={loading}
                            loadingMore={loadingMore}
                            hasMore={hasMore}
                            loadMore={loadMore}
                            selectedIds={selectedIds}
                            onToggleSelection={toggleSelection}
                            onSelectAll={selectAllDocuments}
                            onClearSelection={clearSelection}
                        />
                    )}
                </div>

                {/* Filters Panel (always visible) */}
                {renderFiltersPanel()}
            </div>

            {/* Selection Action Bar */}
            <SelectionActionBar
                selectedCount={selectedIds.size}
                onAddToCollection={handleAddToCollection}
                onAddToFavorites={handleAddToFavorites}
                onClearSelection={clearSelection}
            />

            {/* Add to Collection Modal */}
            <AddToCollectionModal
                documents={selectedDocuments}
                open={isAddToCollectionOpen}
                onOpenChange={setIsAddToCollectionOpen}
                onActionDone={handleAddToCollectionDone}
            />
        </div>
    )
}
