import { useTranslation } from "react-i18next"
import { Activity } from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { useRecentActivity } from "@/hooks/use-recent-activity"
import { ActivityItem } from "./ActivityItem"

interface ActivityFeedProps {
    limit?: number
    showHeader?: boolean
    maxHeight?: string
}

export function ActivityFeed({ limit = 10, showHeader = true, maxHeight = "266px" }: ActivityFeedProps) {
    const { t } = useTranslation("common")
    const { activities, loading } = useRecentActivity(limit)

    if (loading) {
        return (
            <Card className="w-full h-full flex flex-col" style={{ maxHeight }}>
                {showHeader && (
                    <CardHeader className="flex-shrink-0">
                        <CardTitle className="flex flex-row items-center gap-2">
                            <Activity className="h-5 w-5" />
                            {t("activityFeed.recentActivity")}
                        </CardTitle>
                    </CardHeader>
                )}
                <CardContent className="flex-1 overflow-hidden">
                    <div className="flex flex-col gap-3">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="flex flex-row items-center gap-4">
                                <Skeleton className="h-9 w-9 rounded-full" />
                                <div className="flex flex-col gap-2 flex-1">
                                    <Skeleton className="h-4 w-48" />
                                    <Skeleton className="h-3 w-32" />
                                </div>
                            </div>
                        ))}
                    </div>
                </CardContent>
            </Card>
        )
    }

    if (activities.length === 0) {
        return (
            <Card className="w-full h-full flex flex-col" style={{ maxHeight }}>
                {showHeader && (
                    <CardHeader className="flex-shrink-0">
                        <CardTitle className="flex flex-row items-center gap-2">
                            <Activity className="h-5 w-5" />
                            {t("activityFeed.recentActivity")}
                        </CardTitle>
                    </CardHeader>
                )}
                <CardContent className="flex flex-col items-center justify-center py-12 gap-2 flex-1">
                    <Activity className="h-12 w-12 text-muted-foreground" />
                    <p className="text-sm font-medium">{t("activityFeed.noActivity")}</p>
                    <p className="text-xs text-muted-foreground">{t("activityFeed.activityWillAppear")}</p>
                </CardContent>
            </Card>
        )
    }

    return (
        <Card className="w-full h-full flex flex-col" style={{ maxHeight }}>
            {showHeader && (
                <CardHeader className="flex-shrink-0">
                    <CardTitle className="flex flex-row items-center gap-2">
                        <Activity className="h-5 w-5" />
                        {t("activityFeed.recentActivity")}
                    </CardTitle>
                </CardHeader>
            )}
            <CardContent className="flex-1 overflow-hidden">
                <ScrollArea className="h-full">
                    <div className="flex flex-col">
                        {activities.map((activity, index) => (
                            <div key={activity.id}>
                                <ActivityItem activity={activity} />
                                {index < activities.length - 1 && <Separator />}
                            </div>
                        ))}
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    )
}
