import { useState, useEffect, useCallback } from "react"
import { ContentObjectItem } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"
import { RECENTLY_VIEWED_DOCUMENTS } from "@/constants/cookies"
import { SharedState, useWatchSharedState } from "@/hooks/use-shared-state"

const MAX_ENTRIES = 50

interface RecentlyViewedEntry {
    documentId: string
    viewedAt: number
    areas: string[]
}

interface UseRecentlyViewedOptions {
    areaName?: string
    limit?: number
}

// Module-level version counter — triggers re-renders across all hook instances
const recentlyViewedVersion = new SharedState(0)

function readEntries(): RecentlyViewedEntry[] {
    try {
        const raw = localStorage.getItem(RECENTLY_VIEWED_DOCUMENTS)
        return raw ? JSON.parse(raw) : []
    } catch {
        return []
    }
}

function writeEntries(entries: RecentlyViewedEntry[]) {
    try {
        localStorage.setItem(RECENTLY_VIEWED_DOCUMENTS, JSON.stringify(entries))
    } catch {
        // localStorage full or unavailable — silently degrade
    }
}

export function useRecentlyViewed(options?: UseRecentlyViewedOptions) {
    const { areaName, limit = 10 } = options ?? {}
    const { client } = useUserSession()
    const [documents, setDocuments] = useState<ContentObjectItem[]>([])
    const [loading, setLoading] = useState(true)
    const version = useWatchSharedState(recentlyViewedVersion)

    const recordView = useCallback((document: ContentObjectItem) => {
        const entries = readEntries()
        const filtered = entries.filter(e => e.documentId !== document.id)
        const newEntry: RecentlyViewedEntry = {
            documentId: document.id,
            viewedAt: Date.now(),
            areas: document.properties?.areas || [],
        }
        const updated = [newEntry, ...filtered].slice(0, MAX_ENTRIES)
        writeEntries(updated)
        recentlyViewedVersion.value = recentlyViewedVersion.value + 1
    }, [])

    useEffect(() => {
        if (!client) {
            setLoading(false)
            return
        }

        let cancelled = false

        const fetchDocuments = async () => {
            setLoading(true)
            let entries = readEntries()

            if (areaName) {
                entries = entries.filter(e => e.areas.includes(areaName))
            }

            const targetEntries = entries.slice(0, limit)

            if (targetEntries.length === 0) {
                setDocuments([])
                setLoading(false)
                return
            }

            const results = await Promise.allSettled(
                targetEntries.map(entry => client.objects.retrieve(entry.documentId))
            )

            if (cancelled) return

            const fetched: ContentObjectItem[] = []
            const idsToRemove: string[] = []

            results.forEach((result, index) => {
                if (result.status === "fulfilled" && result.value) {
                    fetched.push(result.value)
                } else {
                    idsToRemove.push(targetEntries[index].documentId)
                }
            })

            // Clean up stale entries
            if (idsToRemove.length > 0) {
                const cleanedEntries = readEntries().filter(
                    e => !idsToRemove.includes(e.documentId)
                )
                writeEntries(cleanedEntries)
            }

            setDocuments(fetched)
            setLoading(false)
        }

        fetchDocuments()

        return () => {
            cancelled = true
        }
    }, [client, areaName, limit, version])

    return { documents, loading, recordView }
}
