import { useUserSession } from "@vertesia/ui/session"
import { ApplicationLayout } from "@/components/layouts/ApplicationLayout"
import { DASHBOARD_VIEW_PREFERENCE } from "@/constants/cookies"
import { AdvancedDashboardPanel } from "@/features/dashboard/AdvancedDashboardPanel"
import { UserDashboardPanel } from "@/features/dashboard/UserDashboardPanel"
import { isAdmin } from "@/lib/user"

export function DashboardPage() {
    const { user } = useUserSession()
    const userIsAdmin = isAdmin(user)
    const dashboardPreference = localStorage.getItem(DASHBOARD_VIEW_PREFERENCE)
    const showAdminDashboard = userIsAdmin && dashboardPreference === "admin"

    return (
        <ApplicationLayout>
            {showAdminDashboard ? <AdvancedDashboardPanel /> : <UserDashboardPanel />}
        </ApplicationLayout>
    )
}
