import { useTranslation } from "react-i18next"
import { Edit } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { FieldDefinition } from "@/features/agents/utils/schemaParser"
import { PropertyValue } from "@/features/executions/components/PropertyValue"

type AgentState = "details" | "parameters" | "summary" | "done"

interface AgentSummaryPanelProps {
    name: string
    description: string
    interactionName: string
    fields: FieldDefinition[]
    formData: Record<string, any>
    onNavigate: (state: AgentState) => void
}

export function AgentSummaryPanel({
    name,
    description,
    interactionName,
    fields,
    formData,
    onNavigate,
}: Readonly<AgentSummaryPanelProps>) {
    const { t } = useTranslation(["agents", "common"])

    return (
        <div className="flex-1 overflow-y-auto space-y-4 mt-4">
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <div>
                        <CardTitle className="text-lg">{t("agents:execution.executionDetails")}</CardTitle>
                        <CardDescription>{t("agents:execution.executionDetailsDescription")}</CardDescription>
                    </div>
                    <Button variant="ghost" size="sm" onClick={() => onNavigate("details")}>
                        <Edit className="h-4 w-4" />
                    </Button>
                </CardHeader>
                <CardContent>
                    <div className="space-y-2">
                        <div>
                            <p className="text-sm font-medium text-muted-foreground">{t("common:properties.name")}</p>
                            <p className="text-sm">{name}</p>
                        </div>
                        <Separator />
                        <div>
                            <p className="text-sm font-medium text-muted-foreground">{t("common:properties.description")}</p>
                            <p className="text-sm">{description}</p>
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <div>
                        <CardTitle className="text-lg">{t("agents:execution.interactionLabel")}</CardTitle>
                        <CardDescription>{t("agents:execution.interactionDescription")}</CardDescription>
                    </div>
                </CardHeader>
                <CardContent>
                    <p className="text-sm font-medium">{interactionName}</p>
                </CardContent>
            </Card>

            {fields.length > 0 && (
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <div>
                            <CardTitle className="text-lg">{t("agents:execution.parameters")}</CardTitle>
                            <CardDescription>{t("agents:execution.parametersDescription")}</CardDescription>
                        </div>
                        <Button variant="ghost" size="sm" onClick={() => onNavigate("parameters")}>
                            <Edit className="h-4 w-4" />
                        </Button>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-3">
                            {fields.map((field, index) => (
                                <div key={field.name}>
                                    <div className="flex flex-col gap-1">
                                        <span className="text-xs font-medium text-muted-foreground">{field.label}</span>
                                        <div className="max-h-32 overflow-auto">
                                            <PropertyValue value={formData[field.name]} />
                                        </div>
                                    </div>
                                    {index < fields.length - 1 && <Separator className="mt-3" />}
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </Card>
            )}
        </div>
    )
}
