import { type ReactNode, useEffect } from "react"
import { useLocation, useNavigate } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { ApplicationSidebar } from "@/components/navigation/ApplicationSidebar"
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar"
import { Toaster } from "@/components/ui/sonner"
import { LANGUAGE_PREFERENCE, COLOR_SCHEME_PREFERENCE } from "@/constants/cookies"
import { BreadcrumbProvider } from "@/contexts/BreadcrumbContext"
import { usePreloadDashboardBackground } from "@/hooks/use-preload-dashboard-background"
import i18n from "@/i18n"
import { getSidebarStateFromCookie } from "@/lib/sidebar"
import { getHiddenSidebarUrls, isPathHidden } from "@/lib/sidebar-visibility"
import { applyColorScheme, type ColorSchemeId } from "@/themes"

interface ApplicationLayoutProps {
    children?: ReactNode | ReactNode[]
}
export function ApplicationLayout({ children }: Readonly<ApplicationLayoutProps>) {
    const { user } = useUserSession()
    const appInstallation = useAppInstallation()
    const location = useLocation()
    const navigate = useNavigate()
    usePreloadDashboardBackground()

    // Guard against direct access to items hidden from the sidebar: redirect to home.
    useEffect(() => {
        const hidden = getHiddenSidebarUrls(appInstallation?.settings)
        if (hidden.length === 0) {
            return
        }
        const appName = appInstallation?.manifest?.name
        const appPath = appName ? `/apps/${appName}` : ""
        let path = location.pathname
        if (appPath && path.startsWith(appPath)) {
            path = path.slice(appPath.length) || "/"
        }
        if (isPathHidden(path, hidden)) {
            navigate("/", { replace: true })
        }
    }, [location.pathname, appInstallation?.settings, appInstallation?.manifest?.name, navigate])

    useEffect(() => {
        const userPref = localStorage.getItem(LANGUAGE_PREFERENCE)
        const defaultLang = appInstallation?.settings?.DEFAULT_LANGUAGE as string | undefined
        if (!userPref && defaultLang) {
            i18n.changeLanguage(defaultLang)
        }
    }, [appInstallation?.settings?.DEFAULT_LANGUAGE])

    useEffect(() => {
        const userPref = localStorage.getItem(COLOR_SCHEME_PREFERENCE)
        const defaultScheme = appInstallation?.settings?.DEFAULT_COLOR_SCHEME as string | undefined
        const scheme = userPref || defaultScheme || "default"
        applyColorScheme(scheme as ColorSchemeId)
    }, [appInstallation?.settings?.DEFAULT_COLOR_SCHEME])

    return (user) ? (
        <BreadcrumbProvider>
            <div className="[var(--header-height):calc(theme(spacing.14))]" style={{ all: "initial", fontFamily: "inherit", color: "inherit" }}>
                <Toaster position="top-right" toastOptions={{ style: { zIndex: 9999 } }} />
                <SidebarProvider defaultOpen={getSidebarStateFromCookie()} className="flex flex-col">
                    <div className="flex max-h-[100vh]">
                        <ApplicationSidebar />
                        <SidebarInset className="max-h-[100vh] mr-1 min-w-0">
                            <div className="h-full w-full min-w-0 overflow-auto">{children}</div>
                        </SidebarInset>
                    </div>
                </SidebarProvider>
            </div>
        </BreadcrumbProvider>
    ) : (
        <main className="flex-1 overflow-hidden">{children}</main>
    )
}
