const DEFAULTS = {
    DASHBOARD_BACKGROUND_POSITION_X: 50,
    DASHBOARD_BACKGROUND_POSITION_Y: 50,
    DASHBOARD_BACKGROUND_ZOOM: 100,
    DASHBOARD_BANNER_RENDITION_SIZE: 2048,
    DASHBOARD_BANNER_MAX_HEIGHT: 160,
    DASHBOARD_BANNER_MIN_HEIGHT: 64,
} as const

type DashboardNumericKey = keyof typeof DEFAULTS

function parseNumericSetting(settings: Record<string, any> | undefined, key: DashboardNumericKey): number {
    const value = settings?.[key]
    if (value == null) return DEFAULTS[key]
    const parsed = Number(value)
    return isNaN(parsed) ? DEFAULTS[key] : parsed
}

export function getDashboardBackgroundSettings(settings: Record<string, any> | undefined) {
    return {
        positionX: parseNumericSetting(settings, "DASHBOARD_BACKGROUND_POSITION_X"),
        positionY: parseNumericSetting(settings, "DASHBOARD_BACKGROUND_POSITION_Y"),
        zoom: parseNumericSetting(settings, "DASHBOARD_BACKGROUND_ZOOM"),
        renditionSize: parseNumericSetting(settings, "DASHBOARD_BANNER_RENDITION_SIZE"),
        bannerMaxHeight: parseNumericSetting(settings, "DASHBOARD_BANNER_MAX_HEIGHT"),
        bannerMinHeight: parseNumericSetting(settings, "DASHBOARD_BANNER_MIN_HEIGHT"),
    }
}

/** What the dashboard renders as its main content. */
export type DashboardDisplayMode = "imageGrid" | "recentlyViewed"

export const DASHBOARD_DISPLAY_MODES: DashboardDisplayMode[] = ["imageGrid", "recentlyViewed"]

/**
 * Resolves the dashboard display mode from settings, falling back to the legacy
 * ENABLE_DASHBOARD_RECENTLY_VIEWED_LIST boolean for installations saved before
 * the selector was introduced.
 */
export function getDashboardDisplayMode(settings: Record<string, any> | undefined): DashboardDisplayMode {
    const mode = settings?.DASHBOARD_DISPLAY_MODE
    if (mode === "imageGrid" || mode === "recentlyViewed") {
        return mode
    }
    const legacyRecentlyViewed = String(settings?.ENABLE_DASHBOARD_RECENTLY_VIEWED_LIST).toLowerCase() === "true"
    return legacyRecentlyViewed ? "recentlyViewed" : "imageGrid"
}
