import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { AgentMessageType, Collection, WorkflowRunWithDetails } from "@vertesia/common"
import { useNavigate, useParams } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { MarkdownRenderer } from "@vertesia/ui/widgets"
import { AlertCircle, Bot, Calendar, Clock, Loader2, RotateCcw, User } from "lucide-react"
import { FileButton } from "@/components/buttons/FileButton"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { formatPropertyKey, PropertyValue } from "@/features/executions/components/PropertyValue"
import { useUserCache } from "@/hooks/use-user-cache"
import { insertMessageInTimeline } from "@/lib/agent"
import { toLocaleDateTimeString } from "@/lib/date"
import { AgentMessage, Plan, PlanTask } from "@/models/agents"

export function ExecutionPanel() {
    const { t } = useTranslation(["executions", "common"])
    const id = useParams("id")
    const { client, isLoading: sessionLoading } = useUserSession()
    const { getUserDisplayName } = useUserCache(client)
    const navigate = useNavigate()

    const [collection, setCollection] = useState<Collection | undefined>(undefined)
    const [runDetails, setRunDetails] = useState<WorkflowRunWithDetails | undefined>(undefined)
    const [messages, setMessages] = useState<AgentMessage[]>([])
    const [inError, setInError] = useState<boolean>(false)
    const [notFound, setNotFound] = useState<boolean>(false)
    const [isLoading, setIsLoading] = useState<boolean>(true)

    const [plans, setPlans] = useState<Array<{ plan: Plan; timestamp: number }>>([])
    const [activePlanIndex, setActivePlanIndex] = useState<number>(0)
    const [workstreamStatusMap, setWorkstreamStatusMap] = useState<Map<number, Map<string, "pending" | "in_progress" | "completed" | "skipped">>>(new Map())

    const [isAnimatingCompletion, setIsAnimatingCompletion] = useState<boolean>(false)
    const [showResult, setShowResult] = useState<boolean>(false)

    const streamRef = useRef<boolean>(false)
    const animationStartedRef = useRef<boolean>(false)

    const handleRerunAgent = useCallback(() => {
        if (!collection?.properties?.interactionId || !runDetails?.input) {
            return
        }

        const input = runDetails.input as { interaction?: string; data?: Record<string, unknown> }
        const interaction = collection?.properties?.interactionId

        if (!interaction) {
            return
        }

        const prefilledData = {
            executionName: `${collection.name} (Rerun)`,
            executionDescription: collection.description || "",
            formData: input.data || {}
        }

        const searchParams = new URLSearchParams()
        searchParams.set("prefilled", encodeURIComponent(JSON.stringify(prefilledData)))

        navigate(`/agents/${interaction}/create?${searchParams.toString()}`)
    }, [collection, runDetails, navigate])

    const canRerun = useMemo(() => {
        if (!collection?.properties?.interactionId || !runDetails?.input) {
            return false
        }
        return true
    }, [collection, runDetails])

    const getActivePlan = useMemo(() => {
        const currentPlanData = plans[activePlanIndex] || { plan: { plan: [] }, timestamp: 0 }
        const currentWorkstreamStatus = workstreamStatusMap.get(currentPlanData.timestamp) || new Map()
        return {
            plan: currentPlanData.plan,
            workstreamStatus: currentWorkstreamStatus,
        }
    }, [plans, activePlanIndex, workstreamStatusMap])

    const progressPercentage = useMemo(() => {
        return calculateProgress(getActivePlan.plan, getActivePlan.workstreamStatus)
    }, [getActivePlan])

    const isComplete = useMemo(() => {
        if (messages.length === 0) {
            return false
        }
        const lastMessage = messages[messages.length - 1]
        return lastMessage.type === AgentMessageType.IDLE
    }, [messages])

    const latestAnswer = useMemo(() => {
        const answerMessages = messages.filter((m) => m.type === AgentMessageType.ANSWER)
        if (answerMessages.length === 0) {
            return null
        }
        return answerMessages[answerMessages.length - 1]
    }, [messages])

    const latestThought = useMemo(() => {
        const thoughtMessages = messages.filter((m) => m.type === AgentMessageType.THOUGHT)
        if (thoughtMessages.length === 0) {
            return null
        }
        return thoughtMessages[thoughtMessages.length - 1]
    }, [messages])

    useEffect(() => {
        if (isComplete && !animationStartedRef.current) {
            animationStartedRef.current = true
            setIsAnimatingCompletion(true)
            setTimeout(() => {
                setIsAnimatingCompletion(false)
                setShowResult(true)
            }, 2000)
        }
    }, [isComplete])

    const retrieveCollection = useCallback(async (collectionId: string) => {
        if (!client) {
            return
        }

        setIsLoading(true)
        try {
            const coll = await client.store.collections.retrieve(collectionId) as Collection
            setCollection(coll)

            const properties = coll.properties || {}
            const runId = properties.run_id as string | undefined
            const workflowId = properties.workflow_id as string | undefined

            if (runId && workflowId) {
                try {
                    const details = await client.workflows.getRunDetails(runId, workflowId)
                    if (details.status === "FAILED") {
                        setInError(true)
                    } else {
                        setRunDetails(details as WorkflowRunWithDetails)
                    }
                } catch {
                    setInError(true)
                }
            }
        } catch (error: unknown) {
            if (error && typeof error === "object" && "status" in error && error.status === 404) {
                setNotFound(true)
            } else {
                setInError(true)
            }
        } finally {
            setIsLoading(false)
        }
    }, [client])

    const customComponents = useMemo(
        () => ({
            a: ({ ...props }: { href?: string; children?: React.ReactNode }) => {
                const href = props.href || ""

                if (href.startsWith("/store/objects/")) {
                    const documentId = href.split("/store/objects/")[1]
                    return <FileButton id={documentId} name={String(props?.children || "")} />
                }
                return <a {...props} target="_blank" rel="noopener noreferrer" className="text-info hover:text-info" />
            },
            p: ({ ...props }: { children?: React.ReactNode }) => {
                return <span {...props} className="my-2 block text-foreground/65 whitespace-pre-wrap leading-relaxed" />
            },
            strong: ({ ...props }: { children?: React.ReactNode }) => <strong {...props} className="font-bold text-foreground/80" />,
            em: ({ ...props }: { children?: React.ReactNode }) => <em {...props} className="italic text-foreground/65" />,
            pre: ({ ...props }: { children?: React.ReactNode }) => <pre {...props} className="my-2 bg-foreground/65 p-3 rounded-md text-secondary whitespace-pre-wrap break-words border border-border" />,
            code: ({ className, children, ...props }: { className?: string; children?: React.ReactNode }) => {
                const match = /language-(\w+)/.exec(className || "")
                const isInline = !match
                const language = match ? match[1] : ""

                return (
                    <>
                        {!isInline && language && <div className="code-language-indicator">{language}</div>}
                        <code {...props}>{children}</code>
                    </>
                )
            },
            h1: ({ ...props }: { children?: React.ReactNode }) => <h1 {...props} className="text-foreground/80 font-bold text-2xl my-3" />,
            h2: ({ ...props }: { children?: React.ReactNode }) => <h2 {...props} className="text-foreground/80 font-bold text-xl my-2" />,
            h3: ({ ...props }: { children?: React.ReactNode }) => <h3 {...props} className="text-foreground/80 font-bold text-lg my-2" />,
            li: ({ ...props }: { children?: React.ReactNode }) => {
                return <li {...props} className="text-foreground/65 my-2 pl-1" />
            },
            ul: ({ ...props }: { children?: React.ReactNode }) => <ul {...props} className="my-3 pl-6 list-disc space-y-1" />,
            ol: ({ ...props }: { children?: React.ReactNode }) => <ol {...props} className="my-3 pl-6 list-decimal space-y-1" />,
            blockquote: ({ ...props }: { children?: React.ReactNode }) => <blockquote {...props} className="border-l-4 border-border pl-4 italic text-muted-foreground my-3" />,
            hr: ({ ...props }: { children?: React.ReactNode }) => <hr {...props} className="border-border my-4" />,
            table: ({ ...props }: { children?: React.ReactNode }) => (
                <div className="overflow-x-auto my-4">
                    <table {...props} className="min-w-full border-collapse border border-border" />
                </div>
            ),
            th: ({ ...props }: { children?: React.ReactNode }) => <th {...props} className="border border-border bg-secondary px-4 py-2 text-left text-muted-foreground" />,
            td: ({ ...props }: { children?: React.ReactNode }) => <td {...props} className="border border-border px-4 py-2 text-foreground/65" />,
        }),
        [],
    )

    const streamMessages = useCallback(() => {
        if (!client || !collection || streamRef.current) {
            return
        }

        const properties = collection.properties || {}
        const runId = properties.run_id as string | undefined
        const workflowId = properties.workflow_id as string | undefined

        if (!runId || !workflowId) {
            return
        }

        streamRef.current = true
        client.store.workflows.streamMessages(workflowId, runId, (message) => {
            if (message.message) {
                setMessages((prevMessages) => {
                    if (!prevMessages.find((m) => m.timestamp === message.timestamp)) {
                        insertMessageInTimeline(prevMessages, message)
                        return [...prevMessages]
                    }
                    return prevMessages
                })
            }
        })
    }, [client, collection])

    useEffect(() => {
        if (!id || sessionLoading) {
            return
        }

        retrieveCollection(id)
    }, [id, sessionLoading, retrieveCollection])

    useEffect(() => {
        if (collection && runDetails && !isComplete && !inError) {
            streamMessages()
        }
    }, [collection, runDetails, isComplete, inError, streamMessages])

    useEffect(() => {
        messages.forEach((message) => {
            if (message.type === AgentMessageType.PLAN) {
                try {
                    let newPlanDetails: Plan | null = null
                    if (message.details && typeof message.details === "object") {
                        const details = message.details as { plan?: PlanTask[] }
                        if (details.plan && Array.isArray(details.plan)) {
                            newPlanDetails = { plan: details.plan } as Plan
                        }
                    }

                    if (newPlanDetails) {
                        const timestamp =
                            typeof message.timestamp === "number"
                                ? message.timestamp
                                : new Date(message.timestamp).getTime()

                        const existingPlanIndex = plans.findIndex((p) => p.timestamp === timestamp)

                        if (existingPlanIndex === -1) {
                            const newPlan = {
                                plan: newPlanDetails,
                                timestamp,
                            }

                            setPlans((prev) => [newPlan, ...prev])
                            setActivePlanIndex(0)

                            const newWorkstreamStatus = new Map<string, "pending" | "in_progress" | "completed" | "skipped">()
                            newWorkstreamStatus.set("main", "in_progress")

                            if (Array.isArray(newPlanDetails.plan)) {
                                newPlanDetails.plan.forEach((task) => {
                                    if (task && typeof task === "object" && task.id) {
                                        const taskId = task.id.toString()
                                        newWorkstreamStatus.set(taskId, task.status || "pending")
                                    }
                                })
                            }

                            setWorkstreamStatusMap((prev) => {
                                const newMap = new Map(prev)
                                newMap.set(timestamp, newWorkstreamStatus)
                                return newMap
                            })
                        }
                    }
                } catch {
                    // Silently handle plan parsing errors
                }
            }
        })
    }, [messages, plans])

    useEffect(() => {
        if (!client || !collection || isComplete) {
            return
        }

        const properties = collection.properties || {}
        const runId = properties.run_id as string | undefined
        const workflowId = properties.workflow_id as string | undefined

        if (!runId || !workflowId) {
            return
        }

        const interval = setInterval(async () => {
            try {
                const details = await client.workflows.getRunDetails(runId, workflowId)
                if (details.status === "FAILED") {
                    setInError(true)
                    clearInterval(interval)
                } else if (details.status === "COMPLETED") {
                    setRunDetails(details as WorkflowRunWithDetails)
                    clearInterval(interval)
                }
            } catch {
                // Silently handle polling errors
            }
        }, 5000)

        return () => clearInterval(interval)
    }, [client, collection, isComplete])

    if (sessionLoading || isLoading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
        )
    }

    if (notFound) {
        return (
            <div className="flex flex-col items-center justify-center h-full gap-4">
                <AlertCircle className="w-16 h-16 text-destructive" />
                <h1 className="text-2xl font-bold">{t("executions:detail.notFound")}</h1>
                <p className="text-muted-foreground">{t("executions:detail.notFoundDescription")}</p>
            </div>
        )
    }

    if (!collection) {
        return null
    }

    return (
        <div className="flex flex-col w-full h-full px-2 pt-2 pb-4">
            <div className="flex items-center justify-between pb-2 border-b">
                <h1 className="text-2xl font-bold">{collection.name}</h1>
                {canRerun && (
                    <Button variant="outline" size="sm" onClick={handleRerunAgent}>
                        <RotateCcw className="h-4 w-4" />
                        Rerun Agent
                    </Button>
                )}
            </div>

            <div className="flex flex-1 min-h-0 gap-4">
                <div className="flex-1 flex flex-col gap-2 items-center justify-center">
                    {inError ? (
                        <div className="flex flex-col items-center justify-center gap-4">
                            <AlertCircle className="h-16 w-16 text-destructive" />
                            <p className="text-destructive font-medium text-lg">{t("executions:detail.encounteredError")}</p>
                            <p className="text-muted-foreground text-sm">
                                {t("executions:detail.contactAdmin")}
                            </p>
                        </div>
                    ) : showResult ? (
                        <div className="flex flex-col mt-4 h-full w-full overflow-auto">
                            {latestAnswer?.message ? (
                                <div className="flex flex-col gap-1">
                                    <div className="flex items-center gap-2 text-muted-foreground">
                                        <div className="flex items-center justify-center h-6 w-6 rounded-full bg-primary/10">
                                            <Bot className="h-4 w-4 text-primary" />
                                        </div>
                                        <span className="text-sm font-medium">{t("executions:detail.agentResponse")}</span>
                                        <span className="text-xs">
                                            {toLocaleDateTimeString(new Date(latestAnswer.timestamp))}
                                        </span>
                                    </div>
                                    <div className="border rounded-sm p-2 bg-secondary vprose prose prose-slate dark:prose-invert prose-p:leading-relaxed prose-p:my-1.5 max-w-none text-sm">
                                        <MarkdownRenderer
                                            artifactRunId={id}
                                            components={customComponents}
                                        >
                                            {latestAnswer.message}
                                        </MarkdownRenderer>
                                    </div>
                                </div>
                            ) : (
                                <div className="flex flex-col items-center justify-center gap-4 flex-1">
                                    <div className="h-16 w-16 rounded-full bg-success-background flex items-center justify-center">
                                        <svg
                                            className="h-8 w-8 text-success"
                                            fill="none"
                                            stroke="currentColor"
                                            viewBox="0 0 24 24"
                                        >
                                            <path
                                                strokeLinecap="round"
                                                strokeLinejoin="round"
                                                strokeWidth={2}
                                                d="M5 13l4 4L19 7"
                                            />
                                        </svg>
                                    </div>
                                    <p className="text-success font-medium text-lg">{t("executions:detail.completedSuccessfully")}</p>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="flex flex-col justify-center gap-0 w-full max-w-md">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2 text-primary">
                                    <Loader2 className="size-6 animate-spin" />
                                    <span className="text-lg font-medium">
                                        {isAnimatingCompletion ? "Completing..." : "Processing..."}
                                    </span>
                                </div>
                                <span className="text-sm font-medium">
                                    {isAnimatingCompletion ? "100" : progressPercentage}%
                                </span>
                            </div>
                            <div className="w-full bg-secondary rounded-full h-3">
                                <div
                                    className="bg-primary h-3 rounded-full"
                                    style={{
                                        width: `${isAnimatingCompletion ? 100 : progressPercentage}%`,
                                        transition: isAnimatingCompletion ? "width 2s ease-out" : "width 300ms ease-out"
                                    }}
                                />
                            </div>
                            {latestThought?.message && (
                                <div className="flex mt-2 items-start gap-2 text-muted-foreground">
                                    <Bot className="h-4 w-4 flex-shrink-0 mt-0.5" />
                                    <p className="text-sm italic line-clamp-2">{latestThought.message}</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="w-80 mt-2 flex flex-col min-h-0">
                    <Card className="flex flex-col min-h-0 flex-1">
                        <CardHeader className="flex-shrink-0">
                            <CardTitle>{t("executions:detail.executionDetails")}</CardTitle>
                        </CardHeader>
                        <CardContent className="flex flex-col gap-4 overflow-y-auto min-h-0 flex-1">
                            {runDetails?.input?.data && Object.keys(runDetails.input.data).length > 0 && (
                                <>
                                    <div className="flex flex-col gap-3">
                                        <span className="text-xs font-medium uppercase text-muted-foreground">{t("executions:detail.inputParameters")}</span>
                                        {Object.entries(runDetails.input.data).map(([key, value]) => (
                                            <div key={key} className="flex flex-col gap-1">
                                                <span className="text-xs font-medium text-muted-foreground">
                                                    {formatPropertyKey(key)}
                                                </span>
                                                <PropertyValue value={value} />
                                            </div>
                                        ))}
                                    </div>
                                    <div className="border-b pb-2 mb-2" />
                                </>
                            )}
                            {collection.description && (
                                <div className="flex flex-col gap-1">
                                    <span className="text-xs font-medium uppercase text-muted-foreground">Description</span>
                                    <span className="text-sm">{collection.description}</span>
                                </div>
                            )}
                            <div className="flex flex-col gap-1">
                                <div className="flex items-center gap-2 text-muted-foreground">
                                    <User className="h-4 w-4" />
                                    <span className="text-xs font-medium uppercase">Created by</span>
                                </div>
                                <span className="text-sm">
                                    {getUserDisplayName(collection.created_by, "Unknown")}
                                </span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <div className="flex items-center gap-2 text-muted-foreground">
                                    <Calendar className="h-4 w-4" />
                                    <span className="text-xs font-medium uppercase">Created</span>
                                </div>
                                <span className="text-sm">
                                    {toLocaleDateTimeString(new Date(collection.created_at))}
                                </span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <div className="flex items-center gap-2 text-muted-foreground">
                                    <Clock className="h-4 w-4" />
                                    <span className="text-xs font-medium uppercase">Updated</span>
                                </div>
                                <span className="text-sm">
                                    {toLocaleDateTimeString(new Date(collection.updated_at))}
                                </span>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    )
}

function calculateProgress(plan: Plan, workstreamStatus: Map<string, "pending" | "in_progress" | "completed" | "skipped">) {
    const planTasks = plan.plan || []
    const totalTasks = planTasks.length
    let completedTasks = 0

    if (totalTasks > 0) {
        planTasks.forEach((task) => {
            if (task && task.id) {
                const taskId = task.id.toString()
                const taskStatus = workstreamStatus.get(taskId)
                if (taskStatus === "completed") {
                    completedTasks++
                } else if (taskStatus === "in_progress") {
                    completedTasks += 0.5
                }
            }
        })
    }

    return totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0
}
