import { useState, useEffect, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Check, ChevronsUpDown, Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

interface TypeOption {
    id: string
    name: string
}

interface TypeSelectProps {
    value: string
    onChange: (value: string) => void
    placeholder?: string
    disabled?: boolean
    allowEmpty?: boolean
    emptyLabel?: string
    allowedTypes?: string[]
    refreshKey?: number
}

export function TypeSelect({
    value,
    onChange,
    placeholder,
    disabled = false,
    allowEmpty = true,
    emptyLabel,
    allowedTypes,
    refreshKey,
}: TypeSelectProps) {
    const { t } = useTranslation("common")
    const resolvedPlaceholder = placeholder ?? t("inputs.selectType")
    const resolvedEmptyLabel = emptyLabel ?? t("inputs.none")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const [types, setTypes] = useState<TypeOption[]>([])
    const [isLoading, setIsLoading] = useState(true)
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")

    useEffect(() => {
        if (!client) return

        const fetchTypes = async () => {
            setIsLoading(true)
            try {
                const typesList = await client.types.list()
                const typeOptions: TypeOption[] = typesList.map((type: unknown) => {
                    const t = type as { id: string; name?: string }
                    return {
                        id: t.id,
                        name: typeRegistry?.getTypeName(t.id) || t.name || t.id,
                    }
                })
                // Sort alphabetically by name
                typeOptions.sort((a, b) => a.name.localeCompare(b.name))
                setTypes(typeOptions)
            } catch (error) {
                console.error("Failed to fetch types:", error)
                setTypes([])
            } finally {
                setIsLoading(false)
            }
        }

        fetchTypes()
    }, [client, typeRegistry, refreshKey])

    const filteredTypes = useMemo(() => {
        if (!allowedTypes || allowedTypes.length === 0) return types
        return types.filter((type) => allowedTypes.includes(type.id))
    }, [types, allowedTypes])

    const selectedType = useMemo(() => {
        return filteredTypes.find((type) => type.id === value)
    }, [filteredTypes, value])

    const handleSelect = (typeId: string) => {
        if (typeId === "__none__") {
            onChange("")
        } else {
            onChange(typeId)
        }
        setOpen(false)
        setSearch("")
    }

    if (isLoading) {
        return (
            <div className="flex h-9 w-full items-center justify-center rounded-md border border-input bg-popover px-3 py-2">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            </div>
        )
    }

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className="w-full justify-between font-normal bg-popover"
                    disabled={disabled}
                >
                    {selectedType ? selectedType.name : (value ? value : resolvedPlaceholder)}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="p-0" align="start" style={{ width: "var(--radix-popover-trigger-width)" }}>
                <Command>
                    <CommandInput
                        placeholder={t("inputs.searchTypes")}
                        value={search}
                        onValueChange={setSearch}
                    />
                    <CommandList>
                        <CommandEmpty>{t("inputs.noTypeFound")}</CommandEmpty>
                        <CommandGroup>
                            {allowEmpty && (
                                <CommandItem
                                    value="__none__"
                                    onSelect={() => handleSelect("__none__")}
                                >
                                    <Check
                                        className={cn(
                                            "mr-2 h-4 w-4",
                                            !value ? "opacity-100" : "opacity-0"
                                        )}
                                    />
                                    {resolvedEmptyLabel}
                                </CommandItem>
                            )}
                            {filteredTypes.map((type) => (
                                <CommandItem
                                    key={type.id}
                                    value={type.name}
                                    onSelect={() => handleSelect(type.id)}
                                >
                                    <Check
                                        className={cn(
                                            "mr-2 h-4 w-4",
                                            value === type.id ? "opacity-100" : "opacity-0"
                                        )}
                                    />
                                    {type.name}
                                </CommandItem>
                            ))}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    )
}
