import { createContext, useContext, useState, useCallback, useEffect, type ReactNode } from "react"

type BreadcrumbLabels = Record<string, string>

interface BreadcrumbContextValue {
    labels: BreadcrumbLabels
    setLabel: (segment: string, label: string) => void
    clearLabel: (segment: string) => void
}

const BreadcrumbContext = createContext<BreadcrumbContextValue | null>(null)

interface BreadcrumbProviderProps {
    children: ReactNode
}

export function BreadcrumbProvider({ children }: Readonly<BreadcrumbProviderProps>) {
    const [labels, setLabels] = useState<BreadcrumbLabels>({})

    const setLabel = useCallback((segment: string, label: string) => {
        setLabels(prev => ({ ...prev, [segment]: label }))
    }, [])

    const clearLabel = useCallback((segment: string) => {
        setLabels(prev => {
            const { [segment]: _, ...rest } = prev
            return rest
        })
    }, [])

    return (
        <BreadcrumbContext.Provider value={{ labels, setLabel, clearLabel }}>
            {children}
        </BreadcrumbContext.Provider>
    )
}

export function useBreadcrumbContext() {
    const context = useContext(BreadcrumbContext)
    if (!context) {
        throw new Error("useBreadcrumbContext must be used within a BreadcrumbProvider")
    }
    return context
}

/**
 * Hook for pages to register a dynamic breadcrumb label.
 * Automatically clears the label on unmount.
 *
 * @param segment - The URL segment (e.g., document ID) to replace
 * @param label - The display label to show instead (e.g., document title)
 */
export function useBreadcrumbLabel(segment: string | undefined, label: string | undefined) {
    const { setLabel, clearLabel } = useBreadcrumbContext()

    useEffect(() => {
        if (segment && label) {
            setLabel(segment, label)
        }

        return () => {
            if (segment) {
                clearLabel(segment)
            }
        }
    }, [segment, label, setLabel, clearLabel])
}
