import { useContext, useEffect, useRef } from "react"
import { ThemeProviderContext } from "@vertesia/ui/core"
import { setThemeRootElement } from "@/themes"

/**
 * Wrapper that applies theme attributes (dark/light class, data-scheme)
 * on an element inside the shadow DOM tree, so CSS selectors like .dark
 * and [data-scheme] can match within the shadow boundary.
 *
 * In standalone mode this is redundant but harmless — ThemeProvider also
 * sets .dark on document.documentElement.
 */
export function ThemeRoot({ children }: { children: React.ReactNode }) {
    const ref = useRef<HTMLDivElement>(null)
    const { theme } = useContext(ThemeProviderContext)

    // Register this element as the theme root for applyColorScheme()
    useEffect(() => {
        if (ref.current) {
            setThemeRootElement(ref.current)
        }
        return () => setThemeRootElement(null)
    }, [])

    // Sync dark/light mode class to this element
    useEffect(() => {
        const el = ref.current
        if (!el) return

        el.classList.remove("light", "dark")

        if (theme === "system") {
            const mq = window.matchMedia("(prefers-color-scheme: dark)")
            el.classList.add(mq.matches ? "dark" : "light")

            const onChange = (e: MediaQueryListEvent) => {
                el.classList.remove("light", "dark")
                el.classList.add(e.matches ? "dark" : "light")
            }
            mq.addEventListener("change", onChange)
            return () => mq.removeEventListener("change", onChange)
        }

        el.classList.add(theme)
    }, [theme])

    return (
        <div ref={ref} className="contents">
            {children}
        </div>
    )
}
