import { useCallback, useSyncExternalStore } from "react"
import { COLOR_SCHEME_PREFERENCE } from "@/constants/cookies"
import { applyColorScheme, getCurrentColorScheme, type ColorSchemeId } from "@/themes"

const listeners = new Set<() => void>()

function subscribe(callback: () => void) {
    listeners.add(callback)
    return () => listeners.delete(callback)
}

function getSnapshot(): ColorSchemeId {
    return getCurrentColorScheme()
}

export function useColorScheme() {
    const colorScheme = useSyncExternalStore(subscribe, getSnapshot)

    const setColorScheme = useCallback((scheme: ColorSchemeId) => {
        localStorage.setItem(COLOR_SCHEME_PREFERENCE, scheme)
        applyColorScheme(scheme)
        listeners.forEach((listener) => listener())
    }, [])

    return { colorScheme, setColorScheme }
}
