import { FacetResponse } from "@/models/facets"

export enum SEARCH_TYPES {
    REGEX,
    EXACT,
    SELECTION_SINGLE,
    SELECTION_MULTIPLE
}

export enum FIELD_TYPES {
    LIST,
    TEXT,
    TEXT_AREA
}

export interface SearchableProperty {
    id: string
    label: string
    placeholder: string
    property: string
    type: FIELD_TYPES
    searchType: SEARCH_TYPES
    values?: FacetResponse[]
    system: boolean
}

/**
 * A single configurable filter shown in the basic search bar.
 * Built from the BASIC_FACETS setting and populated with facet values.
 */
export interface BasicFilterOption {
    /** Key used in the filters state (e.g. "type", "status", "created_by", "mime_type", "properties.foo"). */
    id: string
    /** Facet field path used to look up values (e.g. "type", "content.type", "properties.foo"). */
    field: string
    /** Display label for the filter. */
    label: string
    /** Available values with counts. */
    values: FacetResponse[]
}