import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { LibraryBig, icons, type LucideIcon } from "lucide-react"
import { NavigationSection } from "@/components/navigation/NavigationSection"
import { UserNavigation } from "@/components/navigation/UserNavigation"
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarMenu, SidebarMenuItem, SidebarMenuButton, useSidebar } from "@/components/ui/sidebar"
import { ADMIN_SECTION, APPLICATION_SECTION } from "@/constants/navigations"
import { useRenditionUrl } from "@/hooks/use-rendition-url"
import { formatBreadcrumbLabel } from "@/lib/format"
import { isAdmin } from "@/lib/user"

export function ApplicationSidebar({ ...props }: React.ComponentProps<typeof Sidebar>) {
    const appInstallation = useAppInstallation()
    const { toggleSidebar } = useSidebar()
    const { user } = useUserSession()
    const userIsAdmin = isAdmin(user)
    const settings = appInstallation?.settings || {}

    const appName = settings.APPLICATION_NAME || appInstallation?.manifest.name || undefined
    const iconName = settings.APPLICATION_ICON as string | undefined
    const iconBackground = (settings.APPLICATION_ICON_BACKGROUND as string) || undefined
    const iconImageId = (settings.APPLICATION_ICON_IMAGE as string) || undefined
    const iconImageUrl = useRenditionUrl(iconImageId)
    const AppIcon: LucideIcon = (iconName && (icons as Record<string, LucideIcon>)[iconName]) || LibraryBig

    return (
        <Sidebar collapsible="icon" variant="floating" {...props}>
            <SidebarHeader>
                <SidebarMenu>
                    <SidebarMenuItem>
                        <SidebarMenuButton size="lg" onClick={toggleSidebar} aria-label="Toggle Sidebar">
                            {iconImageUrl ? (
                                <div className="flex aspect-square size-8 items-center justify-center">
                                    <img src={iconImageUrl} alt={appName || "ECM"} className="size-8 object-contain" />
                                </div>
                            ) : (
                                <div
                                    className="text-sidebar-primary-foreground flex aspect-square size-8 items-center justify-center rounded-lg"
                                    style={{ backgroundColor: iconBackground || "#9333ea" }}
                                >
                                    <AppIcon className="size-4" />
                                </div>
                            )}
                            <div className="flex flex-col gap-0.5 leading-none">
                                <span className="font-medium">{formatBreadcrumbLabel(appName || "ECM", { upperCase: true })}</span>
                                <span className="">v{__APP_VERSION__}</span>
                            </div>
                        </SidebarMenuButton>
                    </SidebarMenuItem>
                </SidebarMenu>
            </SidebarHeader>
            <SidebarContent>
                <NavigationSection section={APPLICATION_SECTION} />
                {userIsAdmin && <NavigationSection section={ADMIN_SECTION} />}
            </SidebarContent>
            <SidebarFooter>
                <div className="flex items-end justify-center w-full h-[60px] relative">
                    <UserNavigation />
                </div>
            </SidebarFooter>
        </Sidebar>
    )
}