import { useCallback, useEffect, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { AgentMessageType, AsyncConversationExecutionPayload } from "@vertesia/common"
import { ModernAgentConversation } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Loader2, Maximize2, MessageSquare, Minimize2, Minus, Send, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { useAgentChat } from "@/contexts/AgentChatContext"

// Hide non-essential message types so the compact panel stays focused on the Q&A exchange.
// The user turn (QUESTION) is tinted darker with its sender label hidden so it reads as a
// distinct bubble.
const HIDDEN_MESSAGE_STYLE = { className: "!hidden", cardClassName: "!hidden" }
const COMPACT_MESSAGE_STYLE_OVERRIDES = {
    [AgentMessageType.THOUGHT]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.PLAN]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.UPDATE]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.SYSTEM]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.COMPLETE]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.IDLE]: HIDDEN_MESSAGE_STYLE,
    [AgentMessageType.TERMINATED]: HIDDEN_MESSAGE_STYLE,
    // User turn: distinct (darker) bubble, no "User" label.
    [AgentMessageType.QUESTION]: {
        cardClassName: "!bg-muted/70 !border-l-muted-foreground/30",
        contentClassName: "!bg-muted/70",
        senderClassName: "!hidden",
    },
}

// Card styling. Hide the redundant "User"/"Agent" sender labels and the per-message "Show
// details" disclosure. The library renders the meta row (timestamp, copy/download icons) and
// links very faint, so darken the timestamp/header icons and render links as underlined primary.
const MESSAGE_ITEM_CLASS_NAMES = {
    cardClassName: "!bg-card text-card-foreground",
    contentClassName: "!bg-card",
    proseClassName: "prose-neutral [&_a]:!text-primary [&_a]:!font-medium [&_a]:underline [&_a:hover]:!text-primary/80",
    senderClassName: "!hidden",
    detailsClassName: "!hidden",
    timestampClassName: "!text-muted-foreground",
    headerClassName: "[&_svg]:!text-muted-foreground [&_button]:!text-muted-foreground",
}
// Stream the answer in live for continuous feedback. Tool-calls and THOUGHT/PLAN noise stay
// hidden, so only the final answer text streams.
const STREAMING_MESSAGE_CLASS_NAMES = {
    cardClassName: "!bg-card text-card-foreground",
    contentClassName: "!bg-card",
    proseClassName: "prose-neutral",
}
// Hide the agent's internal tool-call activity in the stacked view so the panel shows only the
// question→answer exchange.
const HIDE_TOOLCALLS_IN_VIEW_MODES: ("stacked" | "sliding")[] = ["stacked"]
// Make the library's "Working…" indicator more prominent (default is a faint muted pill): primary
// accent bar, subtle background, darker/larger label (`[&>span]` targets the inner text span).
const WORKING_INDICATOR_CLASS =
    "!my-2 !ml-2 !mr-2 !py-2 !px-3 rounded-md bg-primary/10 !border-l-4 !border-l-primary [&>span]:!text-sm [&>span]:!font-semibold [&>span]:!text-foreground"

// Swallow drag-and-drop so the library's file-upload drop zone never fires (we don't support upload).
const blockDrag = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
}

/**
 * Floating "AI Assistant" panel (bottom-right) for the dashboard agentic search.
 *
 * Ticket spec (button-only): launched ONLY by the dashboard "Ask AI Assistant" button via
 * `openChatWithQuery`. Closing removes the panel; it re-opens only from the button. The agent
 * interaction is configured through the `DASHBOARD_AGENTIC_SEARCH_INTERACTION` setting.
 *
 * The conversation uses our own composer (`hideMessageInput`) instead of the library input, which
 * lets us drop the file-upload affordance entirely.
 */
export function AgentChatFloatingPanel() {
    const { t } = useTranslation(["dashboard", "common"])
    const {
        isOpen, isMinimized, pendingQuery, clearPendingQuery,
        minimize, expand, dismiss,
        agentRunId, setAgentRunId,
        hasUnreadResponse, setHasUnreadResponse,
        isEnlarged, toggleEnlarged,
    } = useAgentChat()
    const { client } = useUserSession()
    const appInstallation = useAppInstallation()

    const [isStarting, setIsStarting] = useState(false)
    const [startError, setStartError] = useState<string | null>(null)
    const [isSending, setIsSending] = useState(false)
    const [inputValue, setInputValue] = useState("")
    const lastQueryRef = useRef<string | null>(null)

    const agenticInteractionId = appInstallation?.settings?.DASHBOARD_AGENTIC_SEARCH_INTERACTION as string | undefined

    // Route the agent's document links to the in-app document view in a new tab, whatever URL format
    // the agent emits: catch any anchor whose href carries a Vertesia object id (24-hex) and open
    // `/advanced-search/<id>` (or `/collections/<id>`). The route must be prefixed with the app base
    // path (`/apps/<appName>`) or it resolves against the site root and 404s.
    const handleConversationClick = useCallback((e: React.MouseEvent) => {
        const anchor = (e.target as HTMLElement).closest("a")
        if (!anchor) return
        const href = anchor.getAttribute("href") || ""
        const idMatch = href.match(/([0-9a-f]{24})/i)
        if (!idMatch) return // not a document/collection link — leave it alone
        e.preventDefault()
        e.stopPropagation()
        const id = idMatch[1]
        const appName = appInstallation?.manifest.name || undefined
        const appPath = appName ? `/apps/${appName}` : ""
        const basePath = appPath && window.location.pathname.startsWith(appPath) ? appPath : ""
        const route = /collection/i.test(href) ? `/collections/${id}` : `/advanced-search/${id}`
        window.open(`${window.location.origin}${basePath}${route}`, "_blank", "noopener,noreferrer")
    }, [appInstallation])

    // Start a run: seed an EMPTY `user_prompt` (only to satisfy the agent's `required:["user_prompt"]`
    // schema — key presence is enough), then send the real query as a `UserInput` STRING signal so it
    // renders as a clean user bubble (an object `data.user_prompt` would be echoed as raw JSON).
    const startRun = useCallback(async (query: string) => {
        if (!client) return
        if (!agenticInteractionId) {
            setStartError(t("dashboard:aiAssistant.notConfigured"))
            return
        }
        lastQueryRef.current = query
        setStartError(null)
        setIsStarting(true)
        try {
            const payload = {
                type: "conversation",
                interaction: agenticInteractionId,
                data: { user_prompt: "" },
                interactive: true,
                visibility: "project",
            } as AsyncConversationExecutionPayload
            const result = await client.interactions.executeAsync(payload)
            if (result.agentRunId) {
                setAgentRunId(result.agentRunId)
                try {
                    await client.agents.sendSignal(result.agentRunId, "UserInput", { message: query })
                } catch (signalErr) {
                    console.error("Failed to send initial UserInput signal", signalErr)
                }
            } else {
                setStartError(t("dashboard:aiAssistant.noRunId"))
            }
        } catch (err: unknown) {
            setStartError(err instanceof Error ? err.message : t("dashboard:aiAssistant.startFailed"))
        } finally {
            setIsStarting(false)
        }
    }, [client, agenticInteractionId, setAgentRunId, t])

    // Auto-start when the dashboard button hands off a query.
    useEffect(() => {
        if (!pendingQuery || isStarting || agentRunId) return
        const q = pendingQuery
        clearPendingQuery()
        void startRun(q)
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [pendingQuery])

    // Send a follow-up message on the existing run.
    const sendMessage = useCallback(async (text: string) => {
        const msg = text.trim()
        if (!msg || !agentRunId || isSending || !client) return
        setInputValue("")
        setIsSending(true)
        try {
            await client.agents.sendSignal(agentRunId, "UserInput", { message: msg })
        } catch (err) {
            console.error("Failed to send message", err)
        } finally {
            setIsSending(false)
        }
    }, [agentRunId, client, isSending])

    const handleReset = () => {
        setAgentRunId(null)
        setStartError(null)
    }

    const handleRetry = () => {
        if (lastQueryRef.current) void startRun(lastQueryRef.current)
    }

    // When minimized, flag an unread response so the bubble shows a notification badge.
    const isMinimizedRef = useRef(isMinimized)
    isMinimizedRef.current = isMinimized

    const handleShowInputChange = useCallback((canSendFollowUp: boolean) => {
        if (canSendFollowUp && isMinimizedRef.current) setHasUnreadResponse(true)
    }, [setHasUnreadResponse])

    // Defensive hide for the seeded empty prompt.
    const seedObserverRef = useRef<MutationObserver | null>(null)
    const conversationRef = useCallback((root: HTMLDivElement | null) => {
        seedObserverRef.current?.disconnect()
        seedObserverRef.current = null
        if (!root) return
        const SEED = '{"user_prompt":""}'
        const norm = (s: string | null) => (s || "").replace(/\s+/g, "")
        const hideSeedBubbles = () => {
            // Platform-agnostic: find every element whose text contains ONLY the empty-seed JSON
            const holders = Array.from(root.querySelectorAll<HTMLElement>("*")).filter((el) =>
                norm(el.textContent).includes(SEED),
            )
            const smallest = holders.filter((el) => !holders.some((o) => o !== el && el.contains(o)))
            let hidAny = false
            for (const leaf of smallest) {
                let card: HTMLElement = leaf
                for (let i = 0; i < 8; i++) {
                    const parent = card.parentElement
                    if (!parent || parent === root) break
                    card = parent
                    if (/\d{1,2}:\d{2}/.test(card.textContent || "")) break // reached the bubble (has timestamp)
                }
                if (card.dataset.seedHidden) continue
                card.style.display = "none"
                card.dataset.seedHidden = "1"
                hidAny = true
            }
            return hidAny
        }
        // The empty seed is the first message and appears exactly once, so stop watching as soon as
        // we've hidden it — avoids re-scanning the subtree on every streamed token. If it's already
        // present on mount, we never even attach the observer.
        if (hideSeedBubbles()) return
        const observer = new MutationObserver(() => {
            if (hideSeedBubbles()) observer.disconnect()
        })
        observer.observe(root, { childList: true, subtree: true, characterData: true })
        seedObserverRef.current = observer
    }, [])

    // Button-only: when closed, the panel is gone (re-open only from the dashboard button).
    if (!isOpen) return null

    return (
        <>
            {/* Collapsed: chat bubble with an unread-response ping */}
            {isMinimized && (
                <div className="fixed bottom-6 right-6 z-50">
                    <Button
                        onClick={expand}
                        className="relative size-14 rounded-full shadow-lg [&_svg]:size-6"
                        aria-label={t("dashboard:aiAssistant.open")}
                    >
                        <MessageSquare />
                        {hasUnreadResponse && (
                            <span className="absolute top-0 right-0 flex size-4">
                                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-destructive opacity-75" />
                                <span className="relative inline-flex size-4 rounded-full bg-destructive" />
                            </span>
                        )}
                    </Button>
                </div>
            )}

            {/* Expanded panel — kept mounted (but hidden) when collapsed so the SSE stream stays alive */}
            <div className={`fixed z-50 flex flex-col border bg-background shadow-2xl overflow-hidden transition-all duration-200 ${isEnlarged ? "w-screen h-screen bottom-0 right-0 rounded-none sm:w-[720px] sm:h-[80vh] sm:bottom-6 sm:right-6 sm:rounded-lg" : "w-[420px] h-[560px] bottom-6 right-6 rounded-lg"} ${isMinimized ? "invisible pointer-events-none" : ""}`}>
                {/* Header */}
                <div className="flex items-center justify-between px-4 py-3 border-b bg-muted/40 shrink-0">
                    <div className="flex items-center gap-2">
                        <MessageSquare className="size-4 text-primary" />
                        <span className="font-semibold text-sm">{t("dashboard:aiAssistant.title")}</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <Button
                            variant="ghost"
                            size="xs"
                            onClick={toggleEnlarged}
                            className="text-muted-foreground"
                            aria-label={isEnlarged ? t("dashboard:aiAssistant.shrink") : t("dashboard:aiAssistant.enlarge")}
                        >
                            {isEnlarged ? <Minimize2 /> : <Maximize2 />}
                        </Button>
                        <Button
                            variant="ghost"
                            size="xs"
                            onClick={minimize}
                            className="text-muted-foreground"
                            aria-label={t("dashboard:aiAssistant.minimize")}
                        >
                            <Minus />
                        </Button>
                        <Button
                            variant="ghost"
                            size="xs"
                            onClick={dismiss}
                            className="text-muted-foreground"
                            aria-label={t("common:actions.close")}
                        >
                            <X />
                        </Button>
                    </div>
                </div>

                {/* Body */}
                {isStarting ? (
                    <div className="flex-1 flex flex-col items-center justify-center gap-3 text-muted-foreground">
                        <Loader2 className="size-6 animate-spin" />
                        <span className="text-sm">{t("dashboard:aiAssistant.starting")}</span>
                    </div>
                ) : startError ? (
                    <div className="flex-1 flex flex-col items-center justify-center gap-3 px-6 text-center">
                        <span className="text-sm text-destructive">{startError}</span>
                        <Button variant="link" onClick={handleRetry} className="h-auto p-0 text-xs">
                            {t("dashboard:aiAssistant.tryAgain")}
                        </Button>
                    </div>
                ) : !agentRunId ? (
                    <div className="flex-1 flex flex-col items-center justify-center gap-2 text-muted-foreground px-6 text-center">
                        <MessageSquare className="size-8 opacity-30" />
                        <span className="text-sm">{t("dashboard:aiAssistant.empty")}</span>
                    </div>
                ) : (
                    <>
                        {/* Conversation (read-only view; our own composer is below). The drag handlers
                            swallow file drops; the click handler routes doc links to the in-app view. */}
                        <div
                            ref={conversationRef}
                            className="flex-1 min-h-0 flex flex-col"
                            onClickCapture={handleConversationClick}
                            onDragEnterCapture={blockDrag}
                            onDragOverCapture={blockDrag}
                            onDropCapture={blockDrag}
                        >
                            <ModernAgentConversation
                                agentRunId={agentRunId}
                                hideHeader
                                hideMessageInput
                                hidePlanPanel
                                hideWorkstreamTabs
                                showRightPanel={false}
                                hideFileUpload
                                hideObjectLinking
                                hideDocumentPanel
                                interactive
                                viewMode="stacked"
                                className="flex-1 min-h-0"
                                resetWorkflow={handleReset}
                                onShowInputChange={handleShowInputChange}
                                messageStyleOverrides={COMPACT_MESSAGE_STYLE_OVERRIDES}
                                messageItemClassNames={MESSAGE_ITEM_CLASS_NAMES}
                                streamingMessageClassNames={STREAMING_MESSAGE_CLASS_NAMES}
                                hideToolCallsInViewMode={HIDE_TOOLCALLS_IN_VIEW_MODES}
                                workingIndicatorClassName={WORKING_INDICATOR_CLASS}
                            />
                        </div>

                        {/* Composer (replaces the library input: no file upload). */}
                        <div className="shrink-0 border-t bg-background">
                            <div className="flex items-end gap-2 p-3">
                                <textarea
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter" && !e.shiftKey) {
                                            e.preventDefault()
                                            void sendMessage(inputValue)
                                        }
                                    }}
                                    placeholder={t("dashboard:aiAssistant.inputPlaceholder")}
                                    rows={1}
                                    className="flex-1 resize-none rounded-md border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-ring max-h-32"
                                />
                                <Button
                                    type="button"
                                    size="icon"
                                    onClick={() => void sendMessage(inputValue)}
                                    disabled={!inputValue.trim() || isSending}
                                    className="shrink-0"
                                    aria-label={t("dashboard:aiAssistant.send")}
                                >
                                    <Send />
                                </Button>
                            </div>
                        </div>
                    </>
                )}
            </div>
        </>
    )
}
