import { useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Download, EllipsisVertical, FolderPlus, Heart, HeartOff, LoaderCircle, Trash2 } from "lucide-react"
import mime from "mime-types"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { useFavorites } from "@/contexts/FavoritesContext"
import { AddToCollectionModal } from "@/features/document/modals/AddToCollectionModal"
import { DeleteDocumentModal } from "@/features/document/modals/DeleteDocumentModal"
import { isHtmlContent } from "@/lib/file"

interface DocumentActionsProps {
    document: ContentObjectItem
    disableDeleteDocument?: boolean
    onDeleteDone?: () => void
}
export function DocumentActions({ document, disableDeleteDocument = false, onDeleteDone }: Readonly<DocumentActionsProps>) {
    const { t } = useTranslation(["library", "common"])
    const { client } = useUserSession()
    const toast = useToast()
    const { isFavorite, toggleFavorite } = useFavorites()
    const favorite = isFavorite(document.id)

    const [openAddToCollection, setOpenAddToCollection] = useState(false)
    const [downloading, setDownloading] = useState(false)

    const [openDelete, setOpenDelete] = useState(false)
    const [documentToDelete, setDocumentToDelete] = useState<ContentObjectItem | null>(null)

    const handleOnDelete = (doc: ContentObjectItem) => {
        setDocumentToDelete({ ...doc })
    }

    const handleOnDeleteRefresh = () => {
        setDocumentToDelete(null)
        onDeleteDone?.()
    }

    useEffect(() => {
        setOpenDelete(!!documentToDelete)
    }, [documentToDelete])

    const handleDownload = () => {
        if (!document?.content?.source || downloading) {
            return
        }

        setDownloading(true)
        client.objects
            .getDownloadUrl(document.content.source)
            .then(async (response) => {
                const data = await fetch(response.url)
                const blob = await data.blob()

                let text = undefined
                try {
                    text = await client.store.objects.getObjectText(document.id)
                } catch {
                    console.error("Error fetching object text")
                }
                const fileExtension = text?.text && isHtmlContent(text.text) ? "html" : mime.extension(document?.content?.type || "application/octet-stream") || "bin"
                const baseName = document?.properties?.title || document.name || document.id
                const extRegex = new RegExp(`\\.${(fileExtension ?? "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`, "i")
                const nameWithoutExt = baseName.replace(extRegex, "")
                const fileName = `${nameWithoutExt}.${fileExtension}`

                const link = window.document.createElement("a")
                link.href = URL.createObjectURL(blob)
                link.download = fileName
                link.click()
                window.URL.revokeObjectURL(link.href)
            })
            .catch((error) => {
                toast({
                    status: "error",
                    title: t("library:document.errorDownloading"),
                    description: error.message || t("library:document.errorDownloadingDescription"),
                    duration: 5000,
                })
            })
            .finally(() => {
                setDownloading(false)
            })
    }

    return (
        <>
            <DropdownMenu>
                <DropdownMenuTrigger asChild disabled={downloading}>
                    <Button className="border border-primary/50 bg-popover text-popover-foreground hover:bg-primary/50" disabled={downloading}>
                        {downloading ? (
                            <LoaderCircle className="animate-spin" />
                        ) : (
                            <EllipsisVertical />
                        )}
                        <span className="hidden md:inline">{downloading ? t("common:actions.downloading") : t("library:document.more")}</span>
                    </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent side="bottom" align="end" className="p-1 flex flex-col gap-1 w-[230px]">
                    <DropdownMenuItem onClick={handleDownload}>
                        <Download />
                        <span>{t("library:document.download")}</span>
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => toggleFavorite(document.id)}>
                        {favorite ? <HeartOff /> : <Heart />}
                        <span>{favorite ? t("common:favorites.remove") : t("common:favorites.add")}</span>
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setOpenAddToCollection(true)}>
                        <FolderPlus />
                        <span>{t("library:document.addToCollection")}</span>
                    </DropdownMenuItem>
                    {
                        !disableDeleteDocument && (
                            <DropdownMenuItem onClick={() => { handleOnDelete(document) }}>
                                <Trash2 />
                                <span>{t("library:document.delete")}</span>
                            </DropdownMenuItem>
                        )
                    }
                </DropdownMenuContent>
            </DropdownMenu>
            {(!disableDeleteDocument && openDelete && documentToDelete) && <DeleteDocumentModal document={documentToDelete} open={openDelete} setOpen={setOpenDelete} onDelete={handleOnDeleteRefresh} />}
            {(openAddToCollection) && (<AddToCollectionModal documents={[document]} open={openAddToCollection} onOpenChange={setOpenAddToCollection} />)}
        </>

    )
}