import { AuthTokenPayload } from "@vertesia/common"

export function getInitials(name?: string | undefined) {
    if (!name) {
        return "U"
    }

    const nameParts = name.split(" ")
    const initials = nameParts
        .map((part) => part.charAt(0).toUpperCase())
        .join("")
        .slice(0, 2)
    return initials
}

export function isAdmin(user: AuthTokenPayload | undefined) {
    if (!user) {
        return false
    }

    let accountRoles = (user as any)?.account_roles || []
    if (!Array.isArray(accountRoles)) {
        accountRoles = []
    }
    let projectRoles = (user as any)?.project_roles || []
    if (!Array.isArray(projectRoles)) {
        projectRoles = []
    }

    const roles = [...accountRoles, ...projectRoles]
    if (!Array.isArray(roles) || roles.length === 0) {
        return false
    }

    return roles.includes("admin") || roles.includes("owner")
}
