import { useState } from "react"
import { useTranslation } from "react-i18next"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"

export const useUpdateSettings = () => {
    const { client } = useUserSession()
    const appInstallation = useAppInstallation()
    const toast = useToast()
    const { t } = useTranslation()
    const [loading, setLoading] = useState(false)

    const updateSettings = async (settings: Record<string, any>, options?: { skipRefresh?: boolean }) => {
        if (!client || !appInstallation) {
            return
        }

        setLoading(true)
        try {
            const currentSettings = appInstallation.settings || {}

            await client.apps.updateInstallationSettings({
                app_id: appInstallation.id,
                settings: { ...currentSettings, ...settings },
            })
            if (!options?.skipRefresh) {
                toast?.({
                    status: "success",
                    title: t("settingsToast.successTitle"),
                    description: t("settingsToast.successDescription"),
                })
                setTimeout(() => window.location.reload(), 1000)
            }
        } catch (err) {
            console.error("Failed to update settings:", err)
            toast?.({
                status: "error",
                title: t("settingsToast.errorTitle"),
                description: t("settingsToast.errorDescription"),
            })
        } finally {
            setLoading(false)
        }
    }

    return { updateSettings, loading }
}
