import { useEffect } from "react"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { RENDITION_ID } from "@/constants/cookies"
import { getDashboardBackgroundSettings } from "@/lib/dashboard-settings"
import { retrieveRenditionById } from "@/lib/rendition"

/**
 * Preloads the dashboard background rendition into localStorage cache
 * so it's available synchronously when the dashboard mounts.
 */
export function usePreloadDashboardBackground() {
    const { client } = useUserSession()
    const appInstallation = useAppInstallation()
    const toast = useToast()

    const backgroundId = appInstallation?.settings?.DASHBOARD_BACKGROUND
    const { renditionSize } = getDashboardBackgroundSettings(appInstallation?.settings)

    useEffect(() => {
        if (!client || !backgroundId) return

        // Skip if already cached
        const cacheKey = `${RENDITION_ID}_${backgroundId}_${renditionSize}`
        const cached = localStorage.getItem(cacheKey)
        const cachedTime = localStorage.getItem(`${cacheKey}_time`)
        const now = new Date().getTime() / 1000
        if (cached?.length && cachedTime && Math.abs(now - parseInt(cachedTime)) <= 900) {
            return
        }

        retrieveRenditionById(client, backgroundId, () => {}, () => {}, toast, renditionSize)
    }, [client, backgroundId, renditionSize])
}
