import { useTranslation } from "react-i18next"
import { LoaderCircle } from "lucide-react"

interface AgentExecutionDonePanelProps {
    isExecuting: boolean
    executionError: string | null
}
export function AgentExecutionDonePanel({ isExecuting, executionError }: Readonly<AgentExecutionDonePanelProps>) {
    const { t } = useTranslation("agents")
    return (
        <div className="flex items-center justify-center h-full gap-1">
            {isExecuting && <LoaderCircle className="animate-spin motion-safe:animate-[spin_2s_linear_infinite]" />}
            <span>{executionError ?? t("execution.redirecting")}</span>
        </div>
    )
}