import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { CheckCircle, CloudUpload, File, FileText, Image, Loader2, Music, Video, X, XCircle } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Progress } from "@/components/ui/progress"
import { ScrollArea } from "@/components/ui/scroll-area"
import { filterFiles } from "@/lib/upload"
import { cn } from "@/lib/utils"
import { DocumentUploadResult, FileUploadStatus } from "@/plugins/upload/useSmartFileUploadProcessing"

enum UploadState {
    SELECT = "SELECT",
    UPLOADING = "UPLOADING",
    DONE = "DONE",
}

const BATCH_SIZE = 50

interface UploadDocumentModalProps {
    open: boolean
    collectionId?: string | undefined
    typeId?: string | undefined
    initialFiles?: File[]
    maxFiles?: number
    filteredTypes?: string[]
    onOpenChange: (open: boolean) => void
    onUploadDone: (uploadedIds: ContentObjectItem[]) => void
}

function getFileIcon(file: File) {
    const type = file.type
    if (type.startsWith("image/")) return <Image className="size-4 text-muted-foreground" />
    if (type.startsWith("video/")) return <Video className="size-4 text-muted-foreground" />
    if (type.startsWith("audio/")) return <Music className="size-4 text-muted-foreground" />
    if (type.includes("pdf") || type.includes("document") || type.includes("text")) {
        return <FileText className="size-4 text-muted-foreground" />
    }
    return <File className="size-4 text-muted-foreground" />
}

function formatFileSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / 1024 / 1024).toFixed(2)} MB`
}

interface FileItemProps {
    file: File
    onRemove: () => void
}

function FileItem({ file, onRemove }: FileItemProps) {
    return (
        <div className="border flex items-center gap-3 p-2.5 bg-background rounded-lg group hover:border-primary hover:shadow-xs transition-colors">
            <div className="flex-shrink-0">
                {getFileIcon(file)}
            </div>
            <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">{file.name}</p>
                <p className="text-xs text-muted-foreground">{formatFileSize(file.size)}</p>
            </div>
            <Button
                variant="ghost"
                size="xs"
                className="opacity-0 group-hover:opacity-100 transition-opacity hover:bg-destructive/10 hover:text-destructive"
                onClick={(e) => {
                    e.stopPropagation()
                    onRemove()
                }}
                aria-label={`Remove ${file.name}`}
            >
                <X className="size-4" />
            </Button>
        </div>
    )
}

interface FileStatusItemProps {
    fileStatus: FileUploadStatus
}

function FileStatusItem({ fileStatus }: FileStatusItemProps) {
    const { t } = useTranslation("common")
    const { file, status, message, action } = fileStatus

    return (
        <div className={cn(
            "flex items-center gap-3 p-2.5 rounded-lg transition-colors",
            status === "error" ? "bg-destructive/10" : "bg-muted/50"
        )}>
            <div className="flex-shrink-0">
                {status === "pending" && <File className="size-5 text-muted-foreground" />}
                {status === "uploading" && <Loader2 className="size-5 animate-spin text-primary" />}
                {status === "success" && <CheckCircle className="size-5 text-success" />}
                {status === "error" && <XCircle className="size-5 text-destructive" />}
            </div>
            <div className="flex-1 min-w-0">
                <p className={cn(
                    "text-sm font-medium truncate",
                    status === "error" && "text-destructive"
                )}>
                    {file.name}
                </p>
                <p className="text-xs text-muted-foreground">
                    {status === "pending" && t("states.waiting")}
                    {status === "uploading" && t("states.uploading")}
                    {status === "success" && (action === "create" ? t("states.uploadedSuccessfully") : action === "update" ? t("states.updated") : t("states.skipped"))}
                    {status === "error" && (message || t("states.uploadFailed"))}
                </p>
            </div>
        </div>
    )
}

export function UploadDocumentModal({
    open,
    collectionId,
    typeId,
    initialFiles,
    maxFiles,
    filteredTypes,
    onOpenChange,
    onUploadDone
}: Readonly<UploadDocumentModalProps>) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const toast = useToast()

    const fileInputRef = useRef<HTMLInputElement>(null)
    const initialFilesProcessedRef = useRef(false)

    const [state, setState] = useState<UploadState>(UploadState.SELECT)
    const [files, setFiles] = useState<File[]>([])
    const [fileStatuses, setFileStatuses] = useState<FileUploadStatus[]>([])
    const [overallProgress, setOverallProgress] = useState(0)
    const [isDragging, setIsDragging] = useState(false)
    const [uploadResult, setUploadResult] = useState<DocumentUploadResult | null>(null)

    const isAtLimit = useMemo(() => maxFiles ? files.length >= maxFiles : false, [maxFiles, files.length])
    const isUploading = state === UploadState.UPLOADING

    useEffect(() => {
        if (files.length > 0 && state === UploadState.SELECT) {
            setFileStatuses(
                files.map((file) => ({
                    file,
                    status: "pending" as const,
                    progress: 0,
                    action: "create" as const,
                }))
            )
        }
    }, [files, state])

    useEffect(() => {
        if (fileStatuses.length > 0) {
            const completedFiles = fileStatuses.filter((f) => f.status === "success" || f.status === "error").length
            const progress = Math.round((completedFiles / fileStatuses.length) * 100)
            setOverallProgress(progress)
        }
    }, [fileStatuses])

    useEffect(() => {
        if (open && initialFiles && initialFiles.length > 0 && !initialFilesProcessedRef.current) {
            initialFilesProcessedRef.current = true
            const filtered = filterFiles(initialFiles, filteredTypes)
            setFiles((prev) => {
                const combined = [...prev, ...filtered]
                if (maxFiles && combined.length > maxFiles) {
                    return combined.slice(0, maxFiles)
                }
                return combined
            })
        }
    }, [open, initialFiles, maxFiles, filteredTypes])

    const addFiles = useCallback((newFiles: File[]) => {
        const filtered = filterFiles(newFiles, filteredTypes)
        const rejectedCount = newFiles.length - filtered.length

        if (filtered.length === 0 && newFiles.length > 0) {
            toast({
                status: "error",
                title: t("upload.invalidFileType"),
                description: t("upload.invalidFileTypeDescription"),
                duration: 3000
            })
            return
        }

        if (rejectedCount > 0) {
            toast({
                status: "warning",
                title: t("upload.someFilesIgnored"),
                description: t("upload.filesIgnored", { count: rejectedCount }),
                duration: 3000
            })
        }

        setFiles((prev) => {
            const combined = [...prev, ...filtered]
            if (maxFiles && combined.length > maxFiles) {
                toast({
                    status: "warning",
                    title: t("upload.fileLimitReached"),
                    description: t("upload.maxFilesAllowed", { max: maxFiles }),
                    duration: 3000
                })
                return combined.slice(0, maxFiles)
            }
            return combined
        })
    }, [filteredTypes, maxFiles, toast])

    const handlePaste = useCallback((e: React.ClipboardEvent<HTMLDivElement>) => {
        if (isAtLimit || isUploading) return

        const items = e.clipboardData?.items
        if (!items) return

        const clipboardFiles: File[] = []
        for (let i = 0; i < items.length; i++) {
            const file = items[i].getAsFile()
            if (file) clipboardFiles.push(file)
        }

        if (clipboardFiles.length > 0) {
            addFiles(clipboardFiles)
        }
    }, [isAtLimit, isUploading, addFiles])

    const resetState = useCallback(() => {
        setFiles([])
        setFileStatuses([])
        setOverallProgress(0)
        setState(UploadState.SELECT)
        setUploadResult(null)
        initialFilesProcessedRef.current = false
    }, [])

    const handleClose = useCallback(() => {
        onOpenChange(false)
        resetState()
    }, [onOpenChange, resetState])

    const onDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        if (!isAtLimit && !isUploading) {
            setIsDragging(true)
        }
    }, [isAtLimit, isUploading])

    const onDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragging(false)
    }, [])

    const onDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragging(false)

        if (isAtLimit || isUploading) return

        const droppedFiles = Array.from(e.dataTransfer.files)
        addFiles(droppedFiles)
    }, [isAtLimit, isUploading, addFiles])

    const handleUploadOnChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.target.files) {
            const selectedFiles = Array.from(event.target.files)
            addFiles(selectedFiles)
            // Reset input so same file can be selected again
            event.target.value = ""
        }
    }, [addFiles])

    const removeFile = useCallback((indexToRemove: number) => {
        setFiles((prev) => prev.filter((_, index) => index !== indexToRemove))
    }, [])

    const updateFileStatus = useCallback((file: File, updates: Partial<FileUploadStatus>) => {
        setFileStatuses((current) => current.map((status) => (status.file === file ? { ...status, ...updates } : status)))
    }, [])

    const processBatch = async (files: File[], result: DocumentUploadResult) => {
        const batches = []
        for (let i = 0; i < files.length; i += BATCH_SIZE) {
            batches.push(files.slice(i, i + BATCH_SIZE))
        }

        for (const batch of batches) {
            await Promise.all(
                batch.map(async (file) => {
                    try {
                        updateFileStatus(file, {
                            status: "uploading",
                            progress: 20,
                        })

                        const payload = {
                            type: typeId ? typeId : undefined,
                            content: file,
                            location: file.webkitRelativePath || file.name,
                        }
                        const options = {
                            collection_id: collectionId,
                        }

                        const obj = await client.store.objects.create(payload, options)

                        updateFileStatus(file, {
                            status: "success",
                            progress: 100,
                            id: obj.id,
                        })

                        result.uploadedFiles.push({
                            id: obj.id,
                            name: file.name,
                            type: typeId ? typeId : null,
                            status: "created",
                            location: obj.location,
                        })

                        result.objects.push(obj)
                    } catch (error) {
                        updateFileStatus(file, {
                            status: "error",
                            progress: 100,
                            message: error instanceof Error ? error.message : "Unknown error",
                        })

                        result.failedFiles.push({
                            name: file.name,
                            error: error instanceof Error ? error.message : "Unknown error",
                            status: "failed",
                            location: file.webkitRelativePath || file.name,
                            type: typeId ? typeId : null,
                        })

                        result.success = false
                    }
                })
            )
        }
    }

    const onUpload = async () => {
        if (!client || !files.length) return

        setState(UploadState.UPLOADING)

        const result: DocumentUploadResult = {
            success: true,
            objects: [],
            uploadedFiles: [],
            skippedFiles: [],
            failedFiles: [],
        }

        try {
            await processBatch(files, result)

            setFileStatuses((current) => {
                const pendingFiles = current.filter((status) => status.status === "pending")

                if (pendingFiles.length > 0) {
                    pendingFiles.forEach((status) => {
                        result.failedFiles.push({
                            name: status.file.name,
                            error: "Upload process interrupted",
                            status: "failed",
                            type: typeId ? typeId : null,
                        })
                    })
                    result.success = false
                }

                return current.map((status) =>
                    status.status === "pending"
                        ? { ...status, status: "error" as const, progress: 100, message: "Upload process interrupted" }
                        : status
                )
            })

            setUploadResult(result)
            setState(UploadState.DONE)
            onUploadDone(result.objects)
        } catch (error) {
            toast({
                status: "error",
                title: t("states.uploadFailed"),
                description: error instanceof Error ? error.message : "An unexpected error occurred",
                duration: 5000,
            })
            setState(UploadState.SELECT)
        }
    }

    const successCount = uploadResult?.uploadedFiles.length ?? 0
    const failedCount = uploadResult?.failedFiles.length ?? 0

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-xl">
                <DialogHeader>
                    <DialogTitle>
                        {state === UploadState.SELECT && t("upload.uploadDocuments")}
                        {state === UploadState.UPLOADING && t("upload.uploading")}
                        {state === UploadState.DONE && t("upload.uploadComplete")}
                    </DialogTitle>
                    <DialogDescription>
                        {state === UploadState.SELECT && t("upload.addFilesDescription")}
                        {state === UploadState.UPLOADING && t("upload.uploadingFiles", { count: files.length })}
                        {state === UploadState.DONE && (
                            failedCount > 0
                                ? `${successCount} uploaded, ${failedCount} failed`
                                : t("upload.uploadSuccess", { count: successCount })
                        )}
                    </DialogDescription>
                </DialogHeader>

                {state === UploadState.SELECT && (
                    <div className="flex flex-col gap-4">
                        {/* Drop Zone */}
                        <div
                            onPaste={handlePaste}
                            onDragOver={onDragOver}
                            onDragLeave={onDragLeave}
                            onDrop={onDrop}
                            onClick={() => !isAtLimit && fileInputRef.current?.click()}
                            className={cn(
                                "relative flex flex-col items-center justify-center gap-3 p-8 border-2 border-dashed rounded-xl cursor-pointer transition-all duration-200",
                                isDragging
                                    ? "border-primary bg-primary/5 scale-[1.01]"
                                    : "border-muted-foreground/25 hover:border-primary/50 hover:bg-muted/50",
                                isAtLimit && "opacity-50 cursor-not-allowed"
                            )}
                            role="button"
                            tabIndex={0}
                            aria-label="File upload area"
                            onKeyDown={(e) => {
                                if ((e.key === "Enter" || e.key === " ") && !isAtLimit) {
                                    e.preventDefault()
                                    fileInputRef.current?.click()
                                }
                            }}
                        >
                            <div className={cn(
                                "flex items-center justify-center size-14 rounded-full transition-colors",
                                isDragging ? "bg-primary/10" : "bg-muted"
                            )}>
                                <CloudUpload className={cn(
                                    "size-7 transition-colors",
                                    isDragging ? "text-primary" : "text-muted-foreground"
                                )} />
                            </div>
                            <div className="text-center">
                                <p className="text-sm font-medium">
                                    {isDragging ? "Drop files here" : t("upload.clickToBrowse")}
                                </p>
                                <p className="text-xs text-muted-foreground mt-1">
                                    {t("upload.pasteFromClipboard")}
                                </p>
                            </div>
                            <input
                                ref={fileInputRef}
                                type="file"
                                className="hidden"
                                multiple
                                onChange={handleUploadOnChange}
                                aria-label="Select files to upload"
                                disabled={isAtLimit}
                            />
                        </div>

                        {/* File Count & Limit Warning */}
                        {files.length > 0 && (
                            <div className="flex items-center justify-between text-sm">
                                <span className="text-muted-foreground">
                                    {t("upload.filesSelected", { count: files.length })}
                                    {maxFiles && <span className="text-muted-foreground/70"> (max {maxFiles})</span>}
                                </span>
                                {isAtLimit && (
                                    <span className="text-attention text-xs">
                                        {t("upload.fileLimitReached")}
                                    </span>
                                )}
                            </div>
                        )}

                        {/* File List */}
                        {files.length > 0 && (
                            <ScrollArea className="max-h-56">
                                <div className="flex flex-col gap-2">
                                    {files.map((file, index) => (
                                        <FileItem
                                            key={`${file.name}-${file.size}-${index}`}
                                            file={file}
                                            onRemove={() => removeFile(index)}
                                        />
                                    ))}
                                </div>
                            </ScrollArea>
                        )}
                    </div>
                )}

                {(state === UploadState.UPLOADING || state === UploadState.DONE) && (
                    <div className="flex flex-col gap-4">
                        {/* Progress Bar */}
                        <div className="flex flex-col gap-2">
                            <div className="flex justify-between items-center text-sm">
                                <span className="font-medium">
                                    {state === UploadState.UPLOADING ? t("upload.uploadingProgress") : t("upload.uploadComplete")}
                                </span>
                                <span className="text-muted-foreground">{overallProgress}%</span>
                            </div>
                            <Progress value={overallProgress} className={cn(
                                state === UploadState.DONE && failedCount > 0 && "[&>div]:bg-attention"
                            )} />
                        </div>

                        {/* File Status List */}
                        <ScrollArea className="max-h-72">
                            <div className="flex flex-col gap-2">
                                {fileStatuses.map((fileStatus, index) => (
                                    <FileStatusItem
                                        key={`${fileStatus.file.name}-${index}`}
                                        fileStatus={fileStatus}
                                    />
                                ))}
                            </div>
                        </ScrollArea>
                    </div>
                )}

                <DialogFooter>
                    <div className="flex justify-end items-center w-full gap-3">
                        {state === UploadState.SELECT && (
                            <>
                                <Button variant="outline" onClick={handleClose}>
                                    {t("actions.cancel")}
                                </Button>
                                <Button onClick={onUpload} disabled={!files.length}>
                                    {t("upload.uploadDocuments")} {files.length > 0 && `(${files.length})`}
                                </Button>
                            </>
                        )}

                        {state === UploadState.UPLOADING && (
                            <Button variant="outline" disabled>
                                <Loader2 className="size-4 animate-spin" />
                                {t("upload.uploading")}
                            </Button>
                        )}

                        {state === UploadState.DONE && (
                            <Button onClick={handleClose}>
                                {t("actions.done")}
                            </Button>
                        )}
                    </div>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}
