import { useState, useEffect, useCallback, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Heart, Loader2 } from "lucide-react"
import { DocumentThumbnailWithModal } from "@/components/widgets/DocumentThumbnailWithModal"
import { ItemsDataTable } from "@/components/widgets/ItemsDataTable"
import { ViewModeSwitcher, ViewMode } from "@/components/widgets/ViewModeSwitcher"
import { LAST_VIEW_MODE } from "@/constants/cookies"
import { useFavorites } from "@/contexts/FavoritesContext"
import { findFavoritesCollection, fetchFavoriteDocuments } from "@/lib/favorites"

export function FavoritesPanel() {
    const { t } = useTranslation(["common"])
    const { client, user } = useUserSession()
    const toast = useToast()
    const { favoriteIds } = useFavorites()

    const [documents, setDocuments] = useState<ContentObjectItem[]>([])
    const [loading, setLoading] = useState(true)
    const [viewMode, setViewMode] = useState<ViewMode>(() => {
        const saved = localStorage.getItem(LAST_VIEW_MODE)
        return (saved === "grid" || saved === "table") ? saved : "grid"
    })

    const handleViewModeChange = (mode: ViewMode) => {
        localStorage.setItem(LAST_VIEW_MODE, mode)
        setViewMode(mode)
    }

    const loadFavorites = useCallback(async () => {
        if (!client || !user?.sub) {
            setLoading(false)
            return
        }
        setLoading(true)
        try {
            const collectionId = await findFavoritesCollection(client, user.sub)
            if (!collectionId) {
                setDocuments([])
                return
            }
            const docs = await fetchFavoriteDocuments(client, collectionId)
            setDocuments(docs)
        } catch (error: any) {
            toast({
                status: "error",
                title: t("common:favorites.loadError"),
                description: error?.message,
                duration: 3000,
            })
        } finally {
            setLoading(false)
        }
    }, [client, user?.sub, toast, t])

    useEffect(() => {
        loadFavorites()
    }, [loadFavorites])

    // Reflect live unfavorites (heart toggle) by filtering against the shared set.
    const visibleDocuments = useMemo(
        () => documents.filter((doc) => favoriteIds.has(doc.id)),
        [documents, favoriteIds],
    )

    return (
        <div className="flex flex-col h-full gap-4 p-2">
            {/* Header */}
            <div className="flex items-center justify-between gap-4">
                <div className="flex flex-col">
                    <h1 className="text-xl font-semibold">{t("common:favorites.title")}</h1>
                    <p className="text-sm text-muted-foreground">
                        {user?.name ? t("common:favorites.descriptionUser", { name: user.name }) : t("common:favorites.description")}
                    </p>
                </div>
                <ViewModeSwitcher value={viewMode} onValueChange={handleViewModeChange} />
            </div>

            {/* Content */}
            <div className="flex-1 overflow-auto">
                {loading ? (
                    <div className="flex items-center justify-center h-full">
                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                    </div>
                ) : visibleDocuments.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
                        <Heart className="h-12 w-12 mb-4" />
                        <p className="text-lg font-medium">{t("common:favorites.empty")}</p>
                        <p className="text-sm mt-1">{t("common:favorites.emptyHelp")}</p>
                    </div>
                ) : viewMode === "grid" ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 items-start">
                        {visibleDocuments.map((doc) => (
                            <DocumentThumbnailWithModal
                                key={doc.id}
                                document={doc}
                                showDetails={true}
                                showHoverInfo={false}
                            />
                        ))}
                    </div>
                ) : (
                    <ItemsDataTable
                        items={visibleDocuments.map((doc) => ({ ...doc, itemType: "document" as const }))}
                    />
                )}
            </div>
        </div>
    )
}
