import { useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { TypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { FileText, File, Image as ImageIcon, Video, Music, Archive, FileCode, Check } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"
import { Checkbox } from "@/components/ui/checkbox"
import { formatRelativeDate } from "@/lib/date"
import { retrieveRendition } from "@/lib/rendition"
import { cn } from "@/lib/utils"

interface DocumentThumbnailProps {
    document: ContentObjectItem
    typeRegistry?: TypeRegistry
    selected?: boolean
    onToggleSelection?: () => void
    selectionEnabled?: boolean
    alreadySelected?: boolean
}

export function DocumentThumbnail({ document, typeRegistry, selected = false, onToggleSelection, selectionEnabled = false, alreadySelected = false }: DocumentThumbnailProps) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const toast = useToast()
    const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
    const [thumbnailAlt, setThumbnailAlt] = useState<string>("")
    const [imageError, setImageError] = useState(false)

    useEffect(() => {
        if (client && document) {
            retrieveRendition(
                client,
                document,
                setThumbnailUrl,
                setThumbnailAlt,
                toast,
                512
            ).catch(() => {
                setImageError(true)
            })
        }
    }, [document.id, client, toast])

    const getFileIcon = () => {
        const mime = document.content?.type?.toLowerCase() || ""
        const type = document.type?.id?.toLowerCase() || ""

        if (mime.startsWith("image/") || type === "image") {
            return <ImageIcon className="h-8 w-8 text-chart-2" />
        }
        if (mime.startsWith("video/") || type === "video") {
            return <Video className="h-8 w-8 text-chart-4" />
        }
        if (mime.startsWith("audio/") || type === "audio") {
            return <Music className="h-8 w-8 text-chart-5" />
        }
        if (mime.includes("pdf") || type === "pdf") {
            return <FileText className="h-8 w-8 text-chart-1" />
        }
        if (mime.includes("zip") || mime.includes("tar") || mime.includes("rar") || type === "archive") {
            return <Archive className="h-8 w-8 text-chart-5" />
        }
        if (mime.includes("code") || mime.includes("javascript") || mime.includes("typescript") || type === "code") {
            return <FileCode className="h-8 w-8 text-chart-3" />
        }
        return <File className="h-8 w-8 text-muted-foreground" />
    }

    const hasRendition = () => {
        const mime = document.content?.type?.toLowerCase() || ""
        const type = document.type?.id?.toLowerCase() || ""
        return mime.startsWith("image/") || type === "image" ||
               mime.startsWith("video/") || type === "video" ||
               mime.includes("pdf") || type === "pdf"
    }

    const showThumbnail = hasRendition() && thumbnailUrl && !imageError

    const handleCheckboxClick = (e: React.MouseEvent) => {
        e.stopPropagation()
        e.preventDefault()
        if (!alreadySelected) {
            onToggleSelection?.()
        }
    }

    const thumbnailContent = (
        <div className={cn(
            "ecm-tile border overflow-hidden hover:shadow-md transition-all cursor-pointer group rounded-sm",
            selected && "ring-2 ring-primary ring-offset-2",
            alreadySelected && "opacity-50"
        )}>
            <div className={cn(
                "relative w-full aspect-square bg-muted flex items-center justify-center overflow-hidden",
                showThumbnail && "bg-transparent"
            )}>
                {showThumbnail ? (
                    <img
                        src={thumbnailUrl}
                        alt={thumbnailAlt || document.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                        onError={() => setImageError(true)}
                    />
                ) : (
                    <div className="text-muted-foreground group-hover:text-foreground transition-colors">
                        {getFileIcon()}
                    </div>
                )}

                {/* Selection Checkbox */}
                {selectionEnabled && (
                    <div
                        className={cn(
                            "absolute top-2 left-2 z-10",
                            !selected && !alreadySelected && "opacity-50 group-hover:opacity-100 transition-opacity duration-200"
                        )}
                        onClick={handleCheckboxClick}
                    >
                        {alreadySelected ? (
                            <div className="w-6 h-6 rounded bg-muted text-muted-foreground flex items-center justify-center">
                                <Check className="h-4 w-4" />
                            </div>
                        ) : (
                            <Checkbox
                                checked={selected}
                                onCheckedChange={() => onToggleSelection?.()}
                                onClick={(e) => e.stopPropagation()}
                                className="bg-background/80"
                            />
                        )}
                    </div>
                )}

                {/* Type Badge */}
                <div className="absolute top-2 right-2">
                    <Badge className="bg-primary/90 text-primary-foreground backdrop-blur-sm shadow-lg text-xs">
                        {typeRegistry?.getTypeName(document.type?.id || "") || document.type?.name || t("document")}
                    </Badge>
                </div>
            </div>
            <div className="p-3">
                <div className="flex flex-col gap-1">
                    <p className="text-sm font-medium truncate" title={document.name}>
                        {document.name}
                    </p>
                    {document.created_at && (
                        <span className="text-xs text-muted-foreground">
                            {formatRelativeDate(document.created_at)}
                        </span>
                    )}
                </div>
            </div>
        </div>
    )

    return (
        <DocumentOverlay documentId={document.id}>
            {thumbnailContent}
        </DocumentOverlay>
    )
}
