import { SchemaFormRenderer } from "@/features/agents/components/SchemaFormRenderer"
import { FieldDefinition } from "@/features/agents/utils/schemaParser"

interface AgentParametersPanelProps {
    fields: FieldDefinition[]
    formData: Record<string, any>
    errors: Record<string, string>
    onChange: (fieldName: string, value: any) => void
}

export function AgentParametersPanel({ fields, formData, errors, onChange }: Readonly<AgentParametersPanelProps>) {
    return (
        <div className="flex-1 overflow-y-auto mt-4">
            <SchemaFormRenderer
                fields={fields}
                formData={formData}
                errors={errors}
                onChange={onChange}
            />
        </div>
    )
}
