import { useState, useEffect, useMemo, useCallback } from "react"
import { useTranslation } from "react-i18next"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Check, ChevronsUpDown, Loader2, Settings2 } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command"
import { Label } from "@/components/ui/label"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { PropertyListEditor } from "@/features/settings/PropertyListEditor"
import { cn } from "@/lib/utils"
import { PropertyConfig } from "@/models/property"

interface TypeOption {
    id: string
    name: string
}

interface TypePropertiesSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: {
        basicProperties: Record<string, PropertyConfig[]>
        advancedProperties: Record<string, PropertyConfig[]>
    }) => void
    loading?: boolean
}

export function TypePropertiesSection({ settings, onSave, loading }: Readonly<TypePropertiesSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const [types, setTypes] = useState<TypeOption[]>([])
    const [isLoadingTypes, setIsLoadingTypes] = useState(true)
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")
    const [selectedTypeId, setSelectedTypeId] = useState<string | null>(null)

    const [basicProperties, setBasicProperties] = useState<Record<string, PropertyConfig[]>>(() => {
        if (settings?.BASIC_PROPERTIES && typeof settings.BASIC_PROPERTIES === "object") {
            return structuredClone(settings.BASIC_PROPERTIES)
        }
        return {}
    })

    const [advancedProperties, setAdvancedProperties] = useState<Record<string, PropertyConfig[]>>(() => {
        if (settings?.ADVANCED_PROPERTIES && typeof settings.ADVANCED_PROPERTIES === "object") {
            return structuredClone(settings.ADVANCED_PROPERTIES)
        }
        return {}
    })

    const configuredTypeIds = useMemo(() => {
        const ids = new Set<string>()
        for (const [typeId, props] of Object.entries(basicProperties)) {
            if (props.length > 0) ids.add(typeId)
        }
        for (const [typeId, props] of Object.entries(advancedProperties)) {
            if (props.length > 0) ids.add(typeId)
        }
        return ids
    }, [basicProperties, advancedProperties])

    useEffect(() => {
        if (!client) return
        const fetchTypes = async () => {
            setIsLoadingTypes(true)
            try {
                const typesList = await client.types.list()
                const typeOptions: TypeOption[] = typesList.map((type: unknown) => {
                    const t = type as { id: string; name?: string }
                    return {
                        id: t.id,
                        name: typeRegistry?.getTypeName(t.id) || t.name || t.id,
                    }
                })
                typeOptions.sort((a, b) => a.name.localeCompare(b.name))
                setTypes(typeOptions)
            } catch (error) {
                console.error("Failed to fetch types:", error)
                setTypes([])
            } finally {
                setIsLoadingTypes(false)
            }
        }
        fetchTypes()
    }, [client, typeRegistry])

    const selectedType = useMemo(() => {
        return types.find((t) => t.id === selectedTypeId) ?? null
    }, [types, selectedTypeId])

    const handleSelectType = (typeId: string) => {
        setSelectedTypeId(typeId)
        setOpen(false)
        setSearch("")
        if (!basicProperties[typeId]) {
            setBasicProperties((prev) => ({ ...prev, [typeId]: [] }))
        }
        if (!advancedProperties[typeId]) {
            setAdvancedProperties((prev) => ({ ...prev, [typeId]: [] }))
        }
    }

    const handleAddProperty = useCallback((category: "basic" | "advanced", path: string, label: string) => {
        if (!selectedTypeId) return
        const setter = category === "basic" ? setBasicProperties : setAdvancedProperties
        setter((prev) => ({
            ...prev,
            [selectedTypeId]: [...(prev[selectedTypeId] ?? []), { path, label }],
        }))
    }, [selectedTypeId])

    const handleRemoveProperty = useCallback((category: "basic" | "advanced", index: number) => {
        if (!selectedTypeId) return
        const setter = category === "basic" ? setBasicProperties : setAdvancedProperties
        setter((prev) => ({
            ...prev,
            [selectedTypeId]: prev[selectedTypeId].filter((_, i) => i !== index),
        }))
    }, [selectedTypeId])

    const handlePropertyChange = useCallback((category: "basic" | "advanced", index: number, field: keyof PropertyConfig, value: string) => {
        if (!selectedTypeId) return
        const setter = category === "basic" ? setBasicProperties : setAdvancedProperties
        setter((prev) => ({
            ...prev,
            [selectedTypeId]: prev[selectedTypeId].map((prop, i) => {
                if (i !== index) return prop
                if (field === "modifier") {
                    if (value === "none") {
                        const { modifier: _, ...rest } = prop
                        return rest
                    }
                    return { ...prop, modifier: value as PropertyConfig["modifier"] }
                }
                return { ...prop, [field]: value }
            }),
        }))
    }, [selectedTypeId])

    const cleanProperties = (props: Record<string, PropertyConfig[]>): Record<string, PropertyConfig[]> => {
        const cleaned: Record<string, PropertyConfig[]> = {}
        for (const [typeId, configs] of Object.entries(props)) {
            const validConfigs = configs.filter((c) => c.path.trim() !== "")
            if (validConfigs.length > 0) {
                cleaned[typeId] = validConfigs.map((c) => {
                    const config: PropertyConfig = { path: c.path.trim() }
                    if (c.label?.trim()) config.label = c.label.trim()
                    if (c.modifier) config.modifier = c.modifier
                    return config
                })
            }
        }
        return cleaned
    }

    const handleSave = () => {
        onSave({
            basicProperties: cleanProperties(basicProperties),
            advancedProperties: cleanProperties(advancedProperties),
        })
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:properties.title")}</CardTitle>
                <CardDescription>
                    {t("settings:properties.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:properties.documentType")}</Label>
                    {isLoadingTypes ? (
                        <div className="flex h-9 w-full items-center justify-center rounded-md border border-input bg-popover px-3 py-2">
                            <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                        </div>
                    ) : (
                        <Popover open={open} onOpenChange={setOpen}>
                            <PopoverTrigger asChild>
                                <Button
                                    variant="outline"
                                    role="combobox"
                                    aria-expanded={open}
                                    className="w-full justify-between font-normal bg-popover"
                                >
                                    <span className="truncate">
                                        {selectedType ? selectedType.name : t("settings:properties.selectTypePlaceholder")}
                                    </span>
                                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="p-0" align="start" style={{ width: "var(--radix-popover-trigger-width)" }}>
                                <Command>
                                    <CommandInput
                                        placeholder={t("settings:properties.searchTypes")}
                                        value={search}
                                        onValueChange={setSearch}
                                    />
                                    <CommandList>
                                        <CommandEmpty>{t("settings:properties.noTypeFound")}</CommandEmpty>
                                        <CommandGroup>
                                            {types.map((type) => (
                                                <CommandItem
                                                    key={type.id}
                                                    value={type.name}
                                                    onSelect={() => handleSelectType(type.id)}
                                                >
                                                    <Check
                                                        className={cn(
                                                            "mr-2 h-4 w-4",
                                                            selectedTypeId === type.id ? "opacity-100" : "opacity-0"
                                                        )}
                                                    />
                                                    <span className="flex-1 truncate">{type.name}</span>
                                                    {configuredTypeIds.has(type.id) && (
                                                        <Settings2 className="ml-2 h-3.5 w-3.5 text-primary" />
                                                    )}
                                                </CommandItem>
                                            ))}
                                        </CommandGroup>
                                    </CommandList>
                                </Command>
                            </PopoverContent>
                        </Popover>
                    )}
                    <p className="text-sm text-muted-foreground">
                        {t("settings:properties.selectTypeHelp")} <Settings2 className="inline h-3.5 w-3.5 text-primary" />
                    </p>
                </div>

                {configuredTypeIds.size > 0 && (
                    <div className="flex flex-wrap gap-1.5">
                        {types
                            .filter((t) => configuredTypeIds.has(t.id))
                            .map((type) => (
                                <Badge
                                    key={type.id}
                                    variant={selectedTypeId === type.id ? "default" : "secondary"}
                                    className="cursor-pointer"
                                    onClick={() => handleSelectType(type.id)}
                                >
                                    {type.name}
                                </Badge>
                            ))}
                    </div>
                )}

                {selectedTypeId && (
                    <div className="flex flex-col gap-4 rounded-lg border p-4">
                        <div className="flex flex-col">
                            <Label className="text-sm font-semibold">{selectedType?.name ?? selectedTypeId}</Label>
                            {selectedType && selectedType.name !== selectedTypeId && (
                                <span className="text-xs text-muted-foreground">{selectedTypeId}</span>
                            )}
                        </div>

                        <div className="flex flex-col gap-2">
                            <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{t("settings:properties.basicProperties")}</Label>
                            <PropertyListEditor
                                typeId={selectedTypeId}
                                properties={basicProperties[selectedTypeId] ?? []}
                                onAdd={(path, label) => handleAddProperty("basic", path, label)}
                                onRemove={(index) => handleRemoveProperty("basic", index)}
                                onChange={(index, field, value) => handlePropertyChange("basic", index, field, value)}
                            />
                        </div>

                        <div className="flex flex-col gap-2">
                            <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{t("settings:properties.advancedProperties")}</Label>
                            <PropertyListEditor
                                typeId={selectedTypeId}
                                properties={advancedProperties[selectedTypeId] ?? []}
                                onAdd={(path, label) => handleAddProperty("advanced", path, label)}
                                onRemove={(index) => handleRemoveProperty("advanced", index)}
                                onChange={(index, field, value) => handlePropertyChange("advanced", index, field, value)}
                            />
                        </div>
                    </div>
                )}
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={handleSave} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
