import { useEffect, useState, ReactNode } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem, InteractionRef } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useNavigate, useParams } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { Info, MessageSquare, Pencil, RotateCcw, PanelRightOpen, PanelRightClose, Loader2 } from "lucide-react"
import { ShareDocumentButton } from "@/components/buttons/ShareDocumentButton"
import { DocumentDisplay } from "@/components/displays/DocumentDisplay"
import { ChatPanel } from "@/components/panels/ChatPanel"
import { NoAvailablePanel } from "@/components/panels/NoAvailablePanel"
import { PropertiesPanel } from "@/components/panels/PropertiesPanel"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { LAST_PANEL_STATE } from "@/constants/cookies"
import { useBreadcrumbLabel } from "@/contexts/BreadcrumbContext"
import { DocumentActions } from "@/features/document/DocumentActions"
import { useRecentlyViewed } from "@/hooks/use-recently-viewed"
import { isOfficeFile, isMsFile, isOctetStream } from "@/lib/mime"
import { retrievePdfRendition } from "@/lib/rendition"
import { isAdmin } from "@/lib/user"

interface DocumentPanelProps {
    children?: ReactNode
    id?: string
    onDeleteDone?: () => void
}
export function DocumentPanel({ id: propId, children, onDeleteDone }: Readonly<DocumentPanelProps>) {
    const { t } = useTranslation("common")
    const params = useParams()
    const { client, isLoading, user } = useUserSession()
    const navigate = useNavigate()
    const toast = useToast()

    const { recordView } = useRecentlyViewed()
    const isAdminUser = isAdmin(user)
    const isDeleteDocumentDisabled = !isAdminUser

    const id = propId || params.id

    const [isSidebarOpen, setIsSidebarOpen] = useState(localStorage.getItem(LAST_PANEL_STATE) === "open")

    const [documentObj, setDocumentObj] = useState<ContentObjectItem | undefined>(undefined)
    const [documentUrl, setDocumentUrl] = useState<string | undefined>(undefined)
    const [documentType, setDocumentType] = useState<string | undefined>(undefined)
    const [activeTab, setActiveTab] = useState("properties")
    const [chatInteractionId, setChatInteractionId] = useState<string | undefined>(undefined)
    const [documentInteractions, setDocumentInteractions] = useState<InteractionRef[]>([])
    const [chatResetTrigger, setChatResetTrigger] = useState(0)
    const [isEditingMetadata, setIsEditingMetadata] = useState(false)
    const [objectSchema, setObjectSchema] = useState<Record<string, any> | undefined>(undefined)

    // Register document name for breadcrumb display
    useBreadcrumbLabel(id, documentObj?.properties?.title || documentObj?.name)

    const navigateTo404 = () => {
        navigate("/404")
    }

    const searchDocument = () => {
        if (!client || isLoading) {
            return
        }

        client.objects
            .retrieve(id)
            .then((response) => {
                if (response) {
                    setDocumentObj(response)
                    if (isAdminUser && response.type?.id) {
                        client.store.types.retrieve(response.type.id)
                            .then((typeResponse) => {
                                setObjectSchema(typeResponse.object_schema)
                            })
                            .catch((error) => {
                                console.error("Failed to fetch type schema:", error)
                            })
                    }
                } else {
                    navigateTo404()
                }
            })
            .catch(() => {
                navigateTo404()
            })
    }

    const handleSidebarToggle = () => {
        const current = isSidebarOpen
        localStorage.setItem(LAST_PANEL_STATE, current ? "closed" : "open")
        setIsSidebarOpen(!current)
    }

    const handleResetChat = () => {
        setChatResetTrigger(prev => prev + 1)
    }

    const handleEditMetadata = () => {
        setIsEditingMetadata(true)
        setActiveTab("properties")
        setIsSidebarOpen(true)
    }

    const handleSaveMetadata = async (updatedProperties: any) => {
        if (!client || !documentObj) {
            return
        }
        try {
            await client.objects.update(documentObj.id, { properties: updatedProperties })
            setDocumentObj({ ...documentObj, properties: updatedProperties })
            setIsEditingMetadata(false)
            toast({ status: "success", title: "Properties updated", description: "Document properties have been saved successfully." })
        } catch (error) {
            console.error("Failed to update properties:", error)
            toast({ status: "error", title: "Error", description: "Failed to save document properties." })
        }
    }

    const handleCancelEdit = () => {
        setIsEditingMetadata(false)
    }

    useEffect(() => {
        if (!client || isLoading || documentObj) {
            return
        }

        searchDocument()
    }, [id])

    useEffect(() => {
        if (!client || isLoading || !documentObj) {
            return
        }

        recordView(documentObj)

        if (documentObj.content) {
            const contentType = documentObj.content.type!

            // Check if the document is an Office, MS, or octet-stream file
            if (isOfficeFile(contentType) || isMsFile(contentType) || isOctetStream(contentType)) {
                // Retrieve PDF rendition for Office/MS/octet-stream files
                retrievePdfRendition(client, documentObj, setDocumentUrl, setDocumentType, toast, true)
            } else {
                // For other file types, use the original download URL
                client.objects.getDownloadUrl(documentObj.content.source!, undefined, "inline").then((response) => {
                    setDocumentUrl(response.url)
                    setDocumentType(contentType)
                })
            }
        }

        if (!chatInteractionId) {
            client.interactions
                .list({ query: { tags: ["chat"] } })
                .then((response) => {
                    if (response.length > 0) {
                        setChatInteractionId(response[0].id)
                    } else {
                        setChatInteractionId(undefined)
                    }
                })
                .catch(() => {
                    setChatInteractionId(undefined)
                })
        }

        if (!documentInteractions.length) {
            client.interactions
                .list({ query: { tags: ["document"] } })
                .then((response) => {
                    setDocumentInteractions(response)
                })
                .catch(() => {
                    setDocumentInteractions([])
                })
        }
    }, [documentObj])

    if (!documentObj) {
        return <div></div>
    }

    // Use fixed padding when in document view context (id from params), responsive padding otherwise
    const isDocumentView = !propId
    const containerPadding = isDocumentView ? "p-2" : "p-2 sm:p-4 md:p-6"

    return (
        <div className={`flex flex-col h-full ${containerPadding} gap-2 sm:gap-3 md:gap-4`}>
            {/* Header Card */}
            <Card className="shadow-md bg-muted/50">
                <div className="flex items-center justify-between px-2 sm:px-3 md:px-4 py-2 sm:py-2.5 md:py-3">
                    <div className="flex items-center gap-2 sm:gap-3 flex-1 min-w-0">
                        <h1 className="text-sm sm:text-base md:text-lg font-semibold truncate">
                            {documentObj?.properties?.title || documentObj?.name || documentObj?.id}
                        </h1>
                    </div>
                    <div className="flex items-center gap-1 sm:gap-2">
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={handleSidebarToggle}
                            className="gap-1 sm:gap-2"
                        >
                            {isSidebarOpen ? <PanelRightClose className="h-4 w-4" /> : <PanelRightOpen className="h-4 w-4" />}
                            <span className="hidden sm:inline">{isSidebarOpen ? t("actions.hideInfo") : t("actions.showInfo")}</span>
                        </Button>
                        {isAdminUser && objectSchema && (
                            <Button
                                variant="ghost"
                                size="sm"
                                onClick={handleEditMetadata}
                                className="gap-1 sm:gap-2"
                                disabled={isEditingMetadata}
                            >
                                <Pencil className="h-4 w-4" />
                                <span className="hidden sm:inline">{t("actions.editProperties")}</span>
                            </Button>
                        )}
                        <ShareDocumentButton object={documentObj} variant="ghost" text="Share" />
                        <DocumentActions
                            document={documentObj}
                            disableDeleteDocument={isDeleteDocumentDisabled}
                            onDeleteDone={onDeleteDone}
                        />
                        {children}
                    </div>
                </div>
            </Card>

            {/* Content Area */}
            <div className="flex flex-col md:flex-row flex-1 gap-2 sm:gap-3 md:gap-4 min-h-0">
                {/* Document Display Card - Hidden on mobile when sidebar is open */}
                <Card className={`${isSidebarOpen ? "hidden md:flex" : "flex"} flex-1 items-center justify-center shadow-md  bg-muted/50`}>
                    <div className="w-full h-full overflow-hidden">
                        {
                            (documentUrl && documentType) ? (
                                <DocumentDisplay
                                    key={`${documentObj.id}-${isSidebarOpen}`}
                                    documentId={documentObj.id}
                                    name={documentObj.name}
                                    type={documentType}
                                    url={documentUrl}
                                />
                            ) : documentObj.content ? (
                                <div className="text-muted-foreground flex items-center justify-center h-full">
                                    <Loader2 className="h-6 w-6 animate-spin" />
                                </div>
                            ) : (
                                <div className="text-muted-foreground flex items-center justify-center h-full">{t("documentPanel.noContentSource")}</div>
                            )
                        }
                    </div>
                </Card>

                {/* Sidebar Card - Full height on mobile, fixed width on desktop */}
                {isSidebarOpen && (
                    <Card className="flex flex-col shadow-md w-full md:w-96 flex-1 md:flex-initial bg-muted/50 overflow-hidden">
                        <Tabs value={activeTab} onValueChange={setActiveTab} className="flex flex-col h-full">
                            <div className="p-3 sm:p-4 pb-0">
                                <TabsList className="grid w-full grid-cols-2">
                                    <TabsTrigger value="properties" className="gap-1 sm:gap-2 text-xs sm:text-sm">
                                        <Info className="h-3 w-3 sm:h-4 sm:w-4" />
                                        <span className="xs:inline">{t("documentPanel.properties")}</span>
                                    </TabsTrigger>
                                    {
                                        (chatInteractionId) && (
                                            <TabsTrigger value="chat" className="gap-1 sm:gap-2 text-xs sm:text-sm">
                                                <MessageSquare className="h-3 w-3 sm:h-4 sm:w-4" />
                                                {t("documentPanel.chat")}
                                            </TabsTrigger>
                                        )
                                    }
                                </TabsList>
                            </div>

                            {/* Tab Actions */}
                            {activeTab === "chat" && chatInteractionId && (
                                <>
                                    <Separator />
                                    <div className="px-3 sm:px-4 py-2 flex justify-end">
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            onClick={handleResetChat}
                                            className="gap-1 sm:gap-2 text-xs sm:text-sm"
                                        >
                                            <RotateCcw className="h-3 w-3 sm:h-4 sm:w-4" />
                                            <span className="hidden sm:inline">{t("actions.resetChat")}</span>
                                            <span className="sm:hidden">{t("actions.reset")}</span>
                                        </Button>
                                    </div>
                                </>
                            )}

                            <Separator />

                            <div className="flex-1 overflow-hidden">
                                <TabsContent value="properties" className="h-full m-0 p-0">
                                    <div className="h-full overflow-y-auto p-3 sm:p-4">
                                        <PropertiesPanel
                                            value={documentObj.properties ?? {}}
                                            document={documentObj}
                                            isEditMode={isEditingMetadata}
                                            objectSchema={objectSchema}
                                            onSave={handleSaveMetadata}
                                            onCancel={handleCancelEdit}
                                        />
                                    </div>
                                </TabsContent>

                                <TabsContent value="chat" className="h-full m-0 p-0">
                                    <div className="h-full overflow-y-auto">
                                        {
                                            (chatInteractionId && documentObj) ? (
                                                <ChatPanel
                                                    key={documentObj.id}
                                                    document={documentObj}
                                                    interactionId={chatInteractionId}
                                                    resetTrigger={chatResetTrigger}
                                                />
                                            ) : (
                                                <div className="p-3 sm:p-4">
                                                    <NoAvailablePanel>No Chat available for this document.</NoAvailablePanel>
                                                </div>
                                            )
                                        }
                                    </div>
                                </TabsContent>
                            </div>
                        </Tabs>
                    </Card>
                )}
            </div>
        </div>
    )
}