import { useTranslation } from "react-i18next"
import { basicFacets } from "@/constants/facets"
import { Facet, FacetsEditor } from "@/features/settings/FacetsEditor"

interface BasicFiltersSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: { basicFacets: Facet[] }) => void
    loading?: boolean
}

export function BasicFiltersSection({ settings, onSave, loading }: Readonly<BasicFiltersSectionProps>) {
    const { t } = useTranslation("settings")
    const initialFacets = Array.isArray(settings?.BASIC_FACETS) ? settings.BASIC_FACETS : basicFacets

    return (
        <FacetsEditor
            title={t("basicFilters.title")}
            description={t("basicFilters.description")}
            initialFacets={initialFacets}
            onSave={(facets) => onSave({ basicFacets: facets })}
            loading={loading}
        />
    )
}
