import { useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { useUserSession } from "@vertesia/ui/session"
import { FileText, Loader2 } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"

interface DocumentBadgeProps {
    documentId: string
}

export function DocumentBadge({ documentId }: Readonly<DocumentBadgeProps>) {
    const { t } = useTranslation("executions")
    const { client } = useUserSession()
    const [name, setName] = useState<string | null>(null)
    const [isLoading, setIsLoading] = useState(true)

    useEffect(() => {
        if (!client || !documentId) {
            setIsLoading(false)
            return
        }

        client.store.objects.retrieve(documentId)
            .then((doc) => {
                setName(doc.name || documentId)
            })
            .catch(() => {
                setName(documentId)
            })
            .finally(() => {
                setIsLoading(false)
            })
    }, [client, documentId])

    return (
        <DocumentOverlay documentId={documentId} className="min-w-0 max-w-full">
            <Badge variant="secondary" className="text-xs cursor-pointer hover:bg-secondary/80 gap-1 min-w-0 max-w-full overflow-hidden">
                {isLoading ? (
                    <Loader2 className="h-3 w-3 flex-shrink-0 animate-spin" />
                ) : (
                    <FileText className="h-3 w-3 flex-shrink-0" />
                )}
                <span className="truncate min-w-0">{isLoading ? t("documentLoading") : name}</span>
            </Badge>
        </DocumentOverlay>
    )
}
