import { JSONSchema } from "@vertesia/common"

export interface FieldDefinition {
    name: string
    type: "string" | "number" | "boolean" | "enum" | "array" | "object"
    label: string
    description?: string
    required: boolean
    default?: any
    options?: string[]
    editor?: string
    itemsType?: string
    /** Nested properties for object type fields */
    properties?: FieldDefinition[]
    /** Schema for array items (for arrays of objects) */
    itemsSchema?: FieldDefinition[]
    validation?: {
        min?: number
        max?: number
        pattern?: string
        minLength?: number
        maxLength?: number
    }
}

function toTitleCase(str: string): string {
    return str
        .replace(/([A-Z])/g, " $1")
        .replace(/^./, (s) => s.toUpperCase())
        .replace(/_/g, " ")
        .trim()
}

function detectFieldType(property: JSONSchema): "string" | "number" | "boolean" | "enum" | "array" | "object" {
    if (property.enum && property.enum.length > 0) {
        return "enum"
    }

    if (property.type === "boolean") {
        return "boolean"
    }

    if (property.type === "number" || property.type === "integer") {
        return "number"
    }

    if (property.type === "array") {
        return "array"
    }

    if (property.type === "object") {
        return "object"
    }

    return "string"
}

function extractValidation(property: JSONSchema) {
    return {
        min: property.minimum,
        max: property.maximum,
        pattern: property.pattern,
        minLength: property.minLength,
        maxLength: property.maxLength,
    }
}

/**
 * Parse a single property into a FieldDefinition
 */
function parseProperty(name: string, prop: JSONSchema, isRequired: boolean): FieldDefinition {
    const property = prop as JSONSchema & { editor?: string }
    const fieldType = detectFieldType(property)

    // Get items type for arrays
    let itemsType: string | undefined
    let itemsSchema: FieldDefinition[] | undefined

    if (property.type === "array" && property.items) {
        const items = property.items as JSONSchema & { editor?: string }
        itemsType = items.type as string

        // If array items are objects, parse their schema
        if (items.type === "object" && items.properties) {
            const itemRequired = items.required || []
            itemsSchema = Object.entries(items.properties).map(([itemName, itemProp]) =>
                parseProperty(itemName, itemProp as JSONSchema, itemRequired.includes(itemName))
            )
        }
    }

    // Get nested properties for object type
    let nestedProperties: FieldDefinition[] | undefined
    if (property.type === "object" && property.properties) {
        const nestedRequired = property.required || []
        nestedProperties = Object.entries(property.properties).map(([propName, propValue]) =>
            parseProperty(propName, propValue as JSONSchema, nestedRequired.includes(propName))
        )
    }

    return {
        name,
        type: fieldType,
        label: property.title || toTitleCase(name),
        description: property.description,
        required: isRequired,
        default: property.default,
        options: property.enum as string[] | undefined,
        editor: property.editor,
        itemsType,
        itemsSchema,
        properties: nestedProperties,
        validation: extractValidation(property),
    }
}

export function parseSchema(schema: JSONSchema | null | undefined): FieldDefinition[] {
    if (!schema || !schema.properties) {
        return []
    }

    const properties = schema.properties
    const required = schema.required || []

    return Object.entries(properties).map(([name, prop]) =>
        parseProperty(name, prop as JSONSchema, required.includes(name))
    )
}
