import { useLayoutEffect, useRef, useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"

const MAX_VISIBLE_TAGS = 3

interface InteractionTagsProps {
    tags: string[]
}
export function InteractionTags({ tags }: Readonly<InteractionTagsProps>) {
    const containerRef = useRef<HTMLDivElement>(null)
    const [visibleCount, setVisibleCount] = useState(tags.length)

    useLayoutEffect(() => {
        const container = containerRef.current
        if (!container) return

        const tagElements = Array.from(container.querySelectorAll("[data-tag]")) as HTMLElement[]
        if (tagElements.length === 0) return

        const containerRight = container.getBoundingClientRect().right
        const moreButtonWidth = 80

        let count = 0
        for (const tag of tagElements) {
            const tagRight = tag.getBoundingClientRect().right
            const hasMore = count < tags.length - 1
            const availableSpace = hasMore ? containerRight - moreButtonWidth : containerRight

            if (tagRight <= availableSpace) {
                count++
            } else {
                break
            }
        }

        setVisibleCount(Math.max(1, Math.min(count, MAX_VISIBLE_TAGS)))
    }, [tags])

    const visibleTags = tags.slice(0, visibleCount)
    const hiddenTags = tags.slice(visibleCount)

    return (
        <div ref={containerRef} className="mt-3 flex flex-nowrap gap-2 overflow-hidden">
            {
                visibleTags.map((tag) => (
                    <Badge key={tag} data-tag className="text-xs px-2 py-1 rounded-full whitespace-nowrap">
                        {tag}
                    </Badge>
                ))
            }
            {hiddenTags.length > 0 && (
                <Tooltip>
                    <TooltipTrigger asChild>
                        <Badge variant="secondary" className="text-xs px-2 py-1 rounded-full whitespace-nowrap cursor-default">
                            +{hiddenTags.length} more
                        </Badge>
                    </TooltipTrigger>
                    <TooltipContent className="bg-primary-foreground border p-2">
                        <div className="grid grid-cols-3 gap-1">
                            {
                                hiddenTags.map((tag) => (
                                    <Badge key={tag} className="text-xs px-2 py-1 rounded-full whitespace-nowrap">
                                        {tag}
                                    </Badge>
                                ))
                            }
                        </div>
                    </TooltipContent>
                </Tooltip>
            )}
        </div>
    )
}