import { useEffect, useMemo, useState } from "react"
import { useTranslation } from "react-i18next"
import { AsyncConversationExecutionPayload, Interaction, InteractionRefWithSchema, mergePromptsSchema } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useLocation, useNavigate, useParams } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { ArrowLeft, ArrowRight, Bot, icons } from "lucide-react"
import { Button } from "@/components/ui/button"
import { AgentCreationHeaderPanel } from "@/features/agents/components/AgentCreationHeaderPanel"
import { AgentDetailsPanel } from "@/features/agents/components/AgentDetailsPanel"
import { AgentExecutionDonePanel } from "@/features/agents/components/AgentExecutionDonePanel"
import { AgentPanelHeaderPanel } from "@/features/agents/components/AgentPanelHeaderPanel"
import { AgentParametersPanel } from "@/features/agents/components/AgentParametersPanel"
import { AgentSummaryPanel } from "@/features/agents/components/AgentSummaryPanel"
import { DocumentMediaPanel } from "@/features/agents/components/DocumentMediaPanel"
import { ObjectSelectionPanel } from "@/features/agents/components/ObjectSelectionPanel"
import { validateFormData } from "@/features/agents/utils/formValidator"
import { FieldDefinition, parseSchema } from "@/features/agents/utils/schemaParser"
import { analyzeSteps, DynamicStep, getNormalFields, StepType } from "@/features/agents/utils/stepAnalyzer"

/**
 * Checks if a field value is properly set, including nested required properties for objects
 */
function isFieldValueValid(value: any, field: FieldDefinition): boolean {
    // Check if value is set at the top level
    if (value === null || value === undefined) {
        return false
    }

    // For string values, empty string means not set
    if (typeof value === "string" && value.trim() === "") {
        return false
    }

    // For arrays, empty array means not set
    if (Array.isArray(value) && value.length === 0) {
        return false
    }

    // For object types, check required sub-properties recursively
    if (field.type === "object" && field.properties && typeof value === "object" && !Array.isArray(value)) {
        for (const subField of field.properties) {
            if (subField.required) {
                const subValue = value[subField.name]
                if (!isFieldValueValid(subValue, subField)) {
                    return false
                }
            }
        }
    }

    // For arrays of objects, check each item's required properties
    if (field.type === "array" && field.itemsSchema && Array.isArray(value)) {
        for (const item of value) {
            if (item && typeof item === "object") {
                for (const subField of field.itemsSchema) {
                    if (subField.required) {
                        const subValue = item[subField.name]
                        if (!isFieldValueValid(subValue, subField)) {
                            return false
                        }
                    }
                }
            }
        }
    }

    return true
}

function parseDescriptionIcon(description: string | undefined): { iconName: string | null; cleanDescription: string } {
    if (!description) {
        return { iconName: null, cleanDescription: "No description available" }
    }

    const iconPattern = /^\[icon:([A-Za-z0-9]+)\]\s*/
    const match = description.match(iconPattern)

    if (match) {
        return {
            iconName: match[1],
            cleanDescription: description.replace(iconPattern, "").trimStart(),
        }
    }

    return { iconName: null, cleanDescription: description }
}

export function StartAgentPanel() {
    const { t } = useTranslation(["agents", "common"])
    const { client, isLoading: sessionLoading } = useUserSession()
    const appInstallation = useAppInstallation()
    const toast = useToast()
    const navigate = useNavigate()
    const location = useLocation()
    const id = useParams("id")

    const EXECUTION_CONTAINER = appInstallation?.settings?.EXECUTION_CONTAINER as string || undefined

    // Parse prefilled data from URL search params (for rerun functionality)
    const prefilledData = useMemo(() => {
        const searchParams = new URLSearchParams(location.search)
        const prefilled = searchParams.get("prefilled")
        if (prefilled) {
            try {
                return JSON.parse(decodeURIComponent(prefilled))
            } catch {
                return null
            }
        }
        return null
    }, [location.search])

    const [interaction, setInteraction] = useState<Interaction | null>(null)
    const [currentStepIndex, setCurrentStepIndex] = useState<number>(0)
    const [dynamicSteps, setDynamicSteps] = useState<DynamicStep[]>([])
    const [fields, setFields] = useState<FieldDefinition[]>([])
    const [normalFields, setNormalFields] = useState<FieldDefinition[]>([])

    const [executionName, setExecutionName] = useState("")
    const [executionDescription, setExecutionDescription] = useState("")
    const [formData, setFormData] = useState<Record<string, any>>({})
    const [errors, setErrors] = useState<Record<string, string>>({})

    const [isLoading, setIsLoading] = useState(true)
    const [isExecuting, setIsExecuting] = useState(false)
    const [executionError, setExecutionError] = useState<string | null>(null)
    const [notFound, setNotFound] = useState(false)

    const { iconName, cleanDescription } = useMemo(() => {
        const result = parseDescriptionIcon(interaction?.description)
        return {
            iconName: result.iconName,
            cleanDescription: result.cleanDescription === "No description available" ? t("agents:execution.noDescription") : result.cleanDescription
        }
    }, [interaction?.description, t])

    const IconComponent = useMemo(() => {
        if (iconName && iconName in icons) {
            return icons[iconName as keyof typeof icons]
        }
        return Bot
    }, [iconName])

    useEffect(() => {
        if (!client || sessionLoading || !id) {
            return
        }

        setIsLoading(true)
        client.interactions.retrieve(id)
            .then((response) => {
                setInteraction(response)
                const mergedPrompts = mergePromptsSchema(response as InteractionRefWithSchema)
                const parsedFields = parseSchema(mergedPrompts)
                setFields(parsedFields)

                // Analyze steps based on fields
                const steps = analyzeSteps(parsedFields)
                setDynamicSteps(steps)

                // Get normal fields (non-special)
                const normal = getNormalFields(parsedFields)
                setNormalFields(normal)

                // Initialize form data with defaults, then override with prefilled data if available
                const initialFormData: Record<string, any> = {}
                parsedFields.forEach((field) => {
                    if (field.default !== undefined) {
                        initialFormData[field.name] = field.default
                    }
                })

                // Apply prefilled data if available (for rerun functionality)
                if (prefilledData) {
                    if (prefilledData.formData) {
                        Object.assign(initialFormData, prefilledData.formData)
                    }
                    if (prefilledData.executionName) {
                        setExecutionName(prefilledData.executionName)
                    }
                    if (prefilledData.executionDescription) {
                        setExecutionDescription(prefilledData.executionDescription)
                    }
                }

                setFormData(initialFormData)
            })
            .catch((error) => {
                console.error("Failed to load interaction:", error)
                if (error.status === 404) {
                    setNotFound(true)
                } else {
                    toast({
                        status: "error",
                        title: "Failed to load interaction",
                        description: error.message,
                        duration: 4000
                    })
                }
            })
            .finally(() => {
                setIsLoading(false)
            })
    }, [client, sessionLoading, id, prefilledData])

    const currentStep = dynamicSteps[currentStepIndex]
    const currentStepType = currentStep?.type

    const canContinue = useMemo(() => {
        if (currentStepType === "details") {
            return executionName.trim() !== "" && executionDescription.trim() !== ""
        }

        // For field-based steps (document, documents, media, medias, object, objects)
        if (currentStep?.field && currentStep.fieldName) {
            const field = currentStep.field
            const value = formData[currentStep.fieldName]

            // If the field itself is required, validate it (including nested required properties)
            if (field.required) {
                if (!isFieldValueValid(value, field)) {
                    return false
                }
            }

            // For objects, also check nested required properties even if the parent is not required
            // (as long as a value exists)
            if (field.type === "object" && field.properties && value && typeof value === "object") {
                for (const subField of field.properties) {
                    if (subField.required) {
                        if (!isFieldValueValid(value[subField.name], subField)) {
                            return false
                        }
                    }
                }
            }

            // For arrays of objects, check each item's required properties
            if (field.type === "array" && field.itemsSchema && Array.isArray(value)) {
                for (const item of value) {
                    if (item && typeof item === "object") {
                        for (const subField of field.itemsSchema) {
                            if (subField.required) {
                                if (!isFieldValueValid(item[subField.name], subField)) {
                                    return false
                                }
                            }
                        }
                    }
                }
            }
        }

        // For parameters step, check all required normal fields (including nested properties)
        if (currentStepType === "parameters") {
            for (const field of normalFields) {
                if (field.required) {
                    const value = formData[field.name]
                    if (!isFieldValueValid(value, field)) {
                        return false
                    }
                }

                // Also check nested required properties for object fields even if parent is not required
                if (field.type === "object" && field.properties) {
                    const value = formData[field.name]
                    if (value && typeof value === "object") {
                        for (const subField of field.properties) {
                            if (subField.required) {
                                if (!isFieldValueValid(value[subField.name], subField)) {
                                    return false
                                }
                            }
                        }
                    }
                }
            }
        }

        return true
    }, [currentStepType, currentStep, executionName, executionDescription, formData, normalFields])

    const handleFieldChange = (fieldName: string, value: any) => {
        setFormData((prev) => ({ ...prev, [fieldName]: value }))
        if (errors[fieldName]) {
            setErrors((prev) => {
                const newErrors = { ...prev }
                delete newErrors[fieldName]
                return newErrors
            })
        }
    }

    const handleContinue = () => {
        // Validation for specific steps
        if (currentStepType === "details") {
            if (!executionName.trim() || !executionDescription.trim()) {
                toast({
                    status: "error",
                    title: t("agents:execution.validationError"),
                    description: t("agents:execution.validationNameDescription"),
                    duration: 3000,
                })
                return
            }
        } else if (currentStepType === "parameters") {
            const validationErrors = validateFormData(formData, normalFields)
            if (Object.keys(validationErrors).length > 0) {
                setErrors(validationErrors)
                toast({
                    status: "error",
                    title: t("agents:execution.validationError"),
                    description: t("agents:execution.validationFormErrors"),
                    duration: 3000,
                })
                return
            }
        } else if (currentStepType === "summary") {
            setCurrentStepIndex(currentStepIndex + 1) // Move to "done"
            executeAgent()
            return
        }

        // Move to next step
        if (currentStepIndex < dynamicSteps.length - 1) {
            setCurrentStepIndex(currentStepIndex + 1)
        }
    }

    const handleBack = () => {
        if (currentStepIndex > 0) {
            setCurrentStepIndex(currentStepIndex - 1)
        }
    }

    const handleNavigateToStep = (stepType: StepType) => {
        const stepIndex = dynamicSteps.findIndex((step) => step.type === stepType)
        if (stepIndex >= 0) {
            setCurrentStepIndex(stepIndex)
        }
    }

    const createCollection = async () => {
        if (!client || !interaction) {
            return null
        }

        const properties = {
            interaction: interaction.name,
            interactionId: interaction.id,
        }

        const payload = {
            name: executionName,
            description: executionDescription,
            dynamic: false,
            type: EXECUTION_CONTAINER,
            properties
        }

        return await client.store.collections.create(payload)
    }

    const updateCollection = async (collectionId: string, run_id: string | undefined, workflow_id: string | undefined) => {
        if (!client || !collectionId || !interaction) {
            return
        }

        const properties = {
            interaction: interaction.name,
            interactionId: interaction.id,
            run_id,
            workflow_id
        }

        const payload = {
            name: executionName,
            description: executionDescription,
            dynamic: false,
            type: EXECUTION_CONTAINER,
            properties
        }

        return await client.store.collections.update(collectionId, payload)
    }

    const executeAgent = async () => {
        if (!interaction || !client) {
            return
        }

        setIsExecuting(true)
        setExecutionError(null)

        const container = await createCollection()
        if (!container?.id) {
            toast({
                status: "error",
                title: t("agents:execution.failedCreateCollection"),
                description: t("agents:execution.failedCreateCollectionDescription"),
                duration: 5000
            })
            setIsExecuting(false)
            return
        }

        const payload = {
            type: "conversation",
            data: { ...formData },
            interactive: false,
            interaction: interaction.endpoint,
            environment: interaction.environment,
            model: interaction.model,
            tools: [],
            visibility: "project",
            tags: [`execution:${container.id}`],
        } as AsyncConversationExecutionPayload

        client.interactions.executeAsync(payload)
            .then(async (run) => {
                await updateCollection(container.id, run.runId, run.workflowId)
                navigate(`/agents/executions/${container.id}`)
            }).catch((err) => {
                setExecutionError(err.message || "An unexpected error occurred")
                toast({
                    status: "error",
                    title: t("agents:execution.failedStartReport"),
                    description: err.message,
                    duration: 5000
                })
                setIsExecuting(false)
            })
    }

    if (sessionLoading || isLoading) {
        return (
            <div className="flex flex-col w-full h-full gap-4">
                <div className="flex items-center justify-center h-full">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                </div>
            </div>
        )
    }

    if (notFound) {
        return (
            <div className="flex flex-col w-full h-full gap-4">
                <div className="flex flex-col items-center justify-center h-full gap-4">
                    <h1 className="text-3xl font-bold text-foreground">{t("agents:execution.notFound")}</h1>
                    <p className="text-muted-foreground">{t("agents:execution.notFoundDescription")}</p>
                    <Button onClick={() => navigate("/agents")}>
                        <ArrowLeft />
                        {t("agents:execution.backToAgents")}
                    </Button>
                </div>
            </div>
        )
    }

    if (!interaction) {
        return null
    }

    const isFirstStep = currentStepIndex === 0

    return (
        <div className="flex flex-col w-full h-full gap-4">
            <div className="flex flex-col w-full justify-center items-center text-center flex-shrink-0">
                <div className="flex flex-row gap-1 items-center">
                    <IconComponent className="size-8 text-primary" strokeWidth={2} />
                    <h1 className="text-3xl font-bold text-primary">{interaction.name}</h1>
                </div>
                <p className="text-muted-foreground">{cleanDescription}</p>
            </div>
            <div className="flex flex-col items-center w-full flex-1 min-h-0 gap-4">
                <div className="flex gap-4 flex-col items-center flex-shrink-0 w-full max-w-md sm:max-w-lg md:max-w-xl lg:max-w-3xl xl:max-w-4xl">
                    <AgentCreationHeaderPanel steps={dynamicSteps} currentStepId={currentStep?.id || "details"} isExecuting={isExecuting} />
                </div>
                <div className="flex-1 flex flex-col min-h-0 w-full max-w-md sm:max-w-lg md:max-w-xl lg:max-w-3xl xl:max-w-4xl pb-4">
                    <div className="rounded-lg border bg-card text-card-foreground flex flex-col h-full">
                        <AgentPanelHeaderPanel stepType={currentStepType} />
                        <div className="p-3 pt-0 flex-1 flex flex-col min-h-0 gap-3">
                            <div className="flex-1 flex flex-col space-y-3 min-h-0">
                                {currentStepType === "details" && (
                                    <AgentDetailsPanel
                                        name={executionName}
                                        description={executionDescription}
                                        setName={setExecutionName}
                                        setDescription={setExecutionDescription}
                                    />
                                )}
                                {(currentStepType === "document" || currentStepType === "documents") && currentStep?.fieldName && (
                                    <DocumentMediaPanel
                                        key={currentStep.fieldName}
                                        mode={currentStepType === "document" ? "single" : "multiple"}
                                        type="document"
                                        value={formData[currentStep.fieldName] ?? (currentStepType === "document" ? null : [])}
                                        onChange={(value) => handleFieldChange(currentStep.fieldName!, value)}
                                    />
                                )}
                                {(currentStepType === "media" || currentStepType === "medias") && currentStep?.fieldName && (
                                    <DocumentMediaPanel
                                        key={currentStep.fieldName}
                                        mode={currentStepType === "media" ? "single" : "multiple"}
                                        type="media"
                                        value={formData[currentStep.fieldName] ?? (currentStepType === "media" ? null : [])}
                                        onChange={(value) => handleFieldChange(currentStep.fieldName!, value)}
                                    />
                                )}
                                {(currentStepType === "object" || currentStepType === "objects") && currentStep?.fieldName && (
                                    <ObjectSelectionPanel
                                        key={currentStep.fieldName}
                                        mode={currentStepType === "object" ? "single" : "multiple"}
                                        value={formData[currentStep.fieldName] ?? (currentStepType === "object" ? null : [])}
                                        onChange={(value) => handleFieldChange(currentStep.fieldName!, value)}
                                        field={currentStep.field}
                                    />
                                )}
                                {currentStepType === "parameters" && (
                                    <AgentParametersPanel
                                        fields={normalFields}
                                        formData={formData}
                                        errors={errors}
                                        onChange={handleFieldChange}
                                    />
                                )}
                                {currentStepType === "summary" && (
                                    <AgentSummaryPanel
                                        name={executionName}
                                        description={executionDescription}
                                        interactionName={interaction.name}
                                        fields={fields}
                                        formData={formData}
                                        onNavigate={handleNavigateToStep}
                                    />
                                )}
                                {isExecuting && (
                                    <AgentExecutionDonePanel 
                                        isExecuting={isExecuting}
                                        executionError={executionError}
                                    />
                                )}
                            </div>
                            {(currentStepType !== "done" && !isExecuting) && (
                                <div className="flex justify-between flex-shrink-0">
                                    <div>
                                        {!isFirstStep && (
                                            <Button variant="outline" onClick={handleBack}>
                                                <ArrowLeft />
                                                {t("common:actions.back")}
                                            </Button>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Button onClick={handleContinue} disabled={!canContinue}>
                                            {currentStepType === "summary" ? t("common:actions.execute") : t("common:actions.continue")}
                                            <ArrowRight />
                                        </Button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}
