import { useState, useEffect, useMemo, useCallback } from "react"
import { CollectionItem, ContentObjectItem, CreateCollectionPayload, UserGroup } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"

export type CollectionCategory = "personal" | "organization"

export type MemberItem = {
    id: string
    name: string
    type: "document" | "collection"
}

export type WizardStep = 1 | 2 | 3

export type SearchMode = "documents" | "collections"

interface UseCollectionWizardProps {
    isOpen: boolean
    onClose: () => void
    onSuccess?: () => void
    collection?: CollectionItem
    category?: CollectionCategory
}

export function useCollectionWizard({ isOpen, onClose, onSuccess, collection, category }: UseCollectionWizardProps) {
    const { client, user } = useUserSession()
    const toast = useToast()
    const isEditMode = !!collection

    // Step navigation
    const [currentStep, setCurrentStep] = useState<WizardStep>(1)
    const [direction, setDirection] = useState<"forward" | "backward">("forward")

    // Form state
    const [name, setName] = useState("")
    const [description, setDescription] = useState("")
    const [typeId, setTypeId] = useState<string>("")
    const [isSubmitting, setIsSubmitting] = useState(false)

    // Groups state (for "organization" category)
    const [availableGroups, setAvailableGroups] = useState<UserGroup[]>([])
    const [selectedGroups, setSelectedGroups] = useState<string[]>([])
    const [isLoadingGroups, setIsLoadingGroups] = useState(false)

    // Members state
    const [existingMembers, setExistingMembers] = useState<MemberItem[]>([])
    const [membersToAdd, setMembersToAdd] = useState<MemberItem[]>([])
    const [membersToRemove, setMembersToRemove] = useState<Set<string>>(new Set())
    const [isLoadingMembers, setIsLoadingMembers] = useState(false)

    // Search state
    const [searchMode, setSearchMode] = useState<SearchMode>("documents")
    const [searchQuery, setSearchQuery] = useState("")
    const [debouncedQuery, setDebouncedQuery] = useState("")
    const [documentSearchResults, setDocumentSearchResults] = useState<ContentObjectItem[]>([])
    const [collectionSearchResults, setCollectionSearchResults] = useState<CollectionItem[]>([])
    const [isSearching, setIsSearching] = useState(false)

    // Load available groups when category is "organization"
    useEffect(() => {
        if (!client || !isOpen || category !== "organization") return

        setIsLoadingGroups(true)
        client.iam.groups.list()
            .then((groups) => {
                setAvailableGroups(groups)
            })
            .catch(() => {
                setAvailableGroups([])
            })
            .finally(() => {
                setIsLoadingGroups(false)
            })
    }, [client, isOpen, category])

    // Debounce search query
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedQuery(searchQuery)
        }, 300)
        return () => clearTimeout(timer)
    }, [searchQuery])

    // Search when debounced query or mode changes
    useEffect(() => {
        if (!client || !isOpen) return

        setIsSearching(true)

        if (searchMode === "documents") {
            const query: Record<string, unknown> = {}
            if (debouncedQuery.trim()) {
                query.name = debouncedQuery.trim()
            }

            client.objects.find({ query, limit: 50 })
                .then((docs) => {
                    setDocumentSearchResults(docs)
                })
                .catch(() => {
                    setDocumentSearchResults([])
                })
                .finally(() => {
                    setIsSearching(false)
                })
        } else {
            const searchParams: Record<string, unknown> = { dynamic: false }
            if (debouncedQuery.trim()) {
                searchParams.name = debouncedQuery.trim()
            }

            client.store.collections.search(searchParams)
                .then((cols) => {
                    setCollectionSearchResults(cols.filter((c: CollectionItem) => c.id !== collection?.id))
                })
                .catch(() => {
                    setCollectionSearchResults([])
                })
                .finally(() => {
                    setIsSearching(false)
                })
        }
    }, [client, isOpen, debouncedQuery, searchMode, collection?.id])

    // Load existing members when opening in edit mode
    useEffect(() => {
        if (isOpen && isEditMode && client) {
            setIsLoadingMembers(true)
            Promise.all([
                client.store.collections.searchMembers(collection.id, { limit: 1000 }),
                client.store.collections.searchChildren(collection.id, { limit: 1000 })
            ]).then(([membersData, childrenData]) => {
                const members: MemberItem[] = [
                    ...membersData.results.map((doc: ContentObjectItem) => ({
                        id: doc.id,
                        name: doc.name || doc.id,
                        type: "document" as const
                    })),
                    ...childrenData.map((col: CollectionItem) => ({
                        id: col.id,
                        name: col.name,
                        type: "collection" as const
                    }))
                ]
                setExistingMembers(members)
            }).catch((error) => {
                toast({
                    status: "error",
                    title: "Failed to load members",
                    description: error.message || "An error occurred",
                    duration: 3000,
                })
            }).finally(() => {
                setIsLoadingMembers(false)
            })
        }
    }, [isOpen, isEditMode, collection, client, toast])

    // Reset form when overlay closes or opens
    useEffect(() => {
        if (isOpen && isEditMode) {
            setName(collection.name || "")
            setDescription(collection.description || "")
            setTypeId(collection.type?.id || "")
        } else if (!isOpen) {
            setCurrentStep(1)
            setDirection("forward")
            setName("")
            setDescription("")
            setTypeId("")
            setSelectedGroups([])
            setExistingMembers([])
            setMembersToAdd([])
            setMembersToRemove(new Set())
            setSearchQuery("")
            setDebouncedQuery("")
            setSearchMode("documents")
            setDocumentSearchResults([])
            setCollectionSearchResults([])
        }
    }, [isOpen, isEditMode, collection])

    // Filter out already added items from search results
    const filteredSearchResults = useMemo(() => {
        if (searchMode === "documents") {
            const alreadyAddedIds = new Set([
                ...existingMembers.filter(m => m.type === "document").map(m => m.id),
                ...membersToAdd.filter(m => m.type === "document").map(m => m.id)
            ])
            return documentSearchResults.filter(doc => !alreadyAddedIds.has(doc.id))
        } else {
            const alreadyAddedIds = new Set([
                ...existingMembers.filter(m => m.type === "collection").map(m => m.id),
                ...membersToAdd.filter(m => m.type === "collection").map(m => m.id)
            ])
            return collectionSearchResults.filter(col => !alreadyAddedIds.has(col.id))
        }
    }, [searchMode, documentSearchResults, collectionSearchResults, existingMembers, membersToAdd])

    // Combined list of current members (existing - removed + added)
    const currentMembers = useMemo(() => {
        const existing = existingMembers.filter(m => !membersToRemove.has(m.id))
        return [...existing, ...membersToAdd]
    }, [existingMembers, membersToRemove, membersToAdd])

    const handleAddMember = useCallback((item: ContentObjectItem | CollectionItem) => {
        const isDocument = "root" in item || !("name" in item && "type" in item)
        const memberItem: MemberItem = {
            id: item.id,
            name: (item as ContentObjectItem).name || (item as CollectionItem).name || item.id,
            type: isDocument ? "document" : "collection"
        }

        // Determine type based on search mode for proper categorization
        memberItem.type = searchMode === "documents" ? "document" : "collection"

        setMembersToAdd(prev => [...prev, memberItem])
    }, [searchMode])

    const handleRemoveMember = useCallback((member: MemberItem) => {
        if (membersToAdd.some(m => m.id === member.id)) {
            setMembersToAdd(prev => prev.filter(m => m.id !== member.id))
        } else {
            setMembersToRemove(prev => new Set([...prev, member.id]))
        }
    }, [membersToAdd])

    const goToStep = useCallback((step: WizardStep) => {
        setDirection(step > currentStep ? "forward" : "backward")
        setCurrentStep(step)
    }, [currentStep])

    const goNext = useCallback(() => {
        if (currentStep < 3) {
            setDirection("forward")
            setCurrentStep((prev) => (prev + 1) as WizardStep)
        }
    }, [currentStep])

    const goBack = useCallback(() => {
        if (currentStep > 1) {
            setDirection("backward")
            setCurrentStep((prev) => (prev - 1) as WizardStep)
        }
    }, [currentStep])

    const canProceed = useMemo(() => {
        if (currentStep === 1) {
            return name.trim().length > 0
        }
        return true
    }, [currentStep, name])

    const handleSubmit = async () => {
        if (!client || !name.trim()) {
            return
        }

        setIsSubmitting(true)

        try {
            let targetCollectionId: string

            if (isEditMode) {
                const updateData: Record<string, unknown> = {
                    name: name.trim(),
                }

                if (typeId) {
                    updateData.type = typeId
                }

                updateData.description = description.trim() || ""

                await client.store.collections.update(collection.id, updateData)
                targetCollectionId = collection.id
            } else {
                const properties: Record<string, unknown> = {}
                if (description.trim()) {
                    properties.description = description.trim()
                }
                if (category === "personal" && user?.sub) {
                    properties.user = user.sub
                }

                const collectionData: CreateCollectionPayload = {
                    name: name.trim(),
                    dynamic: false,
                    ...(typeId && { type: typeId }),
                    ...(Object.keys(properties).length > 0 && { properties }),
                }

                const newCollection = await client.store.collections.create(collectionData)
                targetCollectionId = newCollection.id

                // Set security permissions after creation
                const principals: string[] = []
                if (user?.sub) {
                    principals.push(`user:${user.sub}`)
                }
                if (category === "organization" && selectedGroups.length > 0) {
                    principals.push(...selectedGroups.map(groupId => `group:${groupId}`))
                }
                if (principals.length > 0) {
                    const permissions: Record<string, string[]> = {
                        "content:read": principals,
                        "content:write": principals,
                        "content:delete": principals,
                    }
                    await client.store.collections.updatePermissions(targetCollectionId, permissions)
                }
            }

            // Handle member additions
            const documentsToAdd = membersToAdd.filter(m => m.type === "document").map(m => m.id)
            const collectionsToAdd = membersToAdd.filter(m => m.type === "collection").map(m => m.id)

            if (documentsToAdd.length > 0) {
                await client.store.collections.addMembers(targetCollectionId, documentsToAdd)
            }

            if (collectionsToAdd.length > 0) {
                await client.store.collections.addChildren(targetCollectionId, collectionsToAdd)
            }

            // Handle member removals (only in edit mode)
            if (isEditMode && membersToRemove.size > 0) {
                const documentsToRemove = existingMembers
                    .filter(m => m.type === "document" && membersToRemove.has(m.id))
                    .map(m => m.id)
                const collectionsToRemove = existingMembers
                    .filter(m => m.type === "collection" && membersToRemove.has(m.id))
                    .map(m => m.id)

                if (documentsToRemove.length > 0) {
                    await client.store.collections.deleteMembers(targetCollectionId, documentsToRemove)
                }

                if (collectionsToRemove.length > 0) {
                    await client.store.collections.deleteChildren(targetCollectionId, collectionsToRemove)
                }
            }

            toast({
                status: "success",
                title: isEditMode ? "Collection updated" : "Collection created",
                description: `"${name}" has been ${isEditMode ? "updated" : "created"} successfully`,
                duration: 2000,
            })

            onSuccess?.()
            onClose()
        } catch (error: unknown) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred"
            toast({
                status: "error",
                title: isEditMode ? "Failed to update collection" : "Failed to create collection",
                description: errorMessage,
                duration: 3000,
            })
        } finally {
            setIsSubmitting(false)
        }
    }

    return {
        // Step navigation
        currentStep,
        direction,
        goToStep,
        goNext,
        goBack,
        canProceed,

        // Form state
        name,
        setName,
        description,
        setDescription,
        typeId,
        setTypeId,
        isEditMode,

        // Groups (for "organization" category)
        availableGroups,
        selectedGroups,
        setSelectedGroups,
        isLoadingGroups,

        // Members
        currentMembers,
        membersToAdd,
        isLoadingMembers,
        handleAddMember,
        handleRemoveMember,

        // Search
        searchMode,
        setSearchMode,
        searchQuery,
        setSearchQuery,
        filteredSearchResults,
        isSearching,

        // Submit
        isSubmitting,
        handleSubmit,
    }
}
