import { FieldDefinition } from "@/features/agents/utils/schemaParser"

export type StepType =
    | "details"
    | "document"
    | "documents"
    | "media"
    | "medias"
    | "object"
    | "objects"
    | "parameters"
    | "summary"
    | "done"

export interface DynamicStep {
    type: StepType
    label: string
    fieldName?: string
    field?: FieldDefinition
    id: string // Unique identifier for the step
}

function toTitleCase(str: string): string {
    return str
        .replace(/([A-Z])/g, " $1")
        .replace(/^./, (s) => s.toUpperCase())
        .replace(/_/g, " ")
        .trim()
}

/**
 * Analyzes fields and determines which special steps are needed
 */
export function analyzeSteps(fields: FieldDefinition[]): DynamicStep[] {
    const steps: DynamicStep[] = []

    // Always start with details
    steps.push({ type: "details", label: "Details", id: "details" })

    // Track special fields that get their own steps
    const specialFieldNames = new Set<string>()

    // Check for special field types based on schema properties
    fields.forEach((field) => {
        // Use field.label (which comes from schema title or toTitleCase)
        const label = field.label || toTitleCase(field.name)

        // Array of documents: type === "array" && editor === "document"
        if (field.type === "array" && field.editor === "document") {
            steps.push({
                type: "documents",
                label,
                fieldName: field.name,
                field,
                id: `documents-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
        // Array of media: type === "array" && editor === "media"
        else if (field.type === "array" && field.editor === "media") {
            steps.push({
                type: "medias",
                label,
                fieldName: field.name,
                field,
                id: `medias-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
        // Array of objects: type === "array" && itemsType === "object"
        else if (field.type === "array" && field.itemsType === "object") {
            steps.push({
                type: "objects",
                label,
                fieldName: field.name,
                field,
                id: `objects-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
        // Single document: editor === "document"
        else if (field.editor === "document") {
            steps.push({
                type: "document",
                label,
                fieldName: field.name,
                field,
                id: `document-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
        // Single media: editor === "media"
        else if (field.editor === "media") {
            steps.push({
                type: "media",
                label,
                fieldName: field.name,
                field,
                id: `media-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
        // Object: type === "object"
        else if (field.type === "object") {
            steps.push({
                type: "object",
                label,
                fieldName: field.name,
                field,
                id: `object-${field.name}`
            })
            specialFieldNames.add(field.name)
        }
    })

    // Check if there are any remaining "normal" fields
    const normalFields = fields.filter(field => !specialFieldNames.has(field.name))
    if (normalFields.length > 0) {
        steps.push({ type: "parameters", label: "Parameters", id: "parameters" })
    }

    // Always end with summary
    steps.push({ type: "summary", label: "Summary", id: "summary" })

    // Handle duplicate labels by adding numbers
    const labelCounts = new Map<string, number>()
    const labelOccurrences = new Map<string, number>()

    // Count occurrences of each label
    steps.forEach(step => {
        if (step.type !== "details" && step.type !== "parameters" && step.type !== "summary") {
            labelCounts.set(step.label, (labelCounts.get(step.label) || 0) + 1)
        }
    })

    // Add numbers to duplicate labels
    steps.forEach(step => {
        if (step.type !== "details" && step.type !== "parameters" && step.type !== "summary") {
            const count = labelCounts.get(step.label) || 0
            if (count > 1) {
                const occurrence = (labelOccurrences.get(step.label) || 0) + 1
                labelOccurrences.set(step.label, occurrence)
                step.label = `${step.label} ${occurrence}`
            }
        }
    })

    return steps
}

/**
 * Gets normal fields (fields that are not special steps)
 */
export function getNormalFields(fields: FieldDefinition[]): FieldDefinition[] {
    return fields.filter((field) => {
        // Check if it's a special field based on schema properties
        const isArrayOfDocuments = field.type === "array" && field.editor === "document"
        const isArrayOfMedia = field.type === "array" && field.editor === "media"
        const isArrayOfObjects = field.type === "array" && field.itemsType === "object"
        const isSingleDocument = field.editor === "document" && field.type !== "array"
        const isSingleMedia = field.editor === "media" && field.type !== "array"
        const isObject = field.type === "object"

        return !(isArrayOfDocuments || isArrayOfMedia || isArrayOfObjects || isSingleDocument || isSingleMedia || isObject)
    })
}
