import { File } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Button } from "@/components/ui/button"

interface FileButtonProps {
    id: string
    name: string | undefined
    showHelpText?: boolean
}
export function FileButton({ id, name, showHelpText = true }: FileButtonProps) {
    return (
        <DocumentOverlay documentId={id}>
            <Button variant="ghost" size="sm" className="w-full justify-start bg-accent italic">
                <File className="size-4 shrink-0" />
                <span className="truncate">{name || id}</span>
                {showHelpText && (
                    <span className="text-xs text-muted-foreground">(click to view details)</span>
                )}
            </Button>
        </DocumentOverlay>
    )
}
