import { useCallback, useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import type { TFunction } from "i18next"
import { Plus, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { Textarea } from "@/components/ui/textarea"
import { ObjectSelectionPanelProps } from "@/features/agents/components/ObjectSelectionPanel/types"
import { FieldDefinition } from "@/features/agents/utils/schemaParser"

interface ObjectFormProps {
    fields: FieldDefinition[]
    value: Record<string, any>
    onChange: (value: Record<string, any>) => void
    disabled?: boolean
}

function ObjectForm({ fields, value, onChange, disabled }: ObjectFormProps) {
    const { t } = useTranslation("common")
    const handleFieldChange = (fieldName: string, fieldValue: any) => {
        onChange({ ...value, [fieldName]: fieldValue })
    }

    if (fields.length === 0) {
        return (
            <p className="text-sm text-muted-foreground italic">{t("form.noPropertiesDefined")}</p>
        )
    }

    return (
        <div className="space-y-4">
            {fields.map((field) => (
                <div key={field.name} className="space-y-1.5">
                    <Label htmlFor={field.name} className="flex items-center gap-1 text-sm">
                        {field.label}
                        {field.required && <span className="text-destructive">*</span>}
                    </Label>
                    {field.description && (
                        <p className="text-xs text-muted-foreground">{field.description}</p>
                    )}
                    {renderFieldInput(field, value[field.name], (val) => handleFieldChange(field.name, val), disabled, t)}
                </div>
            ))}
        </div>
    )
}

function renderFieldInput(
    field: FieldDefinition,
    value: any,
    onChange: (value: any) => void,
    disabled?: boolean,
    t?: TFunction<"common">
) {
    switch (field.type) {
        case "boolean":
            return (
                <div className="flex items-center space-x-2">
                    <Checkbox
                        id={field.name}
                        checked={value ?? field.default ?? false}
                        onCheckedChange={onChange}
                        disabled={disabled}
                    />
                    <Label htmlFor={field.name} className="text-sm font-normal cursor-pointer">
                        {t?.("form.enable") ?? "Enable"}
                    </Label>
                </div>
            )

        case "number":
            return (
                <Input
                    id={field.name}
                    type="number"
                    value={value ?? field.default ?? ""}
                    min={field.validation?.min}
                    max={field.validation?.max}
                    onChange={(e) => onChange(e.target.value ? Number(e.target.value) : undefined)}
                    placeholder={t?.("form.enterField", { field: field.label.toLowerCase() }) ?? `Enter ${field.label.toLowerCase()}`}
                    disabled={disabled}
                />
            )

        case "enum":
            return (
                <Select
                    value={value ?? field.default ?? ""}
                    onValueChange={onChange}
                    disabled={disabled}
                >
                    <SelectTrigger id={field.name}>
                        <SelectValue placeholder={t?.("form.selectField", { field: field.label.toLowerCase() }) ?? `Select ${field.label.toLowerCase()}`} />
                    </SelectTrigger>
                    <SelectContent>
                        {field.options?.map((option) => (
                            <SelectItem key={option} value={option}>
                                {option}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            )

        case "object":
            // Nested object - recursively render form
            if (field.properties && field.properties.length > 0) {
                return (
                    <div className="border rounded-md p-3 bg-muted/30">
                        <ObjectForm
                            fields={field.properties}
                            value={value || {}}
                            onChange={onChange}
                            disabled={disabled}
                        />
                    </div>
                )
            }
            // Fallback to textarea for objects without schema
            return (
                <Textarea
                    id={field.name}
                    value={typeof value === "object" ? JSON.stringify(value, null, 2) : value ?? ""}
                    onChange={(e) => {
                        try {
                            onChange(JSON.parse(e.target.value))
                        } catch {
                            // Keep raw text if not valid JSON
                        }
                    }}
                    placeholder='{"key": "value"}'
                    className="font-mono text-sm min-h-[80px]"
                    disabled={disabled}
                />
            )

        case "string":
        default: {
            const isLongText = field.validation?.maxLength && field.validation.maxLength > 100

            if (isLongText) {
                return (
                    <Textarea
                        id={field.name}
                        value={value ?? field.default ?? ""}
                        onChange={(e) => onChange(e.target.value)}
                        placeholder={t?.("form.enterField", { field: field.label.toLowerCase() }) ?? `Enter ${field.label.toLowerCase()}`}
                        rows={3}
                        className="resize-none"
                        disabled={disabled}
                    />
                )
            }

            return (
                <Input
                    id={field.name}
                    type="text"
                    value={value ?? field.default ?? ""}
                    onChange={(e) => onChange(e.target.value)}
                    placeholder={t?.("form.enterField", { field: field.label.toLowerCase() }) ?? `Enter ${field.label.toLowerCase()}`}
                    maxLength={field.validation?.maxLength}
                    disabled={disabled}
                />
            )
        }
    }
}

export function ObjectSelectionPanel({
    mode,
    value,
    onChange,
    field,
    description,
    disabled,
    className,
}: Readonly<ObjectSelectionPanelProps>) {
    const { t } = useTranslation("common")
    // Get the schema fields from the field definition
    const schemaFields = mode === "single"
        ? (field?.properties || [])
        : (field?.itemsSchema || field?.properties || [])

    // For single mode: value is an object or null
    // For multiple mode: value is an array of objects or empty array
    const [items, setItems] = useState<Record<string, any>[]>([])

    // Initialize state from value prop
    useEffect(() => {
        if (mode === "multiple") {
            const arr = Array.isArray(value) ? value : []
            setItems(arr as Record<string, any>[])
        }
    }, []) // Only on mount

    // Handle single object change
    const handleSingleChange = useCallback(
        (newValue: Record<string, any>) => {
            onChange(newValue)
        },
        [onChange]
    )

    // Handle multiple objects - add new item
    const handleAddItem = useCallback(() => {
        const newItem: Record<string, any> = {}
        // Initialize with defaults
        schemaFields.forEach((f) => {
            if (f.default !== undefined) {
                newItem[f.name] = f.default
            }
        })
        const newItems = [...items, newItem]
        setItems(newItems)
        onChange(newItems)
    }, [items, schemaFields, onChange])

    // Handle multiple objects - remove item
    const handleRemoveItem = useCallback(
        (index: number) => {
            const newItems = items.filter((_, i) => i !== index)
            setItems(newItems)
            onChange(newItems.length > 0 ? newItems : [])
        },
        [items, onChange]
    )

    // Handle multiple objects - update item
    const handleItemChange = useCallback(
        (index: number, newValue: Record<string, any>) => {
            const newItems = [...items]
            newItems[index] = newValue
            setItems(newItems)
            onChange(newItems)
        },
        [items, onChange]
    )

    // Clear all for multiple mode
    const handleClearAll = useCallback(() => {
        setItems([])
        onChange([])
    }, [onChange])

    if (mode === "single") {
        return (
            <div className={`flex-1 overflow-y-auto mt-4 flex flex-col gap-4 ${className || ""}`}>
                {description && (
                    <p className="text-sm text-muted-foreground">{description}</p>
                )}

                {schemaFields.length > 0 ? (
                    <ObjectForm
                        fields={schemaFields}
                        value={(value as Record<string, any>) || {}}
                        onChange={handleSingleChange}
                        disabled={disabled}
                    />
                ) : (
                    <p className="text-sm text-muted-foreground italic">
                        {t("form.noSchemaDefined")}
                    </p>
                )}
            </div>
        )
    }

    // Multiple mode
    return (
        <div className={`flex-1 overflow-y-auto mt-4 flex flex-col gap-4 ${className || ""}`}>
            {description && (
                <p className="text-sm text-muted-foreground">{description}</p>
            )}

            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <h4 className="text-sm font-medium">{t("items_other", { count: items.length })}</h4>
                    {items.length > 0 && (
                        <Badge variant="secondary">
                            {t("items", { count: items.length })}
                        </Badge>
                    )}
                </div>
                <div className="flex items-center gap-2">
                    {items.length > 0 && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={handleClearAll}
                            disabled={disabled}
                            className="text-muted-foreground"
                        >
                            <X className="h-4 w-4 mr-1" />
                            {t("actions.clearAll")}
                        </Button>
                    )}
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={handleAddItem}
                        disabled={disabled}
                    >
                        <Plus className="h-4 w-4 mr-1" />
                        {t("actions.addItem")}
                    </Button>
                </div>
            </div>

            {items.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 border-2 border-dashed rounded-lg text-muted-foreground">
                    <p>{t("form.noItemsAdded")}</p>
                    <p className="text-xs mt-1">{t("form.clickAddItem")}</p>
                </div>
            ) : (
                <div className="flex flex-col gap-4 max-h-[400px] overflow-y-auto">
                    {items.map((item, index) => (
                        <div key={index} className="border rounded-md p-4">
                            <div className="flex items-center justify-between mb-3">
                                <Label className="text-sm font-medium">
                                    {t("form.itemIndex", { index: index + 1 })}
                                </Label>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={() => handleRemoveItem(index)}
                                    disabled={disabled}
                                    className="h-7 w-7 p-0"
                                >
                                    <X className="h-4 w-4" />
                                </Button>
                            </div>
                            <Separator className="mb-3" />
                            {schemaFields.length > 0 ? (
                                <ObjectForm
                                    fields={schemaFields}
                                    value={item}
                                    onChange={(newValue) => handleItemChange(index, newValue)}
                                    disabled={disabled}
                                />
                            ) : (
                                <p className="text-sm text-muted-foreground italic">
                                    {t("form.noSchemaDefinedForItems")}
                                </p>
                            )}
                        </div>
                    ))}
                </div>
            )}
        </div>
    )
}
