import { useMemo } from "react"
import { FacetSpec } from "@vertesia/common"
import { useAppInstallation } from "@vertesia/ui/shell"
import { ApplicationLayout } from "@/components/layouts/ApplicationLayout"
import { advancedFacets, basicFacets } from "@/constants/facets"
import { LibraryPanel } from "@/features/library/LibraryPanel"
import { DocumentSearchProvider } from "@/plugins/providers/document/DocumentSearchProvider"

export function LibraryPage() {
    const appInstallation = useAppInstallation()

    const ADVANCED_FACETS: FacetSpec[] = appInstallation?.settings?.ADVANCED_FACETS ?? advancedFacets
    const BASIC_FACETS: FacetSpec[] = appInstallation?.settings?.BASIC_FACETS ?? basicFacets

    // Request the union of basic and advanced facet fields so both filter UIs
    // have the data they need. Each UI selects its own subset from the settings.
    const facets = useMemo(() => {
        // The PropertySelect exposes the type as "type.id"; the search facet is "type".
        const normalizeField = (field: string) => (field === "type.id" ? "type" : field)

        const byField = new Map<string, FacetSpec>()
        for (const facet of [...BASIC_FACETS, ...ADVANCED_FACETS]) {
            const field = normalizeField(facet.field)
            if (!byField.has(field)) {
                byField.set(field, { ...facet, field })
            }
        }
        return Array.from(byField.values())
    }, [BASIC_FACETS, ADVANCED_FACETS])

    return (
        <ApplicationLayout>
            <DocumentSearchProvider facets={facets}>
                <LibraryPanel />
            </DocumentSearchProvider>
        </ApplicationLayout>
    )
}
