import { useState, useMemo, useRef } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import type { TFunction } from "i18next"
import { ImagePlus, Loader2, Upload, X, icons, type LucideIcon } from "lucide-react"
import { DocumentSelectionOverlay } from "@/components/overlays/DocumentSelectionOverlay"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { useRenditionUrl } from "@/hooks/use-rendition-url"

interface ApplicationSectionProps {
    settings: Record<string, any>
    appName: string | undefined
    appTitle: string | undefined
    onSave: (values: { applicationName: string; applicationBreadcrumb: string; applicationIcon: string; applicationIconBackground: string; applicationIconImage: string }) => void
    loading?: boolean
}

const POPULAR_ICONS = [
    "LibraryBig", "Library", "BookOpen", "BookMarked", "Folder", "FolderOpen",
    "FileText", "Files", "Archive", "Database", "HardDrive", "Server",
    "Globe", "Building", "Building2", "Briefcase", "Layout", "LayoutDashboard",
    "Box", "Boxes", "Package", "Layers", "Grid3x3", "Table",
    "Settings", "Wrench", "Cog", "Shield", "Lock", "Key",
    "Users", "UserCircle", "Contact", "Crown", "Star", "Heart",
    "Zap", "Rocket", "Target", "Flag", "Bookmark", "Tag",
    "Search", "Eye", "Bell", "Mail", "MessageSquare", "Send",
    "Cloud", "Download", "Upload", "Share2", "Link", "Paperclip",
    "Image", "Camera", "Video", "Music", "Mic", "Monitor",
    "Smartphone", "Tablet", "Laptop", "Printer", "Cpu", "Wifi",
    "Map", "MapPin", "Navigation", "Compass", "Home", "Store",
    "ShoppingCart", "CreditCard", "DollarSign", "BarChart", "PieChart", "TrendingUp",
    "Calendar", "Clock", "Timer", "AlarmClock", "Hourglass", "Activity",
    "CheckCircle", "AlertCircle", "Info", "HelpCircle", "XCircle", "AlertTriangle",
    "Plus", "Minus", "Edit", "Trash2", "Copy", "Clipboard",
    "Terminal", "Code", "GitBranch", "Github", "Blocks", "Puzzle",
] as const

function getIcon(name: string): LucideIcon | undefined {
    return (icons as Record<string, LucideIcon>)[name]
}

function IconPicker({ value, onChange, t }: { value: string; onChange: (name: string) => void; t: TFunction<["settings", "common"]> }) {
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")

    const filteredIcons = useMemo(() => {
        const query = search.toLowerCase()
        if (!query) {
            return POPULAR_ICONS.filter((name) => getIcon(name))
        }
        const allNames = Object.keys(icons)
        return allNames.filter((name) => name.toLowerCase().includes(query)).slice(0, 80)
    }, [search])

    const SelectedIcon = getIcon(value)

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button variant="outline" className="w-full justify-start gap-2">
                    {SelectedIcon ? (
                        <>
                            <SelectedIcon className="size-4" />
                            <span>{value}</span>
                        </>
                    ) : (
                        <span className="text-muted-foreground">{t("common:iconPicker.selectIcon")}</span>
                    )}
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-80 p-0" align="start">
                <Command>
                    <CommandInput
                        placeholder={t("common:iconPicker.searchIcons")}
                        value={search}
                        onValueChange={setSearch}
                    />
                    <CommandList>
                        <CommandEmpty>{t("common:iconPicker.noIconsFound")}</CommandEmpty>
                        <CommandGroup className="max-h-64 overflow-y-auto">
                            {filteredIcons.map((name) => {
                                const Icon = getIcon(name)
                                if (!Icon) return null
                                return (
                                    <CommandItem
                                        key={name}
                                        value={name}
                                        onSelect={() => {
                                            onChange(name)
                                            setOpen(false)
                                            setSearch("")
                                        }}
                                    >
                                        <Icon className="size-4 mr-2 shrink-0" />
                                        <span>{name}</span>
                                    </CommandItem>
                                )
                            })}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    )
}

const COLOR_PRESETS = [
    "#9333ea", // purple-600 (default)
    "#dc2626", // red-600
    "#ea580c", // orange-600
    "#ca8a04", // yellow-600
    "#16a34a", // green-600
    "#0d9488", // teal-600
    "#2563eb", // blue-600
    "#4f46e5", // indigo-600
    "#c026d3", // fuchsia-600
    "#db2777", // pink-600
    "#475569", // slate-600
    "#1e293b", // slate-800
]

export function ApplicationSection({ settings, appName, appTitle, onSave, loading }: Readonly<ApplicationSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const { client } = useUserSession()
    const toast = useToast()
    const [applicationName, setApplicationName] = useState<string>(settings?.APPLICATION_NAME ?? "")
    const [applicationBreadcrumb, setApplicationBreadcrumb] = useState<string>(settings?.APPLICATION_BREADCRUMB ?? "")
    const [applicationIcon, setApplicationIcon] = useState<string>(settings?.APPLICATION_ICON ?? "LibraryBig")
    const [applicationIconBackground, setApplicationIconBackground] = useState<string>(
        settings?.APPLICATION_ICON_BACKGROUND ?? "#9333ea"
    )
    const [applicationIconImage, setApplicationIconImage] = useState<string>(settings?.APPLICATION_ICON_IMAGE ?? "")
    const [iconMode, setIconMode] = useState<"icon" | "image">(settings?.APPLICATION_ICON_IMAGE ? "image" : "icon")
    const [uploading, setUploading] = useState(false)
    const fileInputRef = useRef<HTMLInputElement>(null)
    const iconImageUrl = useRenditionUrl(iconMode === "image" ? applicationIconImage : undefined)

    const PreviewIcon = getIcon(applicationIcon) || getIcon("LibraryBig")!

    const handleImageSelection = (documents: ContentObjectItem[]) => {
        if (documents.length > 0) {
            setApplicationIconImage(documents[0].id)
        }
    }

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        e.target.value = ""
        if (!file || !client) return

        setUploading(true)
        try {
            const result = await client.objects.create({ content: file })
            setApplicationIconImage(result.id)
        } catch (err) {
            console.error("Failed to upload icon image:", err)
            toast?.({
                status: "error",
                title: t("settings:application.uploadFailed"),
            })
        } finally {
            setUploading(false)
        }
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:application.title")}</CardTitle>
                <CardDescription>
                    {t("settings:application.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label htmlFor="application-name">{t("settings:application.applicationName")}</Label>
                    <Input
                        id="application-name"
                        type="text"
                        placeholder={appName || t("settings:application.applicationNamePlaceholder")}
                        value={applicationName}
                        onChange={(e) => setApplicationName(e.target.value)}
                    />
                    <div>
                        <p className="text-xs text-muted-foreground">
                            {t("settings:application.applicationNameHelp")}
                        </p>
                        <p className="text-xs text-muted-foreground">
                        {t("settings:application.leaveEmptyDefault")} <span className="font-bold">{appName || "ECM"}</span>
                    </p>
                    </div>
                </div>

                <div className="flex flex-col gap-2">
                    <Label htmlFor="application-breadcrumb">{t("settings:application.breadcrumbLabel")}</Label>
                    <Input
                        id="application-breadcrumb"
                        type="text"
                        placeholder={appTitle || t("settings:application.breadcrumbPlaceholder")}
                        value={applicationBreadcrumb}
                        onChange={(e) => setApplicationBreadcrumb(e.target.value)}
                    />
                    <div>
                        <p className="text-xs text-muted-foreground">
                            {t("settings:application.breadcrumbHelp")}
                        </p>
                        <p className="text-xs text-muted-foreground">
                            {t("settings:application.leaveEmptyDefault")} <span className="font-bold">{appTitle || "Dashboard"}</span>
                        </p>
                    </div>
                </div>

                <div className="flex flex-col gap-2">
                    <Label>{t("settings:application.applicationIcon")}</Label>
                    <Tabs value={iconMode} onValueChange={(value) => setIconMode(value as "icon" | "image")}>
                        <TabsList>
                            <TabsTrigger value="icon">{t("settings:application.iconTabIcon")}</TabsTrigger>
                            <TabsTrigger value="image">{t("settings:application.iconTabImage")}</TabsTrigger>
                        </TabsList>
                        <TabsContent value="icon" className="flex flex-col gap-6 pt-2">
                            <IconPicker value={applicationIcon} onChange={setApplicationIcon} t={t} />
                            <div className="flex flex-col gap-2">
                                <Label>{t("settings:application.iconBackgroundColor")}</Label>
                                <div className="flex items-center gap-3">
                                    <div className="flex flex-wrap gap-2">
                                        {COLOR_PRESETS.map((color) => (
                                            <button
                                                key={color}
                                                type="button"
                                                className="size-8 rounded-md border-2 transition-all cursor-pointer"
                                                style={{
                                                    backgroundColor: color,
                                                    borderColor: applicationIconBackground === color ? "white" : "transparent",
                                                    boxShadow: applicationIconBackground === color ? `0 0 0 2px ${color}` : "none",
                                                }}
                                                onClick={() => setApplicationIconBackground(color)}
                                            />
                                        ))}
                                    </div>
                                    <Input
                                        type="color"
                                        value={applicationIconBackground}
                                        onChange={(e) => setApplicationIconBackground(e.target.value)}
                                        className="w-10 h-10 p-1 cursor-pointer"
                                    />
                                </div>
                            </div>
                        </TabsContent>
                        <TabsContent value="image" className="flex flex-col gap-2 pt-2">
                            <div className="flex flex-wrap gap-2">
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    accept="image/*"
                                    onChange={handleImageUpload}
                                    className="hidden"
                                />
                                <Button variant="outline" type="button" disabled={uploading} onClick={() => fileInputRef.current?.click()}>
                                    {uploading ? (
                                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                    ) : (
                                        <Upload className="h-4 w-4 mr-2" />
                                    )}
                                    {t("settings:application.uploadImage")}
                                </Button>
                                <DocumentSelectionOverlay
                                    onSelection={handleImageSelection}
                                    selectionMode="single"
                                >
                                    <Button variant="outline" type="button">
                                        <ImagePlus className="h-4 w-4 mr-2" />
                                        {t("settings:application.chooseFromLibrary")}
                                    </Button>
                                </DocumentSelectionOverlay>
                                {applicationIconImage && (
                                    <Button variant="outline" type="button" onClick={() => setApplicationIconImage("")}>
                                        <X className="h-4 w-4 mr-2" />
                                        {t("common:actions.remove")}
                                    </Button>
                                )}
                            </div>
                            <p className="text-xs text-muted-foreground">
                                {t("settings:application.iconImageHelp")}
                            </p>
                        </TabsContent>
                    </Tabs>
                </div>

                <div className="flex flex-col gap-2">
                    <Label>{t("settings:application.preview")}</Label>
                    <div className="flex items-center gap-3 p-3 rounded-lg border bg-sidebar">
                        {iconImageUrl ? (
                            <div className="flex aspect-square size-8 items-center justify-center">
                                <img src={iconImageUrl} alt={applicationName || appName || "ECM"} className="size-8 object-contain" />
                            </div>
                        ) : (
                            <div
                                className="flex aspect-square size-8 items-center justify-center rounded-lg text-white"
                                style={{ backgroundColor: applicationIconBackground }}
                            >
                                {PreviewIcon && <PreviewIcon className="size-4" />}
                            </div>
                        )}
                        <span className="font-medium">
                            {applicationName || appName || "ECM"}
                        </span>
                    </div>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button
                    onClick={() => onSave({
                        applicationName,
                        applicationBreadcrumb,
                        applicationIcon,
                        applicationIconBackground,
                        applicationIconImage: iconMode === "image" ? applicationIconImage : "",
                    })}
                    disabled={loading}
                >
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
