import { useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { useUserSession } from "@vertesia/ui/session"
import { CalendarSearch, ScanSearch, TextSearch } from "lucide-react"
import { CalendarSection } from "@/components/filters/CalendarSection"
import { FilterSection } from "@/components/filters/FilterSection"
import { SearchPropertySection } from "@/components/filters/SearchPropertySection"
import { SearchSection } from "@/components/filters/SearchSection"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { transformUser } from "@/lib/facet"
import { FacetResponse, PropertyFacet } from "@/models/facets"

const AUTO_SEARCH_STATE = "auto-search-state"

const makeLabelFn = (items: any[]) => (id: string) => {
    const item = items.find((i: any) => i._id === id)
    return item?.name || String(id)
}

interface SearchableProperty {
    id: string
    label: string
    property: string
    placeholder: string
}

interface FiltersPanelProps {
    properties?: PropertyFacet[]
    statuses: FacetResponse[]
    types: FacetResponse[]
    users: FacetResponse[]
    simpleProperties?: SearchableProperty[]
    onFiltersChange: (filters: any) => void
    onSearch: () => void
    onClearFilters: number
}

export function FiltersPanel({ properties, statuses, types, users, simpleProperties = [], onFiltersChange, onSearch, onClearFilters }: Readonly<FiltersPanelProps>) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const [filters, setFilters] = useState({})

    const handleDateChange = (date: any) => {
        if (date === undefined) {
            delete (filters as any).date
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, date })
        }
    }

    const handlePropertiesChange = (properties: any) => {
        if (properties === undefined) {
            delete (filters as any).properties
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, properties })
        }
    }

    const handleTypeChange = (type: string | string[] | undefined) => {
        if (type === undefined) {
            delete (filters as any).type
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, type })
        }
    }

    const handleStatusChange = (status: string | string[] | undefined) => {
        if (status === undefined) {
            delete (filters as any).status
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, status })
        }
    }

    const handleUserChange = (user: string | string[] | undefined) => {
        if (user === undefined) {
            delete (filters as any).user
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, user })
        }
    }

    const handleVectorTextChange = (vectorText: string) => {
        if (vectorText === undefined) {
            delete (filters as any).vectorText
            setFilters({ ...filters })
        } else {
            setFilters({ ...filters, vectorText })
        }
    }

    const [triggerSearch, setTriggerSearch] = useState(0)

    const [autoSearch, setAutoSearch] = useState(localStorage.getItem(AUTO_SEARCH_STATE) === "auto")
    const handleAutoSearchChange = (checked: boolean) => {
        localStorage.setItem(AUTO_SEARCH_STATE, checked ? "auto" : "manual")
        setAutoSearch(checked)

        if (checked) {
            setTriggerSearch(triggerSearch + 1)
        }
    }

    useEffect(() => {
        onFiltersChange(filters)

        if (!autoSearch) {
            return
        }

        setTriggerSearch(triggerSearch + 1)
    }, [filters])

    useEffect(() => {
        onSearch()
    }, [triggerSearch])

    useEffect(() => {
        setFilters({})
    }, [onClearFilters])

    return (
        <div className="h-full flex w-[var(--filterbar-width)] min-w-[var(--filterbar-width)] flex-shrink-0 flex-col bg-sidebar text-sidebar-foreground border-r border-sidebar-border">
            <div className="h-full flex flex-col overflow-auto">
                <SearchSection label={t("filters.semanticSearch")} placeholder={t("filters.semanticSearchPlaceholder")} Icon={ScanSearch} onClear={onClearFilters} onSelection={handleVectorTextChange} />
                {(simpleProperties.length > 0 || (properties?.length ?? 0) > 0) && (
                    <SearchPropertySection label={t("filters.propertySearch")} Icon={TextSearch} simpleProperties={simpleProperties} advancedProperties={properties} onClear={onClearFilters} onSelection={handlePropertiesChange} />
                )}
                <FilterSection label={t("filters.types")} items={types} onClear={onClearFilters} onSelection={handleTypeChange} getLabelFn={makeLabelFn(types)} />
                <FilterSection label={t("filters.statuses")} items={statuses} onClear={onClearFilters} onSelection={handleStatusChange} getLabelFn={makeLabelFn(statuses)} />
                <CalendarSection section="Calendar" Icon={CalendarSearch} onClear={onClearFilters} onSelection={handleDateChange} />
                <FilterSection label={t("filters.users")} items={users} onClear={onClearFilters} onSelection={handleUserChange} transform={transformUser} client={client} />
            </div>
            <div className="w-full p-2 text-center">
                <div className="flex items-center space-x-2">
                    <Switch id="search-mode" checked={autoSearch} onCheckedChange={handleAutoSearchChange} />
                    <Label htmlFor="search-mode" className="text-xs">{t("filters.autoSearch")}</Label>
                </div>
                <Button onClick={onSearch} disabled={autoSearch} className="mt-2 w-full hover:cursor-pointer">{t("actions.search")}</Button>
            </div>
        </div>
    )
}
