import type { NavigationSectionModel } from "@/models/navigation"

/**
 * Settings key holding the blacklist of sidebar item URLs that should be hidden.
 * A blacklist is used (rather than a whitelist) so that newly added sidebar
 * items are displayed by default and only become hidden when explicitly listed.
 */
export const SIDEBAR_HIDDEN_SETTING = "SIDEBAR_HIDDEN_ITEMS"

/**
 * URLs that can never be hidden:
 * - "/" is the home page and the redirect target for hidden routes.
 * - "/settings" must stay reachable so admins can re-enable hidden items.
 */
export const LOCKED_SIDEBAR_URLS = ["/", "/settings"]

export function isSidebarUrlLocked(url: string): boolean {
    return LOCKED_SIDEBAR_URLS.includes(url)
}

/** Read and sanitize the hidden-items blacklist from the installation settings. */
export function getHiddenSidebarUrls(settings?: Record<string, unknown>): string[] {
    const value = settings?.[SIDEBAR_HIDDEN_SETTING]
    return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []
}

/** Whether a sidebar item (by its exact URL) should be hidden from the navigation. */
export function isSidebarItemHidden(url: string, hidden: string[]): boolean {
    return !isSidebarUrlLocked(url) && hidden.includes(url)
}

/**
 * Whether a navigated path falls under a hidden item, used to guard direct
 * access. Matches the exact URL or any of its sub-paths (e.g. "/advanced-search/123"
 * is hidden when "/advanced-search" is hidden). The home page ("/") never matches so
 * it always stays accessible as the redirect target.
 */
export function isPathHidden(pathname: string, hidden: string[]): boolean {
    return hidden.some((url) => {
        if (isSidebarUrlLocked(url) || url === "/") {
            return false
        }
        return pathname === url || pathname.startsWith(url + "/")
    })
}

export interface SidebarItemEntry {
    url: string
    /** i18n key in the "navigation" namespace. */
    titleKey: string
    locked: boolean
    /** 0 for top-level items, 1 for nested sub-items. */
    depth: number
    /** URL of the parent item for nested sub-items, otherwise undefined. */
    parentUrl?: string
}

/** Flatten navigation sections into a configurable list of items for the settings UI. */
export function listSidebarItems(sections: NavigationSectionModel[]): SidebarItemEntry[] {
    const entries: SidebarItemEntry[] = []
    for (const section of sections) {
        for (const item of section.items) {
            entries.push({ url: item.url, titleKey: item.title, locked: isSidebarUrlLocked(item.url), depth: 0 })
            if ("items" in item && Array.isArray(item.items)) {
                for (const subItem of item.items) {
                    entries.push({ url: subItem.url, titleKey: subItem.title, locked: isSidebarUrlLocked(subItem.url), depth: 1, parentUrl: item.url })
                }
            }
        }
    }
    return entries
}
