import { useTranslation } from "react-i18next"
import { Check, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { DocumentBadge } from "@/features/executions/components/DocumentBadge"

export function formatPropertyKey(key: string): string {
    return key
        .replace(/_/g, " ")
        .replace(/([a-z])([A-Z])/g, "$1 $2")
        .replace(/\b\w/g, (char) => char.toUpperCase())
}

function isStoreReference(value: unknown): value is string {
    return typeof value === "string" && value.startsWith("store:")
}

function getStoreId(value: string): string {
    return value.replace("store:", "")
}

export function PropertyValue({ value }: { value: unknown }) {
    const { t } = useTranslation("common")

    if (value === null || value === undefined) {
        return <span className="text-muted-foreground italic">{t("states.notSet")}</span>
    }

    if (typeof value === "boolean") {
        return value ? (
            <div className="flex items-center gap-1 text-success">
                <Check className="h-4 w-4" />
                <span>{t("states.yes")}</span>
            </div>
        ) : (
            <div className="flex items-center gap-1 text-muted-foreground">
                <X className="h-4 w-4" />
                <span>{t("states.no")}</span>
            </div>
        )
    }

    if (typeof value === "number") {
        return <span className="font-mono text-sm">{value.toLocaleString()}</span>
    }

    if (isStoreReference(value)) {
        const docId = getStoreId(value)
        return <DocumentBadge documentId={docId} />
    }

    if (Array.isArray(value)) {
        if (value.length === 0) {
            return <span className="text-muted-foreground italic">{t("states.emptyList")}</span>
        }

        const allStoreRefs = value.every((item) => isStoreReference(item))
        if (allStoreRefs) {
            return (
                <div className="flex flex-col gap-1 min-w-0 overflow-hidden">
                    {value.map((item, index) => {
                        const docId = getStoreId(item as string)
                        return <DocumentBadge key={index} documentId={docId} />
                    })}
                </div>
            )
        }

        const hasObjects = value.some((item) => item !== null && typeof item === "object")

        if (hasObjects) {
            return (
                <div className="flex flex-col gap-2">
                    {value.map((item, index) => (
                        <div key={index} className="flex flex-col gap-1 pl-2 border-l-2 border-muted">
                            <span className="text-xs text-muted-foreground">{t("form.itemIndex", { index: index + 1 })}</span>
                            <PropertyValue value={item} />
                        </div>
                    ))}
                </div>
            )
        }

        return (
            <div className="flex flex-wrap gap-1">
                {value.map((item, index) => (
                    <Badge key={index} variant="secondary" className="text-xs">
                        {String(item)}
                    </Badge>
                ))}
            </div>
        )
    }

    if (typeof value === "object") {
        const entries = Object.entries(value)
        if (entries.length === 0) {
            return <span className="text-muted-foreground italic">{t("states.emptyValue")}</span>
        }
        return (
            <div className="flex flex-col gap-2 pl-2 border-l-2 border-muted">
                {entries.map(([k, v]) => (
                    <div key={k} className="flex flex-col gap-0.5">
                        <span className="text-xs text-muted-foreground">{formatPropertyKey(k)}</span>
                        <PropertyValue value={v} />
                    </div>
                ))}
            </div>
        )
    }

    const stringValue = String(value)
    if (stringValue.length > 100) {
        return (
            <p className="text-sm break-words whitespace-pre-wrap">{stringValue}</p>
        )
    }

    return <span className="text-sm">{stringValue}</span>
}
