import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { SUPPORTED_LANGUAGES } from "@/i18n"

interface LanguageSectionProps {
    settings: Record<string, any>
    onSave: (values: { defaultLanguage: string }) => void
    loading?: boolean
}

export function LanguageSection({ settings, onSave, loading }: Readonly<LanguageSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [defaultLanguage, setDefaultLanguage] = useState<string>(
        settings?.DEFAULT_LANGUAGE ?? "en"
    )

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:language.title")}</CardTitle>
                <CardDescription>{t("settings:language.description")}</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:language.defaultLanguage")}</Label>
                    <Select value={defaultLanguage} onValueChange={setDefaultLanguage}>
                        <SelectTrigger className="w-[280px]">
                            <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                            {Object.entries(SUPPORTED_LANGUAGES).map(([code, name]) => (
                                <SelectItem key={code} value={code}>
                                    {name}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <p className="text-xs text-muted-foreground">
                        {t("settings:language.defaultLanguageHelp")}
                    </p>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button
                    onClick={() => onSave({ defaultLanguage })}
                    disabled={loading}
                >
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
