import { useState, useEffect, useRef, useCallback } from "react"
import { useTranslation } from "react-i18next"
import { Collection, ContentObjectItem, VectorSearchQuery } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useNavigate } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Search, Loader2, ExternalLink, FileText, Type, FolderOpen, Bot } from "lucide-react"
import { RecentlyViewedSection } from "@/components/sections/RecentlyViewedSection"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Skeleton } from "@/components/ui/skeleton"
import { DocumentThumbnailWithModal } from "@/components/widgets/DocumentThumbnailWithModal"
import { RENDITION_ID } from "@/constants/cookies"
import { useAgentChat } from "@/contexts/AgentChatContext"
import { useDashboardTypesWhitelist } from "@/hooks/use-dashboard-types-whitelist"
import { resolveAssetUrl } from "@/lib/assets"
import { getDashboardBackgroundSettings, getDashboardDisplayMode } from "@/lib/dashboard-settings"
import { retrieveRendition, retrieveRenditionById } from "@/lib/rendition"

const DEFAULT_ITEMS_PER_PAGE = 12
const DEFAULT_GRID_COLS = { sm: 2, md: 3, lg: 4, xl: 6 }

const SEARCH_RESULTS_LIMIT = 10

// Search modes available from the dashboard search bar.
// - everywhere:  semantic search (full_text + vector) over objects (default)
// - contents:    full_text search over objects
// - title:       name search over objects
// - collections: name search over collections
type SearchMode = "everywhere" | "contents" | "title" | "collections"

export function UserDashboardPanel() {
    const { t } = useTranslation(["dashboard", "common"])
    const appInstallation = useAppInstallation()
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const navigate = useNavigate()
    const dashboardTypesWhitelist = useDashboardTypesWhitelist()
    const { openChatWithQuery } = useAgentChat()

    // Agentic search: the "Ask AI Assistant" button is shown only when an agent interaction
    // is configured via the DASHBOARD_AGENTIC_SEARCH_INTERACTION setting.
    const agenticSearchInteraction = appInstallation?.settings?.DASHBOARD_AGENTIC_SEARCH_INTERACTION as string | undefined

    const toast = useToast()

    const DASHBOARD_TITLE = appInstallation?.settings?.DASHBOARD_TITLE || t("dashboard:defaultTitle")
    const DASHBOARD_DESCRIPTION = appInstallation?.settings?.DASHBOARD_DESCRIPTION || t("dashboard:defaultDescription")
    const DASHBOARD_BACKGROUND = appInstallation?.settings?.DASHBOARD_BACKGROUND
    const bgSettings = getDashboardBackgroundSettings(appInstallation?.settings)
    const { positionX: DASHBOARD_BACKGROUND_POSITION_X, positionY: DASHBOARD_BACKGROUND_POSITION_Y, zoom: DASHBOARD_BACKGROUND_ZOOM, renditionSize: BANNER_RENDITION_SIZE, bannerMaxHeight: BANNER_MAX_HEIGHT, bannerMinHeight: BANNER_MIN_HEIGHT } = bgSettings
    const showImageGrid = getDashboardDisplayMode(appInstallation?.settings) === "imageGrid"

    const ITEMS_PER_PAGE = Number(appInstallation?.settings?.DASHBOARD_ITEMS_PER_PAGE) || DEFAULT_ITEMS_PER_PAGE
    const gridColsSm = Number(appInstallation?.settings?.DASHBOARD_GRID_COLS_SM) || DEFAULT_GRID_COLS.sm
    const gridColsMd = Number(appInstallation?.settings?.DASHBOARD_GRID_COLS_MD) || DEFAULT_GRID_COLS.md
    const gridColsLg = Number(appInstallation?.settings?.DASHBOARD_GRID_COLS_LG) || DEFAULT_GRID_COLS.lg
    const gridColsXl = Number(appInstallation?.settings?.DASHBOARD_GRID_COLS_XL) || DEFAULT_GRID_COLS.xl

    const [images, setImages] = useState<ContentObjectItem[]>([])
    const [imagesLoading, setImagesLoading] = useState(true)
    const [loadingMore, setLoadingMore] = useState(false)
    const [imagesOffset, setImagesOffset] = useState(0)
    const [hasMore, setHasMore] = useState(true)
    const [searchQuery, setSearchQuery] = useState("")
    const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("")
    const [searchResults, setSearchResults] = useState<ContentObjectItem[]>([])
    const [collectionResults, setCollectionResults] = useState<Collection[]>([])
    const [searchMode, setSearchMode] = useState<SearchMode>("everywhere")
    const [searchLoading, setSearchLoading] = useState(false)
    const [showSearchResults, setShowSearchResults] = useState(false)
    const [scrollProgress, setScrollProgress] = useState(0)
    const [thumbnailUrls, setThumbnailUrls] = useState<Record<string, string>>({})
    const [backgroundUrl, setBackgroundUrl] = useState<string>(() => {
        if (!DASHBOARD_BACKGROUND) return ""
        const cacheKey = `${RENDITION_ID}_${DASHBOARD_BACKGROUND}_${BANNER_RENDITION_SIZE}`
        const cached = localStorage.getItem(cacheKey)
        const cachedTime = localStorage.getItem(`${cacheKey}_time`)
        const now = new Date().getTime() / 1000
        if (cached?.length && cachedTime && Math.abs(now - parseInt(cachedTime)) <= 900) {
            return cached
        }
        return ""
    })
    const [backgroundLoading, setBackgroundLoading] = useState(!!DASHBOARD_BACKGROUND && !backgroundUrl)
    const [inputWidth, setInputWidth] = useState<number>(0)
    const gridRef = useRef<HTMLDivElement>(null)
    const inputContainerRef = useRef<HTMLDivElement>(null)
    const loadMoreRef = useRef<HTMLDivElement>(null)
    const loadingMoreRef = useRef(loadingMore)
    const hasMoreRef = useRef(hasMore)
    const offsetRef = useRef(imagesOffset)
    const defaultBackground = resolveAssetUrl("/ecm-background.png")
    const ecmImageUrl = backgroundUrl || defaultBackground

    useEffect(() => {
        if (client && DASHBOARD_BACKGROUND && !backgroundUrl) {
            setBackgroundLoading(true)
            retrieveRenditionById(client, DASHBOARD_BACKGROUND, (url) => {
                setBackgroundUrl(url)
                setBackgroundLoading(false)
            }, () => { }, toast, BANNER_RENDITION_SIZE)
        } else {
            setBackgroundLoading(false)
        }
    }, [client, DASHBOARD_BACKGROUND])

    // Keep refs in sync with state for image grid
    useEffect(() => {
        loadingMoreRef.current = loadingMore
        hasMoreRef.current = hasMore
        offsetRef.current = imagesOffset
    }, [loadingMore, hasMore, imagesOffset])

    const loadMoreImages = useCallback(async () => {
        if (!client || loadingMore || !hasMore) return

        setLoadingMore(true)
        try {
            const searchResponse = await client.objects.search({
                limit: ITEMS_PER_PAGE,
                offset: imagesOffset + ITEMS_PER_PAGE,
                query: {
                    ...(dashboardTypesWhitelist && { types: dashboardTypesWhitelist })
                }
            })
            const objects = searchResponse.results as ContentObjectItem[]

            if (objects.length < ITEMS_PER_PAGE) {
                setHasMore(false)
            }

            if (objects.length > 0) {
                setImages(prev => [...prev, ...objects])
                setImagesOffset(prev => prev + ITEMS_PER_PAGE)
            } else {
                setHasMore(false)
            }
        } catch (error) {
            console.error("Failed to load more images:", error)
            if (toast) {
                toast({
                    status: "error",
                    title: t("dashboard:errors.failedToLoadMore"),
                    description: t("dashboard:errors.failedToLoadMoreDescription")
                })
            }
        } finally {
            setLoadingMore(false)
        }
    }, [client, loadingMore, hasMore, imagesOffset, toast, dashboardTypesWhitelist])

    // Fetch initial images when in image grid mode
    useEffect(() => {
        if (!showImageGrid || !client) {
            setImagesLoading(false)
            return
        }

        const fetchLatestImages = async () => {
            setImagesLoading(true)
            setImagesOffset(0)
            setHasMore(true)
            try {
                const searchResponse = await client.objects.search({
                    limit: ITEMS_PER_PAGE,
                    offset: 0,
                    query: {
                        ...(dashboardTypesWhitelist && { types: dashboardTypesWhitelist })
                    }
                })
                const objects = searchResponse.results as ContentObjectItem[]

                setImages(objects)
                if (objects.length < ITEMS_PER_PAGE) {
                    setHasMore(false)
                }
            } catch (error) {
                console.error("Failed to fetch latest images:", error)
                if (toast) {
                    toast({
                        status: "error",
                        title: t("dashboard:errors.failedToLoad"),
                        description: t("dashboard:errors.failedToLoadDescription")
                    })
                }
            } finally {
                setImagesLoading(false)
            }
        }

        fetchLatestImages()
    }, [client, showImageGrid, toast, dashboardTypesWhitelist])

    // Infinite scroll observer for image grid
    useEffect(() => {
        if (!showImageGrid || imagesLoading) return

        const loadMoreElement = loadMoreRef.current
        if (!loadMoreElement) return

        const observer = new IntersectionObserver(
            (entries) => {
                const isIntersecting = entries[0].isIntersecting
                if (isIntersecting && !loadingMoreRef.current && hasMoreRef.current && client) {
                    loadMoreImages()
                }
            },
            {
                threshold: 0.1,
                rootMargin: "200px"
            }
        )

        observer.observe(loadMoreElement)
        return () => observer.disconnect()
    }, [imagesLoading, showImageGrid, client, loadMoreImages])

    // Debounce search query
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearchQuery(searchQuery)
        }, 300)

        return () => clearTimeout(timer)
    }, [searchQuery])

    // Open the results popover only once the user starts typing (never on a bare click/focus).
    useEffect(() => {
        if (!searchQuery.trim()) {
            setShowSearchResults(false)
        }
    }, [searchQuery])

    // Trigger search when the debounced query or the selected search mode changes.
    // Switching mode keeps the current input value and re-runs the search.
    useEffect(() => {
        performSearch()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [debouncedSearchQuery, searchMode])

    const performSearch = async () => {
        if (!client || !debouncedSearchQuery.trim()) {
            setSearchResults([])
            setCollectionResults([])
            setShowSearchResults(false)
            return
        }

        setSearchLoading(true)
        setShowSearchResults(true)
        try {
            if (searchMode === "collections") {
                const response = await client.store.collections.search({
                    name: debouncedSearchQuery,
                    limit: SEARCH_RESULTS_LIMIT,
                    dynamic: false,
                })
                setCollectionResults(response as Collection[])
                setSearchResults([])
                return
            }

            // Object searches: build the query depending on the selected mode.
            let query: Record<string, unknown>
            if (searchMode === "contents") {
                // Full-text search only.
                query = { full_text: debouncedSearchQuery }
            } else if (searchMode === "title") {
                // Name (title) search only.
                query = { name: debouncedSearchQuery }
            } else {
                // Everywhere (default): hybrid full-text + semantic vector search.
                const vector: VectorSearchQuery = {
                    text: debouncedSearchQuery,
                    config: {
                        text: true,
                        image: true,
                        properties: true
                    }
                }
                query = { full_text: debouncedSearchQuery, vector }
            }

            const payload = {
                limit: SEARCH_RESULTS_LIMIT,
                offset: 0,
                query: {
                    ...query,
                    ...(dashboardTypesWhitelist && { types: dashboardTypesWhitelist })
                }
            }

            const searchResponse = await client.objects.search(payload)
            const results = searchResponse.results

            setSearchResults(results)
            setCollectionResults([])

            results.forEach((doc: ContentObjectItem) => {
                if (doc.id && !thumbnailUrls[doc.id]) {
                    retrieveRendition(client, doc, (url) => { setThumbnailUrls(prev => ({ ...prev, [doc.id]: url })) }, () => { }, toast, 128)
                }
            })
        } catch (error) {
            console.error("Failed to perform search:", error)
            if (toast) {
                toast({
                    status: "error",
                    title: t("dashboard:errors.searchFailed"),
                    description: t("dashboard:errors.searchFailedDescription")
                })
            }
        } finally {
            setSearchLoading(false)
        }
    }

    const handleNavigateToDocument = (documentId: string) => {
        navigate(`/advanced-search/${documentId}`, { replace: true })
    }

    const handleNavigateToCollection = (collectionId: string) => {
        navigate(`/collections/${collectionId}`)
    }

    const handleAskAiAssistant = () => {
        const query = searchQuery.trim()
        if (!query) return
        // Prefix the first prompt (in the UI language) so the agent runs a real first search
        // instead of treating the bare keywords as a chat opener.
        const firstPrompt = `${t("dashboard:aiAssistant.searchPrefix")}${query}`
        // Start the agentic search and hand off to the floating AI Assistant panel.
        openChatWithQuery(firstPrompt)
        setShowSearchResults(false)
    }

    const handleOpenInNewTab = (e: React.MouseEvent, documentId: string) => {
        e.stopPropagation()
        window.open(`/advanced-search/${documentId}`, "_blank")
    }

    useEffect(() => {
        const grid = gridRef.current
        if (!grid) return

        let rafId: number

        const handleScroll = () => {
            if (rafId) {
                cancelAnimationFrame(rafId)
            }

            rafId = requestAnimationFrame(() => {
                const scrollTop = grid.scrollTop
                const maxScroll = 150 // Scroll distance to complete the transition
                const progress = Math.min(scrollTop / maxScroll, 1)
                setScrollProgress(progress)
            })
        }

        grid.addEventListener("scroll", handleScroll, { passive: true })
        return () => {
            grid.removeEventListener("scroll", handleScroll)
            if (rafId) {
                cancelAnimationFrame(rafId)
            }
        }
    }, [])

    useEffect(() => {
        const updateInputWidth = () => {
            if (inputContainerRef.current) {
                setInputWidth(inputContainerRef.current.offsetWidth)
            }
        }

        updateInputWidth()

        // Update on window resize
        window.addEventListener("resize", updateInputWidth)

        // Use ResizeObserver to track the input container size changes
        let resizeObserver: ResizeObserver | null = null
        if (inputContainerRef.current) {
            resizeObserver = new ResizeObserver(updateInputWidth)
            resizeObserver.observe(inputContainerRef.current)
        }

        return () => {
            window.removeEventListener("resize", updateInputWidth)
            if (resizeObserver) {
                resizeObserver.disconnect()
            }
        }
    }, [])

    // Update input width when scroll progress changes (search bar size changes)
    useEffect(() => {
        if (inputContainerRef.current) {
            setInputWidth(inputContainerRef.current.offsetWidth)
        }
    }, [scrollProgress])

    // Calculate interpolated values based on scroll progress
    const headerHeight = BANNER_MAX_HEIGHT - ((BANNER_MAX_HEIGHT - BANNER_MIN_HEIGHT) * scrollProgress)
    // Only shrink search bar when min height is at least half of max height
    const shrinkSearch = BANNER_MIN_HEIGHT < BANNER_MAX_HEIGHT / 2
    const searchProgress = shrinkSearch ? scrollProgress : 0
    const inputHeight = 48 - (12 * searchProgress) // 48px to 36px
    const inputFontSize = 18 - (2 * searchProgress) // 18px (text-lg) to 16px (text-base)
    const searchMaxWidth = 672 - (224 * searchProgress) // 672px (max-w-2xl) to 448px (max-w-md)

    return (
        <div className="flex flex-col w-full h-full gap-4 p-2">
            {/* Hero Section with Background Image and Search */}
            <div className="relative overflow-hidden rounded-sm flex-shrink-0 transition-all duration-200 ease-out" style={{ height: `${headerHeight}px` }}>
                <div className="absolute inset-x-0" style={{ height: `${BANNER_MAX_HEIGHT}px`, top: "50%", transform: "translateY(-50%)" }}>
                    {backgroundLoading ? (
                        <Skeleton className="w-full h-full" />
                    ) : (
                        <div
                            className="w-full h-full"
                            role="img"
                            aria-label={t("dashboard:ecmLandscape")}
                            style={{
                                backgroundImage: `url(${ecmImageUrl})`,
                                backgroundSize: `${DASHBOARD_BACKGROUND_ZOOM}%`,
                                backgroundPosition: `${DASHBOARD_BACKGROUND_POSITION_X}% ${DASHBOARD_BACKGROUND_POSITION_Y}%`,
                                backgroundRepeat: "no-repeat",
                            }}
                        />
                    )}

                    {/* Overlay for better text contrast */}
                    <div className="absolute inset-0 bg-black/30" />
                </div>

                {/* Search Bar Container */}
                <div className="absolute inset-0 flex items-center justify-center px-6 z-20">
                    <div
                        className="w-full transition-all duration-200 ease-out"
                        style={{ maxWidth: `${searchMaxWidth}px` }}
                    >
                        <Popover
                            open={showSearchResults}
                            onOpenChange={(open) => {
                                // Only allow the popover to open when the user has typed something;
                                // a bare click/focus on the empty input must not open it.
                                if (!open || searchQuery.trim()) {
                                    setShowSearchResults(open)
                                }
                                // Update width when popover opens
                                if (open && inputContainerRef.current) {
                                    setInputWidth(inputContainerRef.current.offsetWidth)
                                }
                            }}
                        >
                            <PopoverTrigger asChild>
                                <div ref={inputContainerRef} className="relative">
                                    <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-5 w-5 text-muted-foreground z-10 pointer-events-none" />
                                    {
                                        (searchLoading) && (
                                            <Loader2 className="absolute right-4 top-1/2 transform -translate-y-1/2 h-5 w-5 text-muted-foreground z-10 animate-spin" />
                                        )
                                    }
                                    <Input
                                        placeholder={t("dashboard:searchPlaceholder")}
                                        value={searchQuery}
                                        onChange={(e) => {
                                            setSearchQuery(e.target.value)
                                            if (e.target.value.trim()) {
                                                setShowSearchResults(true)
                                            }
                                        }}
                                        onFocus={() => {
                                            // Reopen results on focus only if there is already a query typed.
                                            if (searchQuery.trim()) {
                                                setShowSearchResults(true)
                                            }
                                        }}
                                        className="ecm-search ecm-search-hero pl-12 pr-12 bg-card text-card-foreground backdrop-blur-sm border-none shadow-lg transition-all duration-200 ease-out"
                                        style={{
                                            height: `${inputHeight}px`,
                                            fontSize: `${inputFontSize}px`
                                        }}
                                    />
                                </div>
                            </PopoverTrigger>
                            <PopoverContent
                                className="p-2 bg-secondary text-primary border border-muted-foreground shadow-lg"
                                style={{ width: inputWidth ? `${inputWidth}px` : "auto" }}
                                align="start"
                                onOpenAutoFocus={(e) => e.preventDefault()}
                            >
                                {/* Search type pills */}
                                <div className="flex items-center gap-1.5 px-1 pb-2 mb-1 border-b border-muted-foreground/30 flex-wrap">
                                    <span className="text-xs text-muted-foreground mr-1">{t("dashboard:searchIn")}</span>
                                    {
                                        ([
                                            { mode: "everywhere" as SearchMode, icon: Search, label: t("dashboard:searchModes.everywhere") },
                                            { mode: "contents" as SearchMode, icon: FileText, label: t("dashboard:searchModes.contents") },
                                            { mode: "title" as SearchMode, icon: Type, label: t("dashboard:searchModes.title") },
                                            { mode: "collections" as SearchMode, icon: FolderOpen, label: t("dashboard:searchModes.collections") },
                                        ]).map(({ mode, icon: Icon, label }) => (
                                            <button
                                                key={mode}
                                                type="button"
                                                onClick={() => setSearchMode(mode)}
                                                className={`inline-flex items-center gap-1 rounded-full px-3 py-1 text-xs font-medium cursor-pointer transition-colors ${searchMode === mode
                                                    ? "bg-primary text-primary-foreground"
                                                    : "bg-muted text-muted-foreground hover:bg-muted-foreground hover:text-secondary"
                                                    }`}
                                            >
                                                <Icon className="h-3 w-3" />
                                                {label}
                                            </button>
                                        ))
                                    }
                                </div>

                                {/* Agentic search — shown only when an agent interaction is configured */}
                                {agenticSearchInteraction && (
                                    <Button
                                        type="button"
                                        variant="ghost"
                                        size="sm"
                                        onClick={handleAskAiAssistant}
                                        className="group w-full justify-start mb-1"
                                    >
                                        <Bot className="text-primary group-hover:text-accent-foreground transition-colors" />
                                        <span className="font-medium">{t("dashboard:aiAssistant.ask")}</span>
                                    </Button>
                                )}

                                <div className="max-h-60 overflow-y-auto">
                                    {
                                        searchLoading ? (
                                            <div className="flex items-center justify-center gap-2 py-4">
                                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                                                <span className="text-sm text-muted-foreground">{t("common:states.loading")}</span>
                                            </div>
                                        ) : searchMode === "collections" ? (
                                            collectionResults.length === 0 ? (
                                                <div className="text-sm text-muted-foreground text-center py-4">
                                                    {t("dashboard:noResults")}
                                                </div>
                                            ) : (
                                                <div className="flex flex-col gap-1">
                                                    {
                                                        collectionResults.map((collection) => (
                                                            <div key={collection.id} className="group flex items-center gap-3 p-2 hover:bg-muted-foreground hover:text-secondary rounded-md cursor-pointer transition-colors" onClick={() => handleNavigateToCollection(collection.id)}>
                                                                {/* Collections have no rendition: show an open folder icon */}
                                                                <div className="w-12 h-12 flex-shrink-0 bg-muted rounded overflow-hidden border border-muted-foreground flex items-center justify-center">
                                                                    <FolderOpen className="h-5 w-5 text-muted-foreground" />
                                                                </div>

                                                                {/* Name and label */}
                                                                <div className="flex-1 min-w-0">
                                                                    <p className="text-sm font-medium truncate">
                                                                        {collection.name}
                                                                    </p>
                                                                    <Badge className="text-xs">
                                                                        {t("dashboard:collection")}
                                                                    </Badge>
                                                                </div>
                                                            </div>
                                                        ))
                                                    }
                                                </div>
                                            )
                                        ) : searchResults.length === 0 ? (
                                            <div className="text-sm text-muted-foreground text-center py-4">
                                                {t("dashboard:noResults")}
                                            </div>
                                        ) : (
                                            <div className="flex flex-col gap-1">
                                                {
                                                    searchResults.map((result) => (
                                                        <div key={result.id} className="group flex items-center gap-3 p-2 hover:bg-muted-foreground hover:text-secondary rounded-md cursor-pointer transition-colors" onClick={() => handleNavigateToDocument(result.id)}>
                                                            {/* Thumbnail */}
                                                            <div className="w-12 h-12 flex-shrink-0 bg-muted rounded overflow-hidden border border-muted-foreground">
                                                                {
                                                                    thumbnailUrls[result.id] ? (
                                                                        <img
                                                                            src={thumbnailUrls[result.id]}
                                                                            alt={result.name}
                                                                            className="w-full h-full object-cover"
                                                                        />
                                                                    ) : (
                                                                        <div className="w-full h-full flex items-center justify-center">
                                                                            <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                                                                        </div>
                                                                    )
                                                                }
                                                            </div>

                                                            {/* Name and Type */}
                                                            <div className="flex-1 min-w-0">
                                                                <p className="text-sm font-medium truncate">
                                                                    {result.name}
                                                                </p>
                                                                <Badge className="text-xs">
                                                                    {typeRegistry?.getTypeName(result.type?.id || "") || result.type?.name || t("common:document")}
                                                                </Badge>
                                                            </div>

                                                            {/* Open in new tab */}
                                                            <button
                                                                onClick={(e) => handleOpenInNewTab(e, result.id)}
                                                                className="flex-shrink-0 p-2 rounded-md hover:bg-primary/10 group-hover:hover:bg-secondary group-hover:hover:text-primary hover:cursor-pointer transition-colors"
                                                                title={t("common:openInNewTab")}
                                                            >
                                                                <ExternalLink className="h-4 w-4" />
                                                            </button>
                                                        </div>
                                                    ))
                                                }
                                            </div>
                                        )
                                    }
                                </div>
                            </PopoverContent>
                        </Popover>
                    </div>
                </div>
            </div>

            {/* Welcome Section */}
            {showImageGrid && (
                <div
                    className="flex flex-col text-center transition-opacity duration-300 ease-out"
                    style={{
                        opacity: Math.max(1 - scrollProgress * 2, 0),
                        display: scrollProgress >= 0.5 ? "none" : undefined,
                    }}
                >
                    <h1 className="text-2xl font-semibold">
                        {DASHBOARD_TITLE}
                    </h1>
                    <p className="text-sm text-muted-foreground">
                        {DASHBOARD_DESCRIPTION}
                    </p>
                </div>
            )}

            {/* Image Grid mode (when recently viewed is disabled) */}
            {showImageGrid ? (
                <div
                    ref={gridRef}
                    className="flex-1 overflow-auto"
                    style={{
                        "--grid-sm": gridColsSm,
                        "--grid-md": gridColsMd,
                        "--grid-lg": gridColsLg,
                        "--grid-xl": gridColsXl,
                    } as React.CSSProperties}
                >
                    <style>{`
                        @media (min-width: 640px) { .dashboard-grid { grid-template-columns: repeat(var(--grid-sm), minmax(0, 1fr)) !important; } }
                        @media (min-width: 768px) { .dashboard-grid { grid-template-columns: repeat(var(--grid-md), minmax(0, 1fr)) !important; } }
                        @media (min-width: 1024px) { .dashboard-grid { grid-template-columns: repeat(var(--grid-lg), minmax(0, 1fr)) !important; } }
                        @media (min-width: 1280px) { .dashboard-grid { grid-template-columns: repeat(var(--grid-xl), minmax(0, 1fr)) !important; } }
                    `}</style>
                    {imagesLoading ? (
                        <div className="dashboard-grid grid grid-cols-1 gap-1">
                            {[...Array(ITEMS_PER_PAGE)].map((_, i) => (
                                <Card key={i} className="overflow-hidden rounded-sm">
                                    <Skeleton className="w-full aspect-square rounded-none" />
                                </Card>
                            ))}
                        </div>
                    ) : (
                        <>
                            <div className="dashboard-grid grid grid-cols-1 gap-1">
                                {images.map((image) => (
                                    <DocumentThumbnailWithModal key={image.id} document={image} showDetails={false} showHoverInfo={true} />
                                ))}
                            </div>

                            {/* Load More Sentinel */}
                            {hasMore && (
                                <div ref={loadMoreRef} className="flex justify-center items-center py-8">
                                    {loadingMore && (
                                        <div className="flex items-center gap-2">
                                            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                                            <span className="text-sm text-muted-foreground">{t("common:states.loadingMore")}</span>
                                        </div>
                                    )}
                                </div>
                            )}

                            {/* End of Results */}
                            {!hasMore && images.length > 0 && (
                                <div className="flex justify-center items-center py-8">
                                    <span className="text-sm text-muted-foreground">{t("common:states.noMoreItems")}</span>
                                </div>
                            )}
                        </>
                    )}
                </div>
            ) : (
                /* Recently Viewed */
                <div ref={gridRef} className="flex-1 flex flex-col gap-6 overflow-y-auto overflow-x-hidden pb-6">
                    <RecentlyViewedSection />
                </div>
            )}
        </div>
    )
}
