import { FieldDefinition } from "@/features/agents/utils/schemaParser"

export function validateField(value: any, field: FieldDefinition): string | null {
    if (field.required && (value === undefined || value === null || value === "")) {
        return `${field.label} is required`
    }

    if (!value && !field.required) {
        return null
    }

    if (field.type === "number") {
        const num = Number(value)
        if (isNaN(num)) {
            return "Must be a valid number"
        }

        if (field.validation?.min !== undefined && num < field.validation.min) {
            return `Must be at least ${field.validation.min}`
        }

        if (field.validation?.max !== undefined && num > field.validation.max) {
            return `Must be at most ${field.validation.max}`
        }
    }

    if (field.type === "string" && typeof value === "string") {
        if (field.validation?.minLength && value.length < field.validation.minLength) {
            return `Must be at least ${field.validation.minLength} characters`
        }

        if (field.validation?.maxLength && value.length > field.validation.maxLength) {
            return `Must be at most ${field.validation.maxLength} characters`
        }

        if (field.validation?.pattern) {
            try {
                const regex = new RegExp(field.validation.pattern)
                if (!regex.test(value)) {
                    return "Invalid format"
                }
            } catch {
                console.error("Invalid regex pattern:", field.validation.pattern)
            }
        }
    }

    if (field.type === "enum" && field.options) {
        if (!field.options.includes(value)) {
            return `Must be one of: ${field.options.join(", ")}`
        }
    }

    return null
}

export function validateFormData(
    data: Record<string, any>,
    fields: FieldDefinition[]
): Record<string, string> {
    const errors: Record<string, string> = {}

    for (const field of fields) {
        const value = data[field.name]
        const error = validateField(value, field)

        if (error) {
            errors[field.name] = error
        }
    }

    return errors
}
