import { useState } from "react"
import { useTranslation } from "react-i18next"
import { useNavigate } from "@vertesia/ui/router"
import { BotMessageSquare, FolderPlus, Upload, Search } from "lucide-react"
import { CreateCollectionOverlay } from "@/components/overlays/CreateCollectionOverlay"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { UploadDocumentModal } from "@/features/document/modals/UploadDocumentModal"

export function QuickActions() {
    const { t } = useTranslation("common")
    const navigate = useNavigate()

    const [isUploadOpen, setIsUploadOpen] = useState(false)
    const [isCreateCollectionOpen, setIsCreateCollectionOpen] = useState(false)

    const handleUpload = () => {
        setIsUploadOpen(true)
    }

    const handleSearch = () => {
        navigate("/advanced-search")
    }

    const handleCreateCollection = () => {
        setIsCreateCollectionOpen(true)
    }

    const handleLatestAgents = () => {
        navigate("/agents")
    }

    return (
        <>
            <Card className="w-full">
                <CardHeader>
                    <CardTitle className="text-base">{t("quickActions.title")}</CardTitle>
                </CardHeader>
                <CardContent className="flex flex-col gap-2">
                    <Button onClick={handleUpload} className="justify-start" variant="default">
                        <Upload className="h-4 w-4" />
                        {t("quickActions.uploadDocument")}
                    </Button>
                    <Button onClick={handleSearch} className="justify-start" variant="outline">
                        <Search className="h-4 w-4" />
                        {t("quickActions.searchDocuments")}
                    </Button>
                    <Button onClick={handleCreateCollection} className="justify-start" variant="outline">
                        <FolderPlus className="h-4 w-4" />
                        {t("quickActions.createCollection")}
                    </Button>
                    <Button onClick={handleLatestAgents} className="justify-start" variant="outline">
                        <BotMessageSquare className="h-4 w-4" />
                        {t("quickActions.latestAgents")}
                    </Button>
                </CardContent>
            </Card>

            <UploadDocumentModal
                open={isUploadOpen}
                onOpenChange={setIsUploadOpen}
                onUploadDone={() => {}}
            />

            <CreateCollectionOverlay
                isOpen={isCreateCollectionOpen}
                onClose={() => setIsCreateCollectionOpen(false)}
            />
        </>
    )
}
