import { VertesiaClient } from "@vertesia/client"
import { ContentObjectItem, MarkdownRenditionFormat } from "@vertesia/common"
import { ToastFn } from "@vertesia/ui/core"
import { RENDITION_ID } from "@/constants/cookies"
import { RENDITION_OPTIONS } from "@/constants/renditions"
import { isImage, isOctetStream, isOfficeFile, isMsFile, isPdf, isVideo } from "@/lib/mime"

/**
 * Clean up expired rendition entries from localStorage
 */
function cleanupExpiredRenditions() {
    const currentTime = new Date().getTime() / 1000
    const keysToRemove: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i)
        if (key && key.startsWith(RENDITION_ID)) {
            if (key.endsWith("_time")) {
                const timeValue = localStorage.getItem(key)
                if (timeValue && Math.abs(currentTime - parseInt(timeValue)) > 900) {
                    // Remove both the time entry and the corresponding URL entry
                    keysToRemove.push(key)
                    keysToRemove.push(key.replace("_time", ""))
                }
            }
        }
    }

    keysToRemove.forEach(key => localStorage.removeItem(key))
}

/**
 * Safely store item in localStorage with quota handling
 */
function safeSetItem(key: string, value: string): boolean {
    try {
        localStorage.setItem(key, value)
        return true
    } catch (error) {
        if (error instanceof DOMException && (error.name === "QuotaExceededError" || error.code === 22)) {
            // Clean up expired entries and retry
            cleanupExpiredRenditions()
            try {
                localStorage.setItem(key, value)
                return true
            } catch {
                // If still failing, clear all rendition entries as last resort
                const keysToRemove: string[] = []
                for (let i = 0; i < localStorage.length; i++) {
                    const k = localStorage.key(i)
                    if (k && k.startsWith(RENDITION_ID)) {
                        keysToRemove.push(k)
                    }
                }
                keysToRemove.forEach(k => localStorage.removeItem(k))

                try {
                    localStorage.setItem(key, value)
                    return true
                } catch (finalError) {
                    console.error("Failed to store rendition in localStorage:", finalError)
                    return false
                }
            }
        }
        console.error("Failed to store rendition in localStorage:", error)
        return false
    }
}

export async function retrieveRendition(client: VertesiaClient, doc: ContentObjectItem, setRenditionUrl: (url: string) => void, setRenditionAlt: (alt: string) => void, toast: ToastFn, size: number = 512) {
    if (!doc?.content?.type || !(isImage(doc.content.type) || isVideo(doc.content.type) || isPdf(doc.content.type))) {
        return
    }

    const options = RENDITION_OPTIONS
    options.max_hw = size

    const currentTime = new Date().getTime() / 1000

    const savedId = localStorage.getItem(`${RENDITION_ID}_${doc.id}_${options.max_hw}`)
    const elapsedTime = localStorage.getItem(`${RENDITION_ID}_${doc.id}_${options.max_hw}_time`)

    if (savedId?.length && elapsedTime && Math.abs(currentTime - parseInt(elapsedTime)) <= 900) {
        setRenditionUrl(savedId)
        setRenditionAlt(`${doc.name} Rendition`)
        return savedId
    }

    client.objects.getRendition(doc.id, options).then((response) => {
        if (response.status === "generating") {
            setTimeout(retrieveRendition, 60000)
        } else if (response.status === "failed") {
            toast({
                status: "error",
                title: "Rendition generation Error",
                description: "Failed to generate Rendition for background removal",
                duration: 4000,
            })
        } else {
            if (!response.renditions || !response.renditions.length) {
                toast({
                    status: "error",
                    title: "Rendition generation Error",
                    description: "Rendition Source is Missing",
                    duration: 4000,
                })
                return
            }

            const renditionUrl = response.renditions[0]
            const currentTime = new Date().getTime() / 1000

            // Save to localStorage with quota handling
            safeSetItem(`${RENDITION_ID}_${doc.id}_${options.max_hw}`, renditionUrl)
            safeSetItem(`${RENDITION_ID}_${doc.id}_${options.max_hw}_time`, currentTime.toString())

            setRenditionUrl(renditionUrl)
            setRenditionAlt(`${doc.name} Rendition`)
        }
    })
}

