export async function retrievePdfRendition(client: VertesiaClient, doc: ContentObjectItem, setRenditionUrl: (url: string) => void, setDocumentType: (type: string) => void, toast: ToastFn, fallbackToOriginal: boolean = true) {
    if (!doc?.content?.type || !(isOfficeFile(doc.content.type) || isMsFile(doc.content.type) || isOctetStream(doc.content.type))) {
        return
    }

    const currentTime = new Date().getTime() / 1000

    const savedId = localStorage.getItem(`${RENDITION_ID}_${doc.id}_pdf`)
    const elapsedTime = localStorage.getItem(`${RENDITION_ID}_${doc.id}_pdf_time`)

    if (savedId?.length && elapsedTime && Math.abs(currentTime - parseInt(elapsedTime)) <= 900) {
        setRenditionUrl(savedId)
        setDocumentType("application/pdf")
        return savedId
    }

    client.objects.getRendition(doc.id, {
        format: MarkdownRenditionFormat.pdf,
        generate_if_missing: true,
        sign_url: true,
    }).then((response) => {
        if (response.status === "generating") {
            if (fallbackToOriginal) {
                client.objects.getDownloadUrl(doc.content.source!, undefined, "inline").then((response) => {
                    setRenditionUrl(response.url)
                    setDocumentType(doc.content.type!)
                })
            } else {
                toast({
                    status: "info",
                    title: "PDF Rendition Generating",
                    description: "PDF rendition is being generated, please check back momentarily.",
                    duration: 4000,
                })
            }
        } else if (response.status === "failed") {
            if (fallbackToOriginal) {
                client.objects.getDownloadUrl(doc.content.source!, undefined, "inline").then((response) => {
                    setRenditionUrl(response.url)
                    setDocumentType(doc.content.type!)
                })
            } else {
                toast({
                    status: "error",
                    title: "PDF Rendition Error",
                    description: "Failed to generate PDF rendition",
                    duration: 4000,
                })
            }
        } else {
            if (!response.renditions || !response.renditions.length) {
                if (fallbackToOriginal) {
                    client.objects.getDownloadUrl(doc.content.source!, undefined, "inline").then((response) => {
                        setRenditionUrl(response.url)
                        setDocumentType(doc.content.type!)
                    })
                } else {
                    toast({
                        status: "error",
                        title: "PDF Rendition Error",
                        description: "PDF rendition source is missing",
                        duration: 4000,
                    })
                }
                return
            }

            const renditionUrl = response.renditions[0]
            const currentTime = new Date().getTime() / 1000

            // Save to localStorage with quota handling
            safeSetItem(`${RENDITION_ID}_${doc.id}_pdf`, renditionUrl)
            safeSetItem(`${RENDITION_ID}_${doc.id}_pdf_time`, currentTime.toString())

            setRenditionUrl(renditionUrl)
            setDocumentType("application/pdf")
        }
    }).catch(() => {
        if (fallbackToOriginal) {
            client.objects.getDownloadUrl(doc.content.source!, undefined, "inline").then((response) => {
                setRenditionUrl(response.url)
                setDocumentType(doc.content.type!)
            })
        } else {
            toast({
                status: "error",
                title: "PDF Rendition Error",
                description: "Error retrieving PDF rendition",
                duration: 4000,
            })
        }
    })
}
