import { useEffect, useMemo, useState } from "react"
import { useTranslation } from "react-i18next"
import { InteractionRef } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { FilterX, ListFilter, X } from "lucide-react"
import { InteractionCard } from "@/components/cards/InteractionCard"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { useInteractionsSearch } from "@/hooks/use-interactions-search"

export function AgentsSearchPanel() {
    const { t } = useTranslation(["agents", "common"])
    const { client, isLoading, user } = useUserSession()
    const { searchInteractions } = useInteractionsSearch()
    const appInstallation = useAppInstallation()
    const excludedIds: string[] = appInstallation?.settings?.AGENT_INTERACTIONS_EXCLUDED_LIST ?? []

    const [open, setOpen] = useState(false)
    const [filterMode, setFilterMode] = useState<"tags" | "version" | undefined>(undefined)
    const [tagsValue, setTagsValue] = useState("")
    const [tags, setTags] = useState<string[]>([])
    const [versionValue, setVersionValue] = useState<number>(0)
    const [version, setVersion] = useState<number | undefined>(undefined)

    const [uniqueTags, setUniqueTags] = useState<string[]>([])
    const [selectedTags, setSelectedTags] = useState<string[]>([])

    const [filterValue, setFilterValue] = useState("")
    const [interactions, setInteractions] = useState<InteractionRef[]>([])

    const filteredOptions = useMemo(() => {
        return interactions.filter((interaction) => {
            const matchesName = interaction.name.toLowerCase().includes(filterValue.toLowerCase())
            const matchesSelectedTags = selectedTags.length === 0 || selectedTags.every((selectedTag) => interaction.tags?.includes(selectedTag))

            return matchesName && matchesSelectedTags
        })
    }, [interactions, filterValue, selectedTags])

    const handleClearFilters = () => {
        setOpen(false)
        setFilterMode(undefined)
        setTagsValue("")
        setTags([])
        setVersionValue(0)
        setVersion(undefined)
    }

    const handleVersionValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        e.stopPropagation()
        const parsedValue = parseFloat(e.target.value)
        setVersionValue(!isNaN(parsedValue) ? parsedValue : 0)
    }

    const handleVersionInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        e.stopPropagation()
        if (e.key === "Enter") {
            setOpen(false)
            setVersion(versionValue)
            setVersionValue(0)
        }
    }

    const handleTagsInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        e.stopPropagation()
        if (e.key === "Enter" && tagsValue.trim() !== "") {
            setOpen(false)
            setTags(
                tagsValue
                    .split(",")
                    .map((tag) => tag.trim())
                    .filter((tag) => tag !== "")
            )
        }
    }

    const handleUniqueTagSelection = (tag: string) => {
        if (selectedTags.includes(tag)) {
            setSelectedTags(selectedTags.filter((t) => t !== tag))
        } else {
            setSelectedTags([...selectedTags, tag])
        }
    }

    useEffect(() => {
        if (!open) {
            setFilterMode(undefined)
            setTagsValue("")
            setVersionValue(0)
        }
    }, [open])

    useEffect(() => {
        if (!client || isLoading) {
            return
        }

        searchInteractions(tags, version, excludedIds, setInteractions)
    }, [client, isLoading, tags, version, excludedIds])

    useEffect(() => {
        if (filteredOptions.length === 0) {
            setUniqueTags([])
            return
        }
        const filteredTags = [...new Set(filteredOptions.flatMap((interaction) => interaction.tags || []))].sort()
        setUniqueTags(filteredTags.filter(tag => tag !== "assistant"))
    }, [filteredOptions])

    if (!isLoading && !user) {
        return null
    }

    return (
        <div className="w-full h-full overflow-hidden flex flex-col p-2">
            <div className="flex flex-col gap-6 flex-shrink-0">
                <div className="flex flex-col items-center gap-6 flex-shrink-0">
                    <div className="flex flex-col w-full border border-border rounded-lg p-2 gap-2">
                        <div className="flex flex-row items-center gap-2 flex-1">
                            <Input value={filterValue} onChange={(e) => setFilterValue(e.target.value)} onClear={() => setFilterValue("")} placeholder={t("agents:search.filterPlaceholder")} className="flex-1 w-full border-none focus-visible:ring-0 focus:ring-0 focus:outline-none outline-none rounded-none shadow-none resize-none" />
                            {
                                (tags.length === 0 || version === undefined) && (
                                    <Popover open={open} onOpenChange={setOpen}>
                                        <PopoverTrigger asChild>
                                            <Button variant="ghost" className={`transition group flex gap-1.5 ${open ? "bg-accent text-accent-foreground" : ""}`}>
                                                <ListFilter />
                                                {t("common:actions.filters")}
                                            </Button>
                                        </PopoverTrigger>
                                        <PopoverContent className={`p-1 ${filterMode === "tags" ? "w-[350px]" : filterMode === "version" ? "w-[150px]" : "w-[100px]"}`} align="end">
                                            <div className="flex flex-col gap-1 text-start">
                                                {
                                                    (!filterMode) && (
                                                        <>
                                                            {
                                                                (tags.length === 0) && (
                                                                    <Button variant="ghost" className="flex flex-row items-center justify-end" onClick={() => setFilterMode("tags")}>
                                                                        {t("agents:search.tags")}
                                                                    </Button>
                                                                )
                                                            }
                                                            {
                                                                (version === undefined) && (
                                                                    <Button variant="ghost" className="flex flex-row items-center justify-end" onClick={() => setFilterMode("version")}>
                                                                        {t("agents:search.version")}
                                                                    </Button>
                                                                )
                                                            }
                                                        </>
                                                    )
                                                }
                                                {
                                                    (filterMode === "tags") && (
                                                        <div className="flex flex-col gap-2 p-2">
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-xs italic text-muted-foreground">{t("agents:search.tagsPlaceholder")}</span>
                                                            </div>
                                                            <Input value={tagsValue} onChange={(e) => setTagsValue(e.target.value)} onKeyDown={handleTagsInputKeyDown} placeholder={t("agents:search.tagsHint")} className="w-full resize-none" />
                                                        </div>
                                                    )
                                                }
                                                {
                                                    (filterMode === "version") && (
                                                        <div className="flex flex-col gap-2 p-2">
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-xs italic text-muted-foreground">{t("agents:search.versionPlaceholder")}</span>
                                                            </div>
                                                            <Input value={versionValue} onChange={handleVersionValueChange} onKeyDown={handleVersionInputKeyDown} placeholder={t("agents:search.versionHint")} type="number" className="w-full resize-none" />
                                                        </div>
                                                    )
                                                }
                                            </div>
                                        </PopoverContent>
                                    </Popover>
                                )
                            }
                            {
                                (tags.length !== 0 && version !== undefined) && (
                                    <Button variant="ghost" onClick={handleClearFilters}>
                                        <FilterX />
                                    </Button>
                                )
                            }
                        </div>
                        {
                            (tags.length > 0 || version !== undefined) && (
                                <div className="flex flex-row items-center gap-4">
                                    {
                                        (tags.length > 0) && (
                                            <div className="flex flex-row items-center gap-0.5">
                                                <Button variant="ghost" className="text-xs bg-muted rounded-r-none rounded-l-sm h-7 w-10">
                                                    {t("agents:search.tags")}
                                                </Button>
                                                {
                                                    tags.map((tag, index) => (
                                                        <Button key={index} variant="ghost" className="text-xs bg-muted rounded-r-none rounded-l-none h-7" onClick={() => setTags(tags.filter((t) => t !== tag))}>
                                                            {tag}
                                                        </Button>
                                                    ))
                                                }
                                                <Button variant="ghost" size="icon" className="bg-muted rounded-l-none rounded-r-sm size-7" onClick={() => setTags([])}>
                                                    <X />
                                                </Button>
                                            </div>
                                        )
                                    }
                                    {
                                        (version !== undefined) && (
                                            <div className="flex flex-row items-center gap-0.5">
                                                <Button variant="ghost" className="text-xs bg-muted rounded-r-none rounded-l-sm h-7 w-14">
                                                    {t("agents:search.version")}
                                                </Button>
                                                <Button variant="ghost" className="text-xs bg-muted rounded-r-none rounded-l-none h-7">
                                                    {version}
                                                </Button>
                                                <Button variant="ghost" size="icon" className="bg-muted rounded-l-none rounded-r-sm size-7" onClick={() => setVersion(undefined)}>
                                                    <X />
                                                </Button>
                                            </div>
                                        )
                                    }
                                </div>
                            )
                        }
                    </div>
                </div>
            </div>
            <div className="flex flex-row gap-2 items-center py-2 overflow-x-auto scrollbar-hide [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                {
                    uniqueTags.map((tag, index) => (
                        <Badge key={index} onClick={() => handleUniqueTagSelection(tag)} variant={selectedTags.includes(tag) ? "default" : "secondary"} className="p-2 text-xs cursor-pointer hover:bg-accent transition-colors duration-200 whitespace-nowrap flex-shrink-0">
                            {tag}
                        </Badge>
                    ))
                }
            </div>
            <div className="flex-1 min-h-0 overflow-y-auto pb-4">
                {
                    filteredOptions.length ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {
                                filteredOptions.map((interaction) => (
                                    <InteractionCard key={interaction.id} interaction={interaction} showTags />
                                ))
                            }
                        </div>
                    ) : (
                        <div className="h-full w-full flex items-center justify-center flex flex-col gap-1">
                            <span className="text-xl">{t("agents:search.noServicesAvailable")}</span>
                            {
                                (tags.length || version) ? (
                                    <>
                                        <span className="text-xl text-muted-foreground">{t("agents:search.noServicesHint")}</span>
                                        <Button onClick={handleClearFilters}>
                                            <FilterX />
                                            {t("common:actions.clearFilters")}
                                        </Button>
                                    </>
                                ) : (
                                    <span className="text-xl text-muted-foreground">{t("agents:search.contactAdmin")}</span>
                                )
                            }
                        </div>
                    )
                }
            </div>
        </div>
    )
}
