import { useMemo } from "react"
import { useAppInstallation } from "@vertesia/ui/shell"

/**
 * The optional type id used when lazily creating a user's favorites collection.
 * Configured via the FAVORITES_COLLECTION_TYPE application setting.
 */
export function useFavoritesCollectionType(): string | undefined {
    const appInstallation = useAppInstallation()

    return useMemo(() => {
        const raw = appInstallation?.settings?.FAVORITES_COLLECTION_TYPE
        if (typeof raw !== "string" || raw.trim().length === 0) {
            return undefined
        }
        return raw
    }, [appInstallation?.settings?.FAVORITES_COLLECTION_TYPE])
}
