import { ContentObjectItem } from "@vertesia/common"
import { FileSearch } from "lucide-react"
import { DocumentSelectionOverlay } from "@/components/overlays/DocumentSelectionOverlay"
import { Button } from "@/components/ui/button"

interface SearchDocumentsButtonProps {
    onSelection?: (document: ContentObjectItem) => void
    onMultipleSelection?: (documents: ContentObjectItem[]) => void
}
export function SearchDocumentsButton({ onSelection, onMultipleSelection }: Readonly<SearchDocumentsButtonProps>) {
    const handleOnSelection = (documents: ContentObjectItem[]) => {
        if (onMultipleSelection) {
            onMultipleSelection(documents)
        } else if (onSelection && documents.length > 0) {
            onSelection(documents[0])
        }
    }

    return (
        <DocumentSelectionOverlay
            onSelection={handleOnSelection}
            selectionMode={onMultipleSelection ? "multiple" : "single"}
        >
            <Button variant="outline" size="icon" type="button" className="h-9 w-9">
                <FileSearch className="h-4 w-4" />
            </Button>
        </DocumentSelectionOverlay>
    )
}
