import { useState, useEffect, useRef, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { VertesiaClient } from "@vertesia/client"
import { ChevronDown, ChevronRight, ChevronUp } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

// Facets with more than this many values are collapsed behind a "Show more" toggle.
const DEFAULT_VISIBLE_COUNT = 6

interface FilterSectionProps {
    label: string
    items: any[]
    selectedValue?: string | string[]
    onSelection?: (selection: string | string[] | undefined) => void
    onClear: number
    getLabelFn?: (value: any) => string
    multiple?: boolean
    transform?: (value: string, client: VertesiaClient, callback: (result: string) => void) => void
    client?: VertesiaClient
}
export function FilterSection({ label, items, selectedValue, onSelection, onClear, getLabelFn, multiple = false, transform, client }: Readonly<FilterSectionProps>) {
    const { t } = useTranslation("common")
    const [searchTerm, setSearchTerm] = useState("")
    const [showAll, setShowAll] = useState(false)
    const [transformedItems, setTransformedItems] = useState(items)
    const [selectedItems, setSelectedItems] = useState<string[]>(() => {
        if (multiple) {
            return Array.isArray(selectedValue) ? selectedValue : selectedValue ? [selectedValue] : []
        }
        return selectedValue ? [String(selectedValue)] : []
    })

    useEffect(() => {
        // Initialize based on whether it's single or multi-select
        if (multiple) {
            setSelectedItems(Array.isArray(selectedValue) ? selectedValue : selectedValue ? [selectedValue] : [])
        } else {
            setSelectedItems(selectedValue ? [String(selectedValue)] : [])
        }
    }, [selectedValue, multiple])

    const prevClearRef = useRef(onClear)
    useEffect(() => {
        if (prevClearRef.current !== onClear) {
            prevClearRef.current = onClear
            setSelectedItems([])
            setSearchTerm("")
            setShowAll(false)
        }
    }, [onClear])

    useEffect(() => {
        if (transform && client) {
            const updatedItems = [...items]
            let completedTransforms = 0

            for (let i = 0; i < items.length; i++) {
                const item = items[i]
                transform(item.name, client, (transformedName) => {
                    updatedItems[i] = { ...item, name: transformedName }
                    completedTransforms++
                    if (completedTransforms === items.length) {
                        setTransformedItems([...updatedItems])
                    }
                })
            }
        } else {
            setTransformedItems(items)
        }
    }, [items, transform, client])

    // Show the highest-count values first so the visible top-N is the most relevant subset.
    const sortedItems = useMemo(() => {
        return [...transformedItems].sort((a, b) => (b.count ?? 0) - (a.count ?? 0))
    }, [transformedItems])

    const filteredItems = sortedItems.filter((item) => {
        const displayName = getLabelFn ? getLabelFn(item._id) : String(item.name ?? item._id)
        return displayName.toLowerCase().includes(searchTerm.toLowerCase())
    })

    const isSearching = searchTerm.length > 0
    const hasMore = filteredItems.length > DEFAULT_VISIBLE_COUNT
    const visibleItems = (showAll || isSearching) ? filteredItems : filteredItems.slice(0, DEFAULT_VISIBLE_COUNT)
    const hiddenCount = filteredItems.length - DEFAULT_VISIBLE_COUNT

    const handleOnSelection = (id: string) => {
        let newSelection: string[]

        if (multiple) {
            // Multi-select: toggle the item
            if (selectedItems.includes(id)) {
                newSelection = selectedItems.filter(item => item !== id)
            } else {
                newSelection = [...selectedItems, id]
            }
        } else {
            // Single-select: replace or clear
            newSelection = selectedItems.includes(id) ? [] : [id]
        }

        setSelectedItems(newSelection)

        // Call onSelection with appropriate format
        if (multiple) {
            onSelection?.(newSelection.length > 0 ? newSelection : undefined)
        } else {
            onSelection?.(newSelection.length > 0 ? newSelection[0] : undefined)
        }
    }

    const isItemSelected = (id: string) => {
        return selectedItems.includes(String(id))
    }

    if (items.length === 0) return null

    return (
        <div className="border-b">
            <Collapsible defaultOpen={false} className="group/collapsible">
                <CollapsibleTrigger className={cn(
                    "flex h-10 w-full items-center justify-between px-4 py-2 text-sm font-medium",
                    "hover:bg-accent transition-colors hover:cursor-pointer",
                    "outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}>
                    {label}
                    <ChevronRight className="h-4 w-4 transition-transform group-data-[state=open]/collapsible:rotate-90" />
                </CollapsibleTrigger>
                <CollapsibleContent>
                    <div className="flex flex-col px-4 pb-2">
                        {items.length > DEFAULT_VISIBLE_COUNT && (
                            <Input
                                placeholder={t("search.searchPlaceholder", { label: label.toLowerCase() })}
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="mb-2"
                            />
                        )}
                        <div className="flex flex-col gap-1">
                            {visibleItems.map((item, index) => {
                                const displayName = getLabelFn ? getLabelFn(item._id) : String(item.name ?? item._id)
                                return (
                                    <div
                                        key={`${item._id}-${index}`}
                                        className="flex items-center justify-between rounded-md px-2 py-2 hover:bg-accent transition-colors cursor-pointer"
                                        onClick={() => handleOnSelection(item._id)}
                                    >
                                        <div className="flex items-center gap-2 flex-1 min-w-0">
                                            <Checkbox
                                                id={`filter-${label}-${item._id}`}
                                                checked={isItemSelected(item._id)}
                                                onCheckedChange={() => handleOnSelection(item._id)}
                                                onClick={(e) => e.stopPropagation()}
                                            />
                                            <label
                                                htmlFor={`filter-${label}-${item._id}`}
                                                className="text-sm cursor-pointer truncate flex-1"
                                            >
                                                {displayName}
                                            </label>
                                        </div>
                                        {item.count !== undefined && (
                                            <Badge variant="secondary" className="text-xs ml-2 flex-shrink-0">
                                                {item.count}
                                            </Badge>
                                        )}
                                    </div>
                                )
                            })}
                        </div>
                        {hasMore && !isSearching && (
                            <Button
                                variant="ghost"
                                size="sm"
                                className="mt-1 h-7 text-xs text-muted-foreground"
                                onClick={() => setShowAll(prev => !prev)}
                            >
                                {showAll ? (
                                    <>
                                        <ChevronUp className="mr-1 h-3 w-3" />
                                        {t("filters.showLess")}
                                    </>
                                ) : (
                                    <>
                                        <ChevronDown className="mr-1 h-3 w-3" />
                                        {t("filters.showMore", { count: hiddenCount })}
                                    </>
                                )}
                            </Button>
                        )}
                    </div>
                </CollapsibleContent>
            </Collapsible>
        </div>
    )
}
