import { useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Calendar, User, FileType, Tag, ExternalLink } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Separator } from "@/components/ui/separator"
import { DocumentThumbnail } from "@/components/widgets/DocumentThumbnail"
import { useUserCache } from "@/hooks/use-user-cache"
import { retrieveRendition } from "@/lib/rendition"

interface DocumentThumbnailWithModalProps {
    document: ContentObjectItem
    showDetails?: boolean
    showHoverInfo?: boolean
    selected?: boolean
    onToggleSelection?: () => void
    selectionEnabled?: boolean
}
export function DocumentThumbnailWithModal({ document, showDetails, showHoverInfo, selected, onToggleSelection, selectionEnabled }: DocumentThumbnailWithModalProps) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const toast = useToast()
    const appInstallation = useAppInstallation()
    const modalPreviewSize = Number(appInstallation?.settings?.RENDITION_MODAL_PREVIEW_SIZE) || 1024
    const { getUserDisplayName } = useUserCache(client)
    const [open, setOpen] = useState(false)
    const [overlayOpen, setOverlayOpen] = useState(false)
    const [imageUrl, setImageUrl] = useState<string | null>(null)

    const name = document?.properties?.title || document?.name || document.id
    const typeName = typeRegistry?.getTypeName(document.type?.id || "") || document.type?.name || t("document")
    const mimeType = document.content?.type || "Unknown"

    useEffect(() => {
        if (open && client && document) {
            retrieveRendition(client, document, setImageUrl, () => {}, toast, modalPreviewSize)
        }
    }, [open, client, document.id, toast])

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString(undefined, {
            year: "numeric",
            month: "long",
            day: "numeric",
            hour: "2-digit",
            minute: "2-digit",
        })
    }

    const handleOpenDocument = () => {
        setOpen(false)
        setOverlayOpen(true)
    }

    return (
        <>
            <DocumentThumbnail
                document={document}
                showDetails={showDetails}
                showHoverInfo={showHoverInfo}
                selected={selected}
                onToggleSelection={onToggleSelection}
                selectionEnabled={selectionEnabled}
                onSelect={() => setOpen(true)}
                onQuickAction={() => setOverlayOpen(true)}
            />
            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 gap-0 bg-card">
                    <DialogHeader className="p-6 pb-0">
                        <DialogTitle className="truncate pr-8" title={name}>{name}</DialogTitle>
                    </DialogHeader>
                    <Separator className="border-b mt-6" />
                    <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                        {/* Image */}
                        <div className="flex-1 flex items-center justify-center p-6 min-h-[300px] bg-muted/30">
                            {imageUrl ? (
                                <img
                                    src={imageUrl}
                                    alt={name}
                                    className="max-w-full max-h-[60vh] object-contain rounded-sm"
                                />
                            ) : (
                                <div className="text-muted-foreground text-sm">{t("states.loading")}</div>
                            )}
                        </div>
                        {/* Metadata sidebar */}
                        <div className="w-full md:w-64 flex-shrink-0 border-t md:border-t-0 md:border-l overflow-y-auto flex flex-col">
                            <div className="flex flex-col p-4 gap-4 flex-1">
                                <div className="flex items-center gap-2">
                                    <Tag className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                                    <div>
                                        <p className="text-xs text-muted-foreground">{t("properties.type")}</p>
                                        <Badge>{typeName}</Badge>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    <FileType className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                                    <div>
                                        <p className="text-xs text-muted-foreground">{t("properties.format")}</p>
                                        <p className="text-sm">{mimeType}</p>
                                    </div>
                                </div>
                                {document.created_at && (
                                    <div className="flex items-center gap-2">
                                        <Calendar className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                                        <div>
                                            <p className="text-xs text-muted-foreground">{t("properties.createdAt")}</p>
                                            <p className="text-sm">{formatDate(document.created_at)}</p>
                                        </div>
                                    </div>
                                )}
                                {document.updated_at && (
                                    <div className="flex items-center gap-2">
                                        <Calendar className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                                        <div>
                                            <p className="text-xs text-muted-foreground">{t("properties.modified")}</p>
                                            <p className="text-sm">{formatDate(document.updated_at)}</p>
                                        </div>
                                    </div>
                                )}
                                {document.created_by && (
                                    <div className="flex items-center gap-2">
                                        <User className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                                        <div>
                                            <p className="text-xs text-muted-foreground">{t("properties.createdBy")}</p>
                                            <p className="text-sm">{getUserDisplayName(document.created_by, undefined)}</p>
                                        </div>
                                    </div>
                                )}
                            </div>
                            <div className="mt-auto">
                                <Separator />
                                <div className="p-4">
                                    <Button
                                        className="w-full"
                                        onClick={handleOpenDocument}
                                    >
                                        <ExternalLink className="h-4 w-4 mr-2" />
                                        Open Asset
                                    </Button>
                                </div>
                            </div>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>
            <DocumentOverlay
                documentId={document.id}
                isOpen={overlayOpen}
                onClose={() => setOverlayOpen(false)}
            />
        </>
    )
}
