import { useState, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { Plus, Trash2 } from "lucide-react"
import { PropertySelect } from "@/components/inputs/PropertySelect"
import { TypeSelect } from "@/components/inputs/TypeSelect"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

export interface Facet {
    name: string
    field: string
}

interface FacetsEditorProps {
    title: string
    description: string
    initialFacets: Facet[]
    onSave: (facets: Facet[]) => void
    loading?: boolean
}

function FacetRow({
    facet,
    index,
    showLabels,
    onRemove,
    onChange,
}: Readonly<{
    facet: Facet
    index: number
    showLabels: boolean
    onRemove: (index: number) => void
    onChange: (index: number, key: keyof Facet, value: string) => void
}>) {
    const { t } = useTranslation(["settings", "common"])
    return (
        <div className="grid grid-cols-[1fr_1fr_auto] gap-2 items-end">
            <div className="flex flex-col gap-1">
                {showLabels && <Label className="text-xs text-muted-foreground">{t("settings:facets.field")}</Label>}
                <Input
                    placeholder={t("settings:facets.fieldPlaceholder")}
                    value={facet.field}
                    onChange={(e) => onChange(index, "field", e.target.value)}
                />
            </div>
            <div className="flex flex-col gap-1">
                {showLabels && <Label className="text-xs text-muted-foreground">{t("settings:facets.name")}</Label>}
                <Input
                    placeholder={t("settings:facets.displayName")}
                    value={facet.name}
                    onChange={(e) => onChange(index, "name", e.target.value)}
                />
            </div>
            <Button
                variant="ghost"
                size="icon"
                onClick={() => onRemove(index)}
            >
                <Trash2 className="h-4 w-4 text-destructive" />
            </Button>
        </div>
    )
}

export function FacetsEditor({ title, description, initialFacets, onSave, loading }: Readonly<FacetsEditorProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [facets, setFacets] = useState<Facet[]>(() => structuredClone(initialFacets))
    const [selectedTypeId, setSelectedTypeId] = useState("")

    const excludeFields = useMemo(() => facets.map((f) => f.field), [facets])

    const handleAdd = (path: string, label: string) => {
        setFacets((prev) => [...prev, { name: label, field: path }])
    }

    const handleAddCustom = () => {
        setFacets((prev) => [...prev, { name: "", field: "" }])
    }

    const handleRemove = (index: number) => {
        setFacets((prev) => prev.filter((_, i) => i !== index))
    }

    const handleChange = (index: number, key: keyof Facet, value: string) => {
        setFacets((prev) => prev.map((facet, i) => (i === index ? { ...facet, [key]: value } : facet)))
    }

    const handleSave = () => {
        const cleaned = facets.filter((f) => f.name.trim() !== "" && f.field.trim() !== "")
            .map((f) => ({ name: f.name.trim(), field: f.field.trim() }))
        onSave(cleaned)
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{title}</CardTitle>
                <CardDescription>
                    {description}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-4">
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:facets.filterByType")}</Label>
                    <TypeSelect
                        value={selectedTypeId}
                        onChange={setSelectedTypeId}
                        placeholder={t("settings:facets.selectTypePlaceholder")}
                        allowEmpty
                        emptyLabel={t("settings:facets.allTypes")}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:facets.typeFilterHelp")}
                    </p>
                </div>

                <div className="flex flex-col gap-3">
                    {facets.length === 0 && (
                        <p className="text-sm text-muted-foreground italic">{t("settings:facets.noFacetsConfigured")}</p>
                    )}

                    {facets.map((facet, index) => (
                        <FacetRow
                            key={index}
                            facet={facet}
                            index={index}
                            showLabels={index === 0}
                            onRemove={handleRemove}
                            onChange={handleChange}
                        />
                    ))}

                    <div className="flex flex-col gap-2">
                        <PropertySelect
                            typeId={selectedTypeId || undefined}
                            value=""
                            onChange={(path, label) => handleAdd(path, label)}
                            excludePaths={excludeFields}
                            placeholder={t("settings:facets.addFacet")}
                        />
                        <Button variant="outline" size="sm" onClick={handleAddCustom} className="self-start">
                            <Plus className="h-4 w-4" />
                            {t("settings:facets.addCustomFacet")}
                        </Button>
                    </div>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={handleSave} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
