import { useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { Upload } from "lucide-react"
import { Button } from "@/components/ui/button"
import { UploadDocumentModal } from "@/features/document/modals/UploadDocumentModal"

interface UploadDocumentButtonProps {
    collectionId?: string | undefined
    typeId?: string | undefined
    onUploadDone: (uploadedIds: ContentObjectItem[]) => void
}
export function UploadDocumentButton({ collectionId, typeId, onUploadDone }: Readonly<UploadDocumentButtonProps>) {
    const { t } = useTranslation("common")
    const [open, setOpen] = useState(false)

    const handleOpenModal = () => {
        setOpen(true)
    }

    return (
        <>
            <Button variant="outline" size="icon" onClick={handleOpenModal} className="h-8 w-8 sm:h-9 sm:w-auto sm:px-3 sm:gap-2">
                <Upload className="h-4 w-4" />
                <span className="hidden sm:inline">{t("actions.upload")}</span>
            </Button>
            <UploadDocumentModal open={open} onOpenChange={setOpen} collectionId={collectionId} typeId={typeId} onUploadDone={onUploadDone} />
        </>
    )
}