import { useTranslation } from "react-i18next"
import { UserGroup } from "@vertesia/common"
import { Loader2 } from "lucide-react"
import { TypeSelect } from "@/components/inputs/TypeSelect"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Textarea } from "@/components/ui/textarea"
import { useCollectionTypesWhitelist } from "@/hooks/use-collection-types-whitelist"
import type { CollectionCategory } from "./useCollectionWizard"

interface WizardStepDetailsProps {
    name: string
    setName: (name: string) => void
    description: string
    setDescription: (description: string) => void
    typeId: string
    setTypeId: (typeId: string) => void
    disabled?: boolean
    category?: CollectionCategory
    selectedGroups?: string[]
    setSelectedGroups?: (groups: string[]) => void
    availableGroups?: UserGroup[]
    isLoadingGroups?: boolean
}

export function WizardStepDetails({
    name,
    setName,
    description,
    setDescription,
    typeId,
    setTypeId,
    disabled = false,
    category,
    selectedGroups = [],
    setSelectedGroups,
    availableGroups = [],
    isLoadingGroups = false,
}: WizardStepDetailsProps) {
    const { t } = useTranslation("common")
    const collectionTypesWhitelist = useCollectionTypesWhitelist()
    const handleGroupToggle = (groupId: string, checked: boolean) => {
        if (!setSelectedGroups) return
        if (checked) {
            setSelectedGroups([...selectedGroups, groupId])
        } else {
            setSelectedGroups(selectedGroups.filter(id => id !== groupId))
        }
    }

    return (
        <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-2">
                <Label htmlFor="collection-name">{t("collectionWizard.nameLabel")}</Label>
                <Input
                    id="collection-name"
                    placeholder={t("collectionWizard.enterName")}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    disabled={disabled}
                    autoFocus
                />
            </div>

            <div className="flex flex-col gap-2">
                <Label htmlFor="collection-description">{t("collectionWizard.descriptionLabel")}</Label>
                <Textarea
                    id="collection-description"
                    placeholder={t("collectionWizard.enterDescription")}
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    disabled={disabled}
                    rows={3}
                />
            </div>

            <div className="flex flex-col gap-2">
                <Label>{t("collectionWizard.typeLabel")}</Label>
                <TypeSelect
                    value={typeId}
                    onChange={setTypeId}
                    placeholder={t("collectionWizard.selectType")}
                    disabled={disabled}
                    allowedTypes={collectionTypesWhitelist}
                />
            </div>

            {category === "organization" && (
                <div className="flex flex-col gap-2">
                    <Label>{t("collectionWizard.groupsLabel")}</Label>
                    {isLoadingGroups ? (
                        <div className="flex items-center gap-2 py-2 text-sm text-muted-foreground">
                            <Loader2 className="h-4 w-4 animate-spin" />
                            {t("collectionWizard.loadingGroups")}
                        </div>
                    ) : availableGroups.length === 0 ? (
                        <p className="text-sm text-muted-foreground py-2">{t("collectionWizard.noGroupsAvailable")}</p>
                    ) : (
                        <ScrollArea className="max-h-[160px] border rounded-md">
                            <div className="p-2 flex flex-col gap-1">
                                {availableGroups.map((group) => (
                                    <label
                                        key={group.id}
                                        className="flex items-center gap-3 p-2 rounded-md hover:bg-muted/50 cursor-pointer"
                                    >
                                        <Checkbox
                                            checked={selectedGroups.includes(group.id)}
                                            onCheckedChange={(checked) => handleGroupToggle(group.id, !!checked)}
                                            disabled={disabled}
                                        />
                                        <div className="flex flex-col min-w-0">
                                            <span className="text-sm font-medium truncate">{group.name}</span>
                                            {group.description && (
                                                <span className="text-xs text-muted-foreground truncate">{group.description}</span>
                                            )}
                                        </div>
                                    </label>
                                ))}
                            </div>
                        </ScrollArea>
                    )}
                </div>
            )}
        </div>
    )
}
