import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from "react"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { useFavoritesCollectionType } from "@/hooks/use-favorites-collection-type"
import {
    addFavorites,
    fetchFavoriteIds,
    findFavoritesCollection,
    findOrCreateFavoritesCollection,
    removeFavorites,
} from "@/lib/favorites"

interface FavoritesContextValue {
    /** Whether the initial favorites lookup has completed. */
    isReady: boolean
    /** Set of favorited document ids. */
    favoriteIds: Set<string>
    /** Whether a document is currently favorited. */
    isFavorite: (documentId: string) => boolean
    /** Toggle a single document's favorite status. */
    toggleFavorite: (documentId: string) => Promise<void>
    /** Add several documents to favorites. */
    addMany: (documentIds: string[]) => Promise<void>
    /** Remove several documents from favorites. */
    removeMany: (documentIds: string[]) => Promise<void>
    /** Reload the favorite ids from the server. */
    refresh: () => Promise<void>
}

const FavoritesContext = createContext<FavoritesContextValue | null>(null)

interface FavoritesProviderProps {
    children: ReactNode
}

export function FavoritesProvider({ children }: Readonly<FavoritesProviderProps>) {
    const { client, user } = useUserSession()
    const toast = useToast()
    const favoritesType = useFavoritesCollectionType()

    const [favoriteIds, setFavoriteIds] = useState<Set<string>>(new Set())
    const [isReady, setIsReady] = useState(false)

    // Cache the resolved collection id so we only create it once.
    const collectionIdRef = useRef<string | null>(null)
    const userSub = user?.sub

    // Resolve the favorites collection (read-only) and load its members on mount.
    useEffect(() => {
        let cancelled = false
        collectionIdRef.current = null
        setFavoriteIds(new Set())
        setIsReady(false)

        if (!client || !userSub) {
            return
        }

        ;(async () => {
            try {
                const collectionId = await findFavoritesCollection(client, userSub)
                if (cancelled) return
                collectionIdRef.current = collectionId
                if (collectionId) {
                    const ids = await fetchFavoriteIds(client, collectionId)
                    if (cancelled) return
                    setFavoriteIds(new Set(ids))
                }
            } catch {
                // Leave favorites empty; toggling will retry resolving the collection.
            } finally {
                if (!cancelled) {
                    setIsReady(true)
                }
            }
        })()

        return () => {
            cancelled = true
        }
    }, [client, userSub])

    const ensureCollectionId = useCallback(async (): Promise<string> => {
        if (collectionIdRef.current) {
            return collectionIdRef.current
        }
        if (!client || !userSub) {
            throw new Error("Favorites are unavailable without a signed-in user")
        }
        const collectionId = await findOrCreateFavoritesCollection(client, userSub, favoritesType)
        collectionIdRef.current = collectionId
        return collectionId
    }, [client, userSub, favoritesType])

    const addMany = useCallback(async (documentIds: string[]) => {
        if (documentIds.length === 0) return
        const toAdd = documentIds.filter((id) => !favoriteIds.has(id))
        if (toAdd.length === 0) return

        setFavoriteIds((prev) => {
            const next = new Set(prev)
            toAdd.forEach((id) => next.add(id))
            return next
        })

        try {
            const collectionId = await ensureCollectionId()
            await addFavorites(client, collectionId, toAdd)
        } catch (error: any) {
            // Revert optimistic update.
            setFavoriteIds((prev) => {
                const next = new Set(prev)
                toAdd.forEach((id) => next.delete(id))
                return next
            })
            toast({
                status: "error",
                title: "Failed to add to favorites",
                description: error?.message,
                duration: 3000,
            })
        }
    }, [client, favoriteIds, ensureCollectionId, toast])

    const removeMany = useCallback(async (documentIds: string[]) => {
        if (documentIds.length === 0) return
        const toRemove = documentIds.filter((id) => favoriteIds.has(id))
        if (toRemove.length === 0) return

        setFavoriteIds((prev) => {
            const next = new Set(prev)
            toRemove.forEach((id) => next.delete(id))
            return next
        })

        try {
            const collectionId = await ensureCollectionId()
            await removeFavorites(client, collectionId, toRemove)
        } catch (error: any) {
            setFavoriteIds((prev) => {
                const next = new Set(prev)
                toRemove.forEach((id) => next.add(id))
                return next
            })
            toast({
                status: "error",
                title: "Failed to remove from favorites",
                description: error?.message,
                duration: 3000,
            })
        }
    }, [client, favoriteIds, ensureCollectionId, toast])

    const toggleFavorite = useCallback(async (documentId: string) => {
        if (favoriteIds.has(documentId)) {
            await removeMany([documentId])
        } else {
            await addMany([documentId])
        }
    }, [favoriteIds, addMany, removeMany])

    const refresh = useCallback(async () => {
        if (!client) return
        const collectionId = collectionIdRef.current
        if (!collectionId) return
        try {
            const ids = await fetchFavoriteIds(client, collectionId)
            setFavoriteIds(new Set(ids))
        } catch {
            // Ignore refresh failures; existing state is kept.
        }
    }, [client])

    const isFavorite = useCallback((documentId: string) => favoriteIds.has(documentId), [favoriteIds])

    return (
        <FavoritesContext.Provider
            value={{ isReady, favoriteIds, isFavorite, toggleFavorite, addMany, removeMany, refresh }}
        >
            {children}
        </FavoritesContext.Provider>
    )
}

export function useFavorites() {
    const context = useContext(FavoritesContext)
    if (!context) {
        throw new Error("useFavorites must be used within a FavoritesProvider")
    }
    return context
}
