import { useState, useEffect, useMemo, useCallback } from "react"
import { useTranslation } from "react-i18next"
import { InteractionRef, InteractionStatus } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"
import { ChevronRight, Loader2, Minus } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"

interface InteractionOption {
    id: string
    name: string
    version: number
}

interface AgentGroup {
    name: string
    versions: InteractionOption[]
}

interface AgentsSectionProps {
    settings: Record<string, unknown> | undefined
    onSave: (values: { excludedAgents: string[] }) => void
    loading?: boolean
}

function groupAgents(interactions: InteractionOption[]): AgentGroup[] {
    const grouped = new Map<string, InteractionOption[]>()

    for (const interaction of interactions) {
        const existing = grouped.get(interaction.name)
        if (existing) {
            existing.push(interaction)
        } else {
            grouped.set(interaction.name, [interaction])
        }
    }

    const groups: AgentGroup[] = []
    for (const [name, versions] of grouped) {
        versions.sort((a, b) => b.version - a.version)
        groups.push({ name, versions })
    }

    groups.sort((a, b) => a.name.localeCompare(b.name))
    return groups
}

function getParentCheckState(
    versions: InteractionOption[],
    excludedIds: Set<string>
): boolean | "indeterminate" {
    const enabledCount = versions.filter((v) => !excludedIds.has(v.id)).length

    if (enabledCount === versions.length) return true
    if (enabledCount === 0) return false
    return "indeterminate"
}

interface AgentRowProps {
    group: AgentGroup
    excludedIds: Set<string>
    onToggleParent: (group: AgentGroup) => void
    onToggleVersion: (id: string) => void
}

function AgentRow({ group, excludedIds, onToggleParent, onToggleVersion }: AgentRowProps) {
    const { t } = useTranslation(["settings", "common"])
    const [expanded, setExpanded] = useState(false)
    const checkState = getParentCheckState(group.versions, excludedIds)

    return (
        <>
            <TableRow className="group">
                <TableCell>
                    <Checkbox
                        checked={checkState}
                        onCheckedChange={() => onToggleParent(group)}
                        aria-label={t("settings:agents.toggleAgent", { name: group.name })}
                    />
                </TableCell>
                <TableCell className="font-medium">{group.name}</TableCell>
                <TableCell>
                    <Badge variant="secondary">
                        {t("settings:agents.version", { count: group.versions.length })}
                    </Badge>
                </TableCell>
                <TableCell className="text-right">
                    {group.versions.length > 1 && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setExpanded(!expanded)}
                            aria-label={expanded ? t("settings:agents.collapseVersions") : t("settings:agents.expandVersions")}
                        >
                            <ChevronRight
                                className={cn(
                                    "h-4 w-4 transition-transform",
                                    expanded && "rotate-90"
                                )}
                            />
                        </Button>
                    )}
                </TableCell>
            </TableRow>
            {expanded &&
                group.versions.map((version) => (
                    <TableRow key={version.id} className="bg-muted/30">
                        <TableCell className="pl-8">
                            <Checkbox
                                checked={!excludedIds.has(version.id)}
                                onCheckedChange={() => onToggleVersion(version.id)}
                                aria-label={t("settings:agents.toggleAgent", { name: `${version.name} v${version.version}` })}
                            />
                        </TableCell>
                        <TableCell className="text-muted-foreground">
                            <div className="flex items-center gap-2">
                                <Minus className="h-3 w-3 text-muted-foreground/50" />
                                {version.name}
                            </div>
                        </TableCell>
                        <TableCell>
                            <Badge variant="outline" className="text-xs">
                                v{version.version}
                            </Badge>
                        </TableCell>
                        <TableCell />
                    </TableRow>
                ))}
        </>
    )
}

export function AgentsSection({ settings, onSave, loading }: Readonly<AgentsSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const { client } = useUserSession()
    const [interactions, setInteractions] = useState<InteractionOption[]>([])
    const [isLoading, setIsLoading] = useState(true)
    const [excludedAgents, setExcludedAgents] = useState<string[]>(
        Array.isArray(settings?.AGENT_INTERACTIONS_EXCLUDED_LIST) ? settings.AGENT_INTERACTIONS_EXCLUDED_LIST : []
    )
    
    useEffect(() => {
        if (!client) return

        const fetchInteractions = async () => {
            setIsLoading(true)
            try {
                const result = await client.interactions.list({
                    query: {
                        status: InteractionStatus.published,
                        tags: ["agent"],
                    },
                })
                const options: InteractionOption[] = result
                    .filter((interaction: InteractionRef) => !interaction.tags.includes("default"))
                    .map((interaction: InteractionRef) => ({
                        id: interaction.id,
                        name: interaction.name,
                        version: interaction.version,
                    }))
                setInteractions(options)
            } catch (error) {
                console.error("Failed to fetch interactions:", error)
                setInteractions([])
            } finally {
                setIsLoading(false)
            }
        }

        fetchInteractions()
    }, [client])

    const excludedIds = useMemo(() => new Set(excludedAgents), [excludedAgents])
    const groups = useMemo(() => groupAgents(interactions), [interactions])

    const handleToggleVersion = useCallback(
        (id: string) => {
            setExcludedAgents((prev) =>
                prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
            )
        },
        []
    )

    const handleToggleParent = useCallback(
        (group: AgentGroup) => {
            setExcludedAgents((prev) => {
                const prevSet = new Set(prev)
                const enabledCount = group.versions.filter((v) => !prevSet.has(v.id)).length
                const allEnabled = enabledCount === group.versions.length

                if (allEnabled) {
                    // Disable all: add all version IDs to excluded
                    return [...prev, ...group.versions.filter((v) => !prevSet.has(v.id)).map((v) => v.id)]
                } else {
                    // Enable all: remove all version IDs from excluded
                    const versionIds = new Set(group.versions.map((v) => v.id))
                    return prev.filter((id) => !versionIds.has(id))
                }
            })
        },
        []
    )

    const enabledCount = interactions.length - excludedAgents.filter((id) => interactions.some((i) => i.id === id)).length
    const totalCount = interactions.length

    return (
        <Card className="flex flex-col h-full overflow-hidden">
            <CardHeader className="shrink-0">
                <CardTitle>{t("settings:agents.title")}</CardTitle>
                <CardDescription>
                    {t("settings:agents.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-4 min-h-0 flex-1">
                {isLoading ? (
                    <div className="flex h-24 items-center justify-center">
                        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                    </div>
                ) : groups.length === 0 ? (
                    <p className="text-sm text-muted-foreground">{t("settings:agents.noAgentsFound")}</p>
                ) : (
                    <>
                        <div className="flex items-center justify-between shrink-0">
                            <p className="text-sm text-muted-foreground">
                                {t("settings:agents.enabledCount", { enabledCount, totalCount, count: totalCount })}
                            </p>
                        </div>
                        <div className="rounded-md border min-h-0 flex-1 overflow-auto">
                            <table className="w-full caption-bottom text-sm">
                                <TableHeader className="sticky top-0 z-10 bg-background">
                                    <TableRow>
                                        <TableHead className="w-[50px]">{t("settings:agents.columns.enabled")}</TableHead>
                                        <TableHead>{t("settings:agents.columns.agent")}</TableHead>
                                        <TableHead className="w-[120px]">{t("settings:agents.columns.versions")}</TableHead>
                                        <TableHead className="w-[60px]" />
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {groups.map((group) => (
                                        <AgentRow
                                            key={group.name}
                                            group={group}
                                            excludedIds={excludedIds}
                                            onToggleParent={handleToggleParent}
                                            onToggleVersion={handleToggleVersion}
                                        />
                                    ))}
                                </TableBody>
                            </table>
                        </div>
                    </>
                )}
            </CardContent>
            <CardFooter className="justify-end shrink-0">
                <Button onClick={() => onSave({ excludedAgents })} disabled={loading || isLoading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
