import { useTranslation } from "react-i18next"
import { FileText, FolderOpen, X } from "lucide-react"
import { motion } from "motion/react"
import { Button } from "@/components/ui/button"
import { type MemberItem as MemberItemType } from "./useCollectionWizard"

interface MemberItemProps {
    member: MemberItemType
    isNew?: boolean
    onRemove: (member: MemberItemType) => void
    disabled?: boolean
}

export function MemberItem({ member, isNew, onRemove, disabled }: MemberItemProps) {
    const { t } = useTranslation("common")
    return (
        <motion.div
            layout
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="flex items-center justify-between p-2 rounded-md hover:bg-muted/50 group"
        >
            <div className="flex items-center gap-2 min-w-0 flex-1">
                {member.type === "document" ? (
                    <FileText className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                ) : (
                    <FolderOpen className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                )}
                <span className="text-sm truncate">{member.name}</span>
                {isNew && (
                    <span className="text-xs text-primary font-medium flex-shrink-0">{t("collectionWizard.newMemberLabel")}</span>
                )}
            </div>
            <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity"
                onClick={() => onRemove(member)}
                disabled={disabled}
            >
                <X className="h-4 w-4 text-muted-foreground hover:text-destructive" />
            </Button>
        </motion.div>
    )
}
