import { InteractionRef, InteractionStatus } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"

export const useInteractionsSearch = () => {
    const { client } = useUserSession()

    const searchInteractions = async (
        tags: string[],
        version: number | undefined,
        excludedIds: string[],
        setInteractions: React.Dispatch<React.SetStateAction<InteractionRef[]>>
    ) => {
        const query: any = {
            status: InteractionStatus.published,
            tags: ["agent", ...tags],
            version
        }

        client.interactions.list({ query })
            .then((interactions) => {
                let tmpInteractions = interactions
                    .filter((interaction) => !interaction.tags.includes("default"))
                    .filter((interaction) => !excludedIds.includes(interaction.id))

                const interactionsMap = tmpInteractions.reduce<Record<string, InteractionRef[]>>((acc, item) => {
                    const key = item.endpoint
                    if (!acc[key]) {
                        acc[key] = []
                    }
                    acc[key].push(item)
                    return acc
                }, {})

                tmpInteractions = Object.values(interactionsMap).map((interactions) => {
                    const publishedVersions = interactions.filter((item) => item.status === InteractionStatus.published)
                    if (publishedVersions.length > 0) {
                        return publishedVersions.reduce((latest, current) => (current.version > latest.version ? current : latest))
                    } else {
                        return interactions.reduce((latest, current) => (current.version > latest.version ? current : latest))
                    }
                })

                setInteractions(tmpInteractions)
            })
    }

    return { searchInteractions }
}