import { useTranslation } from "react-i18next"
import { CircleHelp, RefreshCw, X, Search } from "lucide-react"
import { UploadDocumentButton } from "@/components/buttons/UploadDocumentButton"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Slider } from "@/components/ui/slider"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { BasicFilterOption } from "@/models/search"

interface SearchFilters {
    [key: string]: any
}

interface LibraryFiltersProps {
    filters: SearchFilters
    onFiltersChange: (filters: Partial<SearchFilters>) => void
    onRefresh: () => void
    basicFilters: BasicFilterOption[]
    getValueLabel: (filterId: string, value: string) => string
    isAdvancedSearch?: boolean
    scoreThreshold: number
    onScoreThresholdChange: (value: number) => void
}
export function LibraryFilters({ filters, onFiltersChange, onRefresh, basicFilters, getValueLabel, isAdvancedSearch = false, scoreThreshold, onScoreThresholdChange }: LibraryFiltersProps) {
    const { t } = useTranslation("common")

    const handleSearchChange = (value: string) => {
        onFiltersChange({ search: value })
    }

    const clearAllFilters = () => {
        onFiltersChange({})
    }

    // Only consider single-value (basic) selections for the active filter badges
    const activeFilters = basicFilters.filter((filter) => {
        const value = filters[filter.id]
        return value !== undefined && value !== "" && !Array.isArray(value)
    })

    return (
        <div className="flex flex-col gap-4">
            {/* Search Bar with Refresh and Upload */}
            <div className="flex flex-row gap-2">
                <div className="relative flex-1">
                    <Search className="absolute left-2.5 sm:left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground z-10 pointer-events-none" />
                    <Input
                        placeholder={t("filters.searchDocuments")}
                        value={filters.search || ""}
                        onChange={(e) => handleSearchChange(e.target.value)}
                        className="ecm-search h-8 sm:h-9 pl-9 sm:pl-10"
                    />
                </div>

                {/* Score Threshold Slider */}
                <div className="flex items-center gap-2 min-w-40 max-w-56">
                    <Label className="text-xs text-muted-foreground whitespace-nowrap">{t("filters.scoreLabel")}</Label>
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <CircleHelp className="h-3.5 w-3.5 text-muted-foreground cursor-help shrink-0" />
                        </TooltipTrigger>
                        <TooltipContent side="bottom" className="max-w-64">
                            {t("filters.scoreTooltip")}
                        </TooltipContent>
                    </Tooltip>
                    <Slider
                        min={0.25}
                        max={1}
                        step={0.05}
                        value={[scoreThreshold]}
                        onValueChange={(values) => onScoreThresholdChange(values[0])}
                    />
                    <span className="text-xs font-mono text-muted-foreground w-7 text-right">
                        {scoreThreshold.toFixed(2)}
                    </span>
                </div>

                {/* Refresh Button */}
                <Button variant="outline" size="icon" onClick={onRefresh} className="h-8 w-8 sm:h-9 sm:w-auto sm:px-3 sm:gap-2">
                    <RefreshCw className="h-4 w-4" />
                    <span className="hidden sm:inline">{t("actions.refresh")}</span>
                </Button>

                {/* Upload Button */}
                <UploadDocumentButton onUploadDone={() => onRefresh()} />
            </div>

            {/* Active Filters as Tags (basic single-select selections) */}
            {!isAdvancedSearch && activeFilters.length > 0 && (
                <div className="flex flex-row items-center gap-2 flex-wrap">
                    {activeFilters.map((filter) => (
                        <Badge
                            key={filter.id}
                            variant="secondary"
                            className="flex flex-row items-center gap-1 max-w-48"
                            title={`${filter.label}: ${getValueLabel(filter.id, filters[filter.id])}`}
                        >
                            <span className="truncate">{filter.label}: {getValueLabel(filter.id, filters[filter.id])}</span>
                            <X
                                className="h-3 w-3 cursor-pointer shrink-0"
                                onClick={() => onFiltersChange({ [filter.id]: undefined })}
                            />
                        </Badge>
                    ))}
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearAllFilters}
                        className="h-6 text-xs"
                    >
                        {t("actions.clearAll")}
                    </Button>
                </div>
            )}
        </div>
    )
}
