import { useState, useEffect, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { CollectionItem, ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Loader2, PanelRightOpen, PanelRightClose, ChevronRight, Pencil, Filter, Check } from "lucide-react"
import { CreateCollectionOverlay } from "@/components/overlays/CreateCollectionOverlay"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Separator } from "@/components/ui/separator"
import { CollectionThumbnail } from "@/components/widgets/CollectionThumbnail"
import { DocumentThumbnailWithModal } from "@/components/widgets/DocumentThumbnailWithModal"
import { ItemsDataTable } from "@/components/widgets/ItemsDataTable"
import { ViewModeSwitcher, ViewMode } from "@/components/widgets/ViewModeSwitcher"
import { LAST_PANEL_STATE, LAST_VIEW_MODE } from "@/constants/cookies"
import { useBreadcrumbLabel } from "@/contexts/BreadcrumbContext"

type MemberItem = (ContentObjectItem | CollectionItem) & { itemType: "document" | "collection" }

type DisplayFilter = "all" | "collections" | "documents"

type BreadcrumbItem = {
    id: string
    name: string
}

interface CollectionDetailPanelProps {
    collectionId: string
}
export function CollectionDetailPanel({ collectionId }: Readonly<CollectionDetailPanelProps>) {
    const { t } = useTranslation(["collections", "common"])
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const toast = useToast()

    const [collection, setCollection] = useState<CollectionItem | null>(null)
    const [items, setItems] = useState<MemberItem[]>([])
    const [loading, setLoading] = useState(true)
    const [isTransitioning, setIsTransitioning] = useState(false)
    const [isSidebarOpen, setIsSidebarOpen] = useState(localStorage.getItem(LAST_PANEL_STATE) === "open")
    const [breadcrumb, setBreadcrumb] = useState<BreadcrumbItem[]>([])
    const [currentCollectionId, setCurrentCollectionId] = useState<string>(collectionId)
    const [isNavigating, setIsNavigating] = useState(false)
    const [displayFilter, setDisplayFilter] = useState<DisplayFilter>("all")
    const [isEditOverlayOpen, setIsEditOverlayOpen] = useState(false)
    const [viewMode, setViewMode] = useState<ViewMode>(() => {
        const saved = localStorage.getItem(LAST_VIEW_MODE)
        return (saved === "grid" || saved === "table") ? saved : "grid"
    })

    const handleViewModeChange = (mode: ViewMode) => {
        localStorage.setItem(LAST_VIEW_MODE, mode)
        setViewMode(mode)
    }

    // Register collection name for breadcrumb display
    useBreadcrumbLabel(collectionId, collection?.name)

    const loadCollection = async (targetCollectionId: string) => {
        try {
            // Fetch collection details
            const collectionData = await client.store.collections.retrieve(targetCollectionId)

            // Fetch collection members (documents)
            const membersPromise = client.store.collections.searchMembers(targetCollectionId, { limit: 1000 })

            // Fetch collection children (sub-collections)
            const childrenPromise = client.store.collections.searchChildren(targetCollectionId, { limit: 1000 })

            const [membersData, childrenData] = await Promise.all([membersPromise, childrenPromise])

            // Combine both arrays with type information
            const memberItems: MemberItem[] = [
                ...childrenData.map(child => ({ ...child, itemType: "collection" as const })),
                ...membersData.results.map(member => ({ ...member, itemType: "document" as const }))
            ]

            // Small delay for smooth transition when navigating
            if (isNavigating) {
                await new Promise(resolve => setTimeout(resolve, 150))
            }

            setCollection(collectionData)
            setItems(memberItems)
        } catch (error: any) {
            toast({
                status: "error",
                title: "Failed to load collection",
                description: error.message || "An error occurred",
                duration: 3000,
            })
        } finally {
            setLoading(false)
            setIsTransitioning(false)
            setIsNavigating(false)
        }
    }

    // Initialize breadcrumb with root collection
    useEffect(() => {
        if (!client) return

        const initializeCollection = async () => {
            const rootCollection = await client.store.collections.retrieve(collectionId)
            setBreadcrumb([{ id: collectionId, name: rootCollection.name }])
            setCurrentCollectionId(collectionId)
        }

        initializeCollection()
    }, [client, collectionId])

    // Load collection when currentCollectionId changes
    useEffect(() => {
        if (!client || !currentCollectionId) return

        // Set appropriate loading state
        if (isNavigating) {
            setIsTransitioning(true)
        } else if (!collection) {
            setLoading(true)
        }

        loadCollection(currentCollectionId)
    }, [client, currentCollectionId])

    const handleSidebarToggle = () => {
        const current = isSidebarOpen
        localStorage.setItem(LAST_PANEL_STATE, current ? "closed" : "open")
        setIsSidebarOpen(!current)
    }

    const handleCollectionClick = (childCollection: CollectionItem) => {
        // Mark as navigating and add to breadcrumb
        setIsNavigating(true)
        setDisplayFilter("all") // Reset filter when navigating
        setBreadcrumb(prev => [...prev, { id: childCollection.id, name: childCollection.name }])
        setCurrentCollectionId(childCollection.id)
    }

    const handleBreadcrumbClick = async (index: number) => {
        // Mark as navigating and start transition
        setIsNavigating(true)
        setIsTransitioning(true)
        setDisplayFilter("all") // Reset filter when navigating

        // Small delay to start fade out
        await new Promise(resolve => setTimeout(resolve, 100))

        // Navigate to breadcrumb item and trim breadcrumb
        const targetBreadcrumb = breadcrumb[index]
        setBreadcrumb(prev => prev.slice(0, index + 1))
        setCurrentCollectionId(targetBreadcrumb.id)
    }

    // Filter items based on display filter (must be before early returns)
    const filteredItems = useMemo(() => {
        if (displayFilter === "all") return items
        if (displayFilter === "collections") return items.filter(item => item.itemType === "collection")
        if (displayFilter === "documents") return items.filter(item => item.itemType === "document")
        return items
    }, [items, displayFilter])

    // Count collections and documents (must be before early returns)
    const collectionCount = useMemo(() => items.filter(item => item.itemType === "collection").length, [items])
    const documentCount = useMemo(() => items.filter(item => item.itemType === "document").length, [items])
    const showFilterButtons = collectionCount > 0 && documentCount > 0

    const typeName = typeRegistry?.getTypeName(collection?.type?.id || "") || collection?.type?.name || t("common:collection")

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
        )
    }

    if (!collection) {
        return (
            <div className="flex items-center justify-center h-full">
                <p className="text-muted-foreground">{t("collections:detail.notFound")}</p>
            </div>
        )
    }

    return (
        <div className="flex flex-col h-full gap-2 sm:gap-3 md:gap-4 p-2">
            {/* Header Card */}
            <Card className="shadow-md bg-muted/50 overflow-hidden">
                <div className={`flex flex-col gap-2 px-3 sm:px-4 py-2.5 sm:py-3 transition-opacity duration-200 overflow-hidden ${isTransitioning ? "opacity-50" : "opacity-100"}`}>
                    {/* Header row with title and actions */}
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                        {/* Collection name */}
                        <h1 className="text-base sm:text-lg md:text-xl font-semibold truncate flex-1 w-[50px] min-w-0" title={collection.name}>
                            {collection.name}
                        </h1>

                        {/* Action buttons */}
                        <div className="flex items-center gap-1.5 sm:gap-2 flex-shrink-0">
                            {/* Filter dropdown - visible on smaller screens when filters available */}
                            {showFilterButtons && (
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button
                                            variant="outline"
                                            size="icon"
                                            className="h-8 w-8 sm:h-9 sm:w-auto sm:px-3 sm:gap-1.5 lg:hidden"
                                        >
                                            <Filter className="h-4 w-4" />
                                            <span className="hidden sm:inline text-xs capitalize">{displayFilter}</span>
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="start">
                                        <DropdownMenuItem onClick={() => setDisplayFilter("all")}>
                                            <Check className={`h-4 w-4 mr-2 ${displayFilter === "all" ? "opacity-100" : "opacity-0"}`} />
                                            {t("collections:detail.all")}
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => setDisplayFilter("collections")}>
                                            <Check className={`h-4 w-4 mr-2 ${displayFilter === "collections" ? "opacity-100" : "opacity-0"}`} />
                                            {t("collections:detail.collectionsCount", { count: collectionCount })}
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => setDisplayFilter("documents")}>
                                            <Check className={`h-4 w-4 mr-2 ${displayFilter === "documents" ? "opacity-100" : "opacity-0"}`} />
                                            {t("collections:detail.documentsCount", { count: documentCount })}
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            )}

                            {/* Filter buttons - visible on large screens */}
                            {showFilterButtons && (
                                <div className="hidden lg:flex items-center gap-1 border rounded-md p-1 bg-background">
                                    <Button
                                        variant={displayFilter === "all" ? "default" : "ghost"}
                                        size="sm"
                                        onClick={() => setDisplayFilter("all")}
                                        className="h-7 px-2 text-xs"
                                    >
                                        {t("collections:detail.all")}
                                    </Button>
                                    <Button
                                        variant={displayFilter === "collections" ? "default" : "ghost"}
                                        size="sm"
                                        onClick={() => setDisplayFilter("collections")}
                                        className="h-7 px-2 text-xs"
                                    >
                                        {t("collections:detail.collections")}
                                    </Button>
                                    <Button
                                        variant={displayFilter === "documents" ? "default" : "ghost"}
                                        size="sm"
                                        onClick={() => setDisplayFilter("documents")}
                                        className="h-7 px-2 text-xs"
                                    >
                                        {t("collections:detail.documents")}
                                    </Button>
                                </div>
                            )}

                            <ViewModeSwitcher value={viewMode} onValueChange={handleViewModeChange} />

                            <Button
                                onClick={() => setIsEditOverlayOpen(true)}
                                size="icon"
                                className="h-8 w-8 sm:h-9 sm:w-auto sm:px-3 sm:gap-1.5 border border-primary/50 bg-popover text-popover-foreground hover:bg-primary/50"
                            >
                                <Pencil className="h-4 w-4" />
                                <span className="hidden sm:inline">{t("common:actions.edit")}</span>
                            </Button>

                            <Button
                                variant="ghost"
                                size="icon"
                                onClick={handleSidebarToggle}
                                className="h-8 w-8 sm:h-9 sm:w-9"
                            >
                                {isSidebarOpen ? <PanelRightClose className="h-4 w-4" /> : <PanelRightOpen className="h-4 w-4" />}
                            </Button>
                        </div>
                    </div>

                    {/* Breadcrumb row */}
                    {breadcrumb.length > 1 && (
                        <div className="flex items-center gap-1 text-xs text-muted-foreground overflow-x-auto hide-scrollbar -mx-1 px-1">
                            {breadcrumb.map((item, index) => (
                                <div key={item.id} className="flex items-center gap-1 flex-shrink-0 max-w-[120px] sm:max-w-[180px] md:max-w-[220px]">
                                    {index > 0 && <ChevronRight className="h-3 w-3 flex-shrink-0 text-muted-foreground/60" />}
                                    <button
                                        onClick={() => handleBreadcrumbClick(index)}
                                        className={`truncate min-w-0 hover:cursor-pointer hover:text-foreground transition-colors ${
                                            index === breadcrumb.length - 1 ? "font-medium text-foreground" : "hover:underline"
                                        }`}
                                        disabled={index === breadcrumb.length - 1 || isTransitioning}
                                        title={item.name}
                                    >
                                        {item.name}
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            {/* Content Area */}
            <div className="flex flex-col md:flex-row flex-1 gap-2 sm:gap-3 md:gap-4 min-h-0 overflow-hidden">
                {/* Members Grid - Hidden on mobile when sidebar is open */}
                <div className={`${isSidebarOpen ? "hidden md:flex" : "flex"} flex-1 min-w-0 overflow-hidden`}>
                    <div className={`w-full h-full min-w-0 overflow-auto transition-opacity duration-200 ${isTransitioning ? "opacity-0" : "opacity-100"}`}>
                        {filteredItems.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
                                {items.length === 0 ? (
                                    <>
                                        <p>{t("collections:detail.noItems")}</p>
                                        <p className="text-sm mt-1">{t("collections:detail.noItemsHelp")}</p>
                                    </>
                                ) : (
                                    <>
                                        <p>{t("collections:detail.noFilterResults", { filter: displayFilter === "collections" ? t("collections:detail.collections").toLowerCase() : t("collections:detail.documents").toLowerCase() })}</p>
                                        <p className="text-sm mt-1">{t("collections:detail.noFilterResultsHelp")}</p>
                                    </>
                                )}
                            </div>
                        ) : viewMode === "grid" ? (
                            <div className={`grid gap-4 ${isSidebarOpen ? "grid-cols-1 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4" : "grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5"} items-start`}>
                                {filteredItems.map((item) => (
                                    item.itemType === "collection" ? (
                                        <CollectionThumbnail
                                            key={item.id}
                                            collection={item as CollectionItem}
                                            showDetails={true}
                                            onClick={() => handleCollectionClick(item as CollectionItem)}
                                        />
                                    ) : (
                                        <DocumentThumbnailWithModal
                                            key={item.id}
                                            document={item as ContentObjectItem}
                                            showDetails={true}
                                            showHoverInfo={false}
                                        />
                                    )
                                ))}
                            </div>
                        ) : (
                            <ItemsDataTable
                                items={filteredItems}
                                onCollectionClick={handleCollectionClick}
                            />
                        )}
                    </div>
                </div>

                {/* Properties Sidebar - Full height on mobile, fixed width on desktop */}
                {isSidebarOpen && (
                    <Card className="flex flex-col shadow-md w-full md:w-80 lg:w-96 flex-shrink-0 bg-muted/50 overflow-auto">
                        <CardHeader>
                            <CardTitle>{t("common:documentPanel.properties")}</CardTitle>
                        </CardHeader>
                        <CardContent className={`space-y-4 transition-opacity duration-200 ${isTransitioning ? "opacity-50" : "opacity-100"}`}>
                            <div>
                                <Label>{t("common:properties.name")}</Label>
                                <p className="text-sm text-muted-foreground">{collection.name}</p>
                            </div>

                            <Separator />

                            <div>
                                <Label>{t("common:properties.type")}</Label>
                                <p className="text-sm text-muted-foreground">{typeName}</p>
                            </div>

                            <Separator />

                            <div>
                                <Label>{t("common:items", { count: items.length })}</Label>
                                <p className="text-sm text-muted-foreground">
                                    {items.length} {t("collections:detail.total")}
                                    {showFilterButtons && (
                                        <span className="text-xs ml-1">
                                            ({t("collections:detail.collectionsCount", { count: collectionCount })}, {t("collections:detail.documentsCount", { count: documentCount })})
                                        </span>
                                    )}
                                </p>
                            </div>

                            {collection.created_at && (
                                <>
                                    <Separator />
                                    <div>
                                        <Label>{t("common:properties.createdAt")}</Label>
                                        <p className="text-sm text-muted-foreground">
                                            {new Date(collection.created_at).toLocaleString()}
                                        </p>
                                    </div>
                                </>
                            )}

                            {collection.updated_at && (
                                <>
                                    <Separator />
                                    <div>
                                        <Label>{t("common:properties.updatedAt")}</Label>
                                        <p className="text-sm text-muted-foreground">
                                            {new Date(collection.updated_at).toLocaleString()}
                                        </p>
                                    </div>
                                </>
                            )}

                            {collection?.description && (
                                <>
                                    <Separator />
                                    <div>
                                        <Label>{t("common:properties.description")}</Label>
                                        <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                                            {collection.description}
                                        </p>
                                    </div>
                                </>
                            )}
                        </CardContent>
                    </Card>
                )}
            </div>

            {/* Edit Collection Overlay */}
            <CreateCollectionOverlay
                isOpen={isEditOverlayOpen}
                onClose={() => setIsEditOverlayOpen(false)}
                collection={collection}
                onSuccess={() => loadCollection(currentCollectionId)}
            />
        </div>
    )
}

function Label({ children }: { children: React.ReactNode }) {
    return <p className="text-sm font-medium mb-1">{children}</p>
}
