import { useMemo } from "react"
import { useTranslation } from "react-i18next"
import { Trash2 } from "lucide-react"
import { PropertySelect } from "@/components/inputs/PropertySelect"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { PropertyConfig } from "@/models/property"

const MODIFIER_OPTIONS = [
    { value: "none", label: "None" },
    { value: "date", label: "Date" },
    { value: "type", label: "Type" },
    { value: "user", label: "User" },
] as const

interface PropertyListEditorProps {
    typeId: string
    properties: PropertyConfig[]
    onAdd: (path: string, label: string) => void
    onRemove: (index: number) => void
    onChange: (index: number, field: keyof PropertyConfig, value: string) => void
}

function PropertyRow({
    typeId,
    prop,
    index,
    showLabels,
    excludePaths,
    onRemove,
    onChange,
}: Readonly<{
    typeId: string
    prop: PropertyConfig
    index: number
    showLabels: boolean
    excludePaths: string[]
    onRemove: (index: number) => void
    onChange: (index: number, field: keyof PropertyConfig, value: string) => void
}>) {
    const { t } = useTranslation(["settings", "common"])
    const handlePropertySelect = (path: string, label: string) => {
        onChange(index, "path", path)
        if (!prop.label?.trim()) {
            onChange(index, "label", label)
        }
    }

    return (
        <div className="grid grid-cols-[1fr_1fr_auto_auto] gap-2 items-end">
            <div className="flex flex-col gap-1">
                {showLabels && <Label className="text-xs text-muted-foreground">{t("common:properties.property")}</Label>}
                <PropertySelect
                    typeId={typeId}
                    value={prop.path}
                    onChange={handlePropertySelect}
                    excludePaths={excludePaths}
                />
            </div>
            <div className="flex flex-col gap-1">
                {showLabels && <Label className="text-xs text-muted-foreground">{t("common:properties.label")}</Label>}
                <Input
                    placeholder={t("settings:properties.displayLabel")}
                    value={prop.label ?? ""}
                    onChange={(e) => onChange(index, "label", e.target.value)}
                />
            </div>
            <div className="flex flex-col gap-1">
                {showLabels && <Label className="text-xs text-muted-foreground">{t("common:properties.modifier")}</Label>}
                <Select
                    value={prop.modifier ?? "none"}
                    onValueChange={(v) => onChange(index, "modifier", v)}
                >
                    <SelectTrigger className="w-[100px]">
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        {MODIFIER_OPTIONS.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                                {opt.label}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            </div>
            <Button variant="ghost" size="icon" onClick={() => onRemove(index)}>
                <Trash2 className="h-4 w-4 text-destructive" />
            </Button>
        </div>
    )
}

export function PropertyListEditor({ typeId, properties, onAdd, onRemove, onChange }: Readonly<PropertyListEditorProps>) {
    const excludePaths = useMemo(() => properties.map((p) => p.path), [properties])

    return (
        <div className="flex flex-col gap-3">
            {properties.length === 0 && (
                <p className="text-sm text-muted-foreground italic">No properties configured. Click "Add property" to start.</p>
            )}

            {properties.map((prop, index) => (
                <PropertyRow
                    key={index}
                    typeId={typeId}
                    prop={prop}
                    index={index}
                    showLabels={index === 0}
                    excludePaths={excludePaths}
                    onRemove={onRemove}
                    onChange={onChange}
                />
            ))}

            <div>
                <AddPropertyButton typeId={typeId} excludePaths={excludePaths} onAdd={onAdd} />
            </div>
        </div>
    )
}

function AddPropertyButton({
    typeId,
    excludePaths,
    onAdd,
}: Readonly<{
    typeId: string
    excludePaths: string[]
    onAdd: (path: string, label: string) => void
}>) {
    const { t } = useTranslation("settings")
    return (
        <PropertySelect
            typeId={typeId}
            value=""
            onChange={(path, label) => onAdd(path, label)}
            excludePaths={excludePaths}
            placeholder={t("properties.addProperty")}
        />
    )
}
