import { Check } from "lucide-react"
import { cn } from "@/lib/utils"

interface WizardStepIndicatorProps {
    currentStep: number
    totalSteps: number
    stepLabels?: string[]
}

export function WizardStepIndicator({
    currentStep,
    totalSteps,
    stepLabels = ["Details", "Members", "Review"]
}: WizardStepIndicatorProps) {
    return (
        <div className="flex items-center justify-center gap-2 py-4">
            {Array.from({ length: totalSteps }, (_, index) => {
                const step = index + 1
                const isCompleted = step < currentStep
                const isCurrent = step === currentStep

                return (
                    <StepItem
                        key={step}
                        step={step}
                        label={stepLabels[index]}
                        isCompleted={isCompleted}
                        isCurrent={isCurrent}
                        isLast={step === totalSteps}
                    />
                )
            })}
        </div>
    )
}

interface StepItemProps {
    step: number
    label: string
    isCompleted: boolean
    isCurrent: boolean
    isLast: boolean
}

function StepItem({ step, label, isCompleted, isCurrent, isLast }: StepItemProps) {
    return (
        <>
            <div className="flex flex-col items-center gap-1">
                <div
                    className={cn(
                        "flex h-8 w-8 items-center justify-center rounded-full text-sm font-medium transition-colors",
                        isCompleted && "bg-primary text-primary-foreground",
                        isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/20 ring-offset-2",
                        !isCompleted && !isCurrent && "bg-muted text-muted-foreground"
                    )}
                >
                    {isCompleted ? (
                        <Check className="h-4 w-4" />
                    ) : (
                        step
                    )}
                </div>
                <span
                    className={cn(
                        "text-xs transition-colors",
                        (isCompleted || isCurrent) && "text-foreground font-medium",
                        !isCompleted && !isCurrent && "text-muted-foreground"
                    )}
                >
                    {label}
                </span>
            </div>
            {!isLast && (
                <div
                    className={cn(
                        "h-0.5 w-12 transition-colors -mt-5",
                        isCompleted ? "bg-primary" : "bg-muted"
                    )}
                />
            )}
        </>
    )
}
