import { useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { Collection } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { FolderOpen } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { formatRelativeDate } from "@/lib/date"
import { retrieveRenditionById } from "@/lib/rendition"
import { cn } from "@/lib/utils"

interface CollectionCardProps {
    collection: Collection
    onClick: (collection: Collection) => void
}

export function CollectionCard({ collection, onClick }: CollectionCardProps) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const toast = useToast()
    const [memberCount, setMemberCount] = useState<number>(0)
    const imageObjectId = collection.properties?.image
    const [backgroundUrl, setBackgroundUrl] = useState<string>("")

    const typeName = typeRegistry?.getTypeName(collection.type?.id || "") || collection.type?.name || t("collection")

    useEffect(() => {
        if (client && imageObjectId) {
            retrieveRenditionById(client, imageObjectId, setBackgroundUrl, () => {}, toast, 512)
        }
    }, [client, imageObjectId])

    useEffect(() => {
        if (!client || !collection.id) {
            return
        }

        const fetchMemberCount = async () => {
            try {
                const [members, children] = await Promise.all([
                    client.store.collections.computeFacets(collection.id, {
                        facets: [{ name: "total", field: "total" }]
                    }),
                    client.store.collections.searchChildren(collection.id, { limit: 10000 })
                ])

                const total = ((members)?.total || 0) + children.length
                setMemberCount(total)
            } catch (error) {
                console.error("Failed to fetch member count:", error)
                setMemberCount(0)
            }
        }

        fetchMemberCount()
    }, [client, collection.id])

    return (
        <div
            className="border overflow-hidden hover:shadow-md transition-shadow cursor-pointer group rounded-sm"
            onClick={() => onClick(collection)}
        >
            <div className="relative w-full aspect-square bg-muted flex items-center justify-center overflow-hidden">
                {backgroundUrl ? (
                    <>
                        <div
                            className="absolute inset-0 bg-cover bg-center"
                            style={{ backgroundImage: `url(${backgroundUrl})` }}
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-black/20" />
                    </>
                ) : null}
                <div className={cn(
                    "relative z-10 transition-colors",
                    backgroundUrl
                        ? "text-white/80 group-hover:text-white"
                        : "text-muted-foreground group-hover:text-foreground"
                )}>
                    <FolderOpen className="h-12 w-12" />
                </div>

                {/* Type Badge - Top Right */}
                <div className="absolute top-2 right-2">
                    <Badge className="bg-primary/90 text-secondary backdrop-blur-sm shadow-lg">
                        {typeName}
                    </Badge>
                </div>

                {/* Count Badge - Bottom */}
                <div className="absolute bottom-2 left-2">
                    <Badge variant="secondary" className="backdrop-blur-sm">
                        {memberCount} item{memberCount > 1 && "s"}
                    </Badge>
                </div>
            </div>

            <div className="p-3">
                <div className="flex flex-col gap-1">
                    <p className="text-sm font-medium truncate" title={collection.name}>
                        {collection.name}
                    </p>
                    {collection.updated_at && (
                        <div className="flex flex-row items-center gap-2 text-xs text-muted-foreground">
                            <span>{formatRelativeDate(collection.updated_at)}</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}
