import { useState, ReactNode } from "react"
import { X } from "lucide-react"
import { motion, AnimatePresence } from "motion/react"
import { DocumentPanel } from "@/components/panels/DocumentPanel"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

interface DocumentOverlayBaseProps {
    documentId: string
    onDeleteDone?: () => void
    className?: string
}

interface UncontrolledProps extends DocumentOverlayBaseProps {
    children: ReactNode
    isOpen?: never
    onClose?: never
}

interface ControlledProps extends DocumentOverlayBaseProps {
    children?: never
    isOpen: boolean
    onClose: () => void
}

type DocumentOverlayProps = UncontrolledProps | ControlledProps

export function DocumentOverlay(props: Readonly<DocumentOverlayProps>) {
    const { documentId, onDeleteDone } = props
    const [internalOpen, setInternalOpen] = useState(false)

    const isControlled = props.isOpen !== undefined
    const isOpen = isControlled ? props.isOpen : internalOpen
    const handleClose = isControlled ? props.onClose : () => setInternalOpen(false)

    return (
        <>
            {!isControlled && (
                <div className={cn("flex items-center justify-center w-full", props.className)}>
                    <div onClick={() => setInternalOpen(true)} className="w-full align-left">
                        {props.children}
                    </div>
                </div>
            )}
            <AnimatePresence>
                {isOpen && (
                    <div key={`overlay-${documentId}`} className="z-45 fixed w-full inset-0 bg-opacity-50 flex justify-end top-0">
                        <motion.div initial={{ x: "100%" }} animate={{ x: 0 }} exit={{ x: "100%" }} transition={{ type: "spring", stiffness: 300, damping: 30 }} className="h-full w-full bg-background shadow-lg p-0 relative">
                            <DocumentPanel id={documentId} onDeleteDone={onDeleteDone}>
                                <Button variant="default" onClick={handleClose}>
                                    <X />
                                </Button>
                            </DocumentPanel>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </>
    )
}
