import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { Collection, Interaction } from "@vertesia/common"
import { useNavigate, useParams } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Activity, ArrowLeft, Bot, CheckCircle2, Clock, icons, Loader2, Play, XCircle } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { useUserCache } from "@/hooks/use-user-cache"
import { toLocaleDateTimeString } from "@/lib/date"
import { cn } from "@/lib/utils"

interface ExecutionWithStatus {
    collection: Collection
    status: "completed" | "failed" | "running" | "unknown"
}
function parseDescriptionIcon(description: string | undefined): { iconName: string | null; cleanDescription: string } {
    if (!description) {
        return { iconName: null, cleanDescription: "" }
    }

    const iconPattern = /^\[icon:([A-Za-z0-9]+)\]\s*/
    const match = description.match(iconPattern)

    if (match) {
        return {
            iconName: match[1],
            cleanDescription: description.replace(iconPattern, "").trimStart(),
        }
    }

    return { iconName: null, cleanDescription: description }
}

function KpiCard({ title, value, icon: Icon, description, animateIcon }: Readonly<{ title: string; value: string | number; icon: React.ElementType; description?: string; animateIcon?: boolean }>) {
    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
                <CardTitle className="text-sm font-medium">{title}</CardTitle>
                <Icon className={cn("h-4 w-4 text-muted-foreground", animateIcon && "animate-spin")} />
            </CardHeader>
            <CardContent>
                <div className="text-2xl font-bold">{value}</div>
                {description && (
                    <p className="text-xs text-muted-foreground">{description}</p>
                )}
            </CardContent>
        </Card>
    )
}

function ExecutionRow({ execution, getUserDisplayName, onClick }: Readonly<{
    execution: ExecutionWithStatus
    getUserDisplayName: (id: string, fallback: string | undefined) => string
    onClick: () => void
}>) {
    const { t } = useTranslation(["agents", "common"])
    const { collection, status } = execution

    const statusBadge = useMemo(() => {
        switch (status) {
            case "completed":
                return <Badge className="bg-success-background text-success"><CheckCircle2 className="h-3 w-3 mr-1" />{t("agents:dashboard.statusCompleted")}</Badge>
            case "failed":
                return <Badge className="bg-destructive-background text-destructive"><XCircle className="h-3 w-3 mr-1" />{t("agents:dashboard.statusFailed")}</Badge>
            case "running":
                return <Badge className="bg-info-background text-info"><Loader2 className="h-3 w-3 mr-1 animate-spin" />{t("agents:dashboard.statusRunning")}</Badge>
            default:
                return <Badge variant="secondary">{t("agents:dashboard.statusUnknown")}</Badge>
        }
    }, [status, t])

    return (
        <TableRow className="cursor-pointer" onClick={onClick}>
            <TableCell className="font-medium truncate max-w-[200px]">
                {collection.name}
            </TableCell>
            <TableCell className="hidden md:table-cell truncate max-w-[300px] text-muted-foreground">
                {collection.description || "—"}
            </TableCell>
            <TableCell>{statusBadge}</TableCell>
            <TableCell className="truncate max-w-[150px]">
                {getUserDisplayName(collection.created_by, undefined)}
            </TableCell>
            <TableCell className="text-muted-foreground whitespace-nowrap">
                {toLocaleDateTimeString(new Date(collection.created_at))}
            </TableCell>
        </TableRow>
    )
}

export function AgentDashboardPanel() {
    const { t } = useTranslation(["agents", "common"])
    const { client, isLoading: sessionLoading } = useUserSession()
    const appInstallation = useAppInstallation()
    const navigate = useNavigate()
    const id = useParams("id")
    const { getUserDisplayName } = useUserCache(client)

    const EXECUTION_CONTAINER = appInstallation?.settings?.EXECUTION_CONTAINER as string || undefined

    const [interaction, setInteraction] = useState<Interaction | null>(null)
    const [isLoading, setIsLoading] = useState(true)
    const [notFound, setNotFound] = useState(false)

    const { iconName, cleanDescription } = useMemo(() => {
        return parseDescriptionIcon(interaction?.description)
    }, [interaction?.description])

    const IconComponent = useMemo(() => {
        if (iconName && iconName in icons) {
            return icons[iconName as keyof typeof icons]
        }
        return Bot
    }, [iconName])

    useEffect(() => {
        if (!client || sessionLoading || !id) {
            return
        }

        setIsLoading(true)
        client.interactions.retrieve(id)
            .then((response) => {
                setInteraction(response)
            })
            .catch((error) => {
                if (error.status === 404) {
                    setNotFound(true)
                }
            })
            .finally(() => {
                setIsLoading(false)
            })
    }, [client, sessionLoading, id])

    const PAGE_SIZE = 20

    const [collections, setCollections] = useState<Collection[]>([])
    const [executionsLoading, setExecutionsLoading] = useState(false)
    const [isLoadingMore, setIsLoadingMore] = useState(false)
    const [hasMore, setHasMore] = useState(true)
    const offsetRef = useRef(0)
    const sentinelRef = useRef<HTMLDivElement>(null)

    const [executionStatuses, setExecutionStatuses] = useState<Map<string, "completed" | "failed" | "running" | "unknown">>(new Map())

    const fetchStatusesForCollections = useCallback(async (items: Collection[]) => {
        if (!client || items.length === 0) {
            return
        }

        const promises = items.map(async (collection) => {
            const properties = (collection as any).properties || {}
            const runId = properties.run_id as string | undefined
            const workflowId = properties.workflow_id as string | undefined

            if (!runId || !workflowId) {
                return { id: collection.id, status: "unknown" as const }
            }

            try {
                const details = await client.workflows.getRunDetails(runId, workflowId)
                if (details.status === "FAILED") {
                    return { id: collection.id, status: "failed" as const }
                } else if (details.status === "COMPLETED") {
                    return { id: collection.id, status: "completed" as const }
                } else {
                    return { id: collection.id, status: "running" as const }
                }
            } catch {
                return { id: collection.id, status: "unknown" as const }
            }
        })

        const results = await Promise.allSettled(promises)
        setExecutionStatuses((prev) => {
            const next = new Map(prev)
            for (const result of results) {
                if (result.status === "fulfilled") {
                    next.set(result.value.id, result.value.status)
                }
            }
            return next
        })
    }, [client])

    const loadExecutions = useCallback(async (offset: number, isInitial: boolean) => {
        if (!client || !EXECUTION_CONTAINER || !interaction) {
            return
        }

        if (isInitial) {
            setExecutionsLoading(true)
        } else {
            setIsLoadingMore(true)
        }

        try {
            const results = await client.store.collections.search({
                type: EXECUTION_CONTAINER,
                limit: PAGE_SIZE,
                offset,
                match: { "properties.interaction": interaction.name }
            }) as Collection[]

            if (isInitial) {
                setCollections(results)
            } else {
                setCollections((prev) => [...prev, ...results])
            }

            setHasMore(results.length >= PAGE_SIZE)
            offsetRef.current = offset + results.length
            fetchStatusesForCollections(results)
        } finally {
            if (isInitial) {
                setExecutionsLoading(false)
            } else {
                setIsLoadingMore(false)
            }
        }
    }, [client, EXECUTION_CONTAINER, interaction, fetchStatusesForCollections])

    useEffect(() => {
        if (!interaction) {
            return
        }
        offsetRef.current = 0
        setCollections([])
        setExecutionStatuses(new Map())
        setHasMore(true)
        loadExecutions(0, true)
    }, [interaction, loadExecutions])

    useEffect(() => {
        const sentinel = sentinelRef.current
        if (!sentinel || !hasMore || executionsLoading) {
            return
        }

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && hasMore && !isLoadingMore && !executionsLoading) {
                    loadExecutions(offsetRef.current, false)
                }
            },
            { threshold: 0.1 }
        )

        observer.observe(sentinel)
        return () => observer.disconnect()
    }, [hasMore, isLoadingMore, executionsLoading, loadExecutions])

    const executionsWithStatus: ExecutionWithStatus[] = useMemo(() => {
        return collections.map((collection) => ({
            collection,
            status: executionStatuses.get(collection.id) || "unknown"
        }))
    }, [collections, executionStatuses])

    const kpis = useMemo(() => {
        const total = executionsWithStatus.length
        const completed = executionsWithStatus.filter((e) => e.status === "completed").length
        const failed = executionsWithStatus.filter((e) => e.status === "failed").length
        const running = executionsWithStatus.filter((e) => e.status === "running").length

        return { total, completed, failed, running }
    }, [executionsWithStatus])

    if (sessionLoading || isLoading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
        )
    }

    if (notFound) {
        return (
            <div className="flex flex-col items-center justify-center h-full gap-4">
                <h1 className="text-3xl font-bold text-foreground">{t("agents:dashboard.agentNotFound")}</h1>
                <p className="text-muted-foreground">{t("agents:dashboard.agentNotFoundDescription")}</p>
                <Button onClick={() => navigate("/agents")}>
                    <ArrowLeft />
                    {t("agents:execution.backToAgents")}
                </Button>
            </div>
        )
    }

    if (!interaction) {
        return null
    }

    return (
        <div className="flex flex-col w-full h-full gap-6 px-4 pt-2 pb-4">
            <div className="flex items-center justify-between flex-shrink-0">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-3">
                        <IconComponent className="size-8 text-primary" strokeWidth={2} />
                        <h1 className="text-3xl font-bold text-foreground">{interaction.name}</h1>
                        <Badge variant="secondary">v{interaction.version}</Badge>
                    </div>
                    <p className="text-muted-foreground">{cleanDescription || t("agents:execution.noDescription")}</p>
                </div>
                <Button onClick={() => navigate(`/agents/${id}/create`)}>
                    <Play className="h-4 w-4" />
                    {t("agents:execution.runAgent")}
                </Button>
            </div>

            <Separator />

            <div className="grid gap-4 grid-cols-2 lg:grid-cols-4 flex-shrink-0">
                <KpiCard
                    title={t("agents:dashboard.totalExecutions")}
                    value={kpis.total}
                    icon={Activity}
                    description={t("agents:dashboard.allTime")}
                />
                <KpiCard
                    title={t("agents:dashboard.successful")}
                    value={kpis.completed}
                    icon={CheckCircle2}
                    description={kpis.total > 0 ? `${Math.round((kpis.completed / kpis.total) * 100)}% success rate` : undefined}
                />
                <KpiCard
                    title={t("agents:dashboard.failed")}
                    value={kpis.failed}
                    icon={XCircle}
                    description={kpis.total > 0 ? `${Math.round((kpis.failed / kpis.total) * 100)}% failure rate` : undefined}
                />
                <KpiCard
                    title={t("agents:dashboard.running")}
                    value={kpis.running}
                    icon={Loader2}
                    description={t("agents:dashboard.currentlyInProgress")}
                    animateIcon={kpis.running > 0}
                />
            </div>

            <div className="flex flex-col gap-2 flex-1 min-h-0">
                <h2 className="text-lg font-semibold flex-shrink-0">{t("agents:dashboard.executions")}</h2>

                {executionsLoading && (
                    <div className="flex items-center justify-center py-8">
                        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                    </div>
                )}

                {!executionsLoading && executionsWithStatus.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-12 text-muted-foreground gap-2">
                        <Clock className="h-10 w-10" />
                        <p>{t("agents:dashboard.noExecutionsYet")}</p>
                        <Button variant="outline" onClick={() => navigate(`/agents/${id}/create`)}>
                            <Play className="h-4 w-4" />
                            {t("agents:dashboard.runFirstExecution")}
                        </Button>
                    </div>
                )}

                {!executionsLoading && executionsWithStatus.length > 0 && (
                    <div className="flex-1 min-h-0 border rounded-md overflow-y-auto">
                        <table className="w-full caption-bottom text-sm table-fixed">
                            <TableHeader className="sticky top-0 z-10 bg-muted shadow-[inset_0_-1px_0_var(--border)]">
                                <TableRow>
                                    <TableHead>{t("common:properties.name")}</TableHead>
                                    <TableHead className="hidden md:table-cell">{t("common:properties.description")}</TableHead>
                                    <TableHead>{t("common:properties.status")}</TableHead>
                                    <TableHead>{t("common:properties.createdBy")}</TableHead>
                                    <TableHead>{t("common:properties.createdAt")}</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {executionsWithStatus.map((execution) => (
                                    <ExecutionRow
                                        key={execution.collection.id}
                                        execution={execution}
                                        getUserDisplayName={getUserDisplayName}
                                        onClick={() => navigate(`/agents/executions/${execution.collection.id}`)}
                                    />
                                ))}
                            </TableBody>
                        </table>
                        {hasMore && (
                            <div ref={sentinelRef} className="flex items-center justify-center py-4">
                                {isLoadingMore && <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    )
}
