import { useTranslation } from "react-i18next"
import { CollectionItem } from "@vertesia/common"
import { Loader2, X } from "lucide-react"
import { motion, AnimatePresence } from "motion/react"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
    useCollectionWizard,
    WizardStepIndicator,
    WizardStepDetails,
    WizardStepMembers,
    WizardStepReview,
} from "./collection-wizard"

type CollectionCategory = "personal" | "organization"

interface CreateCollectionOverlayProps {
    isOpen: boolean
    onClose: () => void
    onSuccess?: () => void
    collection?: CollectionItem
    category?: CollectionCategory
}

const slideVariants = {
    enter: (direction: "forward" | "backward") => ({
        x: direction === "forward" ? 50 : -50,
        opacity: 0,
    }),
    center: {
        x: 0,
        opacity: 1,
    },
    exit: (direction: "forward" | "backward") => ({
        x: direction === "forward" ? -50 : 50,
        opacity: 0,
    }),
}

export function CreateCollectionOverlay({
    isOpen,
    onClose,
    onSuccess,
    collection,
    category,
}: Readonly<CreateCollectionOverlayProps>) {
    const wizard = useCollectionWizard({
        isOpen,
        onClose,
        onSuccess,
        collection,
        category,
    })

    const { t } = useTranslation("common")

    const {
        currentStep,
        direction,
        goBack,
        goNext,
        canProceed,
        isEditMode,
        isSubmitting,
        handleSubmit,
    } = wizard

    const handleNext = () => {
        if (currentStep === 3) {
            handleSubmit()
        } else {
            goNext()
        }
    }

    const getNextButtonLabel = () => {
        if (currentStep === 3) {
            if (isSubmitting) {
                return isEditMode ? t("collectionWizard.saving") : t("collectionWizard.creating")
            }
            return isEditMode ? t("collectionWizard.saveChanges") : t("collectionWizard.createCollection")
        }
        return t("collectionWizard.next")
    }

    if (!isOpen) return null

    return (
        <div className="z-50 fixed inset-0 flex justify-end top-0">
            <motion.div
                initial={{ x: "100%" }}
                animate={{ x: 0 }}
                exit={{ x: "100%" }}
                transition={{ type: "spring", stiffness: 300, damping: 30 }}
                className="h-full w-full bg-background shadow-lg relative flex flex-col"
            >
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-4">
                    <div className="flex flex-col gap-1">
                        <h1 className="text-xl font-semibold">
                            {isEditMode ? t("collectionWizard.editCollection") : t("collectionWizard.createCollectionTitle")}
                        </h1>
                        <p className="text-sm text-muted-foreground">
                            {isEditMode
                                ? t("collectionWizard.editDescription")
                                : t("collectionWizard.createDescription")}
                        </p>
                    </div>
                    <Button
                        variant="ghost"
                        size="icon"
                        onClick={onClose}
                        disabled={isSubmitting}
                    >
                        <X className="h-5 w-5" />
                    </Button>
                </div>

                <Separator />

                {/* Step Indicator */}
                <div className="px-6 py-2">
                    <WizardStepIndicator
                        currentStep={currentStep}
                        totalSteps={3}
                        stepLabels={[t("collectionWizard.stepDetails"), t("collectionWizard.stepMembers"), t("collectionWizard.stepReview")]}
                    />
                </div>

                <Separator />

                {/* Content */}
                <div className="flex-1 overflow-hidden px-6 py-6">
                    <AnimatePresence mode="wait" custom={direction}>
                        <motion.div
                            key={currentStep}
                            custom={direction}
                            variants={slideVariants}
                            initial="enter"
                            animate="center"
                            exit="exit"
                            transition={{ duration: 0.2, ease: "easeInOut" }}
                            className="h-full"
                        >
                            {currentStep === 1 && (
                                <div className="max-w-xl mx-auto h-full flex flex-col justify-center">
                                    <WizardStepDetails
                                        name={wizard.name}
                                        setName={wizard.setName}
                                        description={wizard.description}
                                        setDescription={wizard.setDescription}
                                        typeId={wizard.typeId}
                                        setTypeId={wizard.setTypeId}
                                        disabled={isSubmitting}
                                        category={category}
                                        selectedGroups={wizard.selectedGroups}
                                        setSelectedGroups={wizard.setSelectedGroups}
                                        availableGroups={wizard.availableGroups}
                                        isLoadingGroups={wizard.isLoadingGroups}
                                    />
                                </div>
                            )}
                            {currentStep === 2 && (
                                <WizardStepMembers
                                    searchMode={wizard.searchMode}
                                    setSearchMode={wizard.setSearchMode}
                                    searchQuery={wizard.searchQuery}
                                    setSearchQuery={wizard.setSearchQuery}
                                    filteredSearchResults={wizard.filteredSearchResults}
                                    isSearching={wizard.isSearching}
                                    currentMembers={wizard.currentMembers}
                                    membersToAdd={wizard.membersToAdd}
                                    isLoadingMembers={wizard.isLoadingMembers}
                                    handleAddMember={wizard.handleAddMember}
                                    handleRemoveMember={wizard.handleRemoveMember}
                                    disabled={isSubmitting}
                                />
                            )}
                            {currentStep === 3 && (
                                <div className="max-w-xl mx-auto">
                                    <WizardStepReview
                                        name={wizard.name}
                                        description={wizard.description}
                                        typeId={wizard.typeId}
                                        currentMembers={wizard.currentMembers}
                                        membersToAdd={wizard.membersToAdd}
                                        isEditMode={isEditMode}
                                        category={category}
                                        selectedGroups={wizard.selectedGroups}
                                        availableGroups={wizard.availableGroups}
                                    />
                                </div>
                            )}
                        </motion.div>
                    </AnimatePresence>
                </div>

                <Separator />

                {/* Footer */}
                <div className="flex items-center justify-between px-6 py-4">
                    <Button
                        variant="outline"
                        onClick={onClose}
                        disabled={isSubmitting}
                    >
                        {t("actions.cancel")}
                    </Button>
                    <div className="flex flex-row gap-2">
                        {currentStep > 1 && (
                            <Button
                                variant="outline"
                                onClick={goBack}
                                disabled={isSubmitting}
                            >
                                {t("actions.back")}
                            </Button>
                        )}
                        <Button
                            onClick={handleNext}
                            disabled={!canProceed || isSubmitting}
                        >
                            {isSubmitting && (
                                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                            )}
                            {getNextButtonLabel()}
                        </Button>
                    </div>
                </div>
            </motion.div>
        </div>
    )
}
