import { useCallback, useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"
import { FolderSearch } from "lucide-react"
import { DocumentSelectionOverlay } from "@/components/overlays/DocumentSelectionOverlay"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { SelectedItemsDisplay } from "@/features/agents/components/DocumentMediaPanel/components/SelectedItemsDisplay"
import { UploadSection } from "@/features/agents/components/DocumentMediaPanel/components/UploadSection"
import { DocumentMediaPanelProps, ContentItem } from "@/features/agents/components/DocumentMediaPanel/types"

// Helper to format ID for storage (adds "store:" prefix)
const formatStoreId = (id: string): string => {
    if (id.startsWith("store:")) return id
    return `store:${id}`
}

// Helper to parse stored ID (removes "store:" prefix for API calls)
const parseStoreId = (storeId: string): string => {
    if (storeId.startsWith("store:")) return storeId.slice(6)
    return storeId
}

export function DocumentMediaPanel({
    mode,
    type,
    value,
    onChange,
    disabled,
    className,
}: Readonly<DocumentMediaPanelProps>) {
    const { t } = useTranslation(["agents", "common"])
    const { client } = useUserSession()
    const [selectedItems, setSelectedItems] = useState<ContentItem[]>([])

    // Get the stored IDs (with store: prefix) and parse them for display/API
    const storedIds = Array.isArray(value) ? value : value ? [value] : []
    const selectedIds = storedIds.map(parseStoreId)

    useEffect(() => {
        const fetchSelectedItems = async () => {
            if (!client || selectedIds.length === 0) {
                setSelectedItems([])
                return
            }

            try {
                const items = await Promise.all(
                    selectedIds.map(async (id) => {
                        try {
                            const obj = await client.objects.retrieve(id)
                            return {
                                id: obj.id,
                                name: obj.name || obj.id,
                                mimeType: obj.content?.type,
                                createdAt: obj.created_at,
                                type: obj.type?.name,
                            } as ContentItem
                        } catch {
                            return {
                                id,
                                name: id,
                            } as ContentItem
                        }
                    })
                )
                setSelectedItems(items)
            } catch {
                setSelectedItems(
                    selectedIds.map((id) => ({ id, name: id } as ContentItem))
                )
            }
        }

        fetchSelectedItems()
    }, [client, value])

    const handleDocumentSelection = useCallback(
        (documents: ContentObjectItem[]) => {
            if (documents.length === 0) return

            const newItems: ContentItem[] = documents.map((doc) => ({
                id: doc.id,
                name: doc.name || doc.id,
                mimeType: doc.content?.type,
                createdAt: doc.created_at,
                type: doc.type?.name,
            }))

            if (mode === "single") {
                const item = newItems[0]
                onChange(formatStoreId(item.id))
                setSelectedItems([item])
            } else {
                const existingIds = new Set(selectedIds)
                const uniqueNewItems = newItems.filter((item) => !existingIds.has(item.id))
                const newStoreIds = [...storedIds, ...uniqueNewItems.map((item) => formatStoreId(item.id))]
                onChange(newStoreIds)
                setSelectedItems((prev) => [...prev, ...uniqueNewItems])
            }
        },
        [mode, selectedIds, storedIds, onChange]
    )

    const handleRemove = useCallback(
        (id: string) => {
            if (mode === "single") {
                onChange(null)
                setSelectedItems([])
            } else {
                const newStoreIds = storedIds.filter((storeId) => parseStoreId(storeId) !== id)
                onChange(newStoreIds.length > 0 ? newStoreIds : [])
                setSelectedItems((prev) => prev.filter((item) => item.id !== id))
            }
        },
        [mode, storedIds, onChange]
    )

    const handleClear = useCallback(() => {
        onChange(mode === "single" ? null : [])
        setSelectedItems([])
    }, [mode, onChange])

    const handleUploadComplete = useCallback(
        (items: ContentItem[]) => {
            if (mode === "single") {
                const item = items[0]
                if (item) {
                    onChange(formatStoreId(item.id))
                    setSelectedItems([item])
                }
            } else {
                const newStoreIds = [...storedIds, ...items.map((item) => formatStoreId(item.id))]
                onChange(newStoreIds)
                setSelectedItems((prev) => [...prev, ...items])
            }
        },
        [mode, storedIds, onChange]
    )

    const getSelectButtonLabel = () => {
        const itemType = type === "media" ? t("agents:media.media") : t("agents:media.document")
        const itemTypePlural = type === "media" ? t("agents:media.mediaFiles") : t("agents:media.documents")
        return t("agents:media.selectItems", { itemType: mode === "single" ? itemType : itemTypePlural })
    }

    return (
        <div className={`flex-1 overflow-y-auto mt-4 flex flex-col gap-4 ${className || ""}`}>
            {selectedItems.length > 0 && (
                <>
                    <SelectedItemsDisplay
                        items={selectedItems}
                        mode={mode}
                        type={type}
                        onRemove={handleRemove}
                        onClear={handleClear}
                        disabled={disabled}
                    />
                    <Separator />
                </>
            )}

            <div className="flex flex-col gap-3">
                <h4 className="text-sm font-medium">{t("common:actions.chooseExisting")}</h4>
                <DocumentSelectionOverlay onSelection={handleDocumentSelection} selectionMode={mode}>
                    <Button variant="outline" className="w-full justify-start" disabled={disabled}>
                        <FolderSearch className="h-4 w-4 mr-2" />
                        {getSelectButtonLabel()}
                    </Button>
                </DocumentSelectionOverlay>
            </div>

            <Separator />

            <UploadSection
                type={type}
                mode={mode}
                onUploadComplete={handleUploadComplete}
                disabled={disabled}
            />
        </div>
    )
}
