/**
 * ⚠️ TEMPORARY — demo-only theme-preset switcher (ClickUp 86aj7mt77 / Phase A).
 *
 * Lets stakeholders flip the whole app between 4 *complete* look presets in
 * realtime so a direction can be picked in a live demo. Each preset is a
 * self-contained identity expressed purely in CSS (see `src/ui/index.css`,
 * "demo theme presets — FULL identity"): colour tokens + density (`--spacing`)
 * + radius (`--radius`) + structural surface vars (`--ecm-surface-*` /
 * `--ecm-tile-*`, i.e. frame-vs-no-frame). The switcher only flips ONE
 * attribute — `data-theme-preset` — on the theme root.
 *
 * SHADOW-DOM CORRECTNESS (the bug this fixes): the plugin renders inside a
 * shadow tree and its stylesheet is shadow-scoped, so a `[data-theme-preset]`
 * rule can only match an element *inside* that shadow tree. The attribute must
 * therefore land on the in-shadow theme wrapper (the element that also carries
 * the `light`/`dark` class + `data-scheme`), NOT on `document.documentElement`
 * (`<html>`, outside the shadow tree — where it has zero effect). We resolve
 * that wrapper from a live node rendered by the switcher itself.
 *
 * REMOVABLE BY DESIGN: no feature component reads the preset — components only
 * ever consume tokens/vars + the `.ecm-surface`/`.ecm-tile` hook classes. To
 * delete the demo entirely:
 *   1. delete this file + `features/_demo/ThemeSwitcher.tsx`
 *   2. remove the `<ThemeSwitcher/>` mount in `App.tsx`
 *   3. delete the "demo theme presets — FULL identity" section + the
 *      `.ecm-surface`/`.ecm-tile` hook rules in `src/ui/index.css`
 *   4. remove the className hooks: `ecm-surface` (card.tsx), `ecm-tile`
 *      (both DocumentThumbnail.tsx), `ecm-search` (LibraryFilters.tsx +
 *      UserDashboardPanel.tsx). The sidebar rules need no hook — they target the
 *      shadcn `data-sidebar="…"` attributes directly.
 * Whatever preset wins just gets promoted into the `:root`/scheme defaults.
 */

export type ThemePresetId = "old" | "vertesia" | "alt" | "accor"

export interface ThemePreset {
    id: ThemePresetId
    /** Short label shown on the switcher chip. */
    label: string
    /** One-liner shown as a tooltip / caption. */
    caption: string
}

/**
 * The 4 demo directions. Their entire look lives in CSS keyed on
 * `data-theme-preset`; this list is only the switcher's labels.
 */
export const THEME_PRESETS: ThemePreset[] = [
    { id: "old", label: "Old", caption: "As-is today — compact, greyscale, flat (baseline)" },
    { id: "vertesia", label: "Vertesia", caption: "Vertesia brand — royal blue + blue→violet, airy, huge radius" },
    { id: "alt", label: "Alt", caption: "Blend of Vertesia + Accor — blue + gold, glass-pill search, subtle lifted cards" },
    { id: "accor", label: "Accor", caption: "Faithful to the real Accor plugin — amber brand, white canvas, subtle cards" },
]

const PRESET_PREFERENCE = "vertesia.psea.demoThemePreset"

export function getThemePresets(): ThemePreset[] {
    return THEME_PRESETS
}

export function getCurrentThemePreset(): ThemePresetId {
    const stored = localStorage.getItem(PRESET_PREFERENCE) as ThemePresetId | null
    return stored && THEME_PRESETS.some((p) => p.id === stored) ? stored : "old"
}

/**
 * Resolve the in-shadow theme wrapper from a node that the switcher rendered.
 * Walks up the ancestor chain (crossing the shadow boundary via `.host` if
 * needed) to the nearest element carrying the `light`/`dark` theme class —
 * that wrapper is exactly where `data-scheme` lives and where the shadow-scoped
 * preset CSS can match. Falls back to `<html>` for standalone (non-shadow) dev.
 */
export function resolveThemeRoot(node: Element | null | undefined): HTMLElement {
    let el: Element | null = node ?? null
    while (el) {
        // Walking up from an in-shadow node, the FIRST light/dark ancestor is the
        // in-shadow theme wrapper (reached before the outer <html>) — exactly the
        // element the shadow-scoped preset CSS can match.
        if (el instanceof HTMLElement && (el.classList.contains("light") || el.classList.contains("dark"))) {
            return el
        }
        const parent = el.parentElement
        if (parent) {
            el = parent
        } else {
            const root = el.getRootNode()
            el = root instanceof ShadowRoot ? root.host : null
        }
    }
    return document.documentElement
}

/**
 * Apply a preset in realtime by flipping the single `data-theme-preset`
 * attribute on the resolved theme root, and persist the choice (so a refresh
 * during the demo keeps it). `old` removes the attribute → the :root baseline.
 *
 * @param id   the preset to apply
 * @param root the theme root resolved from a live switcher node; when omitted
 *             (e.g. very early, before the node mounts) we best-effort fall back
 *             to any existing in-shadow `[data-scheme]`/themed wrapper, then
 *             `<html>`.
 */
export function applyThemePreset(id: ThemePresetId, root?: HTMLElement): void {
    const preset = THEME_PRESETS.find((p) => p.id === id) ?? THEME_PRESETS[0]
    const target = root ?? findThemeRootFallback()

    // Scrub the attribute from EVERY element first (light + shadow trees). The
    // in-shadow theme wrapper can change identity between applies (the shell may
    // re-create it), so a previous preset can linger on a now-stale node — which
    // made `old` not return to the true baseline. Clearing everywhere then
    // setting once on the current target guarantees a single source of truth.
    clearPresetEverywhere()
    // Presets own colour entirely (via their [data-theme-preset] token blocks), so
    // the app's separate `[data-scheme]` colour system must not compete. A stale
    // `data-scheme="blue"` (persisted by an earlier build) was re-applied by the
    // shell on every navigation and, with no token block to beat it, tinted `old`
    // blue. Neutralise it: drop every data-scheme attribute AND the persisted key
    // so navigation can't bring it back.
    clearAppColorScheme()
    if (preset.id !== "old") {
        target.setAttribute("data-theme-preset", preset.id)
    }
    localStorage.setItem(PRESET_PREFERENCE, preset.id)
}

/** Remove `data-theme-preset` from every element across light + shadow DOM. */
function clearPresetEverywhere(): void {
    const scrub = (rootNode: Document | ShadowRoot): void => {
        rootNode.querySelectorAll("[data-theme-preset]").forEach((e) => e.removeAttribute("data-theme-preset"))
        rootNode.querySelectorAll("*").forEach((e) => {
            const sr = (e as HTMLElement).shadowRoot
            if (sr) {
                scrub(sr)
            }
        })
    }
    scrub(document)
}

/** The app's own persisted colour-scheme key (the real Settings colour picker). */
const APP_COLOR_SCHEME_KEY = "vertesia.psea.colorScheme"

/**
 * Remove every `data-scheme` attribute (light + shadow DOM) and clear the
 * persisted app colour-scheme, so the preset system is the single source of
 * colour and navigation can't re-tint the chrome from a stale scheme.
 */
function clearAppColorScheme(): void {
    const scrub = (rootNode: Document | ShadowRoot): void => {
        rootNode.querySelectorAll("[data-scheme]").forEach((e) => e.removeAttribute("data-scheme"))
        rootNode.querySelectorAll("*").forEach((e) => {
            const sr = (e as HTMLElement).shadowRoot
            if (sr) {
                scrub(sr)
            }
        })
    }
    scrub(document)
    try {
        localStorage.removeItem(APP_COLOR_SCHEME_KEY)
    } catch {
        /* ignore */
    }
}

/**
 * Best-effort theme root when we have no switcher node yet: prefer an in-shadow
 * wrapper that already carries `data-scheme` or the `light`/`dark` class; else
 * `<html>`. Used only as a fallback — the switcher passes the resolved root.
 */
function findThemeRootFallback(): HTMLElement {
    const scan = (rootNode: Document | ShadowRoot): HTMLElement | null => {
        const hit = rootNode.querySelector("[data-scheme]") as HTMLElement | null
        if (hit && hit.getRootNode() instanceof ShadowRoot) {
            return hit
        }
        for (const el of Array.from(rootNode.querySelectorAll("*"))) {
            if ((el as HTMLElement).shadowRoot) {
                const inner = scan((el as HTMLElement).shadowRoot as ShadowRoot)
                if (inner) {
                    return inner
                }
            }
        }
        return null
    }
    return scan(document) ?? document.documentElement
}
