export function matchesFilter(fileType: string, filters: string[]) {
    return filters.some(filter => fileType === filter || fileType.startsWith(filter + "/"))
}

export function filterFiles(files: File[], filteredTypes?: string[]) {
    if (!filteredTypes || filteredTypes.length === 0) {
        return files
    }
    return files.filter(file => matchesFilter(file.type, filteredTypes))
}