import { useEffect } from "react"
import { TypeRegistryProvider } from "@vertesia/ui/features"
import { NestedRouterProvider } from "@vertesia/ui/router"
import { useAppInstallation } from "@vertesia/ui/shell"
import { ThemeRoot } from "@/components/layouts/ThemeRoot"
import { AgentChatProvider } from "@/contexts/AgentChatContext"
import { FavoritesProvider } from "@/contexts/FavoritesContext"
// TEMPORARY (ClickUp 86aj7mt77): demo-only theme switcher — remove with the rest of the demo.
import { ThemeSwitcher } from "@/features/_demo/ThemeSwitcher"
import { AgentChatFloatingPanel } from "@/features/dashboard/AgentChatFloatingPanel"
import { routes } from "./routes"

export function App() {
    const appInstallation = useAppInstallation()
    useEffect(() => {
        console.log(
            "[SETTINGS CHECK] app:", appInstallation?.manifest?.name,
            "| installation.settings =",
            JSON.stringify(appInstallation?.settings, null, 2),
        )
    }, [appInstallation])

    return (
        <TypeRegistryProvider>
            <ThemeRoot>
                <FavoritesProvider>
                    {/* AgentChatProvider lives above the router so the AI Assistant panel
                        persists across client-side navigation (but not a browser refresh). */}
                    <AgentChatProvider>
                        <NestedRouterProvider routes={routes} />
                        <AgentChatFloatingPanel />
                        <ThemeSwitcher />
                    </AgentChatProvider>
                </FavoritesProvider>
            </ThemeRoot>
        </TypeRegistryProvider>
    )
}
