import { useEffect, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Copy, Check, Loader2, MessageSquare, Bot, User, Send } from "lucide-react"
import { motion, AnimatePresence } from "motion/react"
import { MarkdownDisplay } from "@/components/displays/MarkdownDisplay"
import { ChatTypingIndicator } from "@/components/indicators/TypingIndicator"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import { Message, ChatMessageRoleType } from "@/models/messages"

interface ChatPanelProps {
    document: ContentObjectItem
    interactionId: string
    resetTrigger?: number
}

interface ChatMessageProps {
    message: Message
    onCopy: (content: string) => void
    messageRef?: React.Ref<HTMLDivElement>
}

function ChatMessage({ message, onCopy, messageRef }: ChatMessageProps) {
    const [copied, setCopied] = useState(false)
    const isUser = message.role === ChatMessageRoleType.USER

    const handleCopy = () => {
        onCopy(message.content)
        setCopied(true)
        setTimeout(() => setCopied(false), 2000)
    }

    const formatTimestamp = (date: Date) => {
        return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    }

    return (
        <motion.div
            ref={messageRef}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className={cn(
                "flex items-start gap-3 scroll-mt-4",
                isUser && "flex-row-reverse"
            )}
        >
            <div className={cn(
                "flex h-8 w-8 shrink-0 items-center justify-center rounded-full",
                isUser ? "bg-primary" : "bg-primary/10"
            )}>
                {isUser ? (
                    <User className="h-4 w-4 text-primary-foreground" />
                ) : (
                    <Bot className="h-4 w-4 text-primary" />
                )}
            </div>
            <div className={cn(
                "group flex flex-col gap-1 max-w-[75%]",
                isUser && "items-end"
            )}>
                <div className={cn(
                    "rounded-2xl px-4 py-2.5",
                    isUser
                        ? "bg-primary text-primary-foreground rounded-tr-sm"
                        : "bg-muted rounded-tl-sm"
                )}>
                    {isUser ? (
                        <p className="text-sm whitespace-pre-wrap">{message.content}</p>
                    ) : (
                        <div className="text-sm prose-sm max-w-none">
                            <MarkdownDisplay content={message.content} />
                        </div>
                    )}
                </div>
                <div className={cn(
                    "flex items-center gap-2 px-1",
                    isUser && "flex-row-reverse"
                )}>
                    <span className="text-xs text-muted-foreground">
                        {formatTimestamp(message.timestamp)}
                    </span>
                    {!isUser && (
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity"
                            onClick={handleCopy}
                        >
                            {copied ? (
                                <Check className="h-3 w-3 text-success" />
                            ) : (
                                <Copy className="h-3 w-3" />
                            )}
                        </Button>
                    )}
                </div>
            </div>
        </motion.div>
    )
}

function EmptyState({ documentName }: { documentName: string }) {
    const { t } = useTranslation("common")
    return (
        <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="flex flex-col items-center justify-center h-full p-8 text-center"
        >
            <div className="flex h-16 w-16 items-center justify-center rounded-full bg-primary/10 mb-4">
                <MessageSquare className="h-8 w-8 text-primary" />
            </div>
            <h3 className="text-lg font-semibold mb-2">{t("chat.chatWithDocument")}</h3>
            <p className="text-sm text-muted-foreground max-w-sm">
                <span dangerouslySetInnerHTML={{ __html: t("chat.askQuestions", { name: documentName }) }} />
            </p>
        </motion.div>
    )
}

export function ChatPanel({ document, interactionId, resetTrigger }: Readonly<ChatPanelProps>) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const toast = useToast()

    const [messages, setMessages] = useState<Message[]>([])
    const [inputMessage, setInputMessage] = useState("")
    const [isLoading, setIsLoading] = useState(false)
    const scrollAreaRef = useRef<HTMLDivElement>(null)
    const textareaRef = useRef<HTMLTextAreaElement>(null)
    const lastMessageRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        if (resetTrigger !== undefined && resetTrigger > 0) {
            setMessages([])
            setInputMessage("")
        }
    }, [resetTrigger])

    // Scroll to show the latest message at the top when messages change
    useEffect(() => {
        if (lastMessageRef.current) {
            lastMessageRef.current.scrollIntoView({ behavior: "smooth", block: "start" })
        }
    }, [messages])

    const handleSendMessage = () => {
        if (inputMessage.trim() === "" || isLoading) {
            return
        }

        const newMessage: Message = {
            id: messages.length,
            content: inputMessage.trim(),
            role: ChatMessageRoleType.USER,
            timestamp: new Date(),
        }

        setMessages((prevMessages) => [...prevMessages, newMessage])
        setInputMessage("")
        setIsLoading(true)

        // Reset textarea height
        if (textareaRef.current) {
            textareaRef.current.style.height = "auto"
        }

        client.interactions
            .execute(interactionId, {
                data: {
                    documents: [`store:${document.id}`],
                    chat: [...messages, newMessage],
                },
            })
            .then((response) => {
                const assistantResponse: Message = {
                    id: messages.length + 1,
                    content: response.result?.[0]?.value || t("chat.errorProcessing"),
                    role: ChatMessageRoleType.ASSISTANT,
                    timestamp: new Date()
                }
                setMessages((prevMessages) => [...prevMessages, assistantResponse])
            })
            .catch(() => {
                const assistantResponse: Message = {
                    id: messages.length + 1,
                    content: t("chat.errorGeneral"),
                    role: ChatMessageRoleType.ASSISTANT,
                    timestamp: new Date()
                }
                setMessages((prevMessages) => [...prevMessages, assistantResponse])
            })
            .finally(() => {
                setIsLoading(false)
            })
    }

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault()
            handleSendMessage()
        }
    }

    const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        setInputMessage(e.target.value)
        // Auto-resize textarea
        e.target.style.height = "auto"
        e.target.style.height = Math.min(e.target.scrollHeight, 120) + "px"
    }

    const copyToClipboard = (content: string) => {
        navigator.clipboard.writeText(content).then(() => {
            toast({
                status: "success",
                title: t("actions.copiedToClipboard"),
                duration: 2000,
            })
        })
    }

    const hasMessages = messages.length > 0

    return (
        <div className="flex flex-col h-full">
            {/* Messages Area */}
            <div className="flex-1 min-h-0 p-4">
                {hasMessages || isLoading ? (
                    <ScrollArea ref={scrollAreaRef} className="h-full">
                        <div className="flex flex-col gap-2">
                            <AnimatePresence mode="popLayout">
                                {messages.map((message, index) => {
                                    const isLastMessage = index === messages.length - 1
                                    return (
                                        <ChatMessage
                                            key={message.id}
                                            message={message}
                                            onCopy={copyToClipboard}
                                            messageRef={isLastMessage ? lastMessageRef : undefined}
                                        />
                                    )
                                })}
                                {isLoading && <ChatTypingIndicator key="typing" />}
                            </AnimatePresence>
                        </div>
                    </ScrollArea>
                ) : (
                    <EmptyState documentName={document.name} />
                )}
            </div>

            {/* Input Area */}
            <div className="flex-shrink-0 border-t bg-background p-4">
                <div className="flex items-end gap-2">
                    <Textarea
                        ref={textareaRef}
                        value={inputMessage}
                        onChange={handleTextareaChange}
                        onKeyDown={handleKeyDown}
                        placeholder={isLoading ? t("chat.waitingPlaceholder") : t("chat.askPlaceholder")}
                        disabled={isLoading}
                        className="min-h-[44px] max-h-[120px] resize-none rounded-xl"
                        rows={1}
                    />
                    <Button
                        onClick={handleSendMessage}
                        disabled={isLoading || !inputMessage.trim()}
                        size="icon"
                        className="h-11 w-11 shrink-0"
                    >
                        {isLoading ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                            <Send className="h-4 w-4" />
                        )}
                    </Button>
                </div>
            </div>
        </div>
    )
}
