import { useEffect, useRef, useState, useCallback, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { ColumnDef, ColumnFiltersState, flexRender, getCoreRowModel, getFilteredRowModel, getSortedRowModel, SortingState, useReactTable, VisibilityState, RowSelectionState } from "@tanstack/react-table"
import { ContentObjectItem } from "@vertesia/common"
import { Loader2 } from "lucide-react"
import { ColumnFilter } from "@/components/datatables/filters/ColumnFilter"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Checkbox } from "@/components/ui/checkbox"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { useIntersectionObserver } from "@/hooks/use-intersection-observer"
import { DynamicColumn } from "@/models/datatable"

type SelectionMode = "single" | "multiple"

function createDynamicColumns(dynamicColumns: DynamicColumn[], selectedIds: string[], selectionMode: SelectionMode, selectAllLabel: string, selectRowLabel: string): ColumnDef<ContentObjectItem>[] {
    const columns: ColumnDef<ContentObjectItem>[] = []

    dynamicColumns.forEach((dynCol) => {
        const getNestedValue = (obj: any, path: string) => {
            try {
                return path.split(".").reduce((current, key) => current?.[key], obj)
            } catch (error) {
                console.error("Error getting nested value:", error)
                return "No Data"
            }
        }

        const column: ColumnDef<ContentObjectItem> = {
            accessorKey: dynCol.key,
            header: ({ column }) => (
                <ColumnFilter
                    column={column}
                    label={dynCol.label}
                    hideFilter={true}
                />
            ),
            sortingFn: (rowA, rowB, _columnId) => {
                const valueA = getNestedValue(rowA.original, dynCol.key)
                const valueB = getNestedValue(rowB.original, dynCol.key)

                const stringA = String(valueA || "").toLowerCase()
                const stringB = String(valueB || "").toLowerCase()

                return stringA.localeCompare(stringB)
            },
            cell: ({ row }) => {
                if (dynCol.key === "title" || dynCol.key === "name") {
                    const displayName = (row.original as any)?.properties?.title || row.original?.name || row.original.id
                    return (
                        <DocumentOverlay documentId={row.original.id}>
                            <div
                                className="truncate font-medium text-primary underline hover:text-primary/80 cursor-pointer"
                                title={`Click to view ${displayName}`}
                            >
                                {displayName}
                            </div>
                        </DocumentOverlay>
                    )
                }

                const value = getNestedValue(row.original, dynCol.key)

                if (dynCol.type === "date" && value) {
                    try {
                        const date = new Date(value)
                        if (!isNaN(date.getTime())) {
                            return <div>{date.toLocaleDateString()} {date.toLocaleTimeString()}</div>
                        }
                    } catch {
                        // If date parsing fails, fall back to string display
                    }
                }

                return <div>{value}</div>
            },
            size: dynCol.size || 200,
            enableSorting: true,
            enableColumnFilter: false
        }

        columns.push(column)
    })

    columns.push({
        id: "select",
        header: ({ table }) => {
            // Don't show "select all" checkbox for single selection mode
            if (selectionMode === "single") {
                return null
            }

            const availableRows = table.getRowModel().rows.filter((row: any) => !selectedIds.includes(row.original.id))
            const availableRowsSelected = availableRows.filter((row: any) => row.getIsSelected())

            const isAllAvailableSelected = availableRows.length > 0 && availableRowsSelected.length === availableRows.length
            const isSomeAvailableSelected = availableRowsSelected.length > 0 && availableRowsSelected.length < availableRows.length

            return (
                <Checkbox
                    checked={isAllAvailableSelected || (isSomeAvailableSelected && "indeterminate")}
                    onCheckedChange={(value) => {
                        availableRows.forEach((row: any) => {
                            row.toggleSelected(!!value)
                        })
                    }}
                    aria-label={selectAllLabel}
                />
            )
        },
        cell: ({ row }) => {
            return (
                <Checkbox
                    checked={row.getIsSelected()}
                    onCheckedChange={(value) => row.toggleSelected(!!value)}
                    aria-label={selectRowLabel}
                    disabled={selectedIds.includes(row.original.id)}
                />
            )
        },
        enableSorting: false,
        enableHiding: false,
        size: 50,
    })

    return columns
}

interface DocumentDataTableProps {
    data: ContentObjectItem[]
    loading: boolean
    loadMore?: () => void
    hasMore?: boolean
    loadingMore?: boolean
    onMultipleSelection: (documents: ContentObjectItem[]) => void
    selection?: ContentObjectItem[]
    selectedIds?: string[]
    hasSearched?: boolean
    noFilterMatch?: boolean
    columns: DynamicColumn[]
    selectionMode?: SelectionMode
}

export function DocumentDataTable({ data, loading, loadMore, hasMore = false, loadingMore = false, onMultipleSelection, selection = [], selectedIds = [], hasSearched = false, noFilterMatch = false, columns: dynamicColumns, selectionMode = "multiple" }: Readonly<DocumentDataTableProps>) {
    const { t } = useTranslation("common")
    const [sorting, setSorting] = useState<SortingState>([])
    const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
    const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
    const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
    const tableContainerRef = useRef<HTMLDivElement>(null)
    const loadMoreRef = useRef<HTMLTableRowElement>(null)

    // Track if selection change is from user interaction (checkbox click)
    const isUserInteraction = useRef(false)

    const columns = useMemo(() => createDynamicColumns(dynamicColumns, selectedIds, selectionMode, t("tables.selectAll"), t("tables.selectRow")), [dynamicColumns, selectedIds, selectionMode, t])

    const selectionIds = useMemo(() => {
        return new Set(selection.map(item => item.id))
    }, [selection])

    // Sync selection prop to rowSelection state (one-way, from props)
    useEffect(() => {
        // Skip if this is a user interaction - let the other effect handle it
        if (isUserInteraction.current) return

        const newRowSelection: RowSelectionState = {}

        data.forEach((item, index) => {
            if (selectionIds.has(item.id)) {
                newRowSelection[index] = true
            }
        })

        setRowSelection(newRowSelection)
    }, [data, selectionIds])

    const table = useReactTable({
        data,
        columns,
        onSortingChange: setSorting,
        onColumnFiltersChange: setColumnFilters,
        onRowSelectionChange: (updater) => {
            isUserInteraction.current = true
            setRowSelection(updater)
        },
        getCoreRowModel: getCoreRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
        onColumnVisibilityChange: setColumnVisibility,
        state: {
            sorting,
            columnFilters,
            columnVisibility,
            rowSelection
        },
        enableRowSelection: true,
        enableMultiRowSelection: selectionMode === "multiple",
        enableMultiSort: true,
        columnResizeMode: "onChange"
    })

    // Notify parent only when user interacts with checkboxes
    useEffect(() => {
        if (!isUserInteraction.current) return
        isUserInteraction.current = false

        const currentlySelectedRows = table.getFilteredSelectedRowModel().rows.map(row => row.original)

        if (selectionMode === "single") {
            // For single selection, just pass the currently selected row (or empty array)
            onMultipleSelection(currentlySelectedRows)
        } else {
            // For multiple selection, preserve selections from previous searches
            const dataIds = new Set(data.map(item => item.id))
            const preservedSelection = selection.filter(item => !dataIds.has(item.id))

            const mergedSelection = [
                ...preservedSelection,
                ...currentlySelectedRows.filter(row => !preservedSelection.some(p => p.id === row.id))
            ]

            onMultipleSelection(mergedSelection)
        }
    }, [rowSelection, onMultipleSelection, table, data, selection, selectionMode])

    const handleScroll = useCallback(() => {
        if (!tableContainerRef.current || loading || loadingMore || !hasMore || !loadMore) {
            return
        }

        const { scrollTop, scrollHeight, clientHeight } = tableContainerRef.current
        const diff = scrollHeight - scrollTop - clientHeight

        const threshold = Math.max(50, clientHeight * 0.1)

        if (diff < threshold) {
            loadMore()
        }
    }, [loading, loadingMore, hasMore, loadMore])

    const handleIntersection = useCallback(() => {
        if (!loading && !loadingMore && hasMore && loadMore) {
            loadMore()
        }
    }, [loading, loadingMore, hasMore, loadMore])

    useEffect(() => {
        const tableContainer = tableContainerRef.current
        if (tableContainer) {
            tableContainer.addEventListener("scroll", handleScroll)

            return () => {
                tableContainer.removeEventListener("scroll", handleScroll)
            }
        }
    }, [handleScroll])

    useIntersectionObserver(loadMoreRef, handleIntersection, {
        deps: [data.length, hasMore, loadingMore, loading],
        threshold: 0.1
    })

    const showInitialLoading = loading && data.length === 0
    const showDataRows = !showInitialLoading && table.getRowModel().rows?.length > 0
    const showNoResults = !loading && hasSearched && data.length === 0 && !noFilterMatch
    const showNoFilterMatch = !loading && noFilterMatch

    return (
        <div className="flex flex-col h-full w-full">
            <div ref={tableContainerRef} className="flex-1 border rounded-md border-border bg-background" style={{ overflow: "auto", position: "relative" }}>
                <div style={{ minHeight: "100%" }}>
                    <Table className="w-full" style={{ height: "100%" }}>
                        <TableHeader className="bg-background after:absolute after:bottom-0 after:left-0 after:w-full after:h-px after:bg-border" style={{ position: "sticky", top: 0, zIndex: 10 }}>
                            {table.getHeaderGroups().map((headerGroup) => (
                                <TableRow key={headerGroup.id}>
                                    {headerGroup.headers.map((header) => (
                                        <TableHead
                                            key={header.id}
                                            style={{
                                                maxWidth: header.getSize(),
                                                position: "sticky",
                                                top: 0,
                                                backgroundColor: "var(--background)",
                                                zIndex: 10
                                            }}
                                        >
                                            {header.isPlaceholder
                                                ? null
                                                : flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext()
                                                )
                                            }
                                        </TableHead>
                                    ))}
                                </TableRow>
                            ))}
                        </TableHeader>
                        <TableBody>
                            {showInitialLoading && (
                                <TableRow>
                                    <TableCell colSpan={dynamicColumns.length + 2}>
                                        <div className="flex justify-center items-center w-full h-full">
                                            <div className="w-full h-full space-y-2">
                                                {[...Array(20)].map((_, index) => (
                                                    <Skeleton key={index} className="h-12 w-full" />
                                                ))}
                                            </div>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                            {showDataRows && table.getRowModel().rows.map((row) => (
                                <TableRow
                                    key={row.id}
                                    data-state={row.getIsSelected() ? "selected" : undefined}
                                    className={`${selectedIds.includes(row.original.id) ? "bg-muted" : ""} ${row.getIsSelected() ? "bg-selection" : ""}`}
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell key={cell.id} style={{ maxWidth: cell.column.getSize() }}>
                                            {flexRender(
                                                cell.column.columnDef.cell,
                                                cell.getContext()
                                            )}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))}
                            {showNoResults && (
                                <TableRow>
                                    <TableCell colSpan={dynamicColumns.length + 2}>
                                        <div className="flex justify-center items-center w-full">
                                            <p className="text-muted-foreground text-center">No documents found.</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                            {showNoFilterMatch && (
                                <TableRow>
                                    <TableCell colSpan={dynamicColumns.length + 2}>
                                        <div className="flex justify-center items-center w-full py-8">
                                            <p className="text-muted-foreground text-center">No documents match the current filtering logic.</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                            {(!loading && !hasSearched && data.length === 0 && !noFilterMatch) && (
                                <TableRow>
                                    <TableCell colSpan={dynamicColumns.length + 2}>
                                        <div className="flex justify-center items-center w-full py-8">
                                            <p className="text-muted-foreground text-center">{t("filters.selectAtLeastOneFilter")}</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                            {loadingMore && (
                                <TableRow>
                                    <TableCell colSpan={dynamicColumns.length + 2}>
                                        <div className="flex justify-center items-center p-4">
                                            <Loader2 className="h-6 w-6 animate-spin text-primary" />
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                            {(hasMore && loadMore && !loadingMore && data.length > 0) && (
                                <TableRow ref={loadMoreRef}>
                                    <TableCell colSpan={dynamicColumns.length + 2} className="h-20 p-0" />
                                </TableRow>
                            )}
                            <TableRow style={{ height: "100%" }}>
                                <TableCell colSpan={dynamicColumns.length + 2} style={{ height: "100%", padding: 0, border: 0 }} />
                            </TableRow>
                        </TableBody>
                    </Table>
                </div>
            </div>
            <div className="flex items-center justify-end space-x-2 pt-2 text-sm text-muted-foreground">
                {showInitialLoading
                    ? "Loading documents..."
                    : loadingMore
                        ? "Loading more..."
                        : (data.length === 0 && !hasSearched)
                            ? "Select filters to search..."
                            : data.length === 0
                                ? "No results."
                                : <>
                                    {table.getFilteredRowModel().rows.length} document{table.getFilteredRowModel().rows.length <= 1 ? "" : "s"}.
                                    {!hasMore ? " (All results loaded)" : ""}
                                </>
                }
            </div>
        </div>
    )
}
