/**
 * ⚠️ TEMPORARY — demo-only theme switcher (ClickUp 86aj7mt77 / Phase A).
 *
 * A small always-present control (bottom-left) that flips the whole app between
 * the 4 look presets in realtime, so a direction can be chosen in a live demo.
 * Throwaway by design — see the removal steps in `lib/theme-preset.ts`. English
 * labels only (not i18n'd) on purpose: it never ships.
 */
import { useEffect, useRef, useState } from "react"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Button } from "@/components/ui/button"
import {
    applyThemePreset,
    getCurrentThemePreset,
    getThemePresets,
    resolveThemeRoot,
    type ThemePresetId,
} from "@/lib/theme-preset"
import { cn } from "@/lib/utils"

const HIDE_KEY = "vertesia.psea.demoThemeSwitcher"

export function ThemeSwitcher() {
    const settings = useAppInstallation()?.settings
    const [active, setActive] = useState<ThemePresetId>("old")
    const [collapsed, setCollapsed] = useState(false)
    // Anchor node — its in-shadow theme root is where data-theme-preset must land
    // (see resolveThemeRoot: the plugin's preset CSS is shadow-scoped).
    const anchorRef = useRef<HTMLDivElement>(null)

    // Restore the persisted preset on mount (survives a refresh during the demo).
    // Runs after the ref is attached, so resolveThemeRoot finds the in-shadow root.
    useEffect(() => {
        const current = getCurrentThemePreset()
        setActive(current)
        applyThemePreset(current, resolveThemeRoot(anchorRef.current))
    }, [])

    // Demo widget: on by default on this branch; hide via app setting
    // `DEMO_THEME_SWITCHER:false` or `localStorage[HIDE_KEY]="off"`.
    const hidden =
        settings?.DEMO_THEME_SWITCHER === false ||
        (typeof window !== "undefined" && localStorage.getItem(HIDE_KEY) === "off")
    if (hidden) {
        return null
    }

    const select = (id: ThemePresetId) => {
        setActive(id)
        applyThemePreset(id, resolveThemeRoot(anchorRef.current))
    }

    return (
        <div ref={anchorRef} className="fixed bottom-4 right-4 z-[9998] rounded-xl border border-border/40 bg-card/30 text-card-foreground shadow-xl backdrop-blur-md">
            <div className="flex items-center gap-2 px-3 py-2">
                <button
                    type="button"
                    onClick={() => setCollapsed((c) => !c)}
                    className="text-xs font-semibold tracking-tight text-muted-foreground hover:text-foreground cursor-pointer"
                    title="Demo only — toggle theme presets"
                >
                    🎨 Theme {collapsed ? "▸" : "▾"}
                </button>
                {!collapsed && (
                    <div className="flex items-center gap-1">
                        {getThemePresets().map((preset) => (
                            <Button
                                key={preset.id}
                                size="sm"
                                variant={active === preset.id ? "default" : "outline"}
                                title={preset.caption}
                                onClick={() => select(preset.id)}
                                className={cn("h-7 px-2.5 text-xs", active === preset.id && "font-semibold")}
                            >
                                {preset.label}
                            </Button>
                        ))}
                    </div>
                )}
            </div>
        </div>
    )
}
