import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Eye, EyeOff } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

interface GridColsConfig {
    sm: number
    md: number
    lg: number
    xl: number
}

export const DEFAULT_LIBRARY_GRID_COLS: GridColsConfig = { sm: 2, md: 3, lg: 4, xl: 5 }
export const DEFAULT_LIBRARY_ADVANCED_GRID_COLS: GridColsConfig = { sm: 1, md: 2, lg: 3, xl: 4 }

interface LibrarySectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: {
        gridCols: GridColsConfig
        advancedGridCols: GridColsConfig
    }) => void
    loading?: boolean
}

export function LibrarySection({ settings, onSave, loading }: Readonly<LibrarySectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [gridCols, setGridCols] = useState<GridColsConfig>({
        sm: Number(settings?.LIBRARY_GRID_COLS_SM) || DEFAULT_LIBRARY_GRID_COLS.sm,
        md: Number(settings?.LIBRARY_GRID_COLS_MD) || DEFAULT_LIBRARY_GRID_COLS.md,
        lg: Number(settings?.LIBRARY_GRID_COLS_LG) || DEFAULT_LIBRARY_GRID_COLS.lg,
        xl: Number(settings?.LIBRARY_GRID_COLS_XL) || DEFAULT_LIBRARY_GRID_COLS.xl,
    })
    const [advancedGridCols, setAdvancedGridCols] = useState<GridColsConfig>({
        sm: Number(settings?.LIBRARY_ADVANCED_GRID_COLS_SM) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.sm,
        md: Number(settings?.LIBRARY_ADVANCED_GRID_COLS_MD) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.md,
        lg: Number(settings?.LIBRARY_ADVANCED_GRID_COLS_LG) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.lg,
        xl: Number(settings?.LIBRARY_ADVANCED_GRID_COLS_XL) || DEFAULT_LIBRARY_ADVANCED_GRID_COLS.xl,
    })

    const [showGridPreview, setShowGridPreview] = useState(false)
    const [showAdvancedPreview, setShowAdvancedPreview] = useState(false)

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:library.title")}</CardTitle>
                <CardDescription>
                    {t("settings:library.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                {/* Standard grid */}
                <div className="flex flex-col gap-4">
                    <div className="flex flex-col gap-1">
                        <Label className="text-base font-semibold">{t("settings:library.gridLayout")}</Label>
                        <p className="text-sm text-muted-foreground">
                            {t("settings:library.gridLayoutHelp")}
                        </p>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                        {(["sm", "md", "lg", "xl"] as const).map((bp) => (
                            <div key={bp} className="flex flex-col gap-2">
                                <Label htmlFor={`library-grid-cols-${bp}`}>
                                    {t(`common:gridCols.${bp}`)}
                                </Label>
                                <Input
                                    id={`library-grid-cols-${bp}`}
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={gridCols[bp]}
                                    onChange={(e) => setGridCols(prev => ({ ...prev, [bp]: Number(e.target.value) }))}
                                    onBlur={(e) => setGridCols(prev => ({ ...prev, [bp]: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">
                                    {t(`common:gridCols.${bp}Hint`)}
                                </p>
                            </div>
                        ))}
                    </div>

                    {/* Preview */}
                    <div className="flex flex-col gap-2">
                        <button
                            type="button"
                            className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                            onClick={() => setShowGridPreview(prev => !prev)}
                        >
                            {showGridPreview ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                            <span>{showGridPreview ? t("common:actions.hidePreview") : t("common:actions.showPreview")}</span>
                        </button>
                        {showGridPreview && (
                            <div className="border rounded-md p-4 bg-muted/30">
                                <div className="flex flex-col gap-3">
                                    {(["xl", "lg", "md", "sm"] as const).map((bp) => (
                                        <div key={bp} className="flex flex-col gap-1">
                                            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{bp}</span>
                                            <div
                                                className="grid gap-1.5"
                                                style={{ gridTemplateColumns: `repeat(${gridCols[bp]}, 1fr)` }}
                                            >
                                                {Array.from({ length: gridCols[bp] }).map((_, i) => (
                                                    <div
                                                        key={i}
                                                        className="aspect-square rounded-sm bg-primary/15 border border-primary/25"
                                                    />
                                                ))}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Advanced search grid */}
                <div className="flex flex-col gap-4 border-t pt-6">
                    <div className="flex flex-col gap-1">
                        <Label className="text-base font-semibold">{t("settings:library.advancedSearchLayout")}</Label>
                        <p className="text-sm text-muted-foreground">
                            {t("settings:library.advancedSearchLayoutHelp")}
                        </p>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                        {(["sm", "md", "lg", "xl"] as const).map((bp) => (
                            <div key={bp} className="flex flex-col gap-2">
                                <Label htmlFor={`library-adv-grid-cols-${bp}`}>
                                    {t(`common:gridCols.${bp}`)}
                                </Label>
                                <Input
                                    id={`library-adv-grid-cols-${bp}`}
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={advancedGridCols[bp]}
                                    onChange={(e) => setAdvancedGridCols(prev => ({ ...prev, [bp]: Number(e.target.value) }))}
                                    onBlur={(e) => setAdvancedGridCols(prev => ({ ...prev, [bp]: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">
                                    {t(`common:gridCols.${bp}Hint`)}
                                </p>
                            </div>
                        ))}
                    </div>

                    {/* Preview */}
                    <div className="flex flex-col gap-2">
                        <button
                            type="button"
                            className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                            onClick={() => setShowAdvancedPreview(prev => !prev)}
                        >
                            {showAdvancedPreview ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                            <span>{showAdvancedPreview ? t("common:actions.hidePreview") : t("common:actions.showPreview")}</span>
                        </button>
                        {showAdvancedPreview && (
                            <div className="border rounded-md p-4 bg-muted/30">
                                <div className="flex flex-col gap-3">
                                    {(["xl", "lg", "md", "sm"] as const).map((bp) => (
                                        <div key={bp} className="flex flex-col gap-1">
                                            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{bp}</span>
                                            <div
                                                className="grid gap-1.5"
                                                style={{ gridTemplateColumns: `repeat(${advancedGridCols[bp]}, 1fr)` }}
                                            >
                                                {Array.from({ length: advancedGridCols[bp] }).map((_, i) => (
                                                    <div
                                                        key={i}
                                                        className="aspect-square rounded-sm bg-primary/15 border border-primary/25"
                                                    />
                                                ))}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ gridCols, advancedGridCols })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
