import { useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { Collection } from "@vertesia/common"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { FileText, FolderOpen } from "lucide-react"
import { Skeleton } from "@/components/ui/skeleton"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { formatRelativeDate } from "@/lib/date"

interface CollectionDataTableProps {
    collections: Collection[]
    loading: boolean
    onCollectionClick: (collection: Collection) => void
}

function CollectionTableRow({ collection, onClick }: {
    collection: Collection
    onClick: () => void
}) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const [memberCount, setMemberCount] = useState<number>(0)

    const typeName = typeRegistry?.getTypeName(collection.type?.id || "") || collection.type?.name || t("collection")

    useEffect(() => {
        if (!client || !collection.id) return

        const fetchMemberCount = async () => {
            try {
                const [members, children] = await Promise.all([
                    client.store.collections.computeFacets(collection.id, {
                        facets: [{ name: "total", field: "total" }]
                    }),
                    client.store.collections.searchChildren(collection.id, { limit: 10000 })
                ])

                const total = ((members)?.total || 0) + children.length
                setMemberCount(total)
            } catch (error) {
                console.error("Failed to fetch member count:", error)
                setMemberCount(0)
            }
        }

        fetchMemberCount()
    }, [client, collection.id])

    return (
        <TableRow
            className="cursor-pointer"
            onClick={onClick}
        >
            <TableCell className="font-medium overflow-hidden">
                <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-muted">
                        <FolderOpen className="h-4 w-4 text-muted-foreground" />
                    </div>
                    <span className="truncate" title={collection.name}>
                        {collection.name}
                    </span>
                </div>
            </TableCell>
            <TableCell className="hidden md:table-cell text-muted-foreground overflow-hidden">
                <span className="truncate block" title={typeName}>
                    {typeName}
                </span>
            </TableCell>
            <TableCell className="text-right">
                <div className="flex items-center justify-end gap-1.5 text-sm text-muted-foreground">
                    <FileText className="h-4 w-4" />
                    <span>{memberCount}</span>
                </div>
            </TableCell>
            <TableCell className="hidden lg:table-cell text-muted-foreground text-sm">
                {collection.updated_at ? formatRelativeDate(collection.updated_at) : "—"}
            </TableCell>
        </TableRow>
    )
}

export function CollectionDataTable({ collections, loading, onCollectionClick }: CollectionDataTableProps) {
    const { t } = useTranslation("common")
    if (loading) {
        return (
            <div className="flex flex-col gap-2">
                {Array.from({ length: 6 }).map((_, i) => (
                    <Skeleton key={i} className="h-12 w-full" />
                ))}
            </div>
        )
    }

    return (
        <Table className="table-fixed">
            <TableHeader>
                <TableRow>
                    <TableHead className="w-[60%]">{t("properties.name")}</TableHead>
                    <TableHead className="hidden md:table-cell w-[18%]">{t("properties.type")}</TableHead>
                    <TableHead className="text-right w-[10%]">{t("tables.items")}</TableHead>
                    <TableHead className="hidden lg:table-cell w-[12%]">{t("properties.updatedAt")}</TableHead>
                </TableRow>
            </TableHeader>
            <TableBody>
                {collections.map((collection) => (
                    <CollectionTableRow
                        key={collection.id}
                        collection={collection}
                        onClick={() => onCollectionClick(collection)}
                    />
                ))}
            </TableBody>
        </Table>
    )
}
