import { useState, useEffect, useCallback, useRef } from "react"
import { useTranslation } from "react-i18next"
import { Collection } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useNavigate } from "@vertesia/ui/router"
import { useUserSession } from "@vertesia/ui/session"
import type { ParseKeys } from "i18next"
import { FolderPlus, Loader2, Search } from "lucide-react"
import { CollectionCard } from "@/components/cards/CollectionCard"
import { CreateCollectionOverlay } from "@/components/overlays/CreateCollectionOverlay"
import { CollectionDataTable } from "@/components/tables/CollectionDataTable"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { ViewModeSwitcher } from "@/components/widgets/ViewModeSwitcher"
import { useCollectionTypesWhitelist } from "@/hooks/use-collection-types-whitelist"
import { useCollectionsViewMode } from "@/hooks/use-collections-view-mode"

type CollectionCategory = "personal" | "organization"

const CATEGORY_LABEL_KEYS: Record<CollectionCategory, ParseKeys<["collections", "common"]>> = {
    personal: "collections:personal",
    organization: "collections:organization",
}

interface CollectionsPanelProps {
    category: CollectionCategory
}

export function CollectionsPanel({ category }: Readonly<CollectionsPanelProps>) {
    const { t } = useTranslation(["collections", "common"])
    const { client, user } = useUserSession()
    const toast = useToast()
    const navigate = useNavigate()

    const [viewMode, setViewMode] = useCollectionsViewMode()
    const whitelist = useCollectionTypesWhitelist()

    const PAGE_SIZE = 50

    const [collections, setCollections] = useState<Collection[]>([])
    const [loading, setLoading] = useState(true)
    const [loadingMore, setLoadingMore] = useState(false)
    const [hasMore, setHasMore] = useState(false)
    const [searchQuery, setSearchQuery] = useState("")
    const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("")
    const [isCreateOverlayOpen, setIsCreateOverlayOpen] = useState(false)

    const buildSearchParams = useCallback((query?: string, offset?: number) => {
        const searchParams: Record<string, unknown> = {
            limit: PAGE_SIZE,
            dynamic: false,
        }
        if (offset) {
            searchParams.offset = offset
        }
        if (query && query.trim()) {
            searchParams.name = query.trim()
        }
        if (whitelist) {
            searchParams.types = whitelist
        }

        if (category === "personal" && user?.sub) {
            // Exclude the hidden per-user favorites collection from the personal list.
            searchParams.match = { "properties.user": user.sub, "properties.favorites": { $ne: true } }
        } else if (category === "organization") {
            searchParams.match = { "properties.user": { "$exists": false } }
        }

        return searchParams
    }, [category, user, whitelist])

    const loadCollections = useCallback(async (query?: string) => {
        if (!client) {
            return
        }

        setLoading(true)
        try {
            const searchParams = buildSearchParams(query)
            const response = await client.store.collections.search(searchParams)
            const results = response as Collection[]
            setCollections(results)
            setHasMore(results.length >= PAGE_SIZE)
        } catch (error: any) {
            toast({
                status: "error",
                title: "Failed to load collections",
                description: error.message || "An error occurred",
                duration: 3000,
            })
        } finally {
            setLoading(false)
        }
    }, [client, buildSearchParams, toast])

    const loadMore = useCallback(async () => {
        if (!client || loadingMore || !hasMore) return

        setLoadingMore(true)
        try {
            const searchParams = buildSearchParams(debouncedSearchQuery, collections.length)
            const response = await client.store.collections.search(searchParams)
            const results = response as Collection[]
            setCollections(prev => [...prev, ...results])
            setHasMore(results.length >= PAGE_SIZE)
        } catch (error: any) {
            toast({
                status: "error",
                title: "Failed to load more collections",
                description: error.message || "An error occurred",
                duration: 3000,
            })
        } finally {
            setLoadingMore(false)
        }
    }, [client, loadingMore, hasMore, buildSearchParams, debouncedSearchQuery, collections.length, toast])

    // Infinite scroll: observe a sentinel element at the bottom
    const sentinelRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        const sentinel = sentinelRef.current
        if (!sentinel) return

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && hasMore && !loadingMore && !loading) {
                    loadMore()
                }
            },
            { threshold: 0.1 }
        )

        observer.observe(sentinel)
        return () => observer.disconnect()
    }, [hasMore, loadingMore, loading, loadMore])

    // Reset search when category changes
    useEffect(() => {
        setSearchQuery("")
        setDebouncedSearchQuery("")
        setCollections([])
        setHasMore(false)
    }, [category])

    // Debounce search query
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearchQuery(searchQuery)
        }, 300)

        return () => clearTimeout(timer)
    }, [searchQuery])

    // Load collections when category or debounced search query changes
    useEffect(() => {
        loadCollections(debouncedSearchQuery)
    }, [loadCollections, debouncedSearchQuery])

    const handleCreateSuccess = () => {
        loadCollections()
    }

    const handleCollectionClick = (collection: Collection) => {
        navigate(`/collections/${collection.id}`)
    }

    const labelKey = CATEGORY_LABEL_KEYS[category]
    const label = labelKey ? t(labelKey) : undefined
    const emptyLabel = label ? t("collections:noCollectionsYet", { label }) : t("collections:noCollectionsYetGeneric")
    const searchEmptyLabel = label ? t("collections:noCollectionsFound", { label }) : t("collections:noCollectionsFoundGeneric")

    return (
        <div className="flex flex-col h-full gap-4 p-2">
            {/* Header */}
            <div className="flex items-center gap-4">
                {/* Search Bar */}
                <div className="relative w-full">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder={t("collections:searchPlaceholder")}
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10"
                    />
                </div>
                <ViewModeSwitcher value={viewMode} onValueChange={setViewMode} />
                <Button onClick={() => setIsCreateOverlayOpen(true)}>
                    <FolderPlus className="h-4 w-4 mr-2" />
                    {t("collections:createCollection")}
                </Button>
            </div>

            {/* Collections Grid */}
            <div className="flex-1 overflow-auto">
                {
                    (loading) ? (
                        <div className="flex items-center justify-center h-full">
                            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                        </div>
                    ) : (collections.length === 0) ? (
                        <Card className="h-full">
                            <CardContent className="flex flex-col items-center justify-center h-full text-muted-foreground">
                                {
                                    (searchQuery) ? (
                                        <>
                                            <Search className="h-12 w-12 mb-4" />
                                            <p className="text-lg font-medium">{searchEmptyLabel}</p>
                                            <p className="text-sm mt-1">{t("collections:tryAdjustingSearch")}</p>
                                        </>
                                    ) : (
                                        <>
                                            <FolderPlus className="h-12 w-12 mb-4" />
                                            <p className="text-lg font-medium">{emptyLabel}</p>
                                            <p className="text-sm mt-1">{t("collections:createFirstCollection")}</p>
                                            <Button
                                                onClick={() => setIsCreateOverlayOpen(true)}
                                                className="mt-4"
                                            >
                                                <FolderPlus className="h-4 w-4 mr-2" />
                                                {t("collections:createCollection")}
                                            </Button>
                                        </>
                                    )
                                }
                            </CardContent>
                        </Card>
                    ) : viewMode === "grid" ? (
                        <>
                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                                {
                                    collections.map((collection) => (
                                        <CollectionCard
                                            key={collection.id}
                                            collection={collection}
                                            onClick={handleCollectionClick}
                                        />
                                    ))
                                }
                            </div>
                            {hasMore && (
                                <div ref={sentinelRef} className="flex justify-center py-4">
                                    {loadingMore && <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />}
                                </div>
                            )}
                        </>
                    ) : (
                        <>
                            <CollectionDataTable
                                collections={collections}
                                loading={false}
                                onCollectionClick={handleCollectionClick}
                            />
                            {hasMore && (
                                <div ref={sentinelRef} className="flex justify-center py-4">
                                    {loadingMore && <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />}
                                </div>
                            )}
                        </>
                    )
                }
            </div>

            {/* Create Collection Overlay */}
            <CreateCollectionOverlay
                isOpen={isCreateOverlayOpen}
                onClose={() => setIsCreateOverlayOpen(false)}
                onSuccess={handleCreateSuccess}
                category={category}
            />
        </div>
    )
}
