import { useTranslation } from "react-i18next"
import { useLocation, useNavigate } from "@vertesia/ui/router"
import { useAppInstallation } from "@vertesia/ui/shell"
import { ChevronRight } from "lucide-react"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton, SidebarMenuSubItem, useSidebar } from "@/components/ui/sidebar"
import { getHiddenSidebarUrls, isSidebarItemHidden } from "@/lib/sidebar-visibility"
import { NavigationSectionModel, NavigatioSubItemModel } from "@/models/navigation"

const matchesRoute = (currentPath: string, routePattern: string): boolean => {
    const regexPattern = routePattern
        .replace(/:[^/]+/g, "[^/]+")
        .replace(/\//g, "\\/")

    const regex = new RegExp(`^${regexPattern}$`)
    return regex.test(currentPath)
}

interface NavigationSectionProps {
    section: NavigationSectionModel
}
export function NavigationSection({ section }: Readonly<NavigationSectionProps>) {
    const appInstallation = useAppInstallation()
    const location = useLocation()
    const navigate = useNavigate()
    const { state } = useSidebar()
    const { t } = useTranslation("navigation")

    const appName = appInstallation?.manifest.name || undefined
    const appPath = appName ? `/apps/${appName}` : ""

    const handleNavigate = (url: string) => {
        if (window.location.hash && appPath && window.location.pathname.includes(appPath)) {
            window.history.pushState(null, "", `${appPath}${url}`)
            window.location.reload()
        } else {
            navigate(url)
        }
    }

    const isActiveRoute = (itemUrl: string): boolean => {
        const isAppPath = appPath && location.pathname.startsWith(appPath)
        const fullPath = isAppPath ? `${appPath}${itemUrl}` : itemUrl

        if (itemUrl.includes(":")) {
            return matchesRoute(location.pathname, fullPath)
        }

        if (itemUrl === "/") {
            return location.pathname === fullPath
        }

        return `${location.pathname}${window.location.hash}` === fullPath || location.pathname.startsWith(fullPath + "/")
    }

    const hasSubItems = (item: typeof section.items[number]): item is NavigatioSubItemModel => {
        return "items" in item && Array.isArray(item.items)
    }

    const hiddenUrls = getHiddenSidebarUrls(appInstallation?.settings)

    // Filter out blacklisted items: drop hidden top-level items and hidden
    // sub-items, then drop any parent whose sub-items are now all hidden.
    const visibleItems = section.items
        .filter((item) => !isSidebarItemHidden(item.url, hiddenUrls))
        .map((item) =>
            hasSubItems(item)
                ? { ...item, items: item.items.filter((subItem) => !isSidebarItemHidden(subItem.url, hiddenUrls)) }
                : item
        )
        .filter((item) => !(hasSubItems(item) && item.items.length === 0))

    if (visibleItems.length === 0) {
        return null
    }

    return (
        <SidebarGroup>
            <SidebarGroupLabel>{t(section.title)}</SidebarGroupLabel>
            <SidebarMenu>
                {
                    visibleItems.map((item) => {
                        if (hasSubItems(item)) {
                            const isCollapsed = state === "collapsed"
                            // Check if any sub-item is active
                            const hasActiveSubItem = item.items.some(subItem => isActiveRoute(subItem.url))
                            const isParentActive = isCollapsed && hasActiveSubItem

                            return (
                                <Collapsible
                                    key={item.title}
                                    asChild
                                    defaultOpen={true}
                                    className="group/collapsible"
                                >
                                    <SidebarMenuItem>
                                        <CollapsibleTrigger asChild>
                                            <SidebarMenuButton
                                                tooltip={t(item.tooltip)}
                                                className="hover:cursor-pointer"
                                                isActive={isParentActive}
                                                onClick={(e) => {
                                                    // When sidebar is collapsed, navigate to parent URL instead of toggling
                                                    if (isCollapsed && item.url) {
                                                        e.preventDefault()
                                                        handleNavigate(item.url)
                                                    }
                                                }}
                                            >
                                                <item.icon />
                                                <span>{t(item.title)}</span>
                                                <ChevronRight className="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90" />
                                            </SidebarMenuButton>
                                        </CollapsibleTrigger>
                                        <CollapsibleContent>
                                            <SidebarMenuSub>
                                                {item.items.map((subItem) => (
                                                    <SidebarMenuSubItem key={subItem.title}>
                                                        <SidebarMenuSubButton
                                                            asChild
                                                            isActive={isActiveRoute(subItem.url)}
                                                            className="hover:cursor-pointer"
                                                        >
                                                            <div onClick={() => handleNavigate(subItem.url)}>
                                                                <subItem.icon />
                                                                <span>{t(subItem.title)}</span>
                                                            </div>
                                                        </SidebarMenuSubButton>
                                                    </SidebarMenuSubItem>
                                                ))}
                                            </SidebarMenuSub>
                                        </CollapsibleContent>
                                    </SidebarMenuItem>
                                </Collapsible>
                            )
                        } else {
                            // NavigationItemModel - render as regular menu item
                            return (
                                <SidebarMenuItem
                                    key={item.title}
                                >
                                    <SidebarMenuButton
                                        asChild
                                        tooltip={t(item.tooltip)}
                                        className="hover:cursor-pointer"
                                        isActive={isActiveRoute(item.url)}
                                    >
                                        <div onClick={() => handleNavigate(item.url)}>
                                            <item.icon />
                                            <span>{t(item.title)}</span>
                                        </div>
                                    </SidebarMenuButton>
                                </SidebarMenuItem>
                            )
                        }
                    })
                }
            </SidebarMenu>
        </SidebarGroup>
    )
}
