import { VertesiaClient } from "@vertesia/client"
import { Collection, ContentObjectItem } from "@vertesia/common"

/**
 * Marker property used to distinguish a user's favorites collection from regular
 * personal collections. The favorites collection is created lazily on the first
 * favorite and is owned by a single user (properties.user === user.sub).
 */
export const FAVORITES_MARKER_PROPERTY = "favorites"

/** Upper bound on how many favorites we load at once. */
const FAVORITES_LIMIT = 1000

/**
 * Find the current user's favorites collection, returning its id, or null when it
 * does not exist yet.
 */
export async function findFavoritesCollection(
    client: VertesiaClient,
    userSub: string,
): Promise<string | null> {
    const collections = await client.store.collections.search({
        dynamic: false,
        limit: 1,
        match: {
            "properties.user": userSub,
            [`properties.${FAVORITES_MARKER_PROPERTY}`]: true,
        },
    })
    return collections.length > 0 ? collections[0].id : null
}

/**
 * Create the current user's favorites collection. The collection is private to the
 * user and tagged with the favorites marker. When a favorites collection type is
 * configured (FAVORITES_COLLECTION_TYPE app setting) the collection is created with
 * that type; otherwise it is created without a specific type.
 */
export async function createFavoritesCollection(
    client: VertesiaClient,
    userSub: string,
    typeId?: string,
): Promise<string> {
    const collection: Collection = await client.store.collections.create({
        name: "Favorites",
        dynamic: false,
        ...(typeId ? { type: typeId } : {}),
        properties: {
            user: userSub,
            [FAVORITES_MARKER_PROPERTY]: true,
        },
    })

    // Keep the favorites collection private to its owner.
    const principals = [`user:${userSub}`]
    await client.store.collections.updatePermissions(collection.id, {
        "content:read": principals,
        "content:write": principals,
        "content:delete": principals,
    })

    return collection.id
}

/**
 * Resolve the current user's favorites collection id, creating it if it does not
 * exist yet.
 */
export async function findOrCreateFavoritesCollection(
    client: VertesiaClient,
    userSub: string,
    typeId?: string,
): Promise<string> {
    const existing = await findFavoritesCollection(client, userSub)
    if (existing) {
        return existing
    }
    return createFavoritesCollection(client, userSub, typeId)
}

export function addFavorites(
    client: VertesiaClient,
    collectionId: string,
    documentIds: string[],
): Promise<{ id: string }> {
    return client.store.collections.addMembers(collectionId, documentIds)
}

export function removeFavorites(
    client: VertesiaClient,
    collectionId: string,
    documentIds: string[],
): Promise<{ id: string }> {
    return client.store.collections.deleteMembers(collectionId, documentIds)
}

/**
 * Fetch the ids of every document in the favorites collection.
 */
export async function fetchFavoriteIds(
    client: VertesiaClient,
    collectionId: string,
): Promise<string[]> {
    const response = await client.store.collections.searchMembers(collectionId, {
        limit: FAVORITES_LIMIT,
        select: "id",
    })
    return response.results.map((item) => item.id)
}

/**
 * Fetch the full documents stored in the favorites collection.
 */
export async function fetchFavoriteDocuments(
    client: VertesiaClient,
    collectionId: string,
): Promise<ContentObjectItem[]> {
    const response = await client.store.collections.searchMembers(collectionId, {
        limit: FAVORITES_LIMIT,
    })
    return response.results
}
