import { useState, useEffect, useCallback } from "react"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { useEcmTypesWhitelist } from "@/hooks/use-ecm-types-whitelist"
import { DashboardStats } from "@/models/dashboard"

export const useDashboardStats = () => {
    const { client } = useUserSession()
    const toast = useToast()
    const ecmTypesWhitelist = useEcmTypesWhitelist()
    const [stats, setStats] = useState<DashboardStats | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<Error | null>(null)

    const getStartOfWeek = () => {
        const date = new Date()
        const day = date.getDay()
        const diff = date.getDate() - day + (day === 0 ? -6 : 1) // Adjust for Monday as start of week
        date.setDate(diff)
        date.setHours(0, 0, 0, 0)
        return date.toISOString()
    }

    const getStartOfMonth = () => {
        const date = new Date()
        date.setDate(1)
        date.setHours(0, 0, 0, 0)
        return date.toISOString()
    }

    const getStartOfYear = () => {
        const date = new Date()
        date.setMonth(0, 1)
        date.setHours(0, 0, 0, 0)
        return date.toISOString()
    }

    const fetchStats = useCallback(async () => {
        if (!client) {
            setLoading(false)
            return
        }

        setLoading(true)
        setError(null)

        try {
            const results = await Promise.allSettled([
                client.objects.computeFacets({
                    facets: [
                        { name: "total", field: "total" }
                    ],
                    ...(ecmTypesWhitelist && { query: { types: ecmTypesWhitelist } })
                }),
                client.objects.count({
                    query: {
                        created_at: { $gte: getStartOfWeek() },
                        ...(ecmTypesWhitelist && { type: { $in: ecmTypesWhitelist } })
                    }
                }),
                client.objects.count({
                    query: {
                        created_at: { $gte: getStartOfMonth() },
                        ...(ecmTypesWhitelist && { type: { $in: ecmTypesWhitelist } })
                    }
                }),
                client.objects.count({
                    query: {
                        created_at: { $gte: getStartOfYear() },
                        ...(ecmTypesWhitelist && { type: { $in: ecmTypesWhitelist } })
                    }
                })
            ])

            const facetsResult = results[0].status === "fulfilled" ? results[0].value : null
            const totalDocs = facetsResult?.total || 0
            const documentsThisWeek = results[1].status === "fulfilled" ? results[1].value.count : 0
            const documentsThisMonth = results[2].status === "fulfilled" ? results[2].value.count : 0
            const documentsThisYear = results[3].status === "fulfilled" ? results[3].value.count : 0

            setStats({
                totalDocuments: totalDocs,
                documentsThisWeek,
                documentsThisMonth,
                documentsThisYear
            })
        } catch (err) {
            const error = err as Error
            setError(error)
            console.error("Failed to fetch dashboard stats:", error)
            if (toast) {
                toast({
                    status: "error",
                    title: "Failed to load statistics",
                    description: "Unable to fetch dashboard statistics. Please try again."
                })
            }
        } finally {
            setLoading(false)
        }
    }, [client, toast, ecmTypesWhitelist])

    useEffect(() => {
        fetchStats()
    }, [fetchStats])

    return { stats, loading, error, refetch: fetchStats }
}
