import { useState, useEffect, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { useUserSession } from "@vertesia/ui/session"
import { Check, ChevronsUpDown, Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
    CommandSeparator,
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { formatPropertyName } from "@/lib/properties"
import { cn } from "@/lib/utils"

export interface SchemaPropertyOption {
    path: string
    label: string
    type: string
}

interface PropertySelectProps {
    typeId?: string
    value: string
    onChange: (path: string, label: string) => void
    excludePaths?: string[]
    placeholder?: string
    disabled?: boolean
}

const COMMON_PROPERTY_OPTIONS: SchemaPropertyOption[] = [
    { path: "name", label: "Name", type: "string" },
    { path: "status", label: "Status", type: "string" },
    { path: "location", label: "Location", type: "string" },
    { path: "tags", label: "Tags", type: "array" },
    { path: "created_at", label: "Created At", type: "string" },
    { path: "updated_at", label: "Updated At", type: "string" },
    { path: "created_by", label: "Created By", type: "string" },
    { path: "updated_by", label: "Updated By", type: "string" },
    { path: "is_deleted", label: "Is Deleted", type: "boolean" },
    { path: "content.type", label: "Content Type", type: "string" },
    { path: "content.name", label: "Content Name", type: "string" },
    { path: "content.source", label: "Content Source", type: "string" },
    { path: "tokens.count", label: "Token Count", type: "number" },
    { path: "tokens.encoding", label: "Token Encoding", type: "string" },
    { path: "type.id", label: "Type", type: "string" },
]

function flattenSchemaProperties(
    properties: Record<string, any>,
    prefix: string
): SchemaPropertyOption[] {
    const result: SchemaPropertyOption[] = []

    for (const [key, schema] of Object.entries(properties)) {
        const path = prefix ? `${prefix}.${key}` : key
        const type = schema.type ?? "unknown"

        if (type === "object" && schema.properties) {
            result.push(...flattenSchemaProperties(schema.properties, path))
        } else {
            result.push({
                path,
                label: schema.title ?? formatPropertyName(key),
                type,
            })
        }
    }

    return result.sort((a, b) => a.label.localeCompare(b.label))
}

function PropertyOption({ option, isSelected }: Readonly<{ option: SchemaPropertyOption; isSelected: boolean }>) {
    return (
        <>
            <Check
                className={cn(
                    "mr-2 h-4 w-4 shrink-0",
                    isSelected ? "opacity-100" : "opacity-0"
                )}
            />
            <div className="flex flex-col">
                <span>{option.label}</span>
                <span className="text-xs text-muted-foreground">{option.path}</span>
            </div>
        </>
    )
}

export function PropertySelect({
    typeId,
    value,
    onChange,
    excludePaths = [],
    placeholder,
    disabled = false,
}: Readonly<PropertySelectProps>) {
    const { t } = useTranslation("common")
    const resolvedPlaceholder = placeholder ?? t("inputs.selectProperty")
    const { client } = useUserSession()
    const [typeOptions, setTypeOptions] = useState<SchemaPropertyOption[]>([])
    const [isLoading, setIsLoading] = useState(true)
    const [open, setOpen] = useState(false)

    useEffect(() => {
        if (!client || !typeId) {
            setTypeOptions([])
            setIsLoading(false)
            return
        }

        setIsLoading(true)
        client.store.types
            .retrieve(typeId)
            .then((typeResponse) => {
                const schema = typeResponse.object_schema
                if (schema?.properties) {
                    setTypeOptions(flattenSchemaProperties(schema.properties, "properties"))
                } else {
                    setTypeOptions([])
                }
            })
            .catch((error) => {
                console.error("Failed to fetch type schema:", error)
                setTypeOptions([])
            })
            .finally(() => {
                setIsLoading(false)
            })
    }, [client, typeId])

    const allOptions = useMemo(() => {
        return [...COMMON_PROPERTY_OPTIONS, ...typeOptions]
    }, [typeOptions])

    const availableCommon = useMemo(() => {
        return COMMON_PROPERTY_OPTIONS.filter((opt) => !excludePaths.includes(opt.path) || opt.path === value)
    }, [excludePaths, value])

    const availableType = useMemo(() => {
        return typeOptions.filter((opt) => !excludePaths.includes(opt.path) || opt.path === value)
    }, [typeOptions, excludePaths, value])

    const selectedOption = useMemo(() => {
        return allOptions.find((opt) => opt.path === value)
    }, [allOptions, value])

    const displayLabel = useMemo(() => {
        if (!value) return resolvedPlaceholder
        if (selectedOption) return selectedOption.label
        // Value is set but not in current options (e.g. from a different type) — show the path
        return formatPropertyName(value.split(".").pop() ?? value)
    }, [value, selectedOption, resolvedPlaceholder])

    const handleSelect = (optionPath: string) => {
        const option = allOptions.find((opt) => opt.path === optionPath)
        if (option) {
            onChange(option.path, option.label)
        }
        setOpen(false)
    }

    if (isLoading) {
        return (
            <div className="flex h-9 w-full items-center justify-center rounded-md border border-input bg-popover px-3 py-2">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            </div>
        )
    }

    if (allOptions.length === 0 && !value) {
        return (
            <div className="flex h-9 w-full items-center rounded-md border border-input bg-popover px-3 py-2">
                <span className="text-sm text-muted-foreground">{t("inputs.noPropertiesAvailable")}</span>
            </div>
        )
    }

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className="w-full justify-between font-normal bg-popover"
                    disabled={disabled}
                >
                    <span className="truncate">
                        {displayLabel}
                    </span>
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="p-0" align="start" style={{ width: "var(--radix-popover-trigger-width)" }}>
                <Command>
                    <CommandInput placeholder={t("inputs.searchProperties")} />
                    <CommandList>
                        <CommandEmpty>{t("inputs.noPropertyFound")}</CommandEmpty>
                        {availableType.length > 0 && (
                            <CommandGroup heading={t("inputs.typeProperties")}>
                                {availableType.map((option) => (
                                    <CommandItem
                                        key={option.path}
                                        value={`${option.label} ${option.path}`}
                                        onSelect={() => handleSelect(option.path)}
                                    >
                                        <PropertyOption option={option} isSelected={value === option.path} />
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                        )}
                        {availableType.length > 0 && availableCommon.length > 0 && <CommandSeparator />}
                        {availableCommon.length > 0 && (
                            <CommandGroup heading={t("inputs.commonProperties")}>
                                {availableCommon.map((option) => (
                                    <CommandItem
                                        key={option.path}
                                        value={`${option.label} ${option.path}`}
                                        onSelect={() => handleSelect(option.path)}
                                    >
                                        <PropertyOption option={option} isSelected={value === option.path} />
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                        )}
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    )
}
