import { useMemo } from "react"
import { useAppInstallation } from "@vertesia/ui/shell"

/**
 * Read a document-type whitelist from the app installation settings.
 *
 * Returns the list of type IDs, or `undefined` when the setting is absent or
 * empty — callers treat `undefined` as "no restriction, show all types".
 */
export function useWhitelist(settingKey: string): string[] | undefined {
    const appInstallation = useAppInstallation()
    const raw = appInstallation?.settings?.[settingKey]

    return useMemo(() => {
        if (!raw || !Array.isArray(raw) || raw.length === 0) {
            return undefined
        }
        return raw as string[]
    }, [raw])
}
