import { useEffect } from "react"
import { useLocation, useNavigate } from "@vertesia/ui/router"
import { ApplicationLayout } from "@/components/layouts/ApplicationLayout"
import { CollectionsPanel } from "@/features/collections/CollectionsPanel"

type CollectionCategory = "personal" | "organization"

const VALID_CATEGORIES: CollectionCategory[] = ["personal", "organization"]

export function CollectionsRedirectPage() {
    const navigate = useNavigate()

    useEffect(() => {
        navigate("/collections/personal", { replace: true })
    }, [navigate])

    return null
}

export function CollectionsPage() {
    const location = useLocation()
    const segment = location.pathname.split("/").filter(Boolean).pop()
    const category: CollectionCategory = VALID_CATEGORIES.includes(segment as CollectionCategory)
        ? (segment as CollectionCategory)
        : "personal"

    return (
        <ApplicationLayout>
            <CollectionsPanel category={category} />
        </ApplicationLayout>
    )
}
