import { useTranslation } from "react-i18next"
import { FileText, CalendarDays, CalendarRange, Calendar } from "lucide-react"
import { useDashboardStats } from "@/hooks/use-dashboard-stats"
import { StatCard } from "./StatCard"

export function StatCardsGrid() {
    const { t } = useTranslation("common")
    const { stats, loading } = useDashboardStats()

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard
                icon={FileText}
                title={t("stats.totalDocuments")}
                value={stats?.totalDocuments || 0}
                description={t("stats.allDocuments")}
                loading={loading}
            />
            <StatCard
                icon={CalendarDays}
                title={t("stats.thisWeek")}
                value={stats?.documentsThisWeek || 0}
                description={t("stats.documentsThisWeek")}
                loading={loading}
            />
            <StatCard
                icon={CalendarRange}
                title={t("stats.thisMonth")}
                value={stats?.documentsThisMonth || 0}
                description={t("stats.documentsThisMonth")}
                loading={loading}
            />
            <StatCard
                icon={Calendar}
                title={t("stats.thisYear")}
                value={stats?.documentsThisYear || 0}
                description={t("stats.documentsThisYear")}
                loading={loading}
            />
        </div>
    )
}
