import { useState, ReactNode, useCallback, useEffect, useMemo } from "react"
import { ContentObjectItem, VectorSearchQuery } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { TypeRegistry, useTypeRegistry } from "@vertesia/ui/features"
import { X, FileCheck, FilterX } from "lucide-react"
import { DocumentDataTable } from "@/components/datatables/DocumentDataTable"
import { DocumentGrid } from "@/components/datatables/DocumentGrid"
import { ViewToggle, ViewMode } from "@/components/datatables/ViewToggle"
import { FiltersPanel } from "@/components/filters/FiltersPanel"
import { Button } from "@/components/ui/button"
import { transformFacetStatusResponses, transformFacetTypeResponses, transformFacetUserResponses, transformPropertiesFacetsWithFilter } from "@/lib/facet"
import { removeEmptyValues } from "@/lib/filters"
import { DynamicColumn } from "@/models/datatable"
import { FacetResponse, PropertyFacet, SearchFilters } from "@/models/facets"
import { DocumentSearchProvider, useWatchDocumentSearchFacets, useWatchDocumentSearchResult } from "@/plugins/providers/document"

const DEFAULT_COLUMNS: DynamicColumn[] = [
    { key: "name", label: "Name", type: "string" },
    { key: "type.name", label: "Type", type: "string" },
    { key: "created_at", label: "Created At", type: "date" },
    { key: "updated_at", label: "Updated At", type: "date" }
]

const DEFAULT_FACETS = [
    { name: "status", field: "status" },
    { name: "type", field: "type" },
    { name: "created_by", field: "created_by" }
]

type SelectionMode = "single" | "multiple"

interface DocumentSelectionSearchPanelProps {
    children?: ReactNode
    onMultipleSelection: (documents: ContentObjectItem[]) => void
    typeRegistry?: TypeRegistry
    columns?: DynamicColumn[]
    facetConfig?: { name: string; field: string }[]
    selectionMode?: SelectionMode
}

function DocumentSelectionSearchPanel({ children, onMultipleSelection, typeRegistry, columns = DEFAULT_COLUMNS, facetConfig = DEFAULT_FACETS, selectionMode = "multiple" }: Readonly<DocumentSelectionSearchPanelProps>) {
    const toast = useToast()
    const { hasMore, search, isSearching, error, objects } = useWatchDocumentSearchResult()
    const facets = useWatchDocumentSearchFacets()

    const documentTypes = useMemo(() => typeRegistry?.types || [], [typeRegistry?.types])

    const [viewMode, setViewMode] = useState<ViewMode>("list")
    const [filters, setFilters] = useState<SearchFilters>({})
    const [statuses, setStatuses] = useState<FacetResponse[]>([])
    const [properties, setProperties] = useState<PropertyFacet[]>([])
    const [types, setTypes] = useState<FacetResponse[]>([])
    const [users, setUsers] = useState<FacetResponse[]>([])

    const [selectionDocuments, setSelectionDocuments] = useState<ContentObjectItem[]>([])
    const [loadingMore, setLoadingMore] = useState(false)
    const [clearFilters, setClearFilters] = useState(0)
    const [hasSearched, setHasSearched] = useState(false)

    const searchObjects = async () => {
        const full_text = filters?.properties?.full_text
        const vectorText = filters?.vectorText as string
        const vector: VectorSearchQuery | undefined = vectorText ? { text: vectorText, config: { text: true, image: true, properties: true } } : undefined

        const properties = removeEmptyValues(filters?.properties)

        const query: any = filters
            ? {
                createdFrom: filters?.date?.createdFrom,
                createdTo: filters?.date?.createdTo,
                updatedFrom: filters?.date?.updatedFrom,
                updatedTo: filters?.date?.updatedTo,
                full_text,
                name: filters?.property?.name,
                status: filters?.status,
                types: filters?.type ? [filters.type] : documentTypes.map((type) => type.id),
                vector,
                match: {
                    created_by: filters?.user,
                    ...properties
                }
            }
            : {}

        search.query = query
        search.search()
        setHasSearched(true)
    }

    const loadMoreDocuments = () => {
        setLoadingMore(true)

        search
            .loadMore()
            .then(() => {
                setLoadingMore(false)
            })
            .catch(() => {
                setLoadingMore(false)
            })
    }

    const handleOnClearFilters = () => {
        setClearFilters(clearFilters + 1)
    }

    const handleMultipleSelection = useCallback((documents: ContentObjectItem[]) => {
        setSelectionDocuments(documents)
    }, [])

    const handleToggleSelection = useCallback((doc: ContentObjectItem) => {
        setSelectionDocuments(prev => {
            const exists = prev.some(d => d.id === doc.id)
            if (exists) {
                return prev.filter(d => d.id !== doc.id)
            }
            // For single selection mode, replace the selection
            if (selectionMode === "single") {
                return [doc]
            }
            return [...prev, doc]
        })
    }, [selectionMode])

    const confirmMultipleSelection = useCallback(() => {
        onMultipleSelection(selectionDocuments)
    }, [onMultipleSelection, selectionDocuments])

    useEffect(() => {
        if (!error) {
            return
        }

        toast({
            status: "error",
            title: "Error while searching documents",
            description: error.message,
            duration: 5000,
        })
    }, [error])

    useEffect(() => {
        if (facets?.total) {
            delete facets.total
        }
        setTypes(transformFacetTypeResponses(facets.type, typeRegistry))
        setStatuses(transformFacetStatusResponses(facets.status))
        setUsers(transformFacetUserResponses((facets as any).created_by))
        setProperties(transformPropertiesFacetsWithFilter(facets, facetConfig))
    }, [facets])

    useEffect(() => {
        searchObjects()
    }, [])

    return (
        <div className="flex h-full w-full">
            <FiltersPanel
                properties={properties}
                statuses={statuses}
                types={types}
                users={users}
                onFiltersChange={setFilters}
                onSearch={() => searchObjects()}
                onClearFilters={clearFilters}
            />
            <div className='w-full h-full flex flex-col gap-2'>
                <div className='w-full flex flex-row gap-2 items-center justify-between p-2 pb-0'>
                    <div className='flex h-10 gap-2 items-center'>
                        <ViewToggle viewMode={viewMode} onViewModeChange={setViewMode} />
                    </div>
                    <div className='flex h-10 gap-2 items-center'>
                        {selectionDocuments.length !== 0 && (
                            <>
                                <span className='text-sm text-muted-foreground'>
                                    {selectionDocuments.length} document{selectionDocuments.length > 1 ? "s" : ""} selected
                                </span>
                                <Button variant='ghost' className='text-muted-foreground' onClick={() => setSelectionDocuments([])}>
                                    <X />
                                </Button>
                                <Button onClick={confirmMultipleSelection}>
                                    <FileCheck />
                                    Confirm Selection
                                </Button>
                            </>
                        )}
                        {filters && (Object.keys(filters?.properties ?? {}).length > 0 || Object.keys(filters?.matches ?? {}).length > 0) && (
                            <Button onClick={handleOnClearFilters}>
                                <FilterX />
                                Clear Filters
                            </Button>
                        )}
                        {children}
                    </div>
                </div>
                <div className="flex-grow w-full overflow-auto px-2">
                    {viewMode === "list" ? (
                        <DocumentDataTable
                            columns={columns}
                            data={objects}
                            loading={isSearching}
                            loadingMore={loadingMore}
                            hasMore={hasMore}
                            loadMore={loadMoreDocuments}
                            onMultipleSelection={handleMultipleSelection}
                            selection={selectionDocuments}
                            hasSearched={hasSearched}
                            selectionMode={selectionMode}
                        />
                    ) : (
                        <DocumentGrid
                            data={objects}
                            loading={isSearching}
                            loadingMore={loadingMore}
                            hasMore={hasMore}
                            loadMore={loadMoreDocuments}
                            selection={selectionDocuments}
                            onToggleSelection={handleToggleSelection}
                            hasSearched={hasSearched}
                            typeRegistry={typeRegistry}
                        />
                    )}
                </div>
            </div>
        </div>
    )
}

interface DocumentSelectionOverlayProps {
    children?: ReactNode
    onSelection: (documents: ContentObjectItem[]) => void
    columns?: DynamicColumn[]
    facetConfig?: { name: string; field: string }[]
    selectionMode?: SelectionMode
    disabled?: boolean
}

export function DocumentSelectionOverlay({ children, onSelection, columns, facetConfig, selectionMode = "multiple", disabled = false }: Readonly<DocumentSelectionOverlayProps>) {
    const [isOpen, setIsOpen] = useState(false)
    const { registry: typeRegistry } = useTypeRegistry()

    const handleOnMultipleSelection = (documents: ContentObjectItem[]) => {
        onSelection(documents)
        setIsOpen(false)
    }

    return (
        <div className="flex items-center justify-center">
            <div
                onClick={() => !disabled && setIsOpen(true)}
                className={`w-full align-left ${disabled ? "cursor-not-allowed opacity-50 pointer-events-none" : "cursor-pointer"}`}
                aria-disabled={disabled}
            >
                {children}
            </div>
            {isOpen && (
                <div className="z-50 fixed w-full inset-0 bg-overlay flex justify-end top-0">
                    <div className="h-full w-full bg-background shadow-lg p-0 relative animate-in slide-in-from-bottom duration-300">
                        <DocumentSearchProvider facets={facetConfig || DEFAULT_FACETS}>
                            <DocumentSelectionSearchPanel
                                onMultipleSelection={handleOnMultipleSelection}
                                typeRegistry={typeRegistry}
                                columns={columns}
                                facetConfig={facetConfig}
                                selectionMode={selectionMode}
                            >
                                <Button onClick={() => setIsOpen(false)} variant="outline">
                                    <X />
                                </Button>
                            </DocumentSelectionSearchPanel>
                        </DocumentSearchProvider>
                    </div>
                </div>
            )}
        </div>
    )
}
