import { VertesiaClient } from "@vertesia/client"
import { ComputedFacetResponse } from "@vertesia/common"
import { TypeRegistry } from "@vertesia/ui/features"
import { FacetResponse, PropertyFacet } from "@/models/facets"
import { FIELD_TYPES, SearchableProperty } from "@/models/search"

interface PropertyObj {
    [key: string]: any
}

export function transformFacetStatusResponses(facets: FacetResponse[] | number | undefined) {
    if (!Array.isArray(facets) || !facets.length) {
        return []
    }

    const options = facets.map((facet) => {
        const name = facet._id != null ? String(facet._id) : "Unknown"
        return {
            _id: facet._id,
            name,
            count: facet.count,
        }
    })
    options.sort((a, b) => String(a.name).localeCompare(String(b.name)))
    return options
}

export function transformFacetTypeResponses(facets: FacetResponse[] | number | undefined, typeRegistry: TypeRegistry | undefined) {
    if (!Array.isArray(facets) || !facets.length) {
        return []
    }

    if (!typeRegistry) {
        return facets
    }

    const options = facets.map((facet) => {
        const name = typeRegistry.getTypeName(facet._id) || "Document"
        return {
            _id: name !== "Document" ? facet._id : "Document",
            name,
            count: facet.count,
        }
    })

    options.sort((a, b) => a.name.localeCompare(b.name))
    return options
}

export function transformPropertiesFacetsWithFilter(facets: any | undefined, properties: PropertyObj[]) {
    if (!facets || !properties) {
        return []
    }

    const propertyFacets: PropertyFacet[] = properties
        .filter(facet => facet.field.startsWith("properties."))
        .map(facet => ({
            name: facet.name,
            field: facet.field,
            values: facets[facet.field] || [],
            match: facet.match || false
        }))

    return propertyFacets
}

export function transformProjectPropertiesFacetsWithFilter(facets: any | undefined, properties: PropertyObj[]) {
    if (!facets || !properties) {
        return []
    }

    const propertyFacets: PropertyFacet[] = properties
        .map(facet => {
            const values = facets[facet.field] || facets[facet.name] || []
            const countMap = new Map<any, number>()

            values.forEach((value: { _id: any, count: number }) => {
                const id = value._id ?? ""
                if (typeof id === "string" && id.includes(",") && !id.includes(", ")) {
                    const ids = id.split(",").map(s => s.trim())
                    ids.forEach(s => {
                        countMap.set(s, (countMap.get(s) || 0) + value.count)
                    })
                } else {
                    countMap.set(id, (countMap.get(id) || 0) + value.count)
                }
            })

            const aggregatedValues = Array.from(countMap.entries())
                .map(([_id, count]) => ({ _id, count }))
                .sort((a, b) => b.count - a.count)

            return {
                name: facet.name,
                field: facet.field,
                values: aggregatedValues,
                match: facet.match || false
            }
        })

    return propertyFacets
}

export function transformFacetUserResponses(facets: FacetResponse[] | number | undefined) {
    if (!Array.isArray(facets) || !facets.length) {
        return []
    }

    const options = facets
        .filter((facet) => !facet._id?.startsWith("agent:agent:"))
        .map((facet) => {
            const name = facet._id != null ? String(facet._id) : "Unknown"
            return {
                _id: facet._id,
                name,
                count: facet.count,
            }
        })
    options.sort((a, b) => String(a.name).localeCompare(String(b.name)))
    return options
}

export function transformUser(user: string, client: VertesiaClient, callback: (result: string) => void): void {
    if (!user) {
        callback("Unknown User")
        return
    }

    if (user.startsWith("agent:agent:")) {
        const parts = user.substring("agent:agent:".length).split(":")
        const userId = parts[0]
        const agentId = parts[1]
        client.users.retrieve(userId)
            .then(u => {
                callback(`Agent by ${u?.name || "Unknown User"} (${agentId})`)
            })
            .catch(() => {
                callback(`Agent (${agentId})`)
            })
        return
    }

    const colonIndex = user.indexOf(":")
    const type = colonIndex >= 0 ? user.substring(0, colonIndex) : user
    const id = colonIndex >= 0 ? user.substring(colonIndex + 1) : ""

    if (!id) {
        callback("Unknown User")
        return
    }

    if (type === "user") {
        client.users
            .retrieve(id)
            .then((user) => {
                callback(user?.name || "Unknown User")
            })
            .catch(() => {
                callback("Unknown User")
            })
    } else if (type === "system") {
        callback("System")
    } else if (type === "service_account") {
        callback(`Service Account (${id})`)
    } else if (type === "apikey") {
        callback(`API Key (${id})`)
    } else if (type === "agent:agent") {
        callback(`Agent (${id})`)
    } else {
        callback("Unknown User")
    }
}

export function getOptionCount(filter: string, options: ComputedFacetResponse): number {
    const filteredOptions: FacetResponse[] = (options as any)[filter] || []
    return Array.isArray(filteredOptions) ? filteredOptions.length : Object.keys(filteredOptions).length
}

export function mergeAndCombineCounts(arr1: { _id: string, count: number }[] = [], arr2: { _id: string, count: number }[] = []) {
    const countMap = new Map<string, number>()

    arr1.forEach(item => {
        countMap.set(item._id, (countMap.get(item._id) || 0) + item.count);
    })

    arr2.forEach(item => {
        countMap.set(item._id, (countMap.get(item._id) || 0) + item.count);
    })

    return Array.from(countMap.entries())
        .map(([_id, count]) => ({ _id, count }))
        .sort((a, b) => b.count - a.count)
}

export function transformPropertiesFacets(properties: SearchableProperty[] | undefined, facets: any): SearchableProperty[] {
    if (!properties || properties.length === 0) {
        return []
    }

    return properties.map((property) => {
        if (property.type === FIELD_TYPES.LIST) {
            const facetKey = property.property
            const facetData = facets[facetKey]
            if (facetData && Array.isArray(facetData)) {
                return {
                    ...property,
                    values: facetData.map((item: any) => ({
                        _id: item._id,
                        count: item.count || 0
                    }))
                }
            }
        }
        return property
    })
}

export function mergePropertiesFacets(initialProperties: SearchableProperty[] | undefined, currentFacets: any): SearchableProperty[] {
    if (!initialProperties || initialProperties.length === 0) {
        return []
    }

    return initialProperties.map((property) => {
        if (property.type === FIELD_TYPES.LIST && property.values) {
            const facetKey = property.property
            const currentFacetData = currentFacets[facetKey]

            // Create a map of current counts for quick lookup
            const currentCountMap = new Map<string, number>()
            if (currentFacetData && Array.isArray(currentFacetData)) {
                currentFacetData.forEach((item: any) => {
                    currentCountMap.set(String(item._id), item.count || 0)
                })
            }

            // Merge: keep all initial values but update counts from current facets
            return {
                ...property,
                values: property.values.map((value) => ({
                    _id: value._id,
                    count: currentCountMap.get(String(value._id)) ?? 0
                }))
            }
        }
        return property
    })
}