import { useState, useRef, useCallback, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { Minus, Plus, RotateCcw } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"

interface BannerPositionDialogProps {
    open: boolean
    onOpenChange: (open: boolean) => void
    imageUrl: string
    positionX: number
    positionY: number
    zoom: number
    /** Width of the actual banner container (settings/dashboard) for accurate preview */
    dashboardWidth: number
    /** Height of the banner in pixels (defaults to 160) */
    bannerHeight?: number
    onApply: (positionX: number, positionY: number, zoom: number) => void
}

export const BANNER_HEIGHT_PX = 160

/**
 * Given background-size: zoom% and a banner container of known width,
 * compute the visible source rectangle as percentages of the natural image dimensions.
 */
export function computeViewport(
    bannerWidth: number,
    zoom: number,
    posX: number,
    posY: number,
    naturalW: number,
    naturalH: number,
    bannerHeightPx: number = BANNER_HEIGHT_PX,
) {
    // Rendered background image dimensions in the banner container
    const bgW = bannerWidth * zoom / 100
    const bgH = bgW * naturalH / naturalW

    // CSS background-position offset
    const offsetX = (bannerWidth - bgW) * posX / 100
    const offsetY = (bannerHeightPx - bgH) * posY / 100

    // Visible source rectangle in natural image pixel coordinates
    const srcX1 = Math.max(0, -offsetX / bgW * naturalW)
    const srcY1 = Math.max(0, -offsetY / bgH * naturalH)
    const srcX2 = Math.min(naturalW, (bannerWidth - offsetX) / bgW * naturalW)
    const srcY2 = Math.min(naturalH, (bannerHeightPx - offsetY) / bgH * naturalH)

    // Convert to percentages of image dimensions for CSS positioning
    return {
        left: srcX1 / naturalW * 100,
        top: srcY1 / naturalH * 100,
        width: (srcX2 - srcX1) / naturalW * 100,
        height: (srcY2 - srcY1) / naturalH * 100,
    }
}

export function BannerPositionDialog({
    open,
    onOpenChange,
    imageUrl,
    positionX: initialPositionX,
    positionY: initialPositionY,
    zoom: initialZoom,
    dashboardWidth,
    bannerHeight = BANNER_HEIGHT_PX,
    onApply,
}: Readonly<BannerPositionDialogProps>) {
    const { t } = useTranslation("common")
    const [posX, setPosX] = useState(initialPositionX)
    const [posY, setPosY] = useState(initialPositionY)
    const [zoom, setZoomState] = useState(initialZoom)
    const [zoomInput, setZoomInput] = useState(String(initialZoom))
    const setZoom = useCallback((v: number | ((prev: number) => number)) => {
        setZoomState(prev => {
            const next = typeof v === "function" ? v(prev) : v
            setZoomInput(String(next))
            return next
        })
    }, [])
    const [naturalSize, setNaturalSize] = useState({ w: 0, h: 0 })
    const [displaySize, setDisplaySize] = useState({ w: 0, h: 0 })

    const containerRef = useRef<HTMLDivElement>(null)
    const isDraggingRef = useRef(false)
    const dragStartRef = useRef({ x: 0, y: 0 })
    const dragStartPosRef = useRef({ x: 0, y: 0 })

    // Reset to initial values when dialog opens
    useEffect(() => {
        if (open) {
            setPosX(initialPositionX)
            setPosY(initialPositionY)
            setZoomState(initialZoom)
            setZoomInput(String(initialZoom))
        }
    }, [open, initialPositionX, initialPositionY, initialZoom])

    const handleImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
        const img = e.currentTarget
        setNaturalSize({ w: img.naturalWidth, h: img.naturalHeight })
    }

    // Also load natural size via a separate Image object to handle cached images
    // where onLoad on the <img> element may not fire reliably on re-open
    useEffect(() => {
        if (!open) return
        const img = new Image()
        img.onload = () => setNaturalSize({ w: img.naturalWidth, h: img.naturalHeight })
        img.src = imageUrl
    }, [open, imageUrl])

    // Use the dashboard/settings width as the reference for the viewport.
    // This ensures the overlay rectangle and banner preview match the real dashboard.
    const refWidth = dashboardWidth > 0 ? dashboardWidth : (displaySize.w > 0 ? displaySize.w : 800)
    const vp = naturalSize.w > 0
        ? computeViewport(refWidth, zoom, posX, posY, naturalSize.w, naturalSize.h, bannerHeight)
        : { left: 0, top: 0, width: 100, height: 20 }

    // For drag: compute how much posX/posY changes per pixel of drag.
    // The viewport can move within the "excess" space (image minus viewport).
    const excessW = Math.max(0, 100 - vp.width)
    const excessH = Math.max(0, 100 - vp.height)

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        isDraggingRef.current = true
        dragStartRef.current = { x: e.clientX, y: e.clientY }
        dragStartPosRef.current = { x: posX, y: posY }
        ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
    }, [posX, posY])

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (!isDraggingRef.current || !containerRef.current) return
        const rect = containerRef.current.getBoundingClientRect()
        const deltaX = e.clientX - dragStartRef.current.x
        const deltaY = e.clientY - dragStartRef.current.y
        // Convert pixel movement to posX/posY delta.
        // The viewport's movable range in pixels is (excessW/100 * rect.width) for X,
        // and (excessH/100 * rect.height) for Y.
        const movableX = Math.max(1, excessW / 100 * rect.width)
        const movableY = Math.max(1, excessH / 100 * rect.height)
        const deltaPctX = (deltaX / movableX) * 100
        const deltaPctY = (deltaY / movableY) * 100
        setPosX(Math.round(Math.max(0, Math.min(100, dragStartPosRef.current.x + deltaPctX))))
        setPosY(Math.round(Math.max(0, Math.min(100, dragStartPosRef.current.y + deltaPctY))))
    }, [excessW, excessH])

    const handlePointerUp = useCallback(() => {
        isDraggingRef.current = false
    }, [])

    const handleApply = () => {
        onApply(posX, posY, zoom)
        onOpenChange(false)
    }

    const handleReset = () => {
        setPosX(50)
        setPosY(50)
        setZoom(100)
    }

    // Measure displayed image container size
    useEffect(() => {
        if (!open || !containerRef.current) return
        const observer = new ResizeObserver((entries) => {
            const entry = entries[0]
            if (entry) {
                setDisplaySize({ w: entry.contentRect.width, h: entry.contentRect.height })
            }
        })
        observer.observe(containerRef.current)
        return () => observer.disconnect()
    }, [open])

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-5xl max-h-[90vh] flex flex-col">
                <DialogHeader>
                    <DialogTitle>{t("bannerPosition.title")}</DialogTitle>
                    <DialogDescription>
                        {t("bannerPosition.description")}
                    </DialogDescription>
                </DialogHeader>

                {/* Image with viewport overlay */}
                <div className="flex-1 min-h-0 flex items-center justify-center">
                    <div
                        ref={containerRef}
                        className="relative select-none cursor-grab active:cursor-grabbing overflow-hidden rounded-md max-h-full"
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                    >
                        <img
                            src={imageUrl}
                            alt="Banner source"
                            className="block pointer-events-none max-w-full max-h-[60vh] w-auto h-auto"
                            onLoad={handleImageLoad}
                            draggable={false}
                        />
                        {/* Viewport cutout: bright rectangle with dark surround via box-shadow */}
                        <div
                            className="absolute rounded-sm pointer-events-none"
                            style={{
                                top: `${vp.top}%`,
                                left: `${vp.left}%`,
                                width: `${vp.width}%`,
                                height: `${vp.height}%`,
                                boxShadow: "0 0 0 9999px rgba(0,0,0,0.6)",
                                border: "2px dashed rgba(255,255,255,0.9)",
                                outline: "2px solid rgba(59,130,246,0.7)",
                                outlineOffset: "-2px",
                            }}
                        />
                    </div>
                </div>

                {/* Controls */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <span className="text-sm text-muted-foreground">{t("bannerPosition.zoom")}</span>
                        <Button
                            variant="outline"
                            size="icon"
                            type="button"
                            onClick={() => setZoom(z => Math.max(100, z - 10))}
                            disabled={zoom <= 100}
                        >
                            <Minus className="h-4 w-4" />
                        </Button>
                        <div className="relative flex items-center">
                            <input
                                type="text"
                                inputMode="decimal"
                                value={zoomInput}
                                onChange={(e) => setZoomInput(e.target.value)}
                                onBlur={() => {
                                    const v = parseFloat(zoomInput)
                                    if (!isNaN(v)) {
                                        const clamped = Math.max(100, Math.min(500, Math.round(v * 10) / 10))
                                        setZoom(clamped)
                                        setZoomInput(String(clamped))
                                    } else {
                                        setZoomInput(String(zoom))
                                    }
                                }}
                                onKeyDown={(e) => {
                                    if (e.key === "Enter") (e.target as HTMLInputElement).blur()
                                }}
                                className="w-16 text-center text-sm text-muted-foreground bg-transparent border border-input rounded-md h-8 px-1"
                            />
                            <span className="text-sm text-muted-foreground ml-1">%</span>
                        </div>
                        <Button
                            variant="outline"
                            size="icon"
                            type="button"
                            onClick={() => setZoom(z => Math.min(500, z + 10))}
                            disabled={zoom >= 500}
                        >
                            <Plus className="h-4 w-4" />
                        </Button>
                    </div>
                    <Button variant="ghost" type="button" onClick={handleReset}>
                        <RotateCcw className="h-4 w-4 mr-2" />
                        {t("actions.reset")}
                    </Button>
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => onOpenChange(false)}>{t("actions.cancel")}</Button>
                    <Button onClick={handleApply}>{t("actions.apply")}</Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}
