import { useTranslation } from "react-i18next"
import { advancedFacets } from "@/constants/facets"
import { Facet, FacetsEditor } from "@/features/settings/FacetsEditor"

interface FacetsSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: { advancedFacets: Facet[] }) => void
    loading?: boolean
}

export function FacetsSection({ settings, onSave, loading }: Readonly<FacetsSectionProps>) {
    const { t } = useTranslation("settings")
    const initialFacets = Array.isArray(settings?.ADVANCED_FACETS) ? settings.ADVANCED_FACETS : advancedFacets

    return (
        <FacetsEditor
            title={t("facets.title")}
            description={t("facets.description")}
            initialFacets={initialFacets}
            onSave={(facets) => onSave({ advancedFacets: facets })}
            loading={loading}
        />
    )
}
