import { useEffect } from "react"
import { useNavigate } from "@vertesia/ui/router"
import { ApplicationLayout } from "@/components/layouts/ApplicationLayout"
import { AgentsSearchPanel } from "@/features/agents/AgentsSearchPanel"

export function AgentsRedirectPage() {
    const navigate = useNavigate()

    useEffect(() => {
        navigate("/agents/browse", { replace: true })
    }, [navigate])

    return null
}

export function AgentsSearchPage() {
    return (
        <ApplicationLayout>
            <AgentsSearchPanel />
        </ApplicationLayout>
    )
}
