import { ReactNode, useMemo } from "react"
import { FacetSpec } from "@vertesia/common"
import { useUserSession } from "@vertesia/ui/session"
import { DocumentSearch, DocumentSearchContext } from "@/plugins/providers/document/DocumentSearchContext"

interface DocumentSearchProviderProps {
    children: ReactNode
    limit?: number
    facets?: FacetSpec[]
    collectionId?: string
}
export function DocumentSearchProvider({ children, limit, facets, collectionId }: Readonly<DocumentSearchProviderProps>) {
    const { store } = useUserSession()

    const search = useMemo(() => {
        const facetSpecs: FacetSpec[] = facets || []

        const search = new DocumentSearch(store, limit).withFacets(facetSpecs)
        search.collectionId = collectionId
        return search
    }, [collectionId, facets, limit, store])

    return <DocumentSearchContext.Provider value={search}>{children}</DocumentSearchContext.Provider>
}
