import { useTranslation } from "react-i18next"
import { File, Image, X, Check, Eye } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Button } from "@/components/ui/button"
import { ItemCardProps } from "@/features/agents/components/DocumentMediaPanel/types"
import { cn } from "@/lib/utils"

export function ItemCard({
    item,
    type,
    onRemove,
    onSelect,
    isSelected,
    showCheckbox,
    disabled,
}: Readonly<ItemCardProps>) {
    const { t } = useTranslation(["agents", "common"])
    const Icon = type === "media" ? Image : File

    const formatDate = (dateString?: string) => {
        if (!dateString) return null
        const date = new Date(dateString)
        return date.toLocaleDateString()
    }

    // Show preview button only when it's a selected item (has onRemove but not onSelect)
    const showPreview = onRemove && !onSelect && !showCheckbox

    return (
        <div
            className={cn(
                "p-3 flex items-center justify-between gap-2 border rounded-md hover:border-primary",
                onSelect && "cursor-pointer hover:bg-muted/50",
                isSelected && "border-primary bg-primary/5",
                disabled && "opacity-50 cursor-not-allowed"
            )}
            onClick={!disabled && onSelect ? onSelect : undefined}
        >
            <div className="flex items-center gap-3 flex-1 min-w-0">
                {showCheckbox && (
                    <div
                        className={cn(
                            "flex-shrink-0 h-4 w-4 rounded border",
                            isSelected ? "bg-primary border-primary text-primary-foreground" : "border-muted-foreground",
                            "flex items-center justify-center"
                        )}
                    >
                        {isSelected && <Check className="h-3 w-3" />}
                    </div>
                )}
                <Icon className="h-4 w-4 text-primary flex-shrink-0" />
                <div className="flex flex-col min-w-0">
                    {showPreview ? (
                        <DocumentOverlay documentId={item.id}>
                            <span
                                className="text-sm font-medium truncate text-primary underline hover:text-primary/80 cursor-pointer"
                                title={t("agents:media.clickToView", { name: item.name })}
                            >
                                {item.name}
                            </span>
                        </DocumentOverlay>
                    ) : (
                        <span className="text-sm font-medium truncate" title={item.name}>
                            {item.name}
                        </span>
                    )}
                    <div className="flex items-center gap-2 text-xs text-muted-foreground">
                        {item.type && <span>{item.type}</span>}
                        {item.type && item.createdAt && <span>|</span>}
                        {item.createdAt && <span>{formatDate(item.createdAt)}</span>}
                    </div>
                </div>
            </div>
            <div className="flex items-center gap-1 flex-shrink-0">
                {showPreview && (
                    <DocumentOverlay documentId={item.id}>
                        <Button
                            variant="ghost"
                            size="sm"
                            disabled={disabled}
                            title={t("agents:media.viewDocument")}
                        >
                            <Eye className="h-4 w-4" />
                        </Button>
                    </DocumentOverlay>
                )}
                {onRemove && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={(e) => {
                            e.stopPropagation()
                            onRemove()
                        }}
                        disabled={disabled}
                        title={t("common:actions.remove")}
                    >
                        <X className="h-4 w-4" />
                    </Button>
                )}
            </div>
        </div>
    )
}
