import { useMemo, useState } from "react"
import { useTranslation } from "react-i18next"
import { CornerDownRight, Eye, EyeOff } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { ADMIN_SECTION, APPLICATION_SECTION } from "@/constants/navigations"
import { getHiddenSidebarUrls, listSidebarItems } from "@/lib/sidebar-visibility"
import { cn } from "@/lib/utils"

interface SidebarSectionProps {
    settings: Record<string, unknown> | undefined
    onSave: (values: { hiddenItems: string[] }) => void
    loading?: boolean
}

export function SidebarSection({ settings, onSave, loading }: Readonly<SidebarSectionProps>) {
    const { t } = useTranslation(["settings", "navigation", "common"])

    const entries = useMemo(() => listSidebarItems([APPLICATION_SECTION, ADMIN_SECTION]), [])
    const [hidden, setHidden] = useState<Set<string>>(() => new Set(getHiddenSidebarUrls(settings)))

    const toggle = (url: string, visible: boolean) => {
        setHidden((prev) => {
            const next = new Set(prev)
            if (visible) {
                next.delete(url)
            } else {
                next.add(url)
            }
            return next
        })
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:sidebar.title")}</CardTitle>
                <CardDescription>{t("settings:sidebar.description")}</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-1">
                {entries.map((entry, index) => {
                    const isChild = entry.depth > 0
                    // Separate top-level groups with a divider (not between sub-items).
                    const showSeparator = !isChild && index > 0
                    // A child follows its parent: when the parent is hidden, the
                    // child is forced hidden and its switch is locked off.
                    const parentHidden = entry.parentUrl ? hidden.has(entry.parentUrl) : false
                    const isVisible = entry.locked || (!hidden.has(entry.url) && !parentHidden)
                    const disabled = entry.locked || parentHidden
                    const label = t(entry.titleKey, { ns: "navigation" })
                    return (
                        <div
                            key={entry.url}
                            className={cn(
                                "flex items-center gap-2 rounded-md py-2 pr-2 hover:bg-muted/50",
                                isChild ? "ml-3 border-l border-border/70 pl-1" : "pl-2",
                                showSeparator && "mt-1 border-t border-border/60 pt-3"
                            )}
                        >
                            <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="size-8 shrink-0"
                                disabled={disabled}
                                onClick={() => toggle(entry.url, !isVisible)}
                                aria-pressed={isVisible}
                                aria-label={
                                    isVisible
                                        ? t("settings:sidebar.hideItem", { item: label })
                                        : t("settings:sidebar.showItem", { item: label })
                                }
                                title={isVisible ? t("settings:sidebar.hideItem", { item: label }) : t("settings:sidebar.showItem", { item: label })}
                            >
                                {isVisible ? (
                                    <Eye className="size-4 text-foreground" />
                                ) : (
                                    <EyeOff className="size-4 text-muted-foreground" />
                                )}
                            </Button>
                            {isChild && (
                                <CornerDownRight className="size-4 shrink-0 text-muted-foreground/60" aria-hidden="true" />
                            )}
                            <Label
                                className={cn(
                                    "cursor-pointer font-normal",
                                    !isChild && "font-medium",
                                    !isVisible && "text-muted-foreground line-through"
                                )}
                            >
                                {label}
                            </Label>
                            {entry.locked && (
                                <Badge variant="secondary">{t("settings:sidebar.alwaysVisible")}</Badge>
                            )}
                        </div>
                    )
                })}
                <p className="mt-2 text-sm text-muted-foreground">{t("settings:sidebar.help")}</p>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ hiddenItems: Array.from(hidden) })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
