import { useEffect, useRef, useCallback } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { TypeRegistry } from "@vertesia/ui/features"
import { FileSearch, Loader2 } from "lucide-react"
import { DocumentThumbnail } from "@/components/datatables/DocumentThumbnail"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

interface DocumentGridProps {
    data: ContentObjectItem[]
    loading: boolean
    loadMore?: () => void
    hasMore?: boolean
    loadingMore?: boolean
    selection?: ContentObjectItem[]
    selectedIds?: string[]
    onToggleSelection?: (doc: ContentObjectItem) => void
    hasSearched?: boolean
    noFilterMatch?: boolean
    typeRegistry?: TypeRegistry
}

export function DocumentGrid({
    data,
    loading,
    loadMore,
    hasMore = false,
    loadingMore = false,
    selection = [],
    selectedIds = [],
    onToggleSelection,
    hasSearched = false,
    noFilterMatch = false,
    typeRegistry
}: Readonly<DocumentGridProps>) {
    const { t } = useTranslation("common")
    const gridContainerRef = useRef<HTMLDivElement>(null)

    const selectionIds = new Set(selection.map(item => item.id))

    const handleScroll = useCallback(() => {
        if (!gridContainerRef.current || loading || loadingMore || !hasMore || !loadMore) {
            return
        }

        const { scrollTop, scrollHeight, clientHeight } = gridContainerRef.current
        const diff = scrollHeight - scrollTop - clientHeight

        if (diff < 100) {
            loadMore()
        }
    }, [loading, loadingMore, hasMore, loadMore])

    useEffect(() => {
        const gridContainer = gridContainerRef.current
        if (gridContainer) {
            gridContainer.addEventListener("scroll", handleScroll)
            return () => gridContainer.removeEventListener("scroll", handleScroll)
        }
    }, [handleScroll])

    const showInitialLoading = loading && data.length === 0
    const showNoResults = !loading && hasSearched && data.length === 0 && !noFilterMatch
    const showNoFilterMatch = !loading && noFilterMatch
    const showInitialState = !loading && !hasSearched && data.length === 0 && !noFilterMatch

    return (
        <div ref={gridContainerRef} className="flex flex-col h-full w-full overflow-auto">
            <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 p-1">
                {showInitialLoading && (
                    [...Array(20)].map((_, i) => (
                        <Card key={i} className="overflow-hidden">
                            <Skeleton className="w-full aspect-square" />
                            <CardContent className="p-3">
                                <Skeleton className="h-4 w-full mb-2" />
                                <Skeleton className="h-3 w-24" />
                            </CardContent>
                        </Card>
                    ))
                )}

                {showNoResults && (
                    <div className="col-span-full">
                        <Card>
                            <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                                <FileSearch className="h-16 w-16 text-muted-foreground" />
                                <div className="text-center">
                                    <p className="text-lg font-medium">No documents found</p>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        Try adjusting your filters or search terms
                                    </p>
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                )}

                {showNoFilterMatch && (
                    <div className="col-span-full">
                        <Card>
                            <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                                <FileSearch className="h-16 w-16 text-muted-foreground" />
                                <div className="text-center">
                                    <p className="text-lg font-medium">No documents match</p>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        No documents match the current filtering logic
                                    </p>
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                )}

                {showInitialState && (
                    <div className="col-span-full">
                        <Card>
                            <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                                <FileSearch className="h-16 w-16 text-muted-foreground" />
                                <div className="text-center">
                                    <p className="text-lg font-medium">{t("filters.selectFiltersToSearch")}</p>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        {t("filters.selectAtLeastOneFilter")}
                                    </p>
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                )}

                {!showInitialLoading && data.map((doc) => (
                    <DocumentThumbnail
                        key={doc.id}
                        document={doc}
                        typeRegistry={typeRegistry}
                        selected={selectionIds.has(doc.id)}
                        alreadySelected={selectedIds.includes(doc.id)}
                        onToggleSelection={() => onToggleSelection?.(doc)}
                        selectionEnabled={!!onToggleSelection}
                    />
                ))}
            </div>

            {(loadingMore || (loading && data.length > 0)) && (
                <div className="w-full flex justify-center items-center p-4">
                    <Loader2 className="h-6 w-6 animate-spin text-primary" />
                </div>
            )}

            {hasMore && loadMore && !loadingMore && data.length > 0 && (
                <div className="h-4" />
            )}

            <div className="flex items-center justify-end space-x-2 pt-2 pb-1 text-sm text-muted-foreground">
                {showInitialLoading
                    ? "Loading documents..."
                    : loadingMore
                        ? "Loading more..."
                        : (data.length === 0 && !hasSearched)
                            ? "Select filters to search..."
                            : data.length === 0
                                ? "No results."
                                : <>
                                    {data.length} document{data.length <= 1 ? "" : "s"}.
                                    {!hasMore ? " (All results loaded)" : ""}
                                </>
                }
            </div>
        </div>
    )
}
