import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

interface RenditionSectionProps {
    settings: Record<string, any>
    onSave: (values: { thumbnailSize: number; modalPreviewSize: number }) => void
    loading?: boolean
}
export function RenditionSection({ settings, onSave, loading }: Readonly<RenditionSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [thumbnailSize, setThumbnailSize] = useState<number>(settings?.RENDITION_THUMBNAIL_SIZE ?? 512)
    const [modalPreviewSize, setModalPreviewSize] = useState<number>(settings?.RENDITION_MODAL_PREVIEW_SIZE ?? 1024)

    const handleChange = (setter: (v: number) => void, value: string) => {
        const parsed = value === "" ? 0 : parseInt(value, 10)
        if (!isNaN(parsed) && parsed >= 0) {
            setter(parsed)
        }
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:rendition.title")}</CardTitle>
                <CardDescription>
                    {t("settings:rendition.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="grid grid-cols-2 gap-6">
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="rendition-thumbnail">{t("settings:rendition.thumbnailGrid")}</Label>
                        <Input
                            id="rendition-thumbnail"
                            type="number"
                            min={64}
                            max={2048}
                            value={thumbnailSize}
                            onChange={(e) => handleChange(setThumbnailSize, e.target.value)}
                        />
                        <p className="text-xs text-muted-foreground">{t("settings:rendition.thumbnailDefault")}</p>
                    </div>
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="rendition-modal">{t("settings:rendition.modalPreview")}</Label>
                        <Input
                            id="rendition-modal"
                            type="number"
                            min={64}
                            max={2048}
                            value={modalPreviewSize}
                            onChange={(e) => handleChange(setModalPreviewSize, e.target.value)}
                        />
                        <p className="text-xs text-muted-foreground">{t("settings:rendition.modalDefault")}</p>
                    </div>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ thumbnailSize, modalPreviewSize })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
