import { useRef, useEffect, useCallback, useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { ChevronLeft, ChevronRight, Clock } from "lucide-react"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { DocumentThumbnailWithModal } from "@/components/widgets/DocumentThumbnailWithModal"
import { useRecentlyViewed } from "@/hooks/use-recently-viewed"
import { cn } from "@/lib/utils"

interface RecentlyViewedSectionProps {
    areaName?: string
}

export function RecentlyViewedSection({ areaName }: RecentlyViewedSectionProps) {
    const { t } = useTranslation("common")
    const { documents, loading } = useRecentlyViewed({ areaName, limit: 10 })
    const scrollContainerRef = useRef<HTMLDivElement>(null)
    const [canScrollLeft, setCanScrollLeft] = useState(false)
    const [canScrollRight, setCanScrollRight] = useState(false)
    const updateScrollState = useCallback(() => {
        const el = scrollContainerRef.current
        if (!el) return
        setCanScrollLeft(el.scrollLeft > 0)
        setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 1)
    }, [])

    useEffect(() => {
        const el = scrollContainerRef.current
        if (!el) return

        updateScrollState()
        el.addEventListener("scroll", updateScrollState, { passive: true })

        const resizeObserver = new ResizeObserver(updateScrollState)
        resizeObserver.observe(el)

        return () => {
            el.removeEventListener("scroll", updateScrollState)
            resizeObserver.disconnect()
        }
    }, [updateScrollState, documents])

    const scroll = (direction: "left" | "right") => {
        scrollContainerRef.current?.scrollBy({
            left: direction === "left" ? -200 : 200,
            behavior: "smooth",
        })
    }

    if (!loading && documents.length === 0) {
        return <RecentlyViewedEmptyState />
    }

    return (
        <div className="grid grid-cols-1 gap-3 min-w-0">
            {/* Header */}
            <h2 className="text-lg font-semibold">{t("recentlyViewed.title")}</h2>

            <Separator />

            {/* Scroll container with arrows */}
            <div className="relative group">
                {canScrollLeft && (
                    <ScrollArrowButton direction="left" onClick={() => scroll("left")} />
                )}

                <div
                    ref={scrollContainerRef}
                    className="flex flex-row gap-4 overflow-x-auto scroll-smooth snap-x snap-mandatory pb-2"
                    style={{ scrollbarWidth: "none" }}
                >
                    {loading && documents.length === 0 ? (
                        Array.from({ length: 5 }).map((_, i) => (
                            <RecentlyViewedSkeleton key={i} />
                        ))
                    ) : (
                        documents.map((doc) => (
                            <RecentlyViewedItem key={doc.id} document={doc} />
                        ))
                    )}
                </div>

                {canScrollRight && (
                    <ScrollArrowButton direction="right" onClick={() => scroll("right")} />
                )}
            </div>

        </div>
    )
}

function RecentlyViewedItem({ document }: { document: ContentObjectItem }) {
    return (
        <div className="flex-shrink-0 w-36 snap-start">
            <DocumentThumbnailWithModal document={document} showHoverInfo />
        </div>
    )
}

function RecentlyViewedSkeleton() {
    return (
        <div className="flex-shrink-0 w-36 snap-start">
            <div className="border rounded-sm overflow-hidden">
                <Skeleton className="w-full aspect-square" />
            </div>
        </div>
    )
}

function RecentlyViewedEmptyState() {
    const { t } = useTranslation("common")
    return (
        <div className="flex flex-col gap-3">
            <h2 className="text-lg font-semibold">{t("recentlyViewed.title")}</h2>
            <Separator />
            <div className="flex flex-col items-center justify-center py-8 gap-2 text-muted-foreground">
                <Clock className="h-8 w-8" />
                <p className="text-sm">{t("recentlyViewed.noDocuments")}</p>
                <p className="text-xs">{t("recentlyViewed.documentsWillAppear")}</p>
            </div>
        </div>
    )
}

function ScrollArrowButton({ direction, onClick }: { direction: "left" | "right"; onClick: () => void }) {
    return (
        <button
            onClick={onClick}
            className={cn(
                "absolute top-1/2 -translate-y-1/2 z-10 bg-background/80 backdrop-blur-sm border rounded-full p-2 shadow-md",
                "opacity-0 group-hover:opacity-100 transition-opacity",
                "hover:bg-background cursor-pointer",
                direction === "left" ? "left-1" : "right-1"
            )}
        >
            {direction === "left"
                ? <ChevronLeft className="h-4 w-4" />
                : <ChevronRight className="h-4 w-4" />
            }
        </button>
    )
}
