import { useTranslation } from "react-i18next"
import type { TFunction } from "i18next"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { FieldDefinition } from "@/features/agents/utils/schemaParser"

interface SchemaFormRendererProps {
    fields: FieldDefinition[]
    formData: Record<string, any>
    errors: Record<string, string>
    onChange: (fieldName: string, value: any) => void
}

export function SchemaFormRenderer({ fields, formData, errors, onChange }: Readonly<SchemaFormRendererProps>) {
    const { t } = useTranslation("common")

    if (fields.length === 0) {
        return (
            <div className="flex items-center justify-center py-12">
                <p className="text-muted-foreground text-lg">{t("form.noParametersRequired")}</p>
            </div>
        )
    }

    return (
        <div className="space-y-4">
            {fields.map((field) => (
                <div key={field.name} className="space-y-2">
                    <Label htmlFor={field.name} className="flex items-center gap-1">
                        {field.label}
                        {field.required && <span className="text-destructive">*</span>}
                    </Label>
                    {field.description && (
                        <p className="text-sm text-muted-foreground">{field.description}</p>
                    )}
                    {renderFieldInput(field, formData[field.name], onChange, t)}
                    {errors[field.name] && (
                        <p className="text-sm text-destructive">{errors[field.name]}</p>
                    )}
                </div>
            ))}
        </div>
    )
}

function renderFieldInput(
    field: FieldDefinition,
    value: any,
    onChange: (fieldName: string, value: any) => void,
    t: TFunction<"common">
) {
    const commonProps = {
        id: field.name,
        value: value ?? field.default ?? "",
    }

    switch (field.type) {
        case "boolean":
            return (
                <div className="flex items-center space-x-2">
                    <Checkbox
                        id={field.name}
                        checked={value ?? field.default ?? false}
                        onCheckedChange={(checked) => onChange(field.name, checked)}
                    />
                    <Label htmlFor={field.name} className="text-sm font-normal cursor-pointer">
                        {field.description || t("form.enable")}
                    </Label>
                </div>
            )

        case "number":
            return (
                <Input
                    {...commonProps}
                    type="number"
                    min={field.validation?.min}
                    max={field.validation?.max}
                    onChange={(e) => onChange(field.name, e.target.value ? Number(e.target.value) : "")}
                    placeholder={t("form.enterField", { field: field.label.toLowerCase() })}
                />
            )

        case "enum":
            return (
                <Select
                    value={value ?? field.default ?? ""}
                    onValueChange={(val) => onChange(field.name, val)}
                >
                    <SelectTrigger id={field.name}>
                        <SelectValue placeholder={t("form.selectField", { field: field.label.toLowerCase() })} />
                    </SelectTrigger>
                    <SelectContent>
                        {field.options?.map((option) => (
                            <SelectItem key={option} value={option}>
                                {option}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            )

        case "string":
        default: {
            const isLongText = field.validation?.maxLength && field.validation.maxLength > 100

            if (isLongText) {
                return (
                    <Textarea
                        {...commonProps}
                        onChange={(e) => onChange(field.name, e.target.value)}
                        placeholder={t("form.enterField", { field: field.label.toLowerCase() })}
                        rows={4}
                        className="resize-none"
                    />
                )
            }

            return (
                <Input
                    {...commonProps}
                    type="text"
                    onChange={(e) => onChange(field.name, e.target.value)}
                    placeholder={t("form.enterField", { field: field.label.toLowerCase() })}
                    maxLength={field.validation?.maxLength}
                />
            )
        }
    }
}
