import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { COLOR_SCHEMES, type ColorSchemeId } from "@/themes"

interface ColorSchemeSectionProps {
    settings: Record<string, any>
    onSave: (values: { defaultColorScheme: string }) => void
    loading?: boolean
}

export function ColorSchemeSection({ settings, onSave, loading }: Readonly<ColorSchemeSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [defaultColorScheme, setDefaultColorScheme] = useState<ColorSchemeId>(
        (settings?.DEFAULT_COLOR_SCHEME as ColorSchemeId) ?? "default"
    )

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:colorScheme.title")}</CardTitle>
                <CardDescription>{t("settings:colorScheme.description")}</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:colorScheme.defaultColorScheme")}</Label>
                    <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
                        {(Object.entries(COLOR_SCHEMES) as [ColorSchemeId, typeof COLOR_SCHEMES[ColorSchemeId]][]).map(([id, scheme]) => (
                            <button
                                key={id}
                                type="button"
                                onClick={() => setDefaultColorScheme(id)}
                                className={`flex items-center gap-2 rounded-md border px-3 py-2 text-sm transition-colors hover:cursor-pointer hover:bg-accent ${defaultColorScheme === id ? "border-primary bg-accent" : ""}`}
                            >
                                <span
                                    className="h-5 w-5 shrink-0 rounded-full border overflow-hidden"
                                    style={{ position: "relative" }}
                                >
                                    <svg viewBox="0 0 20 20" className="h-full w-full">
                                        <defs>
                                            <clipPath id={`light-${id}`}>
                                                <polygon points="0,0 20,0 0,20" />
                                            </clipPath>
                                            <clipPath id={`dark-${id}`}>
                                                <polygon points="20,0 20,20 0,20" />
                                            </clipPath>
                                        </defs>
                                        <rect width="20" height="20" fill={scheme.lightPrimary} clipPath={`url(#light-${id})`} />
                                        <rect width="20" height="20" fill={scheme.darkPrimary} clipPath={`url(#dark-${id})`} />
                                    </svg>
                                </span>
                                {t(`common:${scheme.labelKey}`)}
                            </button>
                        ))}
                    </div>
                    <p className="text-xs text-muted-foreground">
                        {t("settings:colorScheme.defaultColorSchemeHelp")}
                    </p>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button
                    onClick={() => onSave({ defaultColorScheme })}
                    disabled={loading}
                >
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
