import { useState, useEffect, useCallback } from "react"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { useEcmTypesWhitelist } from "@/hooks/use-ecm-types-whitelist"
import { ActivityRecord } from "@/models/dashboard"

export const useRecentActivity = (limit: number = 20) => {
    const { client } = useUserSession()
    const toast = useToast()
    const ecmTypesWhitelist = useEcmTypesWhitelist()
    const [activities, setActivities] = useState<ActivityRecord[]>([])
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<Error | null>(null)

    const fetchActivities = useCallback(async () => {
        if (!client) {
            setLoading(false)
            return
        }

        setLoading(true)
        setError(null)

        try {
            const objects = await client.objects.list({
                limit,
                query: {
                    ...(ecmTypesWhitelist && { types: ecmTypesWhitelist })
                },
                sort: [{ field: "created_at", order: "desc" }],
                select: "id,name,createdAt,creator,type,size,mimeType"
            }) as ContentObjectItem[]

            const activityRecords: ActivityRecord[] = objects.map((obj) => ({
                id: obj.id,
                documentId: obj.id,
                documentName: obj.name || "Untitled",
                action: "upload" as const,
                timestamp: obj.created_at,
                userId: obj.created_by,
                fileType: obj.type?.id,
                fileSize: (obj.content as any)?.size || (obj.metadata as any)?.size,
                userName: undefined,
                userAvatar: undefined
            }))

            // Fetch user information for each activity
            const userIds = [...new Set(activityRecords.map(a => a.userId).filter(Boolean))]
            const userPromises = userIds.map(id =>
                client.users.retrieve(id!).catch(() => null)
            )
            const users = await Promise.allSettled(userPromises)

            const userMap = new Map()
            users.forEach((result, index) => {
                if (result.status === "fulfilled" && result.value) {
                    userMap.set(userIds[index], result.value)
                }
            })

            // Enrich activity records with user data
            const enrichedActivities = activityRecords.map(activity => ({
                ...activity,
                userName: activity.userId ? userMap.get(activity.userId)?.name : undefined,
                userAvatar: activity.userId ? userMap.get(activity.userId)?.picture : undefined
            }))

            setActivities(enrichedActivities)
        } catch (err) {
            const error = err as Error
            setError(error)
            console.error("Failed to fetch recent activity:", error)
            if (toast) {
                toast({
                    status: "error",
                    title: "Failed to load activity",
                    description: "Unable to fetch recent activity. Please try again."
                })
            }
        } finally {
            setLoading(false)
        }
    }, [client, limit, toast, ecmTypesWhitelist])

    useEffect(() => {
        fetchActivities()
    }, [fetchActivities])

    return { activities, loading, error, refetch: fetchActivities }
}
