import { useMemo } from "react"
import { useTranslation } from "react-i18next"
import { UserGroup } from "@vertesia/common"
import { FileText, FolderOpen, FileStack, Users } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"
import { type MemberItem, type CollectionCategory } from "./useCollectionWizard"

interface WizardStepReviewProps {
    name: string
    description: string
    typeId: string
    currentMembers: MemberItem[]
    membersToAdd: MemberItem[]
    isEditMode: boolean
    category?: CollectionCategory
    selectedGroups?: string[]
    availableGroups?: UserGroup[]
}

export function WizardStepReview({
    name,
    description,
    currentMembers,
    membersToAdd,
    isEditMode,
    category,
    selectedGroups = [],
    availableGroups = [],
}: WizardStepReviewProps) {
    const { t } = useTranslation("common")
    const documentCount = currentMembers.filter(m => m.type === "document").length
    const collectionCount = currentMembers.filter(m => m.type === "collection").length
    const newCount = membersToAdd.length

    const resolvedGroupNames = useMemo(() => {
        if (category !== "organization" || selectedGroups.length === 0) return []
        return selectedGroups
            .map(id => availableGroups.find(g => g.id === id)?.name)
            .filter(Boolean) as string[]
    }, [category, selectedGroups, availableGroups])

    return (
        <div className="flex flex-col gap-4">
            {/* Collection Details */}
            <div className="flex flex-col gap-3 p-4 bg-muted/50 rounded-lg">
                <div className="flex items-start gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
                        <FileStack className="h-5 w-5 text-primary" />
                    </div>
                    <div className="flex flex-col gap-1 min-w-0 flex-1">
                        <h3 className="font-semibold text-lg truncate">{name}</h3>
                        {description ? (
                            <p className="text-sm text-muted-foreground line-clamp-2">{description}</p>
                        ) : (
                            <p className="text-sm text-muted-foreground italic">{t("collectionWizard.noDescription")}</p>
                        )}
                    </div>
                </div>
            </div>

            {/* Groups (for organization collections) */}
            {category === "organization" && resolvedGroupNames.length > 0 && (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center gap-2">
                        <Users className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm font-medium">{t("collectionWizard.groupsLabel")}</span>
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                        {resolvedGroupNames.map((groupName) => (
                            <Badge key={groupName} variant="secondary" className="text-xs">
                                {groupName}
                            </Badge>
                        ))}
                    </div>
                </div>
            )}

            {/* Summary Stats */}
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm">
                        {t("collectionWizard.documentCount", { count: documentCount })}
                    </span>
                </div>
                <div className="flex items-center gap-2">
                    <FolderOpen className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm">
                        {t("collectionWizard.subCollectionCount", { count: collectionCount })}
                    </span>
                </div>
                {newCount > 0 && (
                    <Badge variant="secondary" className="text-xs">
                        {t("collectionWizard.newCount", { count: newCount })}
                    </Badge>
                )}
            </div>

            <Separator />

            {/* Members List */}
            <div className="flex flex-col gap-2">
                <h4 className="text-sm font-medium">{t("collectionWizard.members")}</h4>
                {currentMembers.length === 0 ? (
                    <div className="text-center text-sm text-muted-foreground py-6 border rounded-md">
                        {t("collectionWizard.noMembers")}
                    </div>
                ) : (
                    <ScrollArea className="h-[160px] border rounded-md">
                        <div className="p-2 flex flex-col gap-1">
                            {currentMembers.map((member) => (
                                <ReviewMemberItem
                                    key={member.id}
                                    member={member}
                                    isNew={membersToAdd.some(m => m.id === member.id)}
                                />
                            ))}
                        </div>
                    </ScrollArea>
                )}
            </div>

            {/* Action Summary */}
            <div className="p-3 bg-muted/30 rounded-md">
                <p className="text-sm text-muted-foreground">
                    {isEditMode ? (
                        <span dangerouslySetInnerHTML={{ __html: t("collectionWizard.saveChangesDescription") }} />
                    ) : (
                        <span dangerouslySetInnerHTML={{ __html: t("collectionWizard.createCollectionDescription") }} />
                    )}
                </p>
            </div>
        </div>
    )
}

interface ReviewMemberItemProps {
    member: MemberItem
    isNew: boolean
}

function ReviewMemberItem({ member, isNew }: ReviewMemberItemProps) {
    const { t } = useTranslation("common")
    return (
        <div className="flex items-center gap-2 p-2 rounded-md">
            {member.type === "document" ? (
                <FileText className="h-4 w-4 text-muted-foreground flex-shrink-0" />
            ) : (
                <FolderOpen className="h-4 w-4 text-muted-foreground flex-shrink-0" />
            )}
            <span className="text-sm truncate flex-1">{member.name}</span>
            {isNew && (
                <Badge variant="outline" className="text-xs text-primary border-primary/30">
                    {t("collectionWizard.newBadge")}
                </Badge>
            )}
        </div>
    )
}
