import type { JSONValue, JSONObject } from "@llumiverse/core"

export function computeTitleFromName(name: string) {
    name = name.replace(/_/g, " ").replace(/([a-z0-9])&([A-Z])/g, "$1 $2")
    return name[0].toUpperCase() + name.slice(1)
}

export function formatPropertyName(name: string): string {
    if (!name) {
        return ""
    }

    // If the name already contains spaces, return it as-is to preserve formatting
    if (name.includes(" ")) {
        return name
    }

    return name
        .split("_")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(" ")
}

export function flattenObject(obj: JSONObject, prefix = ""): Record<string, string> {
    const result: Record<string, string> = {}

    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
            const newKey = prefix ? `${prefix}.${key}` : key
            const value = obj[key]

            if (typeof value === "object" && value !== null && !Array.isArray(value)) {
                Object.assign(result, flattenObject(value as JSONObject, newKey))
            } else if (Array.isArray(value) || typeof value === "number") {
                result[newKey] = JSON.stringify(value)
            } else {
                result[newKey] = String(value)
            }
        }
    }

    return result
}

export function formatDateValue(value: JSONValue): string {
    if (value == null) return "-"
    if (typeof value === "string" || typeof value === "number") {
        return new Date(value).toLocaleString()
    }
    return String(value)
}

export function getValueByPath(obj: JSONObject, path: string): JSONValue {
    return path.split(".").reduce((acc: JSONValue, part) => {
        if (acc && typeof acc === "object" && !Array.isArray(acc) && part in acc) {
            return (acc as JSONObject)[part]
        }
        return undefined as unknown as JSONValue
    }, obj as JSONValue)
}
