import { FolderPlus, Heart, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

interface SelectionActionBarProps {
    selectedCount: number
    onAddToCollection: () => void
    onAddToFavorites?: () => void
    onClearSelection: () => void
}

export function SelectionActionBar({ selectedCount, onAddToCollection, onAddToFavorites, onClearSelection }: SelectionActionBarProps) {
    if (selectedCount === 0) {
        return null
    }

    return (
        <div
            className={cn(
                "fixed bottom-12 left-1/2 -translate-x-1/2 z-40",
                "flex items-center gap-3 px-5 py-3.5",
                "bg-background/95 backdrop-blur-sm rounded-xl shadow-2xl border-2 border-primary/40",
                "animate-in slide-in-from-bottom-4 fade-in duration-200"
            )}
        >
            <span className="text-sm font-semibold">
                {selectedCount} {selectedCount === 1 ? "document" : "documents"} selected
            </span>

            <div className="h-4 w-px bg-border" />

            <Button
                variant="default"
                size="sm"
                onClick={onAddToCollection}
                className="gap-2"
            >
                <FolderPlus className="h-4 w-4" />
                Add to Collection
            </Button>

            {onAddToFavorites && (
                <Button
                    variant="default"
                    size="sm"
                    onClick={onAddToFavorites}
                    className="gap-2"
                >
                    <Heart className="h-4 w-4" />
                    Add to Favorites
                </Button>
            )}

            <Button
                variant="ghost"
                size="sm"
                onClick={onClearSelection}
                className="gap-1"
            >
                <X className="h-4 w-4" />
                Clear
            </Button>
        </div>
    )
}
