import { useState, useEffect, useRef } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Calendar, File, FileText, FileCode, Image as ImageIcon, Video, Music, Archive, FileSearch, Loader2, User } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"
import { Card } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { useUserCache } from "@/hooks/use-user-cache"
import { formatRelativeDate } from "@/lib/date"
import { retrieveRendition } from "@/lib/rendition"

interface DocumentCardListProps {
    documents: ContentObjectItem[]
    loading?: boolean
    loadingMore?: boolean
    hasMore?: boolean
    loadMore?: () => void
    selectedIds?: Set<string>
    onToggleSelection?: (id: string) => void
    onSelectAll?: () => void
    onClearSelection?: () => void
}

function getFileIcon(doc: ContentObjectItem, className = "h-6 w-6 text-muted-foreground") {
    const mime = doc.content?.type?.toLowerCase() || ""
    const type = doc.type?.id?.toLowerCase() || ""
    if (mime.startsWith("image/") || type === "image") return <ImageIcon className={className} />
    if (mime.startsWith("video/") || type === "video") return <Video className={className} />
    if (mime.startsWith("audio/") || type === "audio") return <Music className={className} />
    if (mime.includes("pdf") || type === "pdf") return <FileText className={className} />
    if (mime.includes("zip") || mime.includes("tar") || mime.includes("rar") || type === "archive") return <Archive className={className} />
    if (mime.includes("code") || mime.includes("javascript") || mime.includes("typescript") || type === "code") return <FileCode className={className} />
    return <File className={className} />
}

function CardThumbnail({ document }: { document: ContentObjectItem }) {
    const { client } = useUserSession()
    const toast = useToast()
    const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
    const [imageError, setImageError] = useState(false)

    const mime = document.content?.type?.toLowerCase() || ""
    const type = document.type?.id?.toLowerCase() || ""
    const canHaveThumbnail = mime.startsWith("image/") || type === "image" ||
        mime.startsWith("video/") || type === "video" ||
        mime.includes("pdf") || type === "pdf"

    useEffect(() => {
        if (client && canHaveThumbnail) {
            retrieveRendition(client, document, setThumbnailUrl, () => {}, toast, 256).catch(() => setImageError(true))
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [document.id, client])

    const showThumbnail = canHaveThumbnail && thumbnailUrl && !imageError

    return (
        <div className="size-20 shrink-0 rounded-md overflow-hidden bg-muted flex items-center justify-center">
            {showThumbnail ? (
                <img
                    src={thumbnailUrl}
                    alt=""
                    className="w-full h-full object-cover"
                    onError={() => setImageError(true)}
                />
            ) : (
                getFileIcon(document)
            )}
        </div>
    )
}

export function DocumentCardList({ documents, loading, loadingMore, hasMore, loadMore, selectedIds, onToggleSelection, onSelectAll, onClearSelection }: DocumentCardListProps) {
    const { t } = useTranslation(["common", "library"])
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const { getUserDisplayName } = useUserCache(client)
    const containerRef = useRef<HTMLDivElement>(null)

    const selectionEnabled = !!onToggleSelection
    const selectedCount = selectedIds?.size ?? 0
    const allSelected = documents.length > 0 && documents.every(doc => selectedIds?.has(doc.id))
    const someSelected = selectedCount > 0 && !allSelected

    const handleHeaderCheckboxChange = () => {
        if (allSelected) {
            onClearSelection?.()
        } else {
            onSelectAll?.()
        }
    }

    // Infinite scroll
    const handleScroll = () => {
        if (!containerRef.current || loading || loadingMore || !hasMore || !loadMore) return
        const { scrollTop, scrollHeight, clientHeight } = containerRef.current
        if (scrollHeight - scrollTop - clientHeight < 100) loadMore()
    }

    useEffect(() => {
        const container = containerRef.current
        if (container) {
            container.addEventListener("scroll", handleScroll)
            return () => container.removeEventListener("scroll", handleScroll)
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [loading, loadingMore, hasMore, loadMore])

    if (loading && documents.length === 0) {
        return (
            <div className="flex flex-col h-full w-full items-center justify-center">
                <Loader2 className="h-6 w-6 animate-spin text-primary" />
            </div>
        )
    }

    if (documents.length === 0) {
        return (
            <Card className="flex flex-col items-center justify-center py-16 gap-4">
                <FileSearch className="h-16 w-16 text-muted-foreground" />
                <div className="text-center">
                    <p className="text-lg font-medium">{t("library:noDocuments.title")}</p>
                    <p className="text-sm text-muted-foreground mt-1">{t("library:noDocuments.description")}</p>
                </div>
            </Card>
        )
    }

    return (
        <div className="flex flex-col h-full w-full">
            {/* Select-all header */}
            {selectionEnabled && (
                <div className="flex items-center gap-3 px-3 py-2 border-b border-border flex-shrink-0">
                    <Checkbox
                        checked={allSelected}
                        onCheckedChange={handleHeaderCheckboxChange}
                        {...(someSelected && { "data-state": "indeterminate" })}
                    />
                    <span className="text-sm text-muted-foreground">
                        {selectedCount > 0
                            ? t("library:selectedCount", { count: selectedCount })
                            : t("common:tables.selectAll")}
                    </span>
                </div>
            )}

            {/* Scrollable card list */}
            <div ref={containerRef} className="flex-1 overflow-y-auto overflow-x-hidden">
                <div className="flex flex-col gap-2 p-1">
                    {documents.map((doc) => {
                        const isSelected = selectedIds?.has(doc.id) ?? false
                        const name = doc?.properties?.title || doc?.name || doc.id
                        const typeName = typeRegistry?.getTypeName(doc.type?.id || "") || doc.type?.name || t("common:document")
                        return (
                            <div key={doc.id} className="flex items-center gap-3">
                                {selectionEnabled && (
                                    <Checkbox
                                        checked={isSelected}
                                        onCheckedChange={() => onToggleSelection?.(doc.id)}
                                        onClick={(e) => e.stopPropagation()}
                                        className="shrink-0"
                                    />
                                )}
                                <DocumentOverlay documentId={doc.id} className="flex-1 min-w-0">
                                    <Card className={`flex flex-row items-center gap-4 p-3 cursor-pointer transition-all hover:shadow-md rounded-sm ${isSelected ? "ring-2 ring-primary" : ""}`}>
                                        <CardThumbnail document={doc} />
                                        <div className="flex flex-col gap-1.5 flex-1 min-w-0">
                                            <p className="text-sm font-medium truncate" title={name}>{name}</p>
                                            <div className="flex flex-row flex-wrap items-center gap-2">
                                                <Badge variant="outline" className="text-xs max-w-full truncate">{typeName}</Badge>
                                                {doc.content?.type && (
                                                    <Badge variant="secondary" className="text-xs">{doc.content.type}</Badge>
                                                )}
                                            </div>
                                            <div className="flex flex-row items-center gap-4 text-xs text-muted-foreground">
                                                {doc.updated_at && (
                                                    <span className="flex items-center gap-1">
                                                        <Calendar className="h-3 w-3" />
                                                        {formatRelativeDate(doc.updated_at)}
                                                    </span>
                                                )}
                                                {doc.created_by && (
                                                    <span className="flex items-center gap-1 truncate min-w-0">
                                                        <User className="h-3 w-3 shrink-0" />
                                                        <span className="truncate">{getUserDisplayName(doc.created_by, undefined)}</span>
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </Card>
                                </DocumentOverlay>
                            </div>
                        )
                    })}
                </div>

                {(loadingMore || loading) && documents.length > 0 && (
                    <div className="w-full flex justify-center items-center p-4">
                        <Loader2 className="h-6 w-6 animate-spin text-primary" />
                    </div>
                )}
                {hasMore && loadMore && !loadingMore && documents.length > 0 && <div className="h-4" />}
            </div>
        </div>
    )
}
