import { useEffect, useRef, useState } from "react"
import { useUserSession } from "@vertesia/ui/session"
import { HtmlDisplay } from "@/components/displays/HtmlDisplay"
import { MarkdownDisplay } from "@/components/displays/MarkdownDisplay"
import { SpreadsheetDisplay } from "@/components/displays/SpreadsheetDisplay"
import { resolveAssetUrl } from "@/lib/assets"
import { isHtmlContent } from "@/lib/file"
import { isAudio, isHtml, isImage, isMarkdown, isMsFile, isOfficeFile, isPdf, isPlainText, isTextMarkdown, isVideo } from "@/lib/mime"

const PLACEHOLDER_LOGO = resolveAssetUrl("/placeholder.svg")

interface DocumentDisplayProps {
    documentId: string
    name: string
    type: string
    url: string
}
export function DocumentDisplay({ documentId, name, type, url }: Readonly<DocumentDisplayProps>) {
    const { store } = useUserSession()

    const [text, setText] = useState("")

    if (isHtml(type)) {
        if (!text.length) {
            store.objects.getObjectText(documentId).then((response) => {
                setText(response.text ?? "")
            })
        }

        return (
            <div className="w-full h-full overflow-auto p-2">
                <HtmlDisplay content={text} name={name} />
            </div>
        )
    }

    if (isVideo(type)) {
        return (
            <div className="flex w-full h-full items-center justify-center">
                <video
                    src={url}
                    controls={true}
                    className="max-w-full max-h-full rounded-sm border bg-muted shadow-md"
                >
                    <track kind="captions" label="Captions" />
                </video>
            </div>
        )
    }

    if (isAudio(type)) {
        return (
            <div className="flex w-full h-full items-center justify-center">
                <audio src={url} controls className="w-full max-w-md" />
            </div>
        )
    }

    if (isImage(type)) {
        const handleError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
            e.currentTarget.onerror = null
            e.currentTarget.src = PLACEHOLDER_LOGO
        }

        return (
            <div className="flex w-full h-full items-center justify-center">
                <img
                    src={url}
                    alt={name}
                    onError={handleError}
                    className="max-w-full max-h-full object-contain"
                />
            </div>
        )
    }

    if (isPdf(type)) {
        return <PdfViewer url={url} name={name} />
    }

    if (isMsFile(type) || isOfficeFile(type)) {
        return <SpreadsheetDisplay uri={url} />
    }

    if (isMarkdown(type) || isTextMarkdown(type) || isPlainText(type)) {
        if (!text.length) {
            store.objects.getObjectText(documentId).then((response) => {
                setText(response.text ?? "")
            })
        }

        return isHtmlContent(text) ? (
            <div className="w-full h-full overflow-auto p-2">
                <HtmlDisplay content={text} name={name} />
            </div>
        ) : (
            <div className="w-full h-full overflow-auto p-2">
                <MarkdownDisplay content={text} />
            </div>
        )
    }

    return <span>Sorry for the inconvenience but {type} is not supported.</span>
}

interface PdfViewerProps {
    url: string
    name: string
}
function PdfViewer({ url, name }: Readonly<PdfViewerProps>) {
    const [blobUrl, setBlobUrl] = useState<string | null>(null)
    const blobUrlRef = useRef<string | null>(null)

    useEffect(() => {
        if (blobUrlRef.current) {
            URL.revokeObjectURL(blobUrlRef.current)
            blobUrlRef.current = null
        }

        fetch(url)
            .then(res => res.blob())
            .then(blob => {
                const objUrl = URL.createObjectURL(blob)
                blobUrlRef.current = objUrl
                setBlobUrl(objUrl)
            })
            .catch(() => {
                // Fallback to direct URL if blob fetch fails
                setBlobUrl(url)
            })

        return () => {
            if (blobUrlRef.current) {
                URL.revokeObjectURL(blobUrlRef.current)
                blobUrlRef.current = null
            }
        }
    }, [url])

    if (!blobUrl) {
        return (
            <div className="flex items-center justify-center h-full text-muted-foreground">
                Loading PDF...
            </div>
        )
    }

    return <iframe src={blobUrl} height="100%" width="100%" title={`PDF viewer for ${name}`} />
}
