import { useState } from "react"
import { useTranslation } from "react-i18next"
import { TypeMultiSelect } from "@/components/inputs/TypeMultiSelect"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"

interface WhitelistSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: { ecmWhitelist: string[]; dashboardWhitelist: string[]; collectionWhitelist: string[] }) => void
    loading?: boolean
}

export function WhitelistSection({ settings, onSave, loading }: Readonly<WhitelistSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const [ecmWhitelist, setEcmWhitelist] = useState<string[]>(
        Array.isArray(settings?.ECM_TYPES_WHITELIST) ? settings.ECM_TYPES_WHITELIST : []
    )
    const [dashboardWhitelist, setDashboardWhitelist] = useState<string[]>(
        Array.isArray(settings?.DASHBOARD_TYPES_WHITELIST) ? settings.DASHBOARD_TYPES_WHITELIST : []
    )
    const [collectionWhitelist, setCollectionWhitelist] = useState<string[]>(
        Array.isArray(settings?.COLLECTION_TYPES_WHITELIST) ? settings.COLLECTION_TYPES_WHITELIST : []
    )

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:whitelist.title")}</CardTitle>
                <CardDescription>
                    {t("settings:whitelist.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:whitelist.dashboardWhitelist")}</Label>
                    <TypeMultiSelect
                        value={dashboardWhitelist}
                        onChange={setDashboardWhitelist}
                        placeholder={t("settings:whitelist.selectTypesPlaceholder")}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:whitelist.dashboardWhitelistHelp")}
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:whitelist.libraryWhitelist")}</Label>
                    <TypeMultiSelect
                        value={ecmWhitelist}
                        onChange={setEcmWhitelist}
                        placeholder={t("settings:whitelist.selectTypesPlaceholder")}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:whitelist.libraryWhitelistHelp")}
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:whitelist.collectionWhitelist")}</Label>
                    <TypeMultiSelect
                        value={collectionWhitelist}
                        onChange={setCollectionWhitelist}
                        placeholder={t("settings:whitelist.selectTypesPlaceholder")}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:whitelist.collectionWhitelistHelp")}
                    </p>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ ecmWhitelist, dashboardWhitelist, collectionWhitelist })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
