import { useTranslation } from "react-i18next"
import { X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { ItemCard } from "@/features/agents/components/DocumentMediaPanel/components/ItemCard"
import { SelectedItemsDisplayProps } from "@/features/agents/components/DocumentMediaPanel/types"

export function SelectedItemsDisplay({
    items,
    mode,
    type,
    onRemove,
    onClear,
    disabled,
}: Readonly<SelectedItemsDisplayProps>) {
    const { t } = useTranslation(["agents", "common"])

    if (items.length === 0) {
        return null
    }

    const itemLabel = type === "media" ? t("agents:media.media") : t("agents:media.document")
    const itemLabelPlural = type === "media" ? t("agents:media.mediaFiles") : t("agents:media.documents")

    return (
        <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <h4 className="text-sm font-medium">{t("agents:media.selected")}</h4>
                    {mode === "multiple" && (
                        <Badge variant="secondary">
                            {items.length} {items.length === 1 ? itemLabel : itemLabelPlural}
                        </Badge>
                    )}
                </div>
                {mode === "multiple" && onClear && items.length > 0 && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={onClear}
                        disabled={disabled}
                        className="text-muted-foreground"
                    >
                        <X className="h-4 w-4 mr-1" />
                        {t("common:actions.clearAll")}
                    </Button>
                )}
            </div>
            <div className="flex flex-col gap-2 max-h-48 overflow-y-auto">
                {items.map((item, index) => (
                    <ItemCard
                        key={item.id || `item-${index}`}
                        item={item}
                        type={type}
                        onRemove={() => onRemove(item.id)}
                        disabled={disabled}
                    />
                ))}
            </div>
        </div>
    )
}
