import { useCallback, useEffect, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { CollectionItem, ContentObjectItem, CreateCollectionPayload, UserGroup } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Check, Loader2, Search, X } from "lucide-react"
import { TypeSelect } from "@/components/inputs/TypeSelect"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { useCollectionTypesWhitelist } from "@/hooks/use-collection-types-whitelist"

interface AddToCollectionModalProps {
    documents: ContentObjectItem[]
    open: boolean
    onActionDone?: () => void
    onOpenChange: (open: boolean) => void
}

export function AddToCollectionModal({ documents, open, onActionDone, onOpenChange }: Readonly<AddToCollectionModalProps>) {
    const { t } = useTranslation(["collections", "common"])
    const toast = useToast()
    const { client, user } = useUserSession()
    const collectionTypesWhitelist = useCollectionTypesWhitelist()

    // Tab state
    const [activeTab, setActiveTab] = useState<"select" | "create">("select")

    const PAGE_SIZE = 50

    // Select collections state
    const [collections, setCollections] = useState<CollectionItem[]>([])
    const [selectedCollectionIds, setSelectedCollectionIds] = useState<Set<string>>(new Set())
    const [searchValue, setSearchValue] = useState("")
    const [debouncedSearchValue, setDebouncedSearchValue] = useState("")
    const [isSearching, setIsSearching] = useState(false)
    const [isLoadingMore, setIsLoadingMore] = useState(false)
    const [hasMore, setHasMore] = useState(false)

    // Create collection state
    const [newCollectionName, setNewCollectionName] = useState("")
    const [newCollectionDescription, setNewCollectionDescription] = useState("")
    const [newCollectionTypeId, setNewCollectionTypeId] = useState("")

    // Groups state
    const [availableGroups, setAvailableGroups] = useState<UserGroup[]>([])
    const [selectedGroups, setSelectedGroups] = useState<string[]>([])
    const [isLoadingGroups, setIsLoadingGroups] = useState(false)

    // Loading state
    const [isLoading, setIsLoading] = useState(false)

    // Scroll ref for infinite scroll
    const collectionsListRef = useRef<HTMLDivElement>(null)

    const documentIds = documents.map(doc => doc.id)
    const documentCount = documents.length
    const documentLabel = documentCount === 1 ? "document" : "documents"

    // Load available groups
    useEffect(() => {
        if (!client || !open) return

        setIsLoadingGroups(true)
        client.iam.groups.list()
            .then((groups) => {
                setAvailableGroups(groups)
            })
            .catch(() => {
                setAvailableGroups([])
            })
            .finally(() => {
                setIsLoadingGroups(false)
            })
    }, [client, open])

    // Debounce search value
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearchValue(searchValue)
        }, 300)
        return () => clearTimeout(timer)
    }, [searchValue])

    // Search collections
    const searchCollections = async (name?: string) => {
        if (!client) return

        setIsSearching(true)
        const searchParams: Record<string, unknown> = { dynamic: false, limit: PAGE_SIZE }
        if (name && name.trim()) {
            searchParams.name = name.trim()
        }

        client.store.collections.search(searchParams)
            .then((response) => {
                setCollections(response)
                setHasMore(response.length >= PAGE_SIZE)
            })
            .finally(() => {
                setIsSearching(false)
            })
    }

    const loadMoreCollections = useCallback(async () => {
        if (!client || isLoadingMore || !hasMore) return

        setIsLoadingMore(true)
        const searchParams: Record<string, unknown> = {
            dynamic: false,
            limit: PAGE_SIZE,
            offset: collections.length,
        }
        if (debouncedSearchValue && debouncedSearchValue.trim()) {
            searchParams.name = debouncedSearchValue.trim()
        }

        client.store.collections.search(searchParams)
            .then((response) => {
                setCollections(prev => [...prev, ...response])
                setHasMore(response.length >= PAGE_SIZE)
            })
            .finally(() => {
                setIsLoadingMore(false)
            })
    }, [client, isLoadingMore, hasMore, collections.length, debouncedSearchValue])

    const handleCollectionsScroll = useCallback(() => {
        const el = collectionsListRef.current
        if (!el || !hasMore || isLoadingMore) return

        const { scrollTop, scrollHeight, clientHeight } = el
        if (scrollTop + clientHeight >= scrollHeight - 20) {
            loadMoreCollections()
        }
    }, [hasMore, isLoadingMore, loadMoreCollections])

    // Initial load
    useEffect(() => {
        if (!client || !open) return
        searchCollections()
    }, [client, open])

    // Search when debounced value changes
    useEffect(() => {
        if (!client || !open) return
        searchCollections(debouncedSearchValue)
    }, [debouncedSearchValue])

    const handleClose = () => {
        onOpenChange(false)
        // Reset state
        setActiveTab("select")
        setSelectedCollectionIds(new Set())
        setSearchValue("")
        setNewCollectionName("")
        setNewCollectionDescription("")
        setNewCollectionTypeId("")
        setSelectedGroups([])
        setHasMore(false)
    }

    const handleSuccess = () => {
        handleClose()
        onActionDone?.()
    }

    const toggleCollectionSelection = (collectionId: string) => {
        setSelectedCollectionIds(prev => {
            const next = new Set(prev)
            if (next.has(collectionId)) {
                next.delete(collectionId)
            } else {
                next.add(collectionId)
            }
            return next
        })
    }

    const handleAddToExistingCollections = async () => {
        if (!client || selectedCollectionIds.size === 0) return

        setIsLoading(true)
        const collectionIdsArray = Array.from(selectedCollectionIds)

        try {
            // Add documents to all selected collections
            await Promise.all(
                collectionIdsArray.map(collectionId =>
                    client.store.collections.addMembers(collectionId, documentIds)
                )
            )

            const collectionLabel = collectionIdsArray.length === 1 ? "collection" : "collections"
            toast({
                status: "success",
                title: t("collections:addToCollection.documentsAdded", { count: documentCount, label: documentLabel }),
                description: t("collections:addToCollection.successAdded", { count: collectionIdsArray.length, label: collectionLabel }),
                duration: 2000,
            })
            handleSuccess()
        } catch (error: any) {
            toast({
                status: "error",
                title: t("collections:addToCollection.errorAdding"),
                description: error.message,
                duration: 2000,
            })
        } finally {
            setIsLoading(false)
        }
    }

    const handleCreateAndAdd = async () => {
        if (!client || !newCollectionName.trim()) return

        setIsLoading(true)

        try {
            const properties: Record<string, unknown> = {}
            if (newCollectionDescription.trim()) {
                properties.description = newCollectionDescription.trim()
            }

            const collectionData: CreateCollectionPayload = {
                name: newCollectionName.trim(),
                dynamic: false,
                ...(newCollectionTypeId && { type: newCollectionTypeId }),
                ...(Object.keys(properties).length > 0 && { properties }),
            }

            const collection = await client.store.collections.create(collectionData)

            // Set security permissions after creation (same as Organization collections)
            const principals: string[] = []
            if (user?.sub) {
                principals.push(`user:${user.sub}`)
            }
            if (selectedGroups.length > 0) {
                principals.push(...selectedGroups.map(groupId => `group:${groupId}`))
            }
            if (principals.length > 0) {
                const permissions: Record<string, string[]> = {
                    "content:read": principals,
                    "content:write": principals,
                    "content:delete": principals,
                }
                await client.store.collections.updatePermissions(collection.id, permissions)
            }

            await client.store.collections.addMembers(collection.id, documentIds)

            toast({
                status: "success",
                title: t("collections:addToCollection.documentsAdded", { count: documentCount, label: documentLabel }),
                description: t("collections:addToCollection.successCreatedAndAdded", { name: collection.name }),
                duration: 2000,
            })
            handleSuccess()
        } catch (error: any) {
            toast({
                status: "error",
                title: t("collections:addToCollection.errorCreating"),
                description: error.message,
                duration: 2000,
            })
        } finally {
            setIsLoading(false)
        }
    }

    const handleAction = () => {
        if (activeTab === "select") {
            handleAddToExistingCollections()
        } else {
            handleCreateAndAdd()
        }
    }

    const isActionDisabled = isLoading ||
        (activeTab === "select" && selectedCollectionIds.size === 0) ||
        (activeTab === "create" && !newCollectionName.trim())

    const getActionLabel = () => {
        if (isLoading) return t("collections:addToCollection.adding")
        if (activeTab === "create") {
            return t("collections:addToCollection.createAndAdd")
        }
        const count = selectedCollectionIds.size
        if (count <= 1) return t("collections:addToCollection.addToCollectionBtn")
        return t("collections:addToCollection.addToCollectionsBtn", { count })
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-xl bg-background">
                <DialogHeader>
                    <DialogTitle>
                        {documentCount === 1 ? t("collections:addToCollection.title") : t("collections:addToCollection.titleWithCount", { count: documentCount })}
                    </DialogTitle>
                </DialogHeader>

                <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "select" | "create")}>
                    <TabsList className="grid w-full grid-cols-2">
                        <TabsTrigger value="select">{t("collections:addToCollection.selectExisting")}</TabsTrigger>
                        <TabsTrigger value="create">{t("collections:addToCollection.createNew")}</TabsTrigger>
                    </TabsList>

                    <TabsContent value="select" className="mt-4">
                        <div className="flex flex-col gap-3">
                            {/* Search input */}
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                                <Input
                                    placeholder={t("collections:addToCollection.searchPlaceholder")}
                                    value={searchValue}
                                    onChange={(e) => setSearchValue(e.target.value)}
                                    className={searchValue ? "pl-9 pr-9" : "pl-9"}
                                />
                                {searchValue && (
                                    <button
                                        type="button"
                                        onClick={() => setSearchValue("")}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground hover:text-foreground transition-colors"
                                    >
                                        <X className="h-4 w-4" />
                                    </button>
                                )}
                            </div>

                            {/* Collections list */}
                            <div
                                ref={collectionsListRef}
                                onScroll={handleCollectionsScroll}
                                className="border border-border rounded-md max-h-[280px] overflow-y-auto bg-background"
                            >
                                {isSearching ? (
                                    <div className="flex items-center justify-center p-8">
                                        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                                    </div>
                                ) : collections.length > 0 ? (
                                    <div>
                                        <div className="divide-y divide-border">
                                            {collections.map((collection) => {
                                                const isSelected = selectedCollectionIds.has(collection.id)
                                                return (
                                                    <label
                                                        key={collection.id}
                                                        className={`flex items-center gap-3 p-3 cursor-pointer transition-colors ${
                                                            isSelected
                                                                ? "bg-primary/10 hover:bg-primary/15"
                                                                : "hover:bg-muted/50"
                                                        }`}
                                                    >
                                                        <Checkbox
                                                            checked={isSelected}
                                                            onCheckedChange={() => toggleCollectionSelection(collection.id)}
                                                        />
                                                        <span className="flex-1 truncate text-sm text-foreground" title={collection.name}>
                                                            {collection.name}
                                                        </span>
                                                        {isSelected && (
                                                            <Check className="h-4 w-4 text-primary flex-shrink-0" />
                                                        )}
                                                    </label>
                                                )
                                            })}
                                        </div>
                                        {isLoadingMore && (
                                            <div className="flex justify-center py-2">
                                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    <div className="flex flex-col items-center justify-center p-8 text-center">
                                        <p className="text-sm text-muted-foreground">{t("collections:addToCollection.noCollectionsFound")}</p>
                                        <Button
                                            variant="link"
                                            size="sm"
                                            onClick={() => setActiveTab("create")}
                                            className="mt-2"
                                        >
                                            {t("collections:addToCollection.createNewCollection")}
                                        </Button>
                                    </div>
                                )}
                            </div>

                            {selectedCollectionIds.size > 0 && (
                                <p className="text-sm text-muted-foreground">
                                    {t("collections:addToCollection.selectedCount", { count: selectedCollectionIds.size })}
                                </p>
                            )}
                        </div>
                    </TabsContent>

                    <TabsContent value="create" className="mt-4">
                        <div className="flex flex-col gap-4">
                            <div className="flex flex-col gap-2">
                                <Label htmlFor="new-collection-name">{t("collections:addToCollection.nameRequired")}</Label>
                                <Input
                                    id="new-collection-name"
                                    placeholder={t("collections:addToCollection.namePlaceholder")}
                                    value={newCollectionName}
                                    onChange={(e) => setNewCollectionName(e.target.value)}
                                    disabled={isLoading}
                                />
                            </div>

                            <div className="flex flex-col gap-2">
                                <Label htmlFor="new-collection-description">{t("collections:addToCollection.descriptionLabel")}</Label>
                                <Textarea
                                    id="new-collection-description"
                                    placeholder={t("collections:addToCollection.descriptionPlaceholder")}
                                    value={newCollectionDescription}
                                    onChange={(e) => setNewCollectionDescription(e.target.value)}
                                    disabled={isLoading}
                                    rows={3}
                                />
                            </div>

                            <div className="flex flex-col gap-2">
                                <Label htmlFor="new-collection-type">{t("collections:addToCollection.typeLabel")}</Label>
                                <TypeSelect
                                    value={newCollectionTypeId}
                                    onChange={setNewCollectionTypeId}
                                    placeholder={t("collections:addToCollection.typePlaceholder")}
                                    disabled={isLoading}
                                    allowedTypes={collectionTypesWhitelist}
                                />
                            </div>

                            <div className="flex flex-col gap-2">
                                <Label>{t("collections:addToCollection.groupsLabel")}</Label>
                                {isLoadingGroups ? (
                                    <div className="flex items-center gap-2 py-2 text-sm text-muted-foreground">
                                        <Loader2 className="h-4 w-4 animate-spin" />
                                        {t("collections:addToCollection.loadingGroups")}
                                    </div>
                                ) : availableGroups.length === 0 ? (
                                    <p className="text-sm text-muted-foreground py-2">{t("collections:addToCollection.noGroupsAvailable")}</p>
                                ) : (
                                    <ScrollArea className="max-h-[120px] border rounded-md">
                                        <div className="p-2 flex flex-col gap-1">
                                            {availableGroups.map((group) => (
                                                <label
                                                    key={group.id}
                                                    className="flex items-center gap-3 p-2 rounded-md hover:bg-muted/50 cursor-pointer"
                                                >
                                                    <Checkbox
                                                        checked={selectedGroups.includes(group.id)}
                                                        onCheckedChange={(checked) => {
                                                            if (checked) {
                                                                setSelectedGroups([...selectedGroups, group.id])
                                                            } else {
                                                                setSelectedGroups(selectedGroups.filter(id => id !== group.id))
                                                            }
                                                        }}
                                                        disabled={isLoading}
                                                    />
                                                    <div className="flex flex-col min-w-0">
                                                        <span className="text-sm font-medium truncate">{group.name}</span>
                                                        {group.description && (
                                                            <span className="text-xs text-muted-foreground truncate">{group.description}</span>
                                                        )}
                                                    </div>
                                                </label>
                                            ))}
                                        </div>
                                    </ScrollArea>
                                )}
                            </div>
                        </div>
                    </TabsContent>
                </Tabs>

                <DialogFooter>
                    <Button variant="outline" onClick={handleClose} disabled={isLoading}>
                        {t("common:actions.cancel")}
                    </Button>
                    <Button onClick={handleAction} disabled={isActionDisabled}>
                        {getActionLabel()}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}
