import { useCallback, useRef, useState } from "react"
import { useTranslation } from "react-i18next"
import { Upload, Loader2 } from "lucide-react"
import { useContentUpload } from "@/features/agents/components/DocumentMediaPanel/hooks/useContentUpload"
import { UploadSectionProps } from "@/features/agents/components/DocumentMediaPanel/types"

export function UploadSection({
    type,
    mode,
    onUploadComplete,
    disabled,
}: Readonly<UploadSectionProps>) {
    const { t } = useTranslation(["agents", "common"])
    const fileInputRef = useRef<HTMLInputElement>(null)
    const [isDragging, setIsDragging] = useState(false)

    const { upload, isUploading, progress } = useContentUpload({
        type,
        onUploadComplete,
    })

    const handleFiles = useCallback(
        async (files: FileList | null) => {
            if (!files || files.length === 0) return

            const fileArray = Array.from(files)
            const filesToUpload = mode === "single" ? [fileArray[0]] : fileArray

            await upload(filesToUpload)
        },
        [mode, upload]
    )

    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault()
        e.stopPropagation()
        setIsDragging(true)
    }, [])

    const handleDragLeave = useCallback((e: React.DragEvent) => {
        e.preventDefault()
        e.stopPropagation()
        setIsDragging(false)
    }, [])

    const handleDrop = useCallback(
        (e: React.DragEvent) => {
            e.preventDefault()
            e.stopPropagation()
            setIsDragging(false)

            if (disabled || isUploading) return
            handleFiles(e.dataTransfer.files)
        },
        [disabled, isUploading, handleFiles]
    )

    const handleClick = () => {
        if (disabled || isUploading) return
        fileInputRef.current?.click()
    }

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        handleFiles(e.target.files)
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const uploadLabel = type === "media" ? t("agents:upload.uploadMedia") : t("agents:upload.uploadDocument")
    const dragLabel =
        type === "media"
            ? t("agents:upload.dragDropMedia")
            : t("agents:upload.dragDropDocuments")

    return (
        <div className="flex flex-col gap-3">
            <h4 className="text-sm font-medium">{t("agents:upload.uploadNew")}</h4>
            <div
                className={`border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
                    isDragging
                        ? "border-primary bg-primary/5"
                        : "border-muted-foreground/25 hover:border-muted-foreground/50"
                } ${disabled || isUploading ? "opacity-50 cursor-not-allowed" : "cursor-pointer"}`}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                onClick={handleClick}
            >
                <input
                    ref={fileInputRef}
                    type="file"
                    multiple={mode === "multiple"}
                    onChange={handleFileChange}
                    className="hidden"
                    disabled={disabled || isUploading}
                />

                {isUploading ? (
                    <>
                        <Loader2 className="h-10 w-10 mx-auto text-primary mb-3 animate-spin" />
                        <p className="text-sm font-medium mb-1">{t("agents:upload.uploading")}</p>
                        <p className="text-xs text-muted-foreground">{t("agents:upload.progressComplete", { progress })}</p>
                    </>
                ) : (
                    <>
                        <Upload className="h-10 w-10 mx-auto text-muted-foreground mb-3" />
                        <p className="text-sm font-medium mb-1">{uploadLabel}</p>
                        <p className="text-xs text-muted-foreground mb-3">{dragLabel}</p>
                    </>
                )}
            </div>
        </div>
    )
}
