import { createContext, useContext, useState, type ReactNode } from "react"

/**
 * In-memory state for the dashboard "Ask AI Assistant" agentic-search panel.
 *
 * The provider lives at the app root (above the router) so the panel persists across
 * client-side navigation. State is intentionally NOT persisted (no localStorage), so a
 * browser refresh clears the conversation — as required by the ticket.
 *
 * The assistant is launched only by the dashboard "Ask AI Assistant" button via
 * `openChatWithQuery(query)`, which opens the panel and auto-starts an agentic run with that
 * query. The persistent element is the collapsed bubble of a running conversation; close
 * (`dismiss`) removes the panel entirely and it can only be re-opened from the button.
 */
interface AgentChatContextValue {
    /** Start (or restart) an agentic search with the given query and open the panel. */
    openChatWithQuery: (query: string) => void
    isOpen: boolean
    isMinimized: boolean
    /** Query waiting to be auto-sent to the agent; consumed by the panel once the run starts. */
    pendingQuery: string | null
    clearPendingQuery: () => void
    minimize: () => void
    expand: () => void
    /** Close: removes the panel entirely (re-open only via the dashboard button). */
    dismiss: () => void
    agentRunId: string | null
    setAgentRunId: (id: string | null) => void
    hasUnreadResponse: boolean
    setHasUnreadResponse: (value: boolean) => void
    isEnlarged: boolean
    toggleEnlarged: () => void
}

const AgentChatContext = createContext<AgentChatContextValue | null>(null)

export function AgentChatProvider({ children }: Readonly<{ children: ReactNode }>) {
    const [isOpen, setIsOpen] = useState(false)
    const [isMinimized, setIsMinimized] = useState(false)
    const [pendingQuery, setPendingQuery] = useState<string | null>(null)
    const [agentRunId, setAgentRunId] = useState<string | null>(null)
    const [hasUnreadResponse, setHasUnreadResponse] = useState(false)
    const [isEnlarged, setIsEnlarged] = useState(false)

    const openChatWithQuery = (query: string) => {
        setPendingQuery(query)
        setAgentRunId(null) // new search → fresh conversation
        setIsOpen(true)
        setIsMinimized(false)
    }

    const clearPendingQuery = () => setPendingQuery(null)

    const minimize = () => setIsMinimized(true)
    const expand = () => {
        setIsMinimized(false)
        setHasUnreadResponse(false)
    }

    const dismiss = () => {
        setIsOpen(false)
        setIsMinimized(false)
        setPendingQuery(null)
        setAgentRunId(null)
        setHasUnreadResponse(false)
        setIsEnlarged(false)
    }

    const toggleEnlarged = () => setIsEnlarged((prev) => !prev)

    return (
        <AgentChatContext.Provider
            value={{
                openChatWithQuery,
                isOpen,
                isMinimized,
                pendingQuery,
                clearPendingQuery,
                minimize,
                expand,
                dismiss,
                agentRunId,
                setAgentRunId,
                hasUnreadResponse,
                setHasUnreadResponse,
                isEnlarged,
                toggleEnlarged,
            }}
        >
            {children}
        </AgentChatContext.Provider>
    )
}

const NOOP = () => { }
const fallback: AgentChatContextValue = {
    openChatWithQuery: NOOP,
    isOpen: false,
    isMinimized: false,
    pendingQuery: null,
    clearPendingQuery: NOOP,
    minimize: NOOP,
    expand: NOOP,
    dismiss: NOOP,
    agentRunId: null,
    setAgentRunId: NOOP,
    hasUnreadResponse: false,
    setHasUnreadResponse: NOOP,
    isEnlarged: false,
    toggleEnlarged: NOOP,
}

export function useAgentChat(): AgentChatContextValue {
    return useContext(AgentChatContext) ?? fallback
}
