import { useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import { FileText, File, Image as ImageIcon, Video, Music, Archive, FileCode, Check, ExternalLink, Heart } from "lucide-react"
import { DocumentOverlay } from "@/components/overlays/DocumentOverlay"
import { Badge } from "@/components/ui/badge"
import { useFavorites } from "@/contexts/FavoritesContext"
import { useUserCache } from "@/hooks/use-user-cache"
import { formatRelativeDate } from "@/lib/date"
import { retrieveRendition } from "@/lib/rendition"
import { cn } from "@/lib/utils"

interface DocumentThumbnailProps {
    document: ContentObjectItem
    showDetails?: boolean
    showHoverInfo?: boolean
    selected?: boolean
    onToggleSelection?: () => void
    selectionEnabled?: boolean
    onSelect?: (documentId: string) => void
    onQuickAction?: () => void
}
export function DocumentThumbnail({ document, showDetails = false, showHoverInfo = false, selected = false, onToggleSelection, selectionEnabled = false, onSelect, onQuickAction }: DocumentThumbnailProps) {
    const { t } = useTranslation("common")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const toast = useToast()
    const appInstallation = useAppInstallation()
    const thumbnailSize = Number(appInstallation?.settings?.RENDITION_THUMBNAIL_SIZE) || 512
    const { getUserDisplayName } = useUserCache(client)
    const { isFavorite, toggleFavorite } = useFavorites()
    const favorite = isFavorite(document.id)
    const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
    const [thumbnailAlt, setThumbnailAlt] = useState<string>("")
    const [imageError, setImageError] = useState(false)

    const name = document?.properties?.title || document?.name || document.id

    useEffect(() => {
        if (client && document) {
            retrieveRendition(
                client,
                document,
                setThumbnailUrl,
                setThumbnailAlt,
                toast,
                thumbnailSize
            ).catch(() => {
                setImageError(true)
            })
        }
    }, [document.id, client, toast])

    const getFileIcon = () => {
        const mime = document.content?.type?.toLowerCase() || ""
        const type = document.type?.id?.toLowerCase() || ""

        if (mime.startsWith("image/") || type === "image") {
            return <ImageIcon className="h-8 w-8" />
        }
        if (mime.startsWith("video/") || type === "video") {
            return <Video className="h-8 w-8" />
        }
        if (mime.startsWith("audio/") || type === "audio") {
            return <Music className="h-8 w-8" />
        }
        if (mime.includes("pdf") || type === "pdf") {
            return <FileText className="h-8 w-8" />
        }
        if (mime.includes("zip") || mime.includes("tar") || mime.includes("rar") || type === "archive") {
            return <Archive className="h-8 w-8" />
        }
        if (mime.includes("code") || mime.includes("javascript") || mime.includes("typescript") || type === "code") {
            return <FileCode className="h-8 w-8" />
        }
        return <File className="h-8 w-8" />
    }

    const hasRendition = () => {
        const mime = document.content?.type?.toLowerCase() || ""
        const type = document.type?.id?.toLowerCase() || ""
        return mime.startsWith("image/") || type === "image" ||
               mime.startsWith("video/") || type === "video" ||
               mime.includes("pdf") || type === "pdf"
    }

    const showThumbnail = hasRendition() && thumbnailUrl && !imageError

    const documentCreatedAt = document.created_at || ""

    const handleCheckboxClick = (e: React.MouseEvent) => {
        e.stopPropagation()
        e.preventDefault()
        onToggleSelection?.()
    }

    const handleQuickActionClick = (e: React.MouseEvent) => {
        e.stopPropagation()
        e.preventDefault()
        onQuickAction?.()
    }

    const handleFavoriteClick = (e: React.MouseEvent) => {
        e.stopPropagation()
        e.preventDefault()
        toggleFavorite(document.id)
    }

    const thumbnailContent = (
        <div className={cn(
            "ecm-tile border-2 overflow-hidden hover:shadow-md transition-all cursor-pointer group rounded-sm",
            selected ? "border-primary" : "border-border"
        )}>
            <div className={cn(
                "relative w-full aspect-square bg-muted flex items-center justify-center overflow-hidden",
                showThumbnail && "bg-transparent"
            )}>
                {showThumbnail ? (
                    <img
                        src={thumbnailUrl}
                        alt={thumbnailAlt || document.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                        onError={() => setImageError(true)}
                    />
                ) : (
                    <div className="text-muted-foreground group-hover:text-foreground transition-colors">
                        {getFileIcon()}
                    </div>
                )}

                {/* Selection Checkbox - Top Left */}
                {selectionEnabled && (
                    <div
                        className={cn(
                            "absolute top-2 left-2 z-10",
                            !selected && "opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                        )}
                        onClick={handleCheckboxClick}
                    >
                        <div className={cn(
                            "w-8 h-8 rounded-full flex items-center justify-center cursor-pointer transition-all border-2",
                            selected
                                ? "bg-primary text-primary-foreground border-primary"
                                : "bg-black/60 text-white hover:bg-black/80 border-white/50 hover:border-white"
                        )}>
                            {selected && <Check className="h-5 w-5" strokeWidth={3} />}
                        </div>
                    </div>
                )}

                {/* Type Badge - Top Center (shown on hover) */}
                <div className="absolute top-2 left-2 right-2 flex justify-end opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                    <Badge className="bg-primary/90 text-secondary backdrop-blur-sm shadow-lg max-w-full truncate">
                        {typeRegistry?.getTypeName(document.type?.id || "") || document.type?.name || t("document")}
                    </Badge>
                </div>

                {/* Quick Action Button - Top Left */}
                {onQuickAction && (
                    <div
                        className={cn(
                            "absolute top-2 left-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-200",
                            selectionEnabled && "left-12"
                        )}
                        onClick={handleQuickActionClick}
                    >
                        <div className="w-8 h-8 rounded-full flex items-center justify-center cursor-pointer transition-all bg-black/60 text-white hover:bg-black/80 border-2 border-white/50 hover:border-white">
                            <ExternalLink className="h-4 w-4" />
                        </div>
                    </div>
                )}

                {/* Favorite Heart - Bottom Right */}
                <button
                    type="button"
                    onClick={handleFavoriteClick}
                    aria-label={favorite ? t("favorites.remove") : t("favorites.add")}
                    className={cn(
                        "absolute bottom-2 right-2 z-10 w-8 h-8 rounded-full flex items-center justify-center transition-all duration-200 shadow-md hover:shadow-lg hover:scale-110 active:scale-95 hover:cursor-pointer bg-card/90 hover:bg-card border border-border",
                        !favorite && "opacity-0 group-hover:opacity-100"
                    )}
                >
                    <Heart className={cn("h-4 w-4 transition-colors", favorite ? "fill-primary text-primary" : "text-muted-foreground hover:text-primary")} />
                </button>

                {showHoverInfo && (
                    /* Name and Date - Bottom with Background Effect */
                    <div className="flex flex-col gap-1 absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 via-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-200 p-3 pt-8">
                        <p className="text-white text-sm font-medium truncate" title={name}>
                            {name}
                        </p>
                        {(document.updated_at || document.created_by) && (
                            <div className="flex flex-row items-center justify-between gap-2 text-white/80 text-xs">
                                {document.updated_at && (
                                    <span className="flex-shrink-0">{formatRelativeDate(document.updated_at)}</span>
                                )}
                                {document.created_by && (
                                    <span className="truncate min-w-0">{getUserDisplayName(document.created_by, undefined)}</span>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
            {showDetails && (
                <div className="p-3 border-t border-border bg-card">
                    <div className="flex flex-col gap-1">
                        <p className="text-sm font-medium truncate" title={name}>
                            {name}
                        </p>
                        {(document.created_at || document.created_by) && (
                            <div className="flex flex-row items-center justify-between gap-2 text-xs text-muted-foreground">
                                {document.created_at && (
                                    <span className="flex-shrink-0">{formatRelativeDate(documentCreatedAt)}</span>
                                )}
                                {document.created_by && (
                                    <span className="truncate min-w-0">{getUserDisplayName(document.created_by, undefined)}</span>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    )

    // When onSelect is provided, use it directly instead of wrapping in DocumentOverlay
    // This allows the parent to manage the overlay state externally
    if (onSelect) {
        return (
            <div onClick={() => onSelect(document.id)} className="w-full">
                {thumbnailContent}
            </div>
        )
    }

    // When selection is enabled and checkbox is clicked, don't open the document overlay
    // The checkbox click handler stops propagation, so DocumentOverlay won't trigger
    return (
        <DocumentOverlay documentId={document.id}>
            {thumbnailContent}
        </DocumentOverlay>
    )
}
