import { useState, useCallback } from "react"
import type { ViewMode } from "@/components/widgets/ViewModeSwitcher"
import { COLLECTIONS_VIEW_MODE } from "@/constants/cookies"

export function useCollectionsViewMode(): [ViewMode, (mode: ViewMode) => void] {
    const [viewMode, setViewMode] = useState<ViewMode>(() => {
        const saved = localStorage.getItem(COLLECTIONS_VIEW_MODE)
        return (saved === "grid" || saved === "table") ? saved : "grid"
    })

    const handleViewModeChange = useCallback((mode: ViewMode) => {
        localStorage.setItem(COLLECTIONS_VIEW_MODE, mode)
        setViewMode(mode)
    }, [])

    return [viewMode, handleViewModeChange]
}
