import { useTranslation } from "react-i18next"
import { LayoutGrid, Table } from "lucide-react"
import { Button } from "@/components/ui/button"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

export type ViewMode = "grid" | "table"

interface ViewModeSwitcherProps {
    value: ViewMode
    onValueChange: (value: ViewMode) => void
}

export function ViewModeSwitcher({ value, onValueChange }: ViewModeSwitcherProps) {
    const { t } = useTranslation("common")
    const toggleView = () => {
        onValueChange(value === "grid" ? "table" : "grid")
    }

    return (
        <>
            {/* Mobile: Single toggle button */}
            <Button
                variant="outline"
                size="icon"
                onClick={toggleView}
                className="h-8 w-8 sm:hidden"
                aria-label={`Switch to ${value === "grid" ? "table" : "grid"} view`}
            >
                {value === "grid" ? <LayoutGrid className="h-4 w-4" /> : <Table className="h-4 w-4" />}
            </Button>

            {/* Desktop: Full toggle group */}
            <ToggleGroup
                type="single"
                value={value}
                onValueChange={(v) => v && onValueChange(v as ViewMode)}
                variant="outline"
                className="hidden sm:flex h-9"
            >
                <ToggleGroupItem value="grid" aria-label={t("tables.gridView")}>
                    <LayoutGrid className="h-4 w-4" />
                </ToggleGroupItem>
                <ToggleGroupItem value="table" aria-label={t("tables.tableView")}>
                    <Table className="h-4 w-4" />
                </ToggleGroupItem>
            </ToggleGroup>
        </>
    )
}
