import { useState } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem } from "@vertesia/common"
import { useAppInstallation } from "@vertesia/ui/shell"
import { Check, Link, Mail, Share2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"

interface ShareDocumentButtonProps {
    object: ContentObjectItem
    variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link"
    text?: string
    className?: string
}
export function ShareDocumentButton({ object, variant, className, text }: Readonly<ShareDocumentButtonProps>) {
    const { t } = useTranslation("common")
    const appInstallation = useAppInstallation()
    const [copied, setCopied] = useState(false)

    const appName = appInstallation?.manifest.name || undefined
    const appPath = appName ? `/apps/${appName}` : ""
    const isAppPath = appPath && location.pathname.startsWith(appPath)
    const basePath = isAppPath ? appPath : ""
    const documentUrl = `${window.location.origin}${basePath}/advanced-search/${object.id}`

    const handleCopyLink = () => {
        if (!object || copied) return

        navigator.clipboard.writeText(documentUrl)
        setCopied(true)
        setTimeout(() => setCopied(false), 1500)
    }

    const handleShareByEmail = () => {
        if (!object) return

        const objectName = object.name || ""
        const truncatedName = objectName.length > 24
            ? objectName.substring(0, 24) + "..."
            : objectName

        const subject = `Sharing document ${truncatedName}`
        const body = `Hello,\n\nYou will find document ${objectName} there: ${documentUrl}\n\nKind regards,`

        window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`
    }

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button
                    variant={variant || "outline"}
                    className={cn("border border-primary/50 bg-popover text-popover-foreground hover:bg-primary/50", className)}
                    onClick={(e) => {
                        e.stopPropagation()
                        e.nativeEvent.stopImmediatePropagation()
                    }}
                >
                    <Share2 />
                    {text && <span className="hidden md:inline">{text}</span>}
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent side="bottom" align="end" className="p-1 flex flex-col gap-1 w-[230px]">
                <DropdownMenuItem
                    onSelect={(e) => {
                        e.preventDefault()
                        handleCopyLink()
                    }}
                >
                    {copied ? (
                        <Check className="text-success" />
                    ) : (
                        <Link />
                    )}
                    <span>{copied ? t("actions.copied") : t("actions.copyLink")}</span>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handleShareByEmail}>
                    <Mail />
                    <span>{t("actions.byEmail")}</span>
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    )
}
