import { useState } from "react"
import { useTranslation } from "react-i18next"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Loader2, Sparkles } from "lucide-react"
import { TypeSelect } from "@/components/inputs/TypeSelect"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"

/** Name of the content type used for users' favorites collections. */
const FAVORITES_TYPE_NAME = "Favorites"

interface FavoritesSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: { favoritesCollectionType: string }) => void
    loading?: boolean
}

export function FavoritesSection({ settings, onSave, loading }: Readonly<FavoritesSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const { client } = useUserSession()
    const toast = useToast()

    const [favoritesCollectionType, setFavoritesCollectionType] = useState<string>(
        typeof settings?.FAVORITES_COLLECTION_TYPE === "string" ? settings.FAVORITES_COLLECTION_TYPE : ""
    )
    const [refreshKey, setRefreshKey] = useState(0)
    const [creating, setCreating] = useState(false)

    // Create the favorites type (or reuse an existing one with the same name) and
    // link it to the FAVORITES_COLLECTION_TYPE setting in a single click.
    const handleCreateAndLink = async () => {
        if (!client || creating) {
            return
        }
        setCreating(true)
        try {
            let typeId: string
            try {
                const existing = await client.store.types.getTypeByName(FAVORITES_TYPE_NAME)
                typeId = existing.id
            } catch {
                const created = await client.store.types.create({
                    name: FAVORITES_TYPE_NAME,
                    description: t("settings:favorites.typeDescription"),
                })
                typeId = created.id
            }

            setFavoritesCollectionType(typeId)
            setRefreshKey((key) => key + 1)
            onSave({ favoritesCollectionType: typeId })
            toast({
                status: "success",
                title: t("settings:favorites.typeLinked"),
                duration: 3000,
            })
        } catch (error: any) {
            toast({
                status: "error",
                title: t("settings:favorites.typeError"),
                description: error?.message,
                duration: 3000,
            })
        } finally {
            setCreating(false)
        }
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:favorites.title")}</CardTitle>
                <CardDescription>{t("settings:favorites.description")}</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                {/* One-click configuration: create the type and link it to the setting. */}
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:favorites.quickSetup")}</Label>
                    <div>
                        <Button onClick={handleCreateAndLink} disabled={creating || loading} className="gap-2">
                            {creating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
                            {t("settings:favorites.createAndLink")}
                        </Button>
                    </div>
                    <p className="text-sm text-muted-foreground">
                        {t("settings:favorites.createAndLinkHelp")}
                    </p>
                </div>

                {/* Advanced: manually link an existing type. */}
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:favorites.collectionType")}</Label>
                    <TypeSelect
                        value={favoritesCollectionType}
                        onChange={setFavoritesCollectionType}
                        placeholder={t("settings:favorites.collectionTypePlaceholder")}
                        refreshKey={refreshKey}
                        allowEmpty
                        emptyLabel={t("settings:favorites.noType")}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:favorites.collectionTypeHelp")}
                    </p>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ favoritesCollectionType })} disabled={loading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>
        </Card>
    )
}
