import { ReactNode, useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import type { JSONArray, JSONObject, JSONValue } from "@llumiverse/core"
import { ContentObjectItem, ContentObjectStatus } from "@vertesia/common"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { useAppInstallation } from "@vertesia/ui/shell"
import clsx from "clsx"
import { GeneratedForm } from "@/components/form/GeneratedForm"
import { NoAvailablePanel } from "@/components/panels/NoAvailablePanel"
import { Button } from "@/components/ui/button"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { useUserCache } from "@/hooks/use-user-cache"
import { computeTitleFromName, formatDateValue, getValueByPath } from "@/lib/properties"
import { PropertyConfig } from "@/models/property"
import { ManagedObject } from "@/plugins/form/ManagedObject"

const DEFAULT_COMMON_PROPERTIES: PropertyConfig[] = [
    { path: "type.id", label: "Type", modifier: "type" },
    { path: "created_at", label: "Created At", modifier: "date" },
    { path: "created_by", label: "Created By", modifier: "user" },
    { path: "updated_at", label: "Updated At", modifier: "date" },
    { path: "updated_by", label: "Updated By", modifier: "user" },
    { path: "tags", label: "Tags" }
]

interface TypeValueDisplayProps {
    value: JSONValue
}
function TypeValueDisplay({ value }: Readonly<TypeValueDisplayProps>) {
    const { registry: typeRegistry } = useTypeRegistry()

    if (value == null) return <span>-</span>

    const typeId = String(value)
    const typeName = typeRegistry?.getTypeName(typeId) || typeId

    return <span>{typeName}</span>
}

interface UserValueDisplayProps {
    value: JSONValue
}
function UserValueDisplay({ value }: Readonly<UserValueDisplayProps>) {
    const { client } = useUserSession()
    const userCache = useUserCache(client!)

    if (value == null) return <span>-</span>

    const userIdentifier = String(value)
    const displayName = userCache.getUserDisplayName(userIdentifier, undefined)

    return <span>{displayName}</span>
}

function getVersionValue(document: ContentObjectItem): string {
    if (document.properties?.version != null) {
        return String(document.properties.version)
    }
    if (document.revision?.label != null) {
        return document.revision.label
    }
    return "initial"
}

interface PropertiesPanelProps {
    value: JSONObject
    document?: ContentObjectItem
    className?: string
    isEditMode?: boolean
    objectSchema?: Record<string, any>
    onSave?: (updatedProperties: JSONObject) => void
    onCancel?: () => void
}
export function PropertiesPanel({ value, document, className, isEditMode = false, objectSchema, onSave, onCancel }: Readonly<PropertiesPanelProps>) {
    const { t } = useTranslation("common")
    const appInstallation = useAppInstallation()
    const [activeView, setActiveView] = useState<"basic" | "advanced">("basic")
    const [managedObject, setManagedObject] = useState<ManagedObject | null>(null)

    useEffect(() => {
        if (isEditMode && objectSchema) {
            const managed = new ManagedObject(objectSchema, { ...value })
            setManagedObject(managed)
        }
    }, [isEditMode, objectSchema, value])

    const documentTypeId = document?.type?.id
    const settingsBasicProperties = documentTypeId
        ? appInstallation?.settings?.BASIC_PROPERTIES?.[documentTypeId]
        : undefined
    const commonProperties: PropertyConfig[] =
        Array.isArray(settingsBasicProperties) && settingsBasicProperties.length > 0
            ? settingsBasicProperties
            : DEFAULT_COMMON_PROPERTIES
    const advancedProperties: PropertyConfig[] | undefined = documentTypeId
        ? appInstallation?.settings?.ADVANCED_PROPERTIES?.[documentTypeId]
        : undefined

    const handleSave = () => {
        if (managedObject) {
            onSave?.(managedObject.value as JSONObject)
        }
    }

    if (isEditMode && managedObject) {
        return (
            <div className={clsx("flex flex-col h-full", className)}>
                <div className="flex-1 overflow-y-auto">
                    <GeneratedForm object={managedObject} />
                </div>
                <div className="flex flex-row justify-end gap-2 pt-4 border-t">
                    <Button onClick={onCancel} variant="outline">
                        Cancel
                    </Button>
                    <Button onClick={handleSave} variant="default">
                        Save
                    </Button>
                </div>
            </div>
        )
    }

    return (
        <div className={clsx("flex flex-col gap-4", className)}>
            <Tabs value={activeView} onValueChange={(v) => setActiveView(v as "basic" | "advanced")} className="w-full">
                <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="basic" className="text-xs sm:text-sm">{t("propertiesPanel.basic")}</TabsTrigger>
                    <TabsTrigger value="advanced" className="text-xs sm:text-sm">{t("propertiesPanel.advanced")}</TabsTrigger>
                </TabsList>

                <TabsContent value="basic" className="mt-4">
                    <BasicPropertiesView
                        document={document}
                        properties={commonProperties}
                    />
                </TabsContent>

                <TabsContent value="advanced" className="mt-4">
                    <div className="flex flex-col gap-4">
                        {document && (
                            <div className="w-full flex flex-col">
                                <PropertyTitle name="Version" />
                                <div className="text-sm">{getVersionValue(document)}</div>
                            </div>
                        )}
                        {advancedProperties ? (
                            <BasicPropertiesView
                                document={document}
                                properties={advancedProperties}
                            />
                        ) : !value || Object.keys(value).length === 0 ? (
                            document?.status === ContentObjectStatus.processing ? (
                                <NoAvailablePanel>{t("propertiesPanel.propertiesGenerating")}</NoAvailablePanel>
                            ) : (
                                <NoAvailablePanel>No Properties available.</NoAvailablePanel>
                            )
                        ) : (
                            Object.entries(value).map(([key, val]) =>
                                <PropertyElement key={key} name={key} value={val} />
                            )
                        )}
                    </div>
                </TabsContent>
            </Tabs>
        </div>
    )
}

interface BasicPropertiesViewProps {
    document?: ContentObjectItem
    properties: PropertyConfig[]
}
function BasicPropertiesView({ document, properties }: Readonly<BasicPropertiesViewProps>) {
    const { t } = useTranslation("common")
    if (!document) {
        return <div className="text-sm text-muted-foreground">{t("form.noDocumentData")}</div>
    }

    return (
        <div className="flex flex-col gap-4">
            {properties.map((prop) => (
                <PropertyField
                    key={prop.path}
                    document={document}
                    config={prop}
                />
            ))}
        </div>
    )
}

interface PropertyFieldProps {
    document: ContentObjectItem
    config: PropertyConfig
}
function PropertyField({ document, config }: Readonly<PropertyFieldProps>) {
    const { t } = useTranslation("common")
    const rawValue = getValueByPath(document as unknown as JSONObject, config.path)
    const label = config.label || config.path.split(".").pop() || config.path
    const isEmpty = rawValue == null || rawValue === "" || (Array.isArray(rawValue) && rawValue.length === 0)

    // Handle empty values
    if (isEmpty) {
        return (
            <div className="w-full flex flex-col">
                <PropertyTitle name={label} />
                <div className="text-sm text-muted-foreground italic">{t("form.noValue")}</div>
            </div>
        )
    }

    // Handle modifier-based rendering (type, user, date)
    if (config.modifier) {
        return (
            <div className="w-full flex flex-col">
                <PropertyTitle name={label} />
                <div className="text-sm">
                    {config.modifier === "type" && <TypeValueDisplay value={rawValue} />}
                    {config.modifier === "user" && <UserValueDisplay value={rawValue} />}
                    {config.modifier === "date" && <span>{formatDateValue(rawValue)}</span>}
                </div>
            </div>
        )
    }

    // Use the same display logic as PropertyElement for non-modifier values
    const info = getValueInfo(rawValue)
    switch (info.type) {
        case ValueType.Inline:
        case ValueType.Paragraph:
            return (
                <div className='w-full flex flex-col'>
                    <PropertyTitle name={label} />
                    <div className="text-sm">{info.value}</div>
                </div>
            )
        case ValueType.Prose:
            return (
                <div className="prose">
                    <PropertyTitle name={label} />
                    <div className='text-sm prose'>{info.value}</div>
                </div>
            )
        case ValueType.Array:
            return (
                <ArrayProperty name={label} value={info.value} />
            )
        case ValueType.Object:
            return (
                <div>
                    <PropertyTitle name={label} />
                    <BlockElement>
                        {Object.entries(info.value).map(([key, value]) => (
                            <PropertyElement key={key} name={key} value={value} />
                        ))}
                    </BlockElement>
                </div>
            )
    }
}

interface PropertyTitleProps {
    name: string
}
function PropertyTitle({ name }: Readonly<PropertyTitleProps>) {
    return (
        <div className='text font-medium font-semibold break-all'>{computeTitleFromName(name)}</div>
    )
}

interface BlockElementProps {
    children: ReactNode | ReactNode[]
    className?: string
}
function BlockElement({ children, className }: Readonly<BlockElementProps>) {
    return (
        <div className={clsx("flex flex-col gap-4 py-0 pl-4 border-l-4 border-l-solid border-border", className)}>
            {children}
        </div>
    )
}

interface PropertyElementProps {
    name: string
    value: JSONValue
}
function PropertyElement({ name, value }: Readonly<PropertyElementProps>) {
    const info = getValueInfo(value)
    switch (info.type) {
        case ValueType.Inline:
            return (
                <div className='w-full flex flex-col'>
                    <PropertyTitle name={name} />
                    <div className="text-sm">{info.value}</div>
                </div>
            )
        case ValueType.Paragraph:
            return (
                <div>
                    <PropertyTitle name={name} />
                    <div className="text-sm">{info.value}</div>
                </div>
            )
        case ValueType.Prose:
            return (
                <div className="prose">
                    <PropertyTitle name={name} />
                    <div className='text-sm prose'>{info.value}</div>
                </div>
            )
        case ValueType.Array:
            return (
                <ArrayProperty name={name} value={value as JSONArray} />
            )
        case ValueType.Object:
            return (
                <div>
                    <PropertyTitle name={name} />
                    <BlockElement>
                        {
                            Object.entries(value as JSONObject).map(([key, value]) => <PropertyElement key={key} name={key} value={value} />)
                        }
                    </BlockElement>
                </div>
            )
    }
}

interface ArrayPropertyProps {
    name?: string,
    value: JSONArray
}
function ArrayProperty({ name, value }: ArrayPropertyProps) {
    const isInline = (typeof value[0] === "string")
    const useBullet = true
    return (
        isInline
            ? (
                <div className='flex flex-col gap-2'>
                    {name && <PropertyTitle name={name} />}
                    <div className="flex flex-wrap gap-2">
                        {
                            value.map((item, index) =>
                                <div onClick={() => navigator.clipboard.writeText(String(item))} key={index} className='w-fit text-sm border border-border rounded-md p-1 gap-1 hover:bg-muted hover:cursor-pointer'>
                                    {String(item)}
                                </div>
                            )
                        }
                    </div>
                </div>
            )
            : (
                <div>
                    {name && <PropertyTitle name={name} />}
                    <div className='flex flex-col gap-2'>
                        {
                            (value).map((value, index) => <ItemProperty key={crypto.randomUUID()} index={index} value={value} useBullet={useBullet} />)
                        }
                    </div>
                </div>
            )
    )
}

interface ItemPropertyProps {
    index: number
    value: JSONValue
    useBullet?: boolean
}
function ItemProperty({ index, value, useBullet }: Readonly<ItemPropertyProps>) {
    const bullet = useBullet ? <span className='text-sm'>•</span> : <span className='text-sm'>{index + 1}.</span>
    const info = getValueInfo(value)
    let content
    switch (info.type) {
        case ValueType.Object:
            content = <BlockElement>
                {
                    Object.entries(value as JSONObject).map(([key, value]) => <PropertyElement key={key} name={key} value={value} />)
                }
            </BlockElement>
            break
        case ValueType.Array:
            content = <ArrayProperty value={value as JSONArray} />
            break
        case ValueType.Prose: content = <div className="text-sm prose">{info.value}</div>
            break
        default: content = <div className="text-sm">{info.value}</div>
            break
    }
    return (
        <div className='flex gap-4 hover:bg-muted/50 py-2 pr-2 pl-4'>
            <div className='font-semibold text-muted-foreground'>{bullet}</div>
            <div className="text-sm muted-foreground"><span className="flex h-full items-center">{content}</span></div>
        </div>
    )
}

enum ValueType {
    Inline,
    Paragraph,
    Prose,
    Array,
    Object
}

type ValueInfo =
    | { type: ValueType.Inline; value: string }
    | { type: ValueType.Paragraph; value: string }
    | { type: ValueType.Prose; value: string }
    | { type: ValueType.Array; value: JSONArray }
    | { type: ValueType.Object; value: JSONObject }

function getValueInfo(value: JSONValue): ValueInfo {
    if (value == null) {
        return {
            value: "-",
            type: ValueType.Inline
        }
    }
    if (Array.isArray(value)) {
        return {
            value,
            type: ValueType.Array
        }
    }
    const valueType = typeof value
    if (valueType === "string") {
        const strValue = value as string
        const len = strValue.length
        if (len < 80) {
            return { type: ValueType.Inline, value: strValue }
        } else if (len > 400) {
            return { type: ValueType.Prose, value: strValue }
        } else {
            return { type: ValueType.Paragraph, value: strValue.replace(/(?:\n\n)+/g, "\n\n") }
        }
    } else if (valueType === "number" || valueType === "boolean") {
        return {
            value: String(value),
            type: ValueType.Inline
        }
    } else {
        return {
            value: value as JSONObject,
            type: ValueType.Object
        }
    }
}