import { useState, useEffect, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { useTypeRegistry } from "@vertesia/ui/features"
import { useUserSession } from "@vertesia/ui/session"
import { Check, ChevronsUpDown, Loader2, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

interface TypeOption {
    id: string
    name: string
}

interface TypeMultiSelectProps {
    value: string[]
    onChange: (value: string[]) => void
    placeholder?: string
    disabled?: boolean
}

export function TypeMultiSelect({
    value,
    onChange,
    placeholder,
    disabled = false,
}: TypeMultiSelectProps) {
    const { t } = useTranslation("common")
    const resolvedPlaceholder = placeholder ?? t("inputs.selectTypes")
    const { client } = useUserSession()
    const { registry: typeRegistry } = useTypeRegistry()
    const [types, setTypes] = useState<TypeOption[]>([])
    const [isLoading, setIsLoading] = useState(true)
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")

    useEffect(() => {
        if (!client) return

        const fetchTypes = async () => {
            setIsLoading(true)
            try {
                const typesList = await client.types.list()
                const typeOptions: TypeOption[] = typesList.map((type: unknown) => {
                    const t = type as { id: string; name?: string }
                    return {
                        id: t.id,
                        name: typeRegistry?.getTypeName(t.id) || t.name || t.id,
                    }
                })
                typeOptions.sort((a, b) => a.name.localeCompare(b.name))
                setTypes(typeOptions)
            } catch (error) {
                console.error("Failed to fetch types:", error)
                setTypes([])
            } finally {
                setIsLoading(false)
            }
        }

        fetchTypes()
    }, [client, typeRegistry])

    const selectedTypes = useMemo(() => {
        return types.filter((type) => value.includes(type.id))
    }, [types, value])

    const handleToggle = (typeId: string) => {
        if (value.includes(typeId)) {
            onChange(value.filter((id) => id !== typeId))
        } else {
            onChange([...value, typeId])
        }
    }

    const handleRemove = (typeId: string) => {
        onChange(value.filter((id) => id !== typeId))
    }

    if (isLoading) {
        return (
            <div className="flex h-9 w-full items-center justify-center rounded-md border border-input bg-popover px-3 py-2">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            </div>
        )
    }

    return (
        <div className="flex flex-col gap-2">
            <Popover open={open} onOpenChange={setOpen}>
                <PopoverTrigger asChild>
                    <Button
                        variant="outline"
                        role="combobox"
                        aria-expanded={open}
                        className="w-full justify-between font-normal bg-popover"
                        disabled={disabled}
                    >
                        <span className="truncate">
                            {selectedTypes.length > 0
                                ? t("inputs.typesSelected", { count: selectedTypes.length })
                                : resolvedPlaceholder}
                        </span>
                        <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="p-0" align="start" style={{ width: "var(--radix-popover-trigger-width)" }}>
                    <Command>
                        <CommandInput
                            placeholder={t("inputs.searchTypes")}
                            value={search}
                            onValueChange={setSearch}
                        />
                        <CommandList>
                            <CommandEmpty>{t("inputs.noTypeFound")}</CommandEmpty>
                            <CommandGroup>
                                {types.map((type) => (
                                    <CommandItem
                                        key={type.id}
                                        value={type.name}
                                        onSelect={() => handleToggle(type.id)}
                                    >
                                        <Check
                                            className={cn(
                                                "mr-2 h-4 w-4",
                                                value.includes(type.id) ? "opacity-100" : "opacity-0"
                                            )}
                                        />
                                        {type.name}
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                        </CommandList>
                    </Command>
                </PopoverContent>
            </Popover>
            {selectedTypes.length > 0 && (
                <div className="flex flex-wrap gap-1">
                    {selectedTypes.map((type) => (
                        <Badge key={type.id} variant="secondary" className="gap-1">
                            {type.name}
                            <button
                                type="button"
                                className="ml-0.5 rounded-sm outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2 hover:bg-secondary-foreground/20"
                                onClick={() => handleRemove(type.id)}
                                disabled={disabled}
                            >
                                <X className="h-3 w-3" />
                            </button>
                        </Badge>
                    ))}
                </div>
            )}
        </div>
    )
}
