import { useState, useEffect, useRef } from "react"
import { useTranslation } from "react-i18next"
import { ContentObjectItem, InteractionRef, InteractionStatus } from "@vertesia/common"
import { useToast } from "@vertesia/ui/core"
import { useUserSession } from "@vertesia/ui/session"
import { Eye, EyeOff, ImagePlus, Loader2, Move, Search, Upload, X } from "lucide-react"
import { BannerPositionDialog } from "@/components/dialogs/BannerPositionDialog"
import { DocumentSelectionOverlay } from "@/components/overlays/DocumentSelectionOverlay"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { resolveAssetUrl } from "@/lib/assets"
import { DASHBOARD_DISPLAY_MODES, DashboardDisplayMode, getDashboardBackgroundSettings, getDashboardDisplayMode } from "@/lib/dashboard-settings"
import { retrieveRenditionById } from "@/lib/rendition"

interface GridColsConfig {
    sm: number
    md: number
    lg: number
    xl: number
}

const DEFAULT_GRID_COLS: GridColsConfig = { sm: 2, md: 3, lg: 4, xl: 6 }
const DEFAULT_ITEMS_PER_PAGE = 12

interface DashboardSectionProps {
    settings: Record<string, any> | undefined
    onSave: (values: {
        title: string
        description: string
        displayMode: DashboardDisplayMode
        backgroundId: string
        backgroundPositionX: number
        backgroundPositionY: number
        backgroundZoom: number
        bannerRenditionSize: number
        bannerMaxHeight: number
        bannerMinHeight: number
        gridCols: GridColsConfig
        itemsPerPage: number
        agenticSearchInteraction: string
    }) => void
    loading?: boolean
}

interface InteractionOption {
    id: string
    name: string
    version: number
}

export function DashboardSection({ settings, onSave, loading }: Readonly<DashboardSectionProps>) {
    const { t } = useTranslation(["settings", "common"])
    const { client } = useUserSession()
    const toast = useToast()

    const [title, setTitle] = useState(settings?.DASHBOARD_TITLE ?? "")
    const [description, setDescription] = useState(settings?.DASHBOARD_DESCRIPTION ?? "")
    const [displayMode, setDisplayMode] = useState<DashboardDisplayMode>(getDashboardDisplayMode(settings))
    const bgSettings = getDashboardBackgroundSettings(settings)
    const [backgroundId, setBackgroundId] = useState<string>(settings?.DASHBOARD_BACKGROUND ?? "")
    const [backgroundUrl, setBackgroundUrl] = useState<string>("")
    const [backgroundPositionX, setBackgroundPositionX] = useState<number>(bgSettings.positionX)
    const [backgroundPositionY, setBackgroundPositionY] = useState<number>(bgSettings.positionY)
    const [backgroundZoom, setBackgroundZoom] = useState<number>(bgSettings.zoom)
    const [bannerRenditionSize, setBannerRenditionSize] = useState<number>(bgSettings.renditionSize)
    const [bannerMaxHeight, setBannerMaxHeight] = useState<number>(bgSettings.bannerMaxHeight)
    const [bannerMinHeight, setBannerMinHeight] = useState<number>(bgSettings.bannerMinHeight)
    const [gridCols, setGridCols] = useState<GridColsConfig>({
        sm: Number(settings?.DASHBOARD_GRID_COLS_SM) || DEFAULT_GRID_COLS.sm,
        md: Number(settings?.DASHBOARD_GRID_COLS_MD) || DEFAULT_GRID_COLS.md,
        lg: Number(settings?.DASHBOARD_GRID_COLS_LG) || DEFAULT_GRID_COLS.lg,
        xl: Number(settings?.DASHBOARD_GRID_COLS_XL) || DEFAULT_GRID_COLS.xl,
    })
    const [itemsPerPage, setItemsPerPage] = useState<number>(
        Number(settings?.DASHBOARD_ITEMS_PER_PAGE) || DEFAULT_ITEMS_PER_PAGE
    )
    const [agenticSearchInteraction, setAgenticSearchInteraction] = useState<string>(settings?.DASHBOARD_AGENTIC_SEARCH_INTERACTION ?? "")
    const [agentInteractions, setAgentInteractions] = useState<InteractionOption[]>([])
    const [interactionsLoading, setInteractionsLoading] = useState(false)
    const showImageGridSettings = displayMode === "imageGrid"
    const [showGridPreview, setShowGridPreview] = useState(false)
    const [positionDialogOpen, setPositionDialogOpen] = useState(false)
    const [previewWidth, setPreviewWidth] = useState(0)
    const [uploading, setUploading] = useState(false)
    const [bgLoading, setBgLoading] = useState(false)
    const fileInputRef = useRef<HTMLInputElement>(null)
    const previewRef = useRef<HTMLDivElement>(null)
    const defaultBackground = resolveAssetUrl("/ecm-background.png")

    useEffect(() => {
        if (client && backgroundId) {
            setBgLoading(true)
            retrieveRenditionById(client, backgroundId, setBackgroundUrl, () => {}, toast, 2048)
        } else {
            setBackgroundUrl("")
            setBgLoading(false)
        }
    }, [client, backgroundId])

    // Clear the loading state once the resolved image has actually been fetched
    useEffect(() => {
        if (!backgroundUrl) return
        const img = new Image()
        img.onload = () => setBgLoading(false)
        img.onerror = () => setBgLoading(false)
        img.src = backgroundUrl
        return () => {
            img.onload = null
            img.onerror = null
        }
    }, [backgroundUrl])

    // Measure settings preview width
    useEffect(() => {
        if (!previewRef.current) return
        const observer = new ResizeObserver((entries) => {
            const entry = entries[0]
            if (entry) setPreviewWidth(entry.contentRect.width)
        })
        observer.observe(previewRef.current)
        return () => observer.disconnect()
    }, [])

    // Load published agent interactions to populate the agentic-search picker.
    useEffect(() => {
        if (!client) return
        let cancelled = false
        setInteractionsLoading(true)
        client.interactions.list({ query: { status: InteractionStatus.published, tags: ["agent"] } })
            .then((result) => {
                if (cancelled) return
                const options: InteractionOption[] = result
                    .filter((interaction: InteractionRef) => !interaction.tags.includes("default"))
                    .map((interaction: InteractionRef) => ({ id: interaction.id, name: interaction.name, version: interaction.version }))
                setAgentInteractions(options)
            })
            .catch((error) => {
                if (!cancelled) {
                    console.error("Failed to fetch agent interactions:", error)
                    setAgentInteractions([])
                }
            })
            .finally(() => {
                if (!cancelled) setInteractionsLoading(false)
            })
        return () => { cancelled = true }
    }, [client])

    const handleImageSelection = (documents: ContentObjectItem[]) => {
        if (documents.length > 0) {
            setBackgroundId(documents[0].id)
        }
    }

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        e.target.value = ""
        if (!file || !client) return

        const MAX_SIZE = 20 * 1024 * 1024 // 20MB
        if (!file.type.startsWith("image/") || file.size > MAX_SIZE) {
            toast?.({
                status: "error",
                title: t("settings:dashboard.invalidImage"),
            })
            return
        }

        setUploading(true)
        try {
            const result = await client.objects.create({ content: file })
            setBackgroundId(result.id)
        } catch (err) {
            console.error("Failed to upload background image:", err)
            toast?.({
                status: "error",
                title: t("settings:dashboard.uploadFailed"),
            })
        } finally {
            setUploading(false)
        }
    }

    const handleClearBackground = () => {
        setBackgroundId("")
        setBackgroundUrl("")
    }

    const handlePositionApply = (posX: number, posY: number, zoom: number) => {
        setBackgroundPositionX(posX)
        setBackgroundPositionY(posY)
        setBackgroundZoom(zoom)
    }

    const previewUrl = backgroundUrl || defaultBackground

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t("settings:dashboard.title")}</CardTitle>
                <CardDescription>
                    {t("settings:dashboard.description")}
                </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <Label htmlFor="dashboard-title">{t("settings:dashboard.titleLabel")}</Label>
                    <Input
                        id="dashboard-title"
                        placeholder={t("settings:dashboard.titlePlaceholder")}
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:dashboard.titleHelp")}
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    <Label htmlFor="dashboard-description">{t("settings:dashboard.descriptionLabel")}</Label>
                    <Textarea
                        id="dashboard-description"
                        placeholder={t("settings:dashboard.descriptionPlaceholder")}
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        rows={2}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:dashboard.descriptionHelp")}
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    <Label>{t("settings:dashboard.backgroundImage")}</Label>
                    {/* Preview */}
                    <div
                        ref={previewRef}
                        className="relative overflow-hidden rounded-sm"
                        style={{ height: `${bannerMaxHeight}px` }}
                    >
                        <div
                            className="w-full h-full"
                            role="img"
                            aria-label={t("settings:dashboard.backgroundPreviewAlt")}
                            style={{
                                backgroundImage: `url(${previewUrl})`,
                                backgroundSize: `${backgroundZoom}%`,
                                backgroundPosition: `${backgroundPositionX}% ${backgroundPositionY}%`,
                                backgroundRepeat: "no-repeat",
                            }}
                        />
                        <div className="absolute inset-0 bg-black/30 pointer-events-none" />
                        {(uploading || bgLoading) && (
                            <div className="absolute inset-0 flex items-center justify-center bg-black/40 pointer-events-none">
                                <Loader2 className="h-8 w-8 animate-spin text-white" />
                            </div>
                        )}
                        <div className="absolute inset-0 flex items-center justify-center px-6 pointer-events-none">
                            <div className="w-full max-w-md">
                                <div className="relative">
                                    <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-5 w-5 text-muted-foreground pointer-events-none" />
                                    <div className="pl-12 pr-4 h-12 bg-card rounded-md flex items-center text-muted-foreground text-lg shadow-lg">
                                        Search for documents or assets...
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    {/* Actions */}
                    <div className="flex flex-wrap gap-2">
                        <input
                            ref={fileInputRef}
                            type="file"
                            accept="image/*"
                            onChange={handleImageUpload}
                            className="hidden"
                        />
                        <Button variant="outline" type="button" disabled={uploading} onClick={() => fileInputRef.current?.click()}>
                            {uploading ? (
                                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                            ) : (
                                <Upload className="h-4 w-4 mr-2" />
                            )}
                            {t("settings:dashboard.uploadImage")}
                        </Button>
                        <DocumentSelectionOverlay
                            onSelection={handleImageSelection}
                            selectionMode="single"
                            disabled={uploading}
                        >
                            <Button variant="outline" type="button" disabled={uploading}>
                                <ImagePlus className="h-4 w-4 mr-2" />
                                {backgroundId ? t("settings:dashboard.changeImage") : t("settings:dashboard.selectImage")}
                            </Button>
                        </DocumentSelectionOverlay>
                        <Button
                            variant="outline"
                            type="button"
                            disabled={uploading}
                            onClick={() => setPositionDialogOpen(true)}
                        >
                            <Move className="h-4 w-4 mr-2" />
                            {t("settings:dashboard.adjustPosition")}
                        </Button>
                        {backgroundId && (
                            <Button variant="outline" type="button" disabled={uploading} onClick={handleClearBackground}>
                                <X className="h-4 w-4 mr-2" />
                                {t("common:actions.remove")}
                            </Button>
                        )}
                    </div>
                    <p className="text-sm text-muted-foreground">
                        {t("settings:dashboard.backgroundHelp")}
                    </p>
                </div>
                <div className="flex flex-col gap-2">
                    <Label htmlFor="banner-rendition-size">{t("settings:dashboard.bannerRenditionSize")}</Label>
                    <Input
                        id="banner-rendition-size"
                        type="number"
                        min={256}
                        max={4096}
                        step={256}
                        value={bannerRenditionSize}
                        onChange={(e) => setBannerRenditionSize(Number(e.target.value))}
                    />
                    <p className="text-sm text-muted-foreground">
                        {t("settings:dashboard.bannerRenditionSizeHelp")}
                    </p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="banner-max-height">{t("settings:dashboard.bannerMaxHeight")}</Label>
                        <Input
                            id="banner-max-height"
                            type="number"
                            min={64}
                            max={400}
                            step={8}
                            value={bannerMaxHeight}
                            onChange={(e) => setBannerMaxHeight(Number(e.target.value))}
                        />
                        <p className="text-sm text-muted-foreground">
                            {t("settings:dashboard.bannerMaxHeightHelp")}
                        </p>
                    </div>
                    <div className="flex flex-col gap-2">
                        <Label htmlFor="banner-min-height">{t("settings:dashboard.bannerMinHeight")}</Label>
                        <Input
                            id="banner-min-height"
                            type="number"
                            min={32}
                            max={400}
                            step={8}
                            value={bannerMinHeight}
                            onChange={(e) => setBannerMinHeight(Number(e.target.value))}
                        />
                        <p className="text-sm text-muted-foreground">
                            {t("settings:dashboard.bannerMinHeightHelp")}
                        </p>
                    </div>
                </div>
                <div className="flex flex-col gap-2 border-t pt-6">
                    <Label htmlFor="dashboard-display-mode">{t("settings:dashboard.displayMode")}</Label>
                    <Select value={displayMode} onValueChange={(value) => setDisplayMode(value as DashboardDisplayMode)}>
                        <SelectTrigger id="dashboard-display-mode" className="w-[280px]">
                            <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                            {DASHBOARD_DISPLAY_MODES.map((mode) => (
                                <SelectItem key={mode} value={mode}>
                                    {t(`settings:dashboard.displayModeOptions.${mode}`)}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <p className="text-sm text-muted-foreground">
                        {t(`settings:dashboard.displayModeHelp.${displayMode}`)}
                    </p>
                </div>

                {/* Image Grid Settings — only visible when the dashboard displays the image grid */}
                {showImageGridSettings && (
                    <div className="flex flex-col gap-4 border-t pt-6">
                        <div className="flex flex-col gap-1">
                            <Label className="text-base font-semibold">{t("settings:dashboard.imageGridLayout")}</Label>
                            <p className="text-sm text-muted-foreground">
                                {t("settings:dashboard.imageGridLayoutHelp")}
                            </p>
                        </div>

                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                            <div className="flex flex-col gap-2">
                                <Label htmlFor="grid-cols-sm">{t("common:gridCols.sm")}</Label>
                                <Input
                                    id="grid-cols-sm"
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={gridCols.sm}
                                    onChange={(e) => setGridCols(prev => ({ ...prev, sm: Number(e.target.value) }))}
                                    onBlur={(e) => setGridCols(prev => ({ ...prev, sm: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">{t("common:gridCols.smHint")}</p>
                            </div>
                            <div className="flex flex-col gap-2">
                                <Label htmlFor="grid-cols-md">{t("common:gridCols.md")}</Label>
                                <Input
                                    id="grid-cols-md"
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={gridCols.md}
                                    onChange={(e) => setGridCols(prev => ({ ...prev, md: Number(e.target.value) }))}
                                    onBlur={(e) => setGridCols(prev => ({ ...prev, md: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">{t("common:gridCols.mdHint")}</p>
                            </div>
                            <div className="flex flex-col gap-2">
                                <Label htmlFor="grid-cols-lg">{t("common:gridCols.lg")}</Label>
                                <Input
                                    id="grid-cols-lg"
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={gridCols.lg}
                                    onChange={(e) => setGridCols(prev => ({ ...prev, lg: Number(e.target.value) }))}
                                    onBlur={(e) => setGridCols(prev => ({ ...prev, lg: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">{t("common:gridCols.lgHint")}</p>
                            </div>
                            <div className="flex flex-col gap-2">
                                <Label htmlFor="grid-cols-xl">{t("common:gridCols.xl")}</Label>
                                <Input
                                    id="grid-cols-xl"
                                    type="number"
                                    min={1}
                                    max={12}
                                    value={gridCols.xl}
                                    onChange={(e) => setGridCols(prev => ({ ...prev, xl: Number(e.target.value) }))}
                                    onBlur={(e) => setGridCols(prev => ({ ...prev, xl: Math.max(1, Math.min(12, Number(e.target.value) || 1)) }))}
                                />
                                <p className="text-xs text-muted-foreground">{t("common:gridCols.xlHint")}</p>
                            </div>
                        </div>

                        <div className="flex flex-col gap-2">
                            <Label htmlFor="items-per-page">{t("settings:dashboard.itemsPerPage")}</Label>
                            <Input
                                id="items-per-page"
                                type="number"
                                min={4}
                                max={100}
                                step={1}
                                value={itemsPerPage}
                                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                                onBlur={(e) => setItemsPerPage(Math.max(4, Math.min(100, Number(e.target.value) || 4)))}
                            />
                            <p className="text-sm text-muted-foreground">
                                {t("settings:dashboard.itemsPerPageHelp")}
                            </p>
                        </div>

                        {/* Grid Preview */}
                        <div className="flex flex-col gap-2">
                            <button
                                type="button"
                                className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                                onClick={() => setShowGridPreview(prev => !prev)}
                            >
                                {showGridPreview ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                                <span>{showGridPreview ? t("common:actions.hidePreview") : t("common:actions.showPreview")}</span>
                            </button>
                            {showGridPreview && (
                                <div className="border rounded-md p-4 bg-muted/30">
                                    <div className="flex flex-col gap-3">
                                        {(["xl", "lg", "md", "sm"] as const).map((bp) => (
                                            <div key={bp} className="flex flex-col gap-1">
                                                <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{bp}</span>
                                                <div
                                                    className="grid gap-1.5"
                                                    style={{ gridTemplateColumns: `repeat(${gridCols[bp]}, 1fr)` }}
                                                >
                                                    {Array.from({ length: gridCols[bp] }).map((_, i) => (
                                                        <div
                                                            key={i}
                                                            className="aspect-square rounded-sm bg-primary/15 border border-primary/25"
                                                        />
                                                    ))}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}
                {/* Agentic search — links the agent used by the dashboard "Ask AI Assistant" button */}
                <div className="flex flex-col gap-2 border-t pt-6">
                    <Label htmlFor="agentic-search-interaction">{t("settings:dashboard.agenticSearch.label")}</Label>
                    <Select
                        value={agenticSearchInteraction || "none"}
                        onValueChange={(value) => setAgenticSearchInteraction(value === "none" ? "" : value)}
                    >
                        <SelectTrigger id="agentic-search-interaction" className="w-[320px]">
                            <SelectValue placeholder={t("settings:dashboard.agenticSearch.placeholder")} />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="none">{t("settings:dashboard.agenticSearch.none")}</SelectItem>
                            {agentInteractions.map((interaction) => (
                                <SelectItem key={interaction.id} value={interaction.id}>
                                    {interaction.name} (v{interaction.version})
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <p className="text-sm text-muted-foreground">
                        {interactionsLoading ? t("common:states.loading") : t("settings:dashboard.agenticSearch.help")}
                    </p>
                </div>
            </CardContent>
            <CardFooter className="justify-end">
                <Button onClick={() => onSave({ title, description, displayMode, backgroundId, backgroundPositionX, backgroundPositionY, backgroundZoom, bannerRenditionSize, bannerMaxHeight, bannerMinHeight, gridCols, itemsPerPage, agenticSearchInteraction })} disabled={loading || uploading}>
                    {loading ? t("common:actions.saving") : t("common:actions.save")}
                </Button>
            </CardFooter>

            <BannerPositionDialog
                open={positionDialogOpen}
                onOpenChange={setPositionDialogOpen}
                imageUrl={previewUrl}
                positionX={backgroundPositionX}
                positionY={backgroundPositionY}
                zoom={backgroundZoom}
                dashboardWidth={previewWidth}
                bannerHeight={bannerMaxHeight}
                onApply={handlePositionApply}
            />
        </Card>
    )
}
