import { useTranslation } from "react-i18next"
import { CollectionItem, ContentObjectItem } from "@vertesia/common"
import { FileText, FolderOpen, Loader2 } from "lucide-react"
import { AnimatePresence } from "motion/react"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandList,
} from "@/components/ui/command"
import { Label } from "@/components/ui/label"
import { ScrollArea } from "@/components/ui/scroll-area"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { MemberItem } from "./MemberItem"
import { MemberSearchItem } from "./MemberSearchItem"
import { type MemberItem as MemberItemType, type SearchMode } from "./useCollectionWizard"

interface WizardStepMembersProps {
    searchMode: SearchMode
    setSearchMode: (mode: SearchMode) => void
    searchQuery: string
    setSearchQuery: (query: string) => void
    filteredSearchResults: (ContentObjectItem | CollectionItem)[]
    isSearching: boolean
    currentMembers: MemberItemType[]
    membersToAdd: MemberItemType[]
    isLoadingMembers: boolean
    handleAddMember: (item: ContentObjectItem | CollectionItem) => void
    handleRemoveMember: (member: MemberItemType) => void
    disabled?: boolean
}

export function WizardStepMembers({
    searchMode,
    setSearchMode,
    searchQuery,
    setSearchQuery,
    filteredSearchResults,
    isSearching,
    currentMembers,
    membersToAdd,
    isLoadingMembers,
    handleAddMember,
    handleRemoveMember,
    disabled = false,
}: WizardStepMembersProps) {
    const { t } = useTranslation("common")
    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-full">
            {/* Left Column - Search */}
            <div className="flex flex-col gap-3 min-h-0">
                <div className="flex items-center justify-between h-9">
                    <Label className="text-base font-medium">{t("collectionWizard.searchItems")}</Label>
                    <ToggleGroup
                        type="single"
                        value={searchMode}
                        onValueChange={(value) => value && setSearchMode(value as SearchMode)}
                        variant="outline"
                    >
                        <ToggleGroupItem value="documents" aria-label={t("collectionWizard.searchDocuments")}>
                            <FileText className="h-4 w-4" />
                            {t("documents")}
                        </ToggleGroupItem>
                        <ToggleGroupItem value="collections" aria-label={t("collectionWizard.searchCollections")}>
                            <FolderOpen className="h-4 w-4" />
                            {t("collections")}
                        </ToggleGroupItem>
                    </ToggleGroup>
                </div>

                <Command className="border rounded-md flex-1 flex flex-col min-h-0" shouldFilter={false}>
                    <CommandInput
                        placeholder={searchMode === "documents" ? t("collectionWizard.searchDocuments") : t("collectionWizard.searchCollections")}
                        value={searchQuery}
                        onValueChange={setSearchQuery}
                        disabled={disabled}
                    />
                    <CommandList className="flex-1 max-h-none">
                        {isSearching ? (
                            <div className="flex items-center justify-center py-12">
                                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                            </div>
                        ) : (
                            <>
                                <CommandEmpty>
                                    {searchQuery
                                        ? (searchMode === "documents" ? t("collectionWizard.noDocumentsFound") : t("collectionWizard.noCollectionsFound"))
                                        : (searchMode === "documents" ? t("collectionWizard.typeToSearchDocuments") : t("collectionWizard.typeToSearchCollections"))}
                                </CommandEmpty>
                                <CommandGroup>
                                    {filteredSearchResults.map((item) => (
                                        <MemberSearchItem
                                            key={item.id}
                                            item={item}
                                            type={searchMode === "documents" ? "document" : "collection"}
                                            onSelect={handleAddMember}
                                        />
                                    ))}
                                </CommandGroup>
                            </>
                        )}
                    </CommandList>
                </Command>

                <p className="text-xs text-muted-foreground h-4">
                    {t("collectionWizard.clickToAdd")}
                </p>
            </div>

            {/* Right Column - Added Members */}
            <div className="flex flex-col gap-3 min-h-0">
                <div className="flex items-center justify-between h-9">
                    <Label className="text-base font-medium">{t("collectionWizard.addedMembers")}</Label>
                    <span className="text-sm text-muted-foreground">
                        {t("collectionWizard.itemCount", { count: currentMembers.length })}
                    </span>
                </div>

                {isLoadingMembers ? (
                    <div className="flex-1 flex items-center justify-center border rounded-md">
                        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                    </div>
                ) : currentMembers.length === 0 ? (
                    <div className="flex-1 flex items-center justify-center border rounded-md">
                        <p className="text-sm text-muted-foreground text-center px-4">
                            {t("collectionWizard.noMembersAdded")}<br />
                            {t("collectionWizard.searchAndClick")}
                        </p>
                    </div>
                ) : (
                    <ScrollArea className="flex-1 border rounded-md">
                        <div className="p-2">
                            <AnimatePresence mode="popLayout">
                                {currentMembers.map((member) => (
                                    <MemberItem
                                        key={member.id}
                                        member={member}
                                        isNew={membersToAdd.some(m => m.id === member.id)}
                                        onRemove={handleRemoveMember}
                                        disabled={disabled}
                                    />
                                ))}
                            </AnimatePresence>
                        </div>
                    </ScrollArea>
                )}

                <div className="flex items-center gap-4 text-xs text-muted-foreground h-4">
                    {currentMembers.length > 0 && (
                        <>
                            <div className="flex items-center gap-1">
                                <FileText className="h-3 w-3" />
                                {t("collectionWizard.documentCount", { count: currentMembers.filter(m => m.type === "document").length })}
                            </div>
                            <div className="flex items-center gap-1">
                                <FolderOpen className="h-3 w-3" />
                                {t("collectionWizard.subCollectionCount", { count: currentMembers.filter(m => m.type === "collection").length })}
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div>
    )
}
